/** [toolLabelRes], worded for a caller that is already drawing. */
@Composable
internal fun toolLabel(tool: ToolbarTool): String = stringResource(toolLabelRes(tool))

private fun toolActive(tool: ToolbarTool, state: KeyboardUiState): Boolean = when (tool) {
    ToolbarTool.EMOJI -> state.panel == PanelMode.EMOJI
    ToolbarTool.CLIPBOARD -> state.panel == PanelMode.CLIPBOARD
    ToolbarTool.SNIPPETS -> state.panel == PanelMode.SNIPPETS
    ToolbarTool.TEXT_EDIT -> state.panel == PanelMode.TEXT_EDIT
    ToolbarTool.TRACKPAD -> state.panel == PanelMode.TRACKPAD
    ToolbarTool.ONE_HANDED -> state.settings.oneHandedMode != OneHandedMode.OFF
    ToolbarTool.SPLIT -> state.settings.splitKeyboard
    ToolbarTool.FLOATING -> state.settings.floatingKeyboard
    ToolbarTool.PERSISTENT -> state.settings.persistentKeyboard
    ToolbarTool.RESIZE -> state.resize
    ToolbarTool.SETTINGS -> false
    ToolbarTool.FLASHLIGHT -> state.torchOn
    ToolbarTool.COMPASS -> state.panel == PanelMode.COMPASS
    ToolbarTool.LEVEL -> state.panel == PanelMode.LEVEL
    ToolbarTool.UNDO -> false
    ToolbarTool.REDO -> false
    ToolbarTool.MOON_PHASE -> state.panel == PanelMode.MOON_PHASE
    ToolbarTool.WEATHER -> state.panel == PanelMode.WEATHER
    ToolbarTool.CALENDAR -> state.panel == PanelMode.CALENDAR
    ToolbarTool.INCOGNITO -> state.incognitoOn
    ToolbarTool.SELECTION_ACTIONS -> state.settings.selectionMacros.enabled
    ToolbarTool.PHONETIC_ENGLISH ->
        state.settings.suggestionStrip.phoneticEnglishFor(state.composer.phoneticLanguage)
    ToolbarTool.POWER_SAVING -> state.powerSavingOn
    ToolbarTool.THEMES -> state.panel == PanelMode.THEMES
    ToolbarTool.AUTOCORRECT -> state.settings.correction.enabled
    ToolbarTool.SOUND_HAPTICS -> state.panel == PanelMode.SOUND_HAPTICS
    ToolbarTool.NUMPAD -> state.panel == PanelMode.NUMPAD
    ToolbarTool.HANDWRITING -> state.panel == PanelMode.HANDWRITING
    ToolbarTool.CAMERA -> state.panel == PanelMode.CAMERA
    ToolbarTool.DICTIONARY -> state.panel == PanelMode.DICTIONARY
    ToolbarTool.VOCABULARY -> state.panel == PanelMode.VOCABULARY
    ToolbarTool.LEARN_FROM_TEXT -> state.panel == PanelMode.LEARN_FROM_TEXT
    ToolbarTool.TRANSLATE -> state.panel == PanelMode.TRANSLATE
    ToolbarTool.GIF -> state.panel == PanelMode.GIF
    ToolbarTool.STICKER -> state.panel == PanelMode.STICKER
    ToolbarTool.WEB_SEARCH -> state.panel == PanelMode.WEB_SEARCH
    ToolbarTool.IMAGE_SEARCH -> state.panel == PanelMode.IMAGE_SEARCH
    ToolbarTool.OCR -> state.panel == PanelMode.OCR
    ToolbarTool.QR_SCAN -> state.panel == PanelMode.QR_SCAN
    ToolbarTool.DOC_SCAN -> false
    ToolbarTool.VOICE -> state.panel == PanelMode.VOICE || state.voice.strip || state.voice.bar
    ToolbarTool.GRAMMAR -> state.panel == PanelMode.GRAMMAR
    ToolbarTool.WIKIPEDIA -> state.panel == PanelMode.WIKIPEDIA
    ToolbarTool.SYMBOLS -> state.panel == PanelMode.SYMBOLS
    ToolbarTool.CALCULATOR -> state.panel == PanelMode.CALCULATOR
    ToolbarTool.UNIT_CONVERT -> state.panel == PanelMode.UNIT_CONVERT
    ToolbarTool.CURRENCY -> state.panel == PanelMode.CURRENCY
    ToolbarTool.QR_GEN -> state.panel == PanelMode.QR_GEN
    ToolbarTool.PASSWORD_GEN -> state.panel == PanelMode.PASSWORD_GEN
    ToolbarTool.TYPING_TEST -> state.panel == PanelMode.TYPING_TEST
    ToolbarTool.MEDIA_CONTROL -> state.panel == PanelMode.MEDIA_CONTROL
    ToolbarTool.KDE_CONNECT -> state.panel == PanelMode.KDE_CONNECT
    ToolbarTool.PLUGINS -> state.panel == PanelMode.PLUGINS
    ToolbarTool.APP_LAUNCHER -> state.panel == PanelMode.APP_LAUNCHER
    ToolbarTool.AI -> state.panel == PanelMode.AI
    ToolbarTool.MODES -> state.panel == PanelMode.MODES || state.activeModeId != null
    // Lit while the fancy layout is the one typing, however it got there:
    // the tool and the 🌐 key reach the same place.
    ToolbarTool.FANCY -> state.language.id == FancyStyles.LANG_ID
    // Lit while any secondary layout is up, whether this tool or a key put it
    // there: the tool takes it down either way.
    ToolbarTool.CUSTOM_LAYOUT ->
        state.layoutMode == LayoutMode.SECONDARY || state.panel == PanelMode.CUSTOM_LAYOUTS
    // Lit while a caret move would extend the selection, however that was
    // asked for: this tool, a hold on it, or the panel's own Select key. The
    // tool is the only indicator the mode has outside that panel, so it reads
    // the whole answer rather than its own flag.
    ToolbarTool.SELECT_MODE -> state.selectingText
    // Stateless one-shot moves, like undo/redo: nothing to stay lit for.
    ToolbarTool.CURSOR_LEFT, ToolbarTool.CURSOR_RIGHT,
    ToolbarTool.CURSOR_WORD_LEFT, ToolbarTool.CURSOR_WORD_RIGHT,
    ToolbarTool.CURSOR_UP, ToolbarTool.CURSOR_DOWN,
    ToolbarTool.CURSOR_HOME, ToolbarTool.CURSOR_END,
    ToolbarTool.PAGE_UP, ToolbarTool.PAGE_DOWN,
    ToolbarTool.SELECT_WORD, ToolbarTool.SELECT_LINE, ToolbarTool.SELECT_ALL,
    // The clipboard trio the same: they act and are done.
    ToolbarTool.COPY, ToolbarTool.CUT, ToolbarTool.PASTE,
    // A one-shot action too — it hides the keyboard, nothing to keep lit.
    ToolbarTool.HIDE_KEYBOARD -> false
}

/**
 * Live state of a toolbar-customization drag. Bounds and positions are all
 * in window-root coordinates; the ghost is drawn relative to the keyboard
 * body's origin. Drops on the toolbar insert at the slot under the finger,
 * drops on the toolbox grid reorder the toolbox (unpinning first when the
 * tool came off the bar), drops anywhere else send a toolbar tool back to
 * the toolbox at its remembered rank.
 *
 * [barSlot] and [boxSlot] are the live drop preview: whichever is non-null
 * is where the tool would land right now, and the owning row/grid renders
 * a ghost stand-in there so the surrounding icons make room ahead of the
 * drop.
 */
private class ToolDragController {
    var dragging by mutableStateOf<ToolbarTool?>(null)
        private set
    var position by mutableStateOf(Offset.Zero)
        private set
    /** Toolbar insertion slot under the finger, or null when off the bar. */
    var barSlot by mutableStateOf<Int?>(null)
        private set
    /** Toolbox grid slot under the finger, or null when off the grid. */
    var boxSlot by mutableStateOf<Int?>(null)
        private set
    private var fromToolbar = false
    var toolbarBounds: Rect? = null
    /**
     * Width, in px, that the toolbar last gave one of its buttons.
     *
     * Not the same as the theme's tool width. The bar spreads its buttons over
     * equal weighted cells, so a tool width wider than a cell is silently capped
     * at the cell — and the emoji shortcut the *strip* draws sits in no cell at
     * all, so it took the full width and the two copies of one icon came out
     * different sizes. At the top of the width slider that is a 60px jump on
     * every strip↔toolbar flip, right as the icon is meant to be sliding
     * smoothly between the two spots. Recorded from the toolbox launcher, which
     * is drawn whenever the bar is and shares the tools' cell.
     */
    var pinnedToolWidthPx: Int = 0
    /** Keyboard-body coordinates; the anchor for tool placement animations. */
    var bodyCoords: LayoutCoordinates? = null
    /**
     * Shared home of the emoji icon. It rides here rather than in [TopBar]
     * because the strip's copy and the toolbar's pinned copy are different
     * nodes: the handoff needs a holder that outlives both.
     */
    val emojiPlacement = SharedPlacement()
    /**
     * The stored pinned-tool list, in the order it is saved back. Every commit
     * is a rewrite of this.
     *
     * Always storage order, never mirrored: an RTL bar is a layout direction on
     * the row that draws the tools, not a different list. Mirroring the list as
     * well was the reorder bug — the row was flipped twice and the slot maths
     * once, so a tool dragged left landed to the right (issue #79).
     */
    var currentTools: List<ToolbarTool> = emptyList()
    /**
     * The subset of [currentTools] the bar actually draws — a pinned tool the
     * user has disabled, or one this build does not ship, is stored but never
     * shown. Slots are counted against this list, because it is the one the
     * finger is pointing at; [end] then translates the slot back into a
     * position in the stored list, so hiding a tool never unpins it.
     */
    var visibleTools: List<ToolbarTool> = emptyList()
    /**
     * Whether the row drawing [visibleTools] lays them out right-to-left.
     *
     * Registered by the bar itself, from the layout direction it actually draws
     * under, so the hit-testing follows the display instead of re-deriving it:
     * under RTL the tool at index 0 is the one hard against the *right* edge,
     * and a slot measured from the left names its mirror image.
     */
    var barRtl: Boolean = false
    var onCommit: (List<ToolbarTool>) -> Unit = {}
    /** Haptic tick when the drop target changes: slot to slot, or on/off the bar. */
    var onSnap: () -> Unit = {}
    /** Hold without dragging past the slop: open the tool's settings page. */
    var onOpenSettings: (ToolbarTool) -> Unit = {}

    /**
     * Runs the tool a hold was remapped to (see `holdActionFor`). Routed through
     * the controller alongside [onOpenSettings] rather than captured per tool:
     * both are the same gesture's outcome, and the tool cells are recomposed on
     * every frame of a drag, so a captured lambda would restart their pointer
     * handlers.
     */
    var onHoldAction: (ToolbarTool) -> Unit = {}

    /**
     * The Selection mode tool held down (true) and let go (false). On the
     * controller for the same reason [onHoldAction] is, and because the release
     * has to reach the service even when the finger travels far enough to turn
     * the gesture into a reorder.
     */
    var onSelectionHold: (Boolean) -> Unit = {}

    /**
     * The Trackpad tool held down (true) and let go (false): the panel is open
     * for exactly that long. Paired the same way [onSelectionHold] is.
     */
    var onTrackpadHold: (Boolean) -> Unit = {}

    /**
     * A voice typing mode picked off the Voice tool's hold menu (#173): the
     * mode's token. On the controller for the reason [onHoldAction] is.
     */
    var onVoiceModePick: (String) -> Unit = {}

    // Toolbox geometry and data, registered by ToolboxPanel while it is
    // open (a drag can only happen with the toolbox open). The viewport is
    // the visible panel box; content coords are the scrolling grid column,
    // so slot math follows the scroll position for free.
    var toolboxViewport: Rect? = null
    var toolboxContentCoords: LayoutCoordinates? = null
    var toolboxCellSize: Size = Size.Zero
    var toolboxColumns: Int = 1
    /** [barRtl] for the grid: column 0 is the rightmost one under RTL. */
    var boxRtl: Boolean = false
    /**
     * Index the visible page starts at, when the toolbox is paginated. The
     * registered content coords belong to that one page, so its first cell is
     * slot [toolboxPageStart], not slot 0. Zero for the scrolling toolbox,
     * where the content is the whole grid.
     */
    var toolboxPageStart: Int = 0
    /**
     * How many slots that page holds — the drop is clamped to it so a drag
     * that wanders past the last pill on page 2 lands at the end of page 2
     * rather than at the end of the toolbox.
     */
    var toolboxPageLength: Int = Int.MAX_VALUE
    /** The tools the toolbox grid is showing, in toolbox order. */
    var toolboxTools: List<ToolbarTool> = emptyList()
    /** Complete ordering over every tool; reorders rewrite this. */
    var toolboxOrder: List<ToolbarTool> = emptyList()
    /**
     * Tools the user hid from the grid. The grid is no drop target for them:
     * it would show a slot and then never draw the tool in it. Dragged off the
     * bar, one simply unpins, the way any off-bar drop does.
     */
    var toolboxHidden: Set<ToolbarTool> = emptySet()
    var onOrderCommit: (List<ToolbarTool>) -> Unit = {}

    /**
     * The order a drop just committed, handed to the grid so it can draw it
     * before the settings come back with it. Separate from [onOrderCommit]
     * because they go different ways: the commit goes out to storage and takes
     * a coroutine hop to return, and this one stays here.
     */
    var onOrderPreview: (List<ToolbarTool>) -> Unit = {}

    fun start(tool: ToolbarTool, fromBar: Boolean, at: Offset) {
        dragging = tool
        fromToolbar = fromBar
        position = at
        barSlot = slotAt(at)
        boxSlot = if (barSlot == null) toolboxSlotAt(at) else null
    }

    fun move(to: Offset) {
        position = to
        val bar = slotAt(to)
        val box = if (bar == null) toolboxSlotAt(to) else null
        if (bar != barSlot || box != boxSlot) {
            barSlot = bar
            boxSlot = box
            onSnap()
        }
    }

    fun cancel() {
        dragging = null
        barSlot = null
        boxSlot = null
    }

    fun end() {
        val tool = dragging ?: return
        val bar = slotAt(position)
        val box = if (bar == null) toolboxSlotAt(position) else null
        cancel()
        if (bar != null) {
            onCommit(barWith(tool, bar))
        } else if (box != null) {
            // Dropped on the grid: place it at that spot in the toolbox
            // order — and off the bar first, when that's where it came from.
            if (fromToolbar) onCommit(currentTools - tool)
            val next = orderWith(tool, box)
            // Shown first, saved second. Both from the same list, so the grid
            // never draws an arrangement the storage will not agree with.
            onOrderPreview(next)
            onOrderCommit(next)
        } else if (fromToolbar && toolboxViewport != null) {
            // Off-bar drops unpin only while the toolbox is open (its
            // viewport is registered) — a reorder drag that wanders off the
            // bar with no toolbox in sight just snaps back.
            onCommit(currentTools - tool)
        }
    }

    /**
     * Insertion slot under [at], or null when off the toolbar. The bar's hit
     * box is inflated so a drop just above/below it still counts.
     */
    private fun slotAt(at: Offset): Int? {
        val tool = dragging ?: return null
        val bar = toolbarBounds?.inflate(30f) ?: return null
        if (!bar.contains(at)) return null
        val without = visibleTools - tool
        if (without.isEmpty()) return 0
        // Measured from the edge the row starts its tools at — the right one
        // when the bar draws RTL ([barRtl]), so the slot always counts in the
        // same direction the icons are laid out in.
        val travel = if (barRtl) bar.right - at.x else at.x - bar.left
        return ((travel / bar.width) * (without.size + 1))
            .toInt()
            .coerceIn(0, without.size)
    }

    /**
     * The stored pinned list with [tool] moved to display slot [slot] of the
     * bar. The same trick [orderWith] uses for the toolbox: the slot indexes
     * the drawn tools, so the drawn tool it lands in front of is what pins the
     * position down in a stored list that may hold tools the bar never drew.
     */
    private fun barWith(tool: ToolbarTool, slot: Int): List<ToolbarTool> {
        val shown = visibleTools - tool
        val successor = shown.getOrNull(slot.coerceIn(0, shown.size))
        val bar = currentTools.toMutableList().apply { remove(tool) }
        val at = successor?.let { bar.indexOf(it) }?.takeIf { it >= 0 } ?: bar.size
        bar.add(at, tool)
        return bar
    }

    /**
     * Toolbox grid slot under [at], or null when off the visible panel. The
     * grid scrolls, so the position converts through the content column's
     * live coordinates rather than a captured rect.
     */
    private fun toolboxSlotAt(at: Offset): Int? {
        val tool = dragging ?: return null
        if (tool in toolboxHidden) return null
        val viewport = toolboxViewport ?: return null
        if (!viewport.contains(at)) return null
        val coords = toolboxContentCoords?.takeIf { it.isAttached } ?: return null
        val cell = toolboxCellSize
        if (cell.width <= 0f || cell.height <= 0f) return null
        val origin = coords.positionInRoot()
        val columns = toolboxColumns.coerceAtLeast(1)
        val count = (toolboxTools - tool).size
        val across = ((at.x - origin.x) / cell.width).toInt().coerceIn(0, columns - 1)
        // The grid fills from the right under RTL, so the leftmost cell of a
        // full row is its last column, not its first.
        val col = if (boxRtl) columns - 1 - across else across
        val row = ((at.y - origin.y) / cell.height).toInt().coerceAtLeast(0)
        // The cell is local to whatever registered the coords: the whole grid
        // when the toolbox scrolls, one page when it paginates.
        val local = (row * columns + col).coerceIn(0, toolboxPageLength)
        return (toolboxPageStart + local).coerceIn(0, count)
    }

    /** The full tool order with [tool] moved to display slot [slot] of the grid. */
    private fun orderWith(tool: ToolbarTool, slot: Int): List<ToolbarTool> {
        // The grid previews the drop with the dragged tool removed, so the
        // slot indexes that list; the displayed tool it lands in front of
        // anchors the position in the complete order.
        val displayed = toolboxTools - tool
        val successor = displayed.getOrNull(slot.coerceIn(0, displayed.size))
        val order = toolboxOrder.toMutableList().apply { remove(tool) }
        val at = successor?.let { order.indexOf(it) }?.takeIf { it >= 0 } ?: order.size
        order.add(at, tool)
        return order
    }
}

/**
 * Distance a held tool has to travel before the gesture counts as a move
 * rather than a stationary hold. Generous on purpose: a hold meant to open
 * the tool's settings drifts a few pixels under any real thumb, and landing
 * in "moved the tool" because of that is the more annoying misfire.
 */
private val ToolDragSlop = 24.dp

/**
 * How often a held toolbar tool repeats its move, or null for the tools (and
 * the settings) where holding means something else.
 *
 * The interval is the text-editing tool's repeat speed: the same key held down
 * at the same rate, whether the user reached it through the panel or pinned it
 * to the bar.
 */
private fun holdRepeatMs(tool: ToolbarTool, state: KeyboardUiState): Long? =
    if (tool in HoldRepeatCursorTools && state.settings.textEditing.cursorToolsRepeatOnHold) {
        state.settings.textEditing.repeatMs.toLong()
    } else {
        null
    }

/**
 * The tool a press and hold on [tool] runs instead of opening its settings page,
 * or null when the hold keeps its original job.
 *
 * Toolbar only, and never for a tool whose hold already repeats — that hold is
 * spoken for, and the tools it covers are the caret moves, where a repeat is the
 * whole point. Reads through to a tool rather than a separate action vocabulary:
 * "holding this does what tapping that does" needs nothing new to be dispatched,
 * and every tool is already a target.
 */
private fun holdActionFor(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    state: KeyboardUiState,
): ToolHoldAction? = if (
    !fromToolbar || holdRepeatMs(tool, state) != null ||
    holdArmsSelection(tool, fromToolbar, state) || holdOpensTrackpad(tool, fromToolbar, state) ||
    holdPicksVoiceMode(tool, fromToolbar, state)
) {
    null
} else {
    state.settings.toolbarBehavior.holdActions[tool]
}

/**
 * Whether a press and hold on [tool] opens the voice typing mode menu: the
 * Voice tool on the toolbar, unless the user has given that hold back (#173).
 * The fifth thing a stationary hold can be, exclusive with the other four the
 * way they are with each other, and toolbar only for the reason
 * [holdArmsSelection] is.
 */
private fun holdPicksVoiceMode(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    state: KeyboardUiState,
): Boolean = fromToolbar &&
    tool == ToolbarTool.VOICE &&
    state.settings.voiceBar.holdPicksTypingMode

/**
 * Whether a press and hold on [tool] opens the trackpad panel for as long as the
 * finger stays down: the Trackpad tool on the toolbar, unless the user has
 * given that hold back (issue #39). The fourth thing a stationary hold can be,
 * exclusive with the other three the way they are with each other, and toolbar
 * only for the reason [holdArmsSelection] is.
 */
private fun holdOpensTrackpad(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    state: KeyboardUiState,
): Boolean = fromToolbar &&
    tool == ToolbarTool.TRACKPAD &&
    state.settings.trackpad.holdToOpen

/**
 * Whether a press and hold on [tool] turns selection mode on for as long as the
 * finger stays down — true for the Selection mode tool on the toolbar, unless
 * the user has given that hold back.
 *
 * The third thing a stationary hold can be, beside repeating a caret move and
 * running a bound action, and it excludes the other two the same way they
 * exclude each other. Toolbar only: in the toolbox a hold reaches every tool's
 * settings page, and there is nothing to select behind an open panel anyway.
 */
private fun holdArmsSelection(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    state: KeyboardUiState,
): Boolean = fromToolbar &&
    tool == ToolbarTool.SELECT_MODE &&
    state.settings.textEditing.selectionModeHold

/**
 * Wires long-press-drag onto a tool. Three outcomes from one gesture: a tap
 * runs [onTap]; a hold that never travels past [ToolDragSlop] opens the
 * tool's settings page — or runs [holdAction] when the user has given that
 * tool one; a hold that does travel picks the tool up and drops it wherever it
 * lands (reorder, pin, or unpin).
 *
 * [holdRepeatMs] replaces the middle one for the caret tools (see
 * [HoldRepeatCursorTools]): a stationary hold runs [onTap] again every
 * [holdRepeatMs] instead, so the cursor keeps moving for as long as the finger
 * is down. Null everywhere else, and on those tools the settings page is a hold
 * away in the toolbox instead.
 *
 * [holdArms] replaces it in the same way for the Selection mode tool: the hold
 * turns selection mode on while the finger is down and the release turns it off
 * (see [holdArmsSelection]). The release reaches the service on the drag path
 * too, or the mode would be left on by a reorder.
 *
 * [holdPanel] is the same shape for the Trackpad tool: the hold opens the
 * trackpad panel and the release closes it (see [holdOpensTrackpad]).
 *
 * Whatever the hold means, the pick-up itself waits for the finger to travel
 * past the slop. Only then does the cell wash out and the scope pill appear:
 * a hold that stays put is one of the three outcomes above, not a reorder, and
 * must not look like one while it is being held.
 *
 * The tap is dispatched from here rather than from a `clickable` on the tool
 * itself: a `clickable` sits deeper in the modifier chain, so it saw the
 * release first and fired its own click on top of every hold.
 */
@Composable
private fun DraggableTool(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    enabled: Boolean,
    drag: ToolDragController,
    onTap: () -> Unit,
    holdRepeatMs: Long? = null,
    /**
     * What a stationary hold does — another tool's tap, or nothing at all —
     * or null to open the tool's settings page.
     */
    holdAction: ToolHoldAction? = null,
    /**
     * Whether a hold that travels picks the tool up. Off (#136), travel is
     * ignored: the hold stays a hold and ends as whatever a stationary one
     * would have, so the bar is rearranged from the toolbox instead.
     */
    dragEnabled: Boolean = true,
    /** Whether a stationary hold arms selection mode for as long as it lasts. */
    holdArms: Boolean = false,
    /** Whether a stationary hold opens the trackpad panel for as long as it lasts. */
    holdPanel: Boolean = false,
    /**
     * Whether a stationary hold opens a menu on its release — the Voice tool's
     * typing modes (#173) — through [onHoldMenu]. Dispatched like the settings
     * page and a bound action, on the lift, not like [holdArms]: the menu is
     * what the hold was for, and it stands after the finger is gone.
     */
    holdMenu: Boolean = false,
    onHoldMenu: () -> Unit = {},
    content: @Composable (Modifier) -> Unit,
) {
    var origin by remember { mutableStateOf(Offset.Zero) }
    val feedback = LocalKeyPressFeedback.current
    val scope = rememberCoroutineScope()
    // Read through a holder rather than keying pointerInput on the lambda:
    // a fresh lambda every recomposition would restart the handler, and the
    // drop preview recomposes this row on every frame of a drag.
    val tapAction by rememberUpdatedState(onTap)
    val menuAction by rememberUpdatedState(onHoldMenu)
    content(
        Modifier
            .onGloballyPositioned { origin = it.positionInRoot() }
            // Keyed on the interval too: it comes from a setting, so the handler
            // has to be rebuilt when it changes. A Long changes far more rarely
            // than the lambda above, which is why that one goes through a holder.
            .pointerInput(enabled, tool, holdRepeatMs, holdArms, holdPanel, holdMenu, dragEnabled) {
                if (!enabled) return@pointerInput
                // Raw press-and-hold, mirroring the key rows' handler, instead
                // of detectDragGesturesAfterLongPress: its long-press never
                // fired inside the IME window on device, so tools could not
                // be dragged at all. An external timer plus a plain event
                // loop is the pattern already proven by the repeat keys.
                val dragSlop = ToolDragSlop.toPx()
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false)
                    // Travel is measured in root coordinates, not from raw
                    // node-relative deltas: the row reflows around the drop
                    // preview while the finger is down, and a node that moves
                    // under a still finger reports deltas of its own.
                    val downRoot = origin + down.position
                    var rootPos = downRoot
                    var longPressed = false
                    var dragged = false
                    var released = false
                    var scrolled = false
                    // Whether selection mode is on because of *this* hold, so
                    // the release turns off exactly what the press turned on.
                    var armed = false
                    // Same for the trackpad panel: open by this hold, closed by
                    // its release, and never by a release that did not open it.
                    var held = false
                    val timer = scope.launch {
                        delay(viewConfiguration.longPressTimeoutMillis)
                        // The buzz tells the user the long-press registered.
                        // The pick-up itself waits for travel (see the drag
                        // slop below), for every kind of hold: starting it here
                        // parked a drag ghost and the scope pill under a finger
                        // that was only holding the button, so a hold that
                        // ended as a bound action or the settings page first
                        // washed its own cell out and flashed a "changing the
                        // tool order" notice for a reorder nobody made (#31).
                        feedback()
                        longPressed = true
                        if (holdArms) {
                            // Selection mode for as long as the finger stays
                            // down. The bar can still be rearranged from this
                            // button: travel picks it up like any other.
                            armed = true
                            drag.onSelectionHold(true)
                        } else if (holdPanel) {
                            // The trackpad for as long as the finger stays
                            // down; the other thumb does the dragging. The bar
                            // can still be rearranged from this button too.
                            held = true
                            drag.onTrackpadHold(true)
                        } else if (holdRepeatMs != null) {
                            // The first move lands with no delay of its own —
                            // the long-press timeout has already served as the
                            // repeat's start delay.
                            while (true) {
                                tapAction()
                                delay(holdRepeatMs)
                            }
                        }
                    }
                    try {
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) {
                                released = true
                                // Swallow the release once the hold is ours so
                                // nothing downstream treats it as a tap too.
                                if (longPressed) change.consume()
                                break
                            }
                            rootPos = origin + change.position
                            val travel = (rootPos - downRoot).getDistance()
                            if (!longPressed) {
                                // Real drift before the hold registers is a
                                // scroll (toolbox grid) — hand the gesture back.
                                if (travel > viewConfiguration.touchSlop) {
                                    scrolled = true
                                    break
                                }
                            } else {
                                change.consume()
                                if (travel > dragSlop && !dragged && dragEnabled) {
                                    dragged = true
                                    // Travel means this was a reorder all along,
                                    // so the tool picks itself up from here. A
                                    // repeating tool stops repeating; the moves
                                    // it already made stand — they are caret
                                    // moves, undone by moving the caret back.
                                    timer.cancel()
                                    // The mode ends here rather than on the
                                    // drop: from this point the gesture is
                                    // about the toolbar, not the text.
                                    if (armed) {
                                        armed = false
                                        drag.onSelectionHold(false)
                                    }
                                    if (held) {
                                        held = false
                                        drag.onTrackpadHold(false)
                                    }
                                    drag.start(tool, fromToolbar, rootPos)
                                }
                                // Nothing to move until the finger has travelled:
                                // no drag has been started, and drag.move would
                                // tick the drop haptic anyway.
                                if (dragged) drag.move(rootPos)
                            }
                        }
                    } finally {
                        timer.cancel()
                        // Whatever ended the gesture — a release, a drop, the
                        // handler being torn down mid-hold — the mode this press
                        // armed ends with it. Nothing else here can be trusted
                        // to run: the branches below are exclusive.
                        if (armed) {
                            armed = false
                            drag.onSelectionHold(false)
                        }
                        if (held) {
                            held = false
                            drag.onTrackpadHold(false)
                        }
                        when {
                            !longPressed -> {
                                drag.cancel()
                                if (released && !scrolled) tapAction()
                            }
                            dragged -> drag.end()
                            // A hold that armed selection mode, or held the
                            // trackpad open, has already done its work, and
                            // there is nothing to drop. Its settings page is a
                            // hold away in the toolbox.
                            holdArms || holdPanel -> drag.cancel()
                            // Same for a repeating hold. Its settings page is a
                            // hold away in the toolbox, which never repeats.
                            holdRepeatMs != null -> drag.cancel()
                            // A hold that opens a menu opens it on the lift,
                            // like the settings page below: a menu under a
                            // finger that is still down would be dismissed by
                            // the release that was meant to read it.
                            holdMenu -> {
                                drag.cancel()
                                menuAction()
                            }
                            // A hold that never travelled past the slop is a
                            // distinct gesture: the action the user bound to it,
                            // nothing at all if that is what they bound (#136),
                            // or the tool's settings page when they bound none.
                            else -> {
                                drag.cancel()
                                when (val bound = holdAction) {
                                    null -> drag.onOpenSettings(tool)
                                    ToolHoldAction.None -> Unit
                                    is ToolHoldAction.Run -> drag.onHoldAction(bound.tool)
                                }
                            }
                        }
                    }
                }
            }
    )
}

/**
 * Slides this element to its new position when layout around it changes —
 * pinned tools shuffle smoothly instead of jumping when the toolbox chevron
 * shows up or a tool is (un)pinned. Fast, no-bounce spring: quick but not
 * sudden.
 *
 * The position is measured against [anchor] (the keyboard body) rather than
 * the immediate parent: the toolbar nests rows inside rows and its weighted
 * cells resize, so an icon's parent-relative position barely moves while
 * its on-screen position shifts a lot. Anchoring at the body captures the
 * whole motion in one spring, so nothing snaps at animation start. Falls
 * back to parent-relative when no anchor is available.
 *
 * [enabled] is the reduce-motion switch. It has to snap rather than skip the
 * modifier: opening a panel adds the back chevron, which shifts every pinned
 * icon, so a disabled slide still needs to track the new position or the
 * icons would sit at their old offsets.
 *
 * [inRow] marks a node that only ever slides along a single row — everything
 * on the toolbar. Those get the row rules [animateSharedPlacement] already
 * used for the emoji tool: a vertical move snaps (the row itself has moved,
 * see [ToolbarRowShiftPx]) and a horizontal one may travel as far as the bar
 * is wide (see [ToolbarSlideCapFraction]). The toolbox grid leaves it false —
 * its cells legitimately move between rows when the grid reflows — and brings
 * its own [cap] instead, because a grid cell is far bigger than the fixed one
 * (see [toolboxSlideCap]).
 *
 * [cap] is the furthest a move may be and still be slid rather than snapped,
 * given the anchor it was measured against. The default is the row/fixed rule
 * [placementCap]; a caller whose layout has a natural step of its own passes
 * that step instead.
 */
private fun Modifier.animatePlacement(
    enabled: Boolean = true,
    inRow: Boolean = false,
    cap: (LayoutCoordinates?) -> Float = { placementCap(inRow, it) },
    anchor: () -> LayoutCoordinates? = { null },
): Modifier =
    composed {
        val scope = rememberCoroutineScope()
        val animatable = remember { Animatable(IntOffset.Zero, IntOffset.VectorConverter) }
        // The displacement drawn right now, set synchronously from onPlaced.
        // Everything below hangs on this: onPlaced runs in the layout phase,
        // by which point a layout-phase offset for this frame has already
        // been decided, and the coroutine that starts the spring does not run
        // until the next one. So the icon was drawn once at its destination,
        // then jumped back to where it came from and slid in — a one-frame
        // flash on every icon, every time the bar changed. Draw runs after
        // layout in the same frame, so a draw-phase displacement written here
        // lands before the icon is ever painted undisplaced.
        var immediate by remember { mutableStateOf<IntOffset?>(null) }
        var lastTarget by remember { mutableStateOf<IntOffset?>(null) }
        // Whether [lastTarget] was measured against the anchor or against the
        // parent. The anchor is published from an onGloballyPositioned, which
        // runs AFTER this node's first placement, so the first target is always
        // parent-relative and every later one anchor-relative. Two different
        // spaces: subtracting one from the other invents a move nothing made.
        var lastAnchored by remember { mutableStateOf(false) }
        this
            .onPlaced { coords ->
                val anchorCoords = anchor()?.takeIf { it.isAttached }
                val target = (
                    anchorCoords?.localPositionOf(coords, Offset.Zero)
                        ?: coords.positionInParent()
                    ).round()
                val anchored = anchorCoords != null
                val previous = lastTarget.takeIf { lastAnchored == anchored }
                lastTarget = target
                lastAnchored = anchored
                // First placement settles in place: a fresh icon has nowhere to
                // have travelled from. So does the first one after the anchor
                // turned up, for the same reason — that target and the one
                // before it are in different spaces.
                //
                // This is what made a freshly opened toolbox slide its pills
                // around: parent-relative, every pill sits at ~(0,0) inside its
                // own cell, so the second pass handed each one a "move" equal to
                // its own slot in the grid. Column offsets and the lower rows
                // were past [PlacementSlideCap] and snapped, but the left column
                // of row 2 is exactly one pill-pitch down — inside the cap — so
                // that one pill, and only that one, slid in from the row above.
                if (previous == null || previous == target) return@onPlaced
                val delta = previous - target
                // A row-bound icon that moved vertically did not move: its row
                // did, and sliding after a row that has already arrived reads
                // as lag. Snap — and snap for every icon in the bar alike. This
                // was [animateSharedPlacement]'s rule alone, so opening the
                // emoji panel over an always-on emoji row (the row folds away,
                // the whole bar rises) left the emoji tool and the toolbox
                // standing still while the clipboard and settings icons drifted
                // in diagonally from where the old row had been.
                val rowShifted = inRow &&
                    (delta.x == 0 || kotlin.math.abs(delta.y) > ToolbarRowShiftPx)
                val jump = delta.toOffset().getDistance()
                // Deadband, and the big-jump escape. The toolbar's cells are
                // weighted, so their widths land on fractions that round
                // differently between passes; nothing travels a single pixel
                // on purpose here, so a move that small is rounding, not
                // motion. A move past the cap is a layout jump (a scroll, a
                // toolbox page flip) and animating it reads as lag.
                val capPx = cap(anchorCoords)
                if (!enabled || rowShifted || jump < 2f || jump > capPx) {
                    immediate = null
                    scope.launch { animatable.snapTo(IntOffset.Zero) }
                    return@onPlaced
                }
                // Carry any displacement still in flight, so a change that
                // lands mid-slide continues from where the icon actually is
                // rather than restarting from the new delta alone.
                val start = delta + (immediate ?: animatable.value)
                immediate = start
                scope.launch {
                    animatable.snapTo(start)
                    immediate = null
                    animatable.animateTo(IntOffset.Zero, ToolbarSlideSpring)
                }
            }
            .graphicsLayer {
                val shift = immediate ?: animatable.value
                translationX = shift.x.toFloat()
                translationY = shift.y.toFloat()
            }
    }

/**
 * The furthest a re-placed icon may have travelled and still be slid rather
 * than snapped.
 *
 * A toolbar icon is measured against the bar it sits in ([anchorCoords] is the
 * keyboard body, so its width is the bar's), because what the bar asks of its
 * icons scales with how wide it is; see [ToolbarSlideCapFraction]. Anything
 * else, and a bar with no anchor to measure, falls back to [PlacementSlideCap].
 */
private fun placementCap(inRow: Boolean, anchorCoords: LayoutCoordinates?): Float {
    if (!inRow) return PlacementSlideCap
    val width = anchorCoords?.size?.width?.toFloat() ?: return PlacementSlideCap
    return (width * ToolbarSlideCapFraction).coerceAtLeast(PlacementSlideCap)
}

/**
 * Headroom over one reorder step, before a toolbox move is taken for a layout
 * jump. A step is never *exactly* a step — a cell's own padding shifts by a
 * pixel or two between passes — so the cap has to clear it rather than sit on
 * it.
 */
private const val ToolboxSlideCapSlack = 1.15f

/**
 * The furthest a toolbox cell may travel and still slide, sized off the grid's
 * own step rather than the fixed [PlacementSlideCap].
 *
 * The fixed cap is a toolbar cap: 160 px is well under half an icon's slot on
 * the bar, but it is under *one cell* of the grid on every phone (four columns
 * of a 1080 px keyboard are 270 px each). So every reorder step the grid ever
 * made was read as a layout jump and snapped, and the tools popped from slot to
 * slot while the toolbar beside them slid — the whole of this bug.
 *
 * The real step is one slot, and the biggest one slot can be is a wrap: the
 * last cell of a row becoming the first of the next, which is [columns] - 1
 * cells across and one cell down. Anything past that is a reflow the grid did
 * not ask for — the column count changed, the panel resized — and snapping
 * those is what the cap is still for.
 */
private fun toolboxSlideCap(columns: Int, cell: Size): Float {
    if (cell.width <= 0f || cell.height <= 0f) return PlacementSlideCap
    val across = cell.width * (columns - 1).coerceAtLeast(1)
    val wrap = Offset(across, cell.height).getDistance()
    return (wrap * ToolboxSlideCapSlack).coerceAtLeast(PlacementSlideCap)
}

/**
 * Where an icon that lives in more than one branch of the tree last sat.
 *
 * [animatePlacement] can only animate a node that survives the layout
 * change, and the emoji icon does not: the strip draws its own copy and
 * the toolbar draws another as a pinned tool, so flipping between them
 * disposes one node and composes a different one. Parking the last
 * body-relative position outside both lets the arriving node start from
 * where the leaving one stood, which is the whole illusion.
 */
private class SharedPlacement {
    var last: IntOffset? = null

    /** Whether [last] was measured against the anchor or against a parent. */
    var lastAnchored: Boolean = false

    /**
     * When the node holding [last] was disposed, or 0 while one still holds it.
     *
     * This is what separates a handoff from a reappearance. A handoff is one
     * node being disposed and another composed inside a single frame, so the
     * arriving node finds a stamp a frame or two old. A reappearance — the
     * icon's whole host went away, because a full-bleed panel takes the top
     * bar with it, and came back seconds later — finds a stale one, and
     * sliding in from a position that old is a phantom: the icon flies in
     * from wherever it happened to sit before the panel opened.
     *
     * It has to be dispose time, not the time [last] was written. Writing it
     * on placement looks equivalent and is not: a node is only re-placed when
     * layout invalidates, so the strip's emoji icon stamps once when it
     * appears and then sits untouched for as long as the user types. Every
     * real handoff then read as ancient and refused to animate, which is
     * exactly the icon snapping into place instead of sliding.
     */
    var vacatedAtNanos: Long = 0L
}

/** Two frames at 60Hz, the window a real strip/toolbar handoff lands in. */
private const val SharedPlacementMaxAgeNanos = 33_000_000L

/**
 * Slides this element in from wherever [shared] was last seen, then keeps
 * [shared] pointing at its own position. The counterpart to
 * [animatePlacement] for an icon that changes parents rather than moving
 * within one.
 */
private fun Modifier.animateSharedPlacement(
    shared: SharedPlacement,
    enabled: Boolean = true,
    anchor: () -> LayoutCoordinates? = { null },
): Modifier =
    composed {
        val scope = rememberCoroutineScope()
        val offset = remember { Animatable(IntOffset.Zero, IntOffset.VectorConverter) }
        var immediate by remember { mutableStateOf<IntOffset?>(null) }
        // Stamp the moment this node leaves, so whichever node replaces it can
        // tell a handoff from a reappearance. onDispose runs while changes are
        // applied, ahead of the layout pass that places the arriving node, so
        // the stamp is always there in time.
        DisposableEffect(shared) {
            onDispose { shared.vacatedAtNanos = System.nanoTime() }
        }
        // This node's own last position, so a re-placement within one parent
        // (the bar reflowing under it) animates like [animatePlacement] does,
        // not just the cross-parent handoff. Without this the emoji snapped
        // whenever the toolbar reshuffled — every other icon slid but it.
        var lastTarget by remember { mutableStateOf<IntOffset?>(null) }
        // Anchor-relative or parent-relative, for this node and for the shared
        // stamp alike. The anchor arrives from an onGloballyPositioned a pass
        // late, so a first position is parent-relative and everything after it
        // is not; comparing across the two would invent a move. See the same
        // note in [animatePlacement].
        var lastAnchored by remember { mutableStateOf(false) }
        this
            .onPlaced { coords ->
                val anchorCoords = anchor()?.takeIf { it.isAttached }
                val position = (
                    anchorCoords?.localPositionOf(coords, Offset.Zero)
                        ?: coords.positionInParent()
                    ).round()
                val anchored = anchorCoords != null
                if (lastTarget == position && lastAnchored == anchored) return@onPlaced
                val ownPrevious = lastTarget.takeIf { lastAnchored == anchored }
                val sharedPrevious = shared.last?.takeIf { shared.lastAnchored == anchored }
                val vacatedAt = shared.vacatedAtNanos
                val first = ownPrevious == null
                lastTarget = position
                lastAnchored = anchored
                shared.last = position
                shared.lastAnchored = anchored
                // Claim the slot: while this node lives there is no vacancy.
                shared.vacatedAtNanos = 0L
                if (!enabled) return@onPlaced
                // A cross-parent handoff: this node just appeared and the
                // sibling it replaces vacated within the last frame or two
                // (see [SharedPlacement.vacatedAtNanos]). It slides in from
                // wherever that sibling stood, however far along the row.
                val handoff = first && sharedPrevious != null && vacatedAt != 0L &&
                    System.nanoTime() - vacatedAt <= SharedPlacementMaxAgeNanos
                // Where this placement travelled *from*: the vacated slot for a
                // handoff, else this node's own previous spot for an ordinary
                // reflow. A fresh node with neither has nowhere to come from.
                val previous = when {
                    handoff -> sharedPrevious
                    !first -> ownPrevious
                    else -> null
                } ?: return@onPlaced
                if (previous == position) return@onPlaced
                val raw = previous - position
                // A handoff travels along the bar and nowhere else, so only the
                // horizontal part of it is real. The two nodes are not the same
                // shape — the toolbar's pinned emoji is a 30dp circle with its
                // name under it, the strip's is a bare 38dp one — so their tops
                // sit a few pixels apart and the vertical rule below read that
                // as "the row moved" and snapped. Which is why the icon stopped
                // sliding across the moment toolbar labels were switched on.
                val delta = if (handoff) IntOffset(raw.x, 0) else raw
                // A slide along the bar never changes height; a vertical move
                // means the rows themselves shifted (a panel opened, the emoji
                // row appeared), which animating reads as lag — snap it.
                if (delta.x == 0 || kotlin.math.abs(delta.y) > ToolbarRowShiftPx) {
                    immediate = null
                    scope.launch { offset.snapTo(IntOffset.Zero) }
                    return@onPlaced
                }
                // A reflow nudge is small; a jump past the bar's own cap is a
                // layout change (a scroll, a resize), not motion. The handoff is
                // exempt — it is deliberately a long slide.
                val jump = delta.toOffset().getDistance()
                if (!handoff && (jump < 2f || jump > placementCap(true, anchorCoords))) {
                    immediate = null
                    scope.launch { offset.snapTo(IntOffset.Zero) }
                    return@onPlaced
                }
                // Carry any displacement still in flight so a change that lands
                // mid-slide continues from where the icon actually is. This is
                // what keeps the drawn position continuous when a handoff is
                // followed a frame later by the layout settling to its final
                // slot: the seed offset re-anchors to the new target instead of
                // snapping the icon out to the row's edge.
                val start = delta + (immediate ?: offset.value)
                // Drawn this frame, not next; see the note in animatePlacement.
                immediate = start
                scope.launch {
                    offset.snapTo(start)
                    immediate = null
                    offset.animateTo(IntOffset.Zero, ToolbarSlideSpring)
                }
            }
            .graphicsLayer {
                val shift = immediate ?: offset.value
                translationX = shift.x.toFloat()
                translationY = shift.y.toFloat()
            }
    }

/**
 * One round tool button; the circle radius comes from the theme (0 = bare
 * icon). With [longPressLabel] set, holding the button pops the tool's name
 * above it — the toolbar shows bare icons, so this is how a user finds out
 * what one does without tapping it.
 */
@Composable
internal fun ToolCircle(
    slot: String,
    description: String,
    active: Boolean,
    modifier: Modifier = Modifier,
    longPressLabel: String? = null,
    onLongPress: (() -> Unit)? = null,
    // False when an ancestor owns the whole gesture (see DraggableTool):
    // a clickable here would sit deeper in the chain and steal the release.
    interactive: Boolean = true,
    // Inactive-icon tint override (the tool's accent colour). Null keeps the
    // theme's toolbar-icon colour; the active state always wins over this.
    tint: Color? = null,
    // The gradient to paint the inactive icon with instead of [tint], when the
    // gradient tool colours are on. Same precedence: active still wins.
    tintBrush: Brush? = null,
    // When set, the tool's name is drawn under the icon (toolbar labels). The
    // long-press tooltip is then redundant and suppressed.
    label: String? = null,
    labelSizeSp: Int = 9,
    // Draws this button as a drop preview — washed out, outlined, "will go
    // here" — while keeping the footprint of the real thing. Same look as
    // [GhostToolCircle], but it follows the label setting, and a bare circle
    // standing in for a labelled button is a whole row's worth of height
    // missing from the preview.
    ghost: Boolean = false,
    // Bar buttons stretch to the theme's tool width (38 = today's circle);
    // panel headers and grids keep the fixed circle regardless of the setting.
    wide: Boolean = false,
    // The physical key that opens this tool, drawn as a badge over the bottom of
    // the button. An overlay, never an extra child: the badge appears the moment
    // the picker arms, and a button that grew a row then would shove the whole
    // keyboard down under the user's hands.
    hint: String? = null,
    // A smaller button for a switch that lives beside something else (the
    // suggestion strip) rather than on the toolbar. Bare-icon form only: a
    // labelled button already has its own, shorter box.
    compact: Boolean = false,
    onClick: () -> Unit,
) {
    val kb = LocalKbTheme.current
    val shape = kb.toolShape()
    val background = when {
        ghost -> kb.toolCircleActive.copy(alpha = 0.22f)
        active -> kb.toolCircleActive
        kb.toolRadiusDp > 0 -> kb.toolCircle
        else -> Color.Transparent
    }
    val outline = when {
        // The ghost's own dashed-out look wins: it is saying "will go here",
        // not wearing the theme's outline.
        ghost -> Modifier.border(1.dp, kb.toolbarIcon.copy(alpha = 0.35f), shape)
        kb.toolBorder != null && kb.toolBorderWidthDp > 0f ->
            Modifier.border(kb.toolBorderWidthDp.dp, kb.toolBorder, shape)
        else -> Modifier
    }
    var showLabel by remember { mutableStateOf(false) }
    val feedback = LocalKeyPressFeedback.current
    val click = if (!interactive) {
        Modifier
    } else if (longPressLabel == null && onLongPress == null) {
        Modifier.clickable(onClick = onClick)
    } else {
        Modifier.pointerInput(longPressLabel, onLongPress != null) {
            detectTapGestures(
                onTap = { onClick() },
                onLongPress = {
                    feedback()
                    if (onLongPress != null) onLongPress() else showLabel = true
                },
            )
        }
    }
    val fullTint = if (active) kb.toolCircleActiveIcon else (tint ?: kb.toolbarIcon)
    val iconTint = if (ghost) fullTint.copy(alpha = 0.45f) else fullTint
    val iconBrush = if (active || ghost) null else tintBrush
    if (label != null) {
        // Labelled variant (toolbar labels): icon in its circle, name beneath.
        Column(
            modifier = modifier.then(click),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center,
        ) {
            Box(
                modifier = Modifier
                    .size(
                        width = (if (wide) (kb.toolWidthDp - 8).coerceAtLeast(30) else 30).dp,
                        height = 30.dp,
                    )
                    .clip(shape)
                    .background(background, shape)
                    .then(outline),
                contentAlignment = Alignment.Center,
            ) {
                SlotIcon(
                    slot,
                    contentDescription = description,
                    modifier = Modifier
                        // Not [ToolIconSize]: this box is 30 dp, not 38, because
                        // the name underneath has to fit in the same toolbar
                        // height. A 22 dp glyph lifted clear of the hint badge
                        // would leave the box through the top. The name grew
                        // instead — which is what is read here anyway.
                        .size(20.dp)
                        // Lifted, not shrunk, so the badge below has room inside
                        // a box whose size must not change (see [HintBadge]).
                        .offset(y = if (hint != null) -(HintBadgeHeight / 2) else 0.dp),
                    tint = iconTint,
                    brush = iconBrush,
                )
                // Under the icon, over the name: the badge is temporary and the
                // name is what the labels setting was turned on for, so the
                // badge borrows the name's top edge rather than the icon's face.
                if (hint != null) {
                    HintBadge(hint, modifier = Modifier.align(Alignment.BottomCenter))
                }
            }
            Text(
                label,
                fontSize = labelSizeSp.sp,
                lineHeight = (labelSizeSp + 1).sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = if (ghost) fullTint.copy(alpha = 0.5f) else fullTint,
                modifier = Modifier.padding(top = 1.dp, start = 1.dp, end = 1.dp),
            )
        }
        return
    }
    val side = if (compact) CompactToolSide else 38
    Box(
        modifier = modifier
            .size(width = (if (wide && !compact) kb.toolWidthDp else side).dp, height = side.dp)
            .clip(shape)
            .background(background, shape)
            .then(outline)
            .then(click),
        contentAlignment = Alignment.Center,
    ) {
        SlotIcon(
            slot,
            contentDescription = description,
            modifier = Modifier
                .size(if (compact) CompactToolIconSize else ToolIconSize)
                // The icon steps up by half the badge's height so the badge sits
                // under it rather than across it. The button's own 38 dp box is
                // untouched, so nothing on the bar moves.
                .offset(y = if (hint != null) -(HintBadgeHeight / 2) else 0.dp),
            tint = iconTint,
            brush = iconBrush,
        )
        if (hint != null) {
            HintBadge(hint, modifier = Modifier.align(Alignment.BottomCenter))
        }
        if (showLabel && longPressLabel != null) {
            LaunchedEffect(Unit) {
                delay(1200)
                showLabel = false
            }
            Popup(
                popupPositionProvider = rememberAboveAnchorPopup(),
                onDismissRequest = { showLabel = false },
            ) {
                Surface(
                    shape = kb.popupShape(),
                    color = kb.popup,
                    border = kb.popupSurfaceBorder(),
                    shadowElevation = elevationFor(kb.popupShapeKind, 6.dp),
                ) {
                    Text(
                        longPressLabel,
                        color = kb.popupText,
                        fontSize = 12.sp,
                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                    )
                }
            }
        }
    }
}

/**
 * The drop-preview stand-in rendered at the slot a dragged tool would land
 * in: same footprint as [ToolCircle], drawn washed out so it reads as
 * "will go here" rather than "is here". Keyed placement animation makes it
 * slide from slot to slot as the finger moves.
 */
@Composable
private fun GhostToolCircle(
    tool: ToolbarTool,
    modifier: Modifier = Modifier,
    wide: Boolean = false,
) {
    val kb = LocalKbTheme.current
    val shape = kb.toolShape()
    Box(
        modifier = modifier
            .size(width = (if (wide) kb.toolWidthDp else 38).dp, height = 38.dp)
            .background(kb.toolCircleActive.copy(alpha = 0.22f), shape)
            .border(1.dp, kb.toolbarIcon.copy(alpha = 0.35f), shape),
        contentAlignment = Alignment.Center,
    ) {
        SlotIcon(
            IconSlots.forTool(tool),
            contentDescription = null,
            modifier = Modifier.size(ToolIconSize),
            tint = kb.toolbarIcon.copy(alpha = 0.45f),
        )
    }
}

/**
 * The glyph inside a tool button, on the bar and in the toolbox alike.
 *
 * It was 20 dp in a 38 dp button, which left the icon floating in a lot of
 * empty circle: at a glance a toolbox page read as a field of identical
 * bubbles, and picking one out meant looking at each in turn rather than
 * seeing the shape. 22 dp still clears the button's edge — and the hint badge
 * that overlays its bottom — while giving the glyph enough of the circle to
 * be recognised on the way past.
 */
private val ToolIconSize = 22.dp

/** A [ToolCircle] drawn `compact`: the box's side in dp, and the glyph in it. */
private const val CompactToolSide = 30
private val CompactToolIconSize = 18.dp

/**
 * The tools on a row of their own, above the suggestion strip — the row
 * [ToolbarPlacement.ON_DEMAND_ROW] and [ToolbarPlacement.ALWAYS_ROW] add.
 *
 * A plain [Row] of the same height as the strip wrapping the same [ToolbarRow]
 * the strip hosts in the shared arrangement, so the two placements draw the same
 * tools, the same widths, and the same drag behaviour. No fade: nothing is being
 * exchanged here — the row is either there or it is not, and its own appearance
 * is the animation.
 *
 * The row mirrors for RTL scripts only when the user asked it to
 * ([toolbarReadsRtl]) — the row holds nothing but buttons, so there is no
 * reading order for the script to dictate, and with the setting off it stays
 * exactly where it was in the last language. The drag hit-testing follows the
 * same answer (see [ToolbarRow]).
 */
@Composable
private fun ToolsRow(
    state: KeyboardUiState,
    onPanelChange: (PanelMode) -> Unit,
    onToolTap: (ToolbarTool) -> Unit,
    drag: ToolDragController,
) {
    val direction = if (toolbarReadsRtl(state)) LayoutDirection.Rtl else LayoutDirection.Ltr
    CompositionLocalProvider(LocalLayoutDirection provides direction) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(topBarHeight(state.settings))
                .toolbarPadding(state.settings),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            ToolbarRow(state, onPanelChange, onToolTap, drag)
        }
    }
}

/**
 * The toolbar itself: fixed toolbox launcher, then the user's tools —
 * spread across the free space when the greedy setting is on, packed to
 * the left otherwise.
 */
@Composable
private fun RowScope.ToolbarRow(
    state: KeyboardUiState,
    onPanelChange: (PanelMode) -> Unit,
    onToolTap: (ToolbarTool) -> Unit,
    drag: ToolDragController,
    // Opacity for the tools while the toolbar fades in. On an in-place
    // strip→toolbar flip the emoji is exempt — it hands its position across and
    // slides instead of fading — so this rides the toolbox launcher and pinned
    // tools only. On a fresh mount nothing slides, so [fadeEmoji] folds the
    // emoji into the same fade and the whole bar comes up together.
    contentAlpha: () -> Float = { 1f },
    fadeEmoji: Boolean = false,
) {
    val customizing = state.panel == PanelMode.TOOLBOX
    // Scrolling wants the tools at their natural width, so it overrides the
    // greedy even-spread (which would keep them all on screen and shrinking).
    val scrollable = state.settings.toolbarBehavior.scrollable
    val greedy = state.settings.toolbarBehavior.greedy && !scrollable
    val labels = state.settings.toolbarLabels
    val labelSize = state.settings.toolbarLabelSize
    val motion = !state.settings.reduceMotion
    // Enter and exit share one duration so the back chevron takes the same
    // time to leave as it took to arrive; a shorter exit made closing a panel
    // finish ahead of the icons still sliding back into the freed slot.
    val enterMs = if (motion) ToolbarMotionMs else 0
    // The tools are always held in storage order; whether they READ
    // right-to-left is a layout direction on the sub-row that draws them
    // ([toolsDirection] below). Keeping the two apart is what fixes the RTL
    // reorder: the enclosing bar is already flipped for the suggestion strip's
    // sake, so a mirrored list flipped it a second time and every drag landed
    // on the slot opposite the finger (issue #79).
    val tools = visibleToolbarTools(state)
    // The D-pad ring reaches the bar as well as the keys: without it a remote
    // could type but never open a tool, change a setting or start voice input.
    // Each button registers where it is while it is drawn (see [dpadTarget]).
    val dpadRing = LocalDpadRing.current
    drag.visibleTools = tools
    val toolsRtl = toolbarReadsRtl(state)
    val toolsDirection = if (toolsRtl) LayoutDirection.Rtl else LayoutDirection.Ltr
    drag.barRtl = toolsRtl
    // The tools hug the toolbox launcher, which sits at the enclosing bar's
    // start. When the sub-row runs the other way that end is its own end, so
    // the packing spacer has to lead instead of trail.
    val toolsPackAtEnd = toolsDirection != LocalLayoutDirection.current
    // While a drag is live the bar previews the drop by MOVING the dragged
    // tool's own cell to the slot under the finger and drawing it as a ghost
    // there. Not by inserting a separate ghost entry: the dragged cell has to
    // stay composed (it hosts the pointer handler driving the drag — dropping
    // it disposed that handler the instant the hold registered, which sent
    // every long-press down the "open settings" path instead), so an inserted
    // ghost made the row one cell longer than the row the drop commits to.
    // Every icon between the tool's old slot and the new one then previewed a
    // slot to the side of where it actually ended up.
    //
    // A keyed move is enough here. Row re-measures and re-places its children
    // on a pure reorder — unlike FlowRow, which is why the toolbox grid has to
    // re-key its ghost per slot instead (see [ToolboxGrid]).
    val dragTool = drag.dragging
    val ghostSlot = drag.barSlot
    val displayTools: List<ToolbarTool> = if (dragTool != null && ghostSlot != null) {
        (tools - dragTool).toMutableList().apply {
            add(ghostSlot.coerceIn(0, size), dragTool)
        }
    } else {
        tools
    }
    // Slot 0 is the toolbox launcher, so a tool's badge is its place in `tools`
    // plus one. Dropped entirely during a drag: the dragged cell may have come
    // from the toolbox and not be in `tools` at all, and a badge indexed off the
    // preview order would label cells with their neighbours' keys.
    val hints = if (dragTool == null) armedHintPlan(state) else null
    val panelOpen = state.panel != PanelMode.NONE

    // In greedy mode every button — chevron, toolbox and tools alike — is an
    // equal-weight cell, so the whole bar is one evenly spaced grid instead
    // of fixed buttons on the left with the tools spread over the leftover.
    val leading: @Composable (Modifier) -> Unit = { cell ->
        // With any tool panel open, one tap on the chevron returns to the keys.
        // The transition state keeps the cell composed until the exit
        // animation finishes, then drops it entirely so a weighted cell
        // doesn't linger as an invisible gap.
        val chevronVisible = remember { MutableTransitionState(false) }
        chevronVisible.targetState = panelOpen
        if (chevronVisible.currentState || chevronVisible.targetState) {
            AnimatedVisibility(
                visibleState = chevronVisible,
                modifier = if (greedy) cell else Modifier,
                // Reduce motion collapses the durations to zero rather than
                // dropping AnimatedVisibility: the transition state still has
                // to run its lifecycle or the weighted cell never releases.
                // Both branches animate paint only, never measured size. The
                // greedy one already did (its slot is weighted, so the chevron
                // scales inside a cell that appears at full width); the other
                // used to expand/shrink its width, which re-measured the row
                // on every frame and made the pinned icons chase a target that
                // moved under them for the whole transition. See the matching
                // note on the suggestions chevron in TopBar.
                enter = if (greedy) {
                    // The weighted slot can't grow, so the chevron itself
                    // scales and fades into it.
                    scaleIn(tween(enterMs)) + fadeIn(tween(enterMs))
                } else {
                    fadeIn(tween(enterMs))
                },
                // Instant, for the same reason as the suggestions chevron: an
                // exit transition holds this cell's width (its whole weighted
                // slot, in greedy mode) until it finishes, so closing a tool
                // played the chevron out, paused, and only then let the icons
                // move — which is why closing felt broken while opening, where
                // the slot is claimed on the first frame, felt fine. Dropping
                // it at once makes the icons' spring the closing animation.
                exit = ExitTransition.None,
            ) {
                Box(
                    if (greedy) Modifier.fillMaxSize() else cell,
                    contentAlignment = Alignment.Center,
                ) {
                    ToolCircle(
                        slot = IconSlots.CHROME_PANEL_BACK,
                        description = stringResource(R.string.ime_panel_back_desc),
                        active = false,
                        longPressLabel = stringResource(R.string.ime_panel_back_desc),
                        modifier = if (dpadRing) {
                            Modifier.dpadTarget(BarBackRingId) { onPanelChange(state.panel) }
                        } else {
                            Modifier
                        },
                        wide = true,
                    ) { onPanelChange(state.panel) }
                }
            }
        }
        Box(cell, contentAlignment = Alignment.Center) {
            ToolCircle(
                slot = IconSlots.CHROME_TOOLBOX,
                description = stringResource(R.string.ime_toolbox_desc),
                active = customizing,
                // The launcher wears its name alongside the tools it sits with:
                // with labels on, one bare icon at the head of a row of named
                // buttons reads as a button that forgot its own label, and it
                // sits a few pixels off the others' baseline as well.
                label = stringResource(R.string.ime_toolbox_desc).takeIf { labels },
                labelSizeSp = labelSize,
                modifier = Modifier
                    .then(
                        if (dpadRing) {
                            Modifier.dpadTarget(BarToolboxRingId) {
                                onPanelChange(PanelMode.TOOLBOX)
                            }
                        } else {
                            Modifier
                        },
                    )
                    // The width a pinned button actually gets, published for the
                    // strip's emoji shortcut to match (see [pinnedToolWidthPx]).
                    .onSizeChanged { drag.pinnedToolWidthPx = it.width }
                    .animatePlacement(enabled = motion, inRow = true) { drag.bodyCoords }
                    // Under the slide, never over it: a fade renders offscreen
                    // and clips to its own node, so a stationary fade around a
                    // displaced icon cuts a slice off it. See the tool cells.
                    .graphicsLayer { alpha = contentAlpha() },
                // The tooltip is what the labels setting replaces; the labelled
                // variant never draws it anyway.
                longPressLabel = stringResource(R.string.ime_toolbox_desc).takeUnless { labels },
                wide = true,
                hint = hints?.label(HintSurface.TOOLBAR, 0),
            ) { onPanelChange(PanelMode.TOOLBOX) }
        }
    }
    val toolCells: @Composable RowScope.() -> Unit = {
        for (tool in displayTools) {
            key(tool) {
                val cell = if (greedy) {
                    Modifier
                        .weight(1f)
                        .fillMaxHeight()
                } else {
                    Modifier.padding(horizontal = 3.dp)
                }
                // On an in-place flip the emoji slides and stays opaque while
                // the rest fade (see [contentAlpha]); on a fresh mount ([fadeEmoji])
                // nothing slides, so it fades in with them.
                //
                // The alpha rides the *icon*, not the cell around it. A
                // graphicsLayer below full opacity renders to an offscreen
                // buffer the size of its node, and that buffer clips — so with
                // the fade on the cell, an icon that [animatePlacement] had
                // displaced out of its cell (which happens whenever the bar
                // reflows mid-fade: a chevron claiming or releasing its slot)
                // was drawn with a slice missing and a hard vertical edge where
                // the cell ended. On the icon's own node the buffer travels
                // with it and there is nothing to clip.
                val fadeThis = tool != ToolbarTool.EMOJI || fadeEmoji
                // The Voice tool's hold menu (#173). Cell-local: it is about
                // this one cell, opens on the hold's lift and closes on a
                // pick or a tap outside, and nothing else needs to know.
                var voiceMenuOpen by remember { mutableStateOf(false) }
                Box(cell, contentAlignment = Alignment.Center) {
                    // Drag is always live: hold-and-drag reorders the bar
                    // (or unpins into an open toolbox); a hold that never
                    // moves opens the tool's settings page instead — or,
                    // on the caret tools, repeats the move for as long as
                    // the finger is down. Only here: the toolbox keeps the
                    // hold-for-settings gesture for every tool, which is
                    // what makes those pages still reachable.
                    DraggableTool(
                        tool,
                        fromToolbar = true,
                        enabled = true,
                        drag = drag,
                        onTap = { onToolTap(tool) },
                        holdRepeatMs = holdRepeatMs(tool, state),
                        holdAction = holdActionFor(tool, fromToolbar = true, state = state),
                        dragEnabled = state.settings.toolbarBehavior.dragToRearrange,
                        holdArms = holdArmsSelection(tool, fromToolbar = true, state = state),
                        // Not while the toolbox is open (#320): the trackpad
                        // took the toolbox's place under the held finger, so a
                        // drag back to the grid found no grid to land on and
                        // the tool could never leave the bar. Customizing, a
                        // hold is for arranging, the way it is in the grid.
                        holdPanel = !customizing &&
                            holdOpensTrackpad(tool, fromToolbar = true, state = state),
                        holdMenu = holdPicksVoiceMode(tool, fromToolbar = true, state = state),
                        onHoldMenu = { voiceMenuOpen = true },
                    ) { dragModifier ->
                        ToolCircle(
                            slot = IconSlots.forTool(tool),
                            description = toolLabel(tool),
                            active = toolActive(tool, state),
                            label = if (labels) toolLabel(tool) else null,
                            labelSizeSp = labelSize,
                            // This cell IS the drop preview while it is the one
                            // being dragged: it has moved to the slot under the
                            // finger and draws washed out there, so the row on
                            // screen is exactly the row the drop commits. The
                            // solid icon to look at is the floating one under
                            // the finger.
                            ghost = tool == dragTool,
                            wide = true,
                            hint = hints?.label(HintSurface.TOOLBAR, tools.indexOf(tool) + 1),
                            // The icon itself animates, anchored at the
                            // keyboard body: cells are weighted so their
                            // widths snap, and only body-relative tracking
                            // sees the true on-screen motion.
                            // The emoji tool also exists on the
                            // suggestion strip, so it hands its position
                            // across that swap instead of tracking only
                            // its own node.
                            modifier = dragModifier
                                .then(
                                    if (dpadRing) {
                                        Modifier.dpadTarget(tool) { onToolTap(tool) }
                                    } else {
                                        Modifier
                                    },
                                )
                                .then(
                                    if (tool == ToolbarTool.EMOJI) {
                                        Modifier.animateSharedPlacement(
                                            drag.emojiPlacement,
                                            enabled = motion,
                                        ) { drag.bodyCoords }
                                    } else {
                                        Modifier.animatePlacement(
                                            enabled = motion,
                                            inRow = true,
                                        ) { drag.bodyCoords }
                                    },
                                )
                                // Inside the slide, so the fade's buffer travels
                                // with the icon rather than clipping it.
                                .then(
                                    if (fadeThis) {
                                        Modifier.graphicsLayer { alpha = contentAlpha() }
                                    } else {
                                        Modifier
                                    },
                                ),
                            interactive = false,
                        ) {}
                    }
                    if (voiceMenuOpen) {
                        StripMenuScrim(onDismiss = { voiceMenuOpen = false })
                        VoiceModeMenu(
                            current = state.settings.voiceBar.typingMode,
                            onDismiss = { voiceMenuOpen = false },
                            onPick = { mode ->
                                voiceMenuOpen = false
                                drag.onVoiceModePick(mode)
                            },
                        )
                    }
                }
            }
        }
    }
    if (greedy) {
        Row(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            leading(
                Modifier
                    .weight(1f)
                    .fillMaxHeight()
            )
            // The tools sub-row carries a weight equal to its cell count, so
            // its cells end up exactly as wide as the leading buttons' cells.
            // It still exists (zero tools aside) as the drag-drop target.
            //
            // The direction is provided around the row rather than on it: the
            // node takes its own layout direction from the composition local,
            // while where the row sits inside the bar still follows the bar.
            CompositionLocalProvider(LocalLayoutDirection provides toolsDirection) {
                Row(
                    modifier = Modifier
                        .weight(displayTools.size.coerceAtLeast(1).toFloat())
                        .fillMaxHeight()
                        .onGloballyPositioned { drag.toolbarBounds = it.boundsInRoot() },
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    toolCells()
                }
            }
        }
    } else {
        leading(Modifier.padding(horizontal = 3.dp))
        CompositionLocalProvider(LocalLayoutDirection provides toolsDirection) {
            Row(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxHeight()
                    // Weighted so it claims exactly the free width; the scroll
                    // then lets the pinned tools overflow that width instead of
                    // packing to fit. Reordering by drag still works — the
                    // toolbox is the simpler place to rearrange a long,
                    // scrolling bar.
                    .then(
                        if (scrollable) {
                            Modifier.horizontalScroll(rememberScrollState())
                        } else {
                            Modifier
                        },
                    )
                    .onGloballyPositioned { drag.toolbarBounds = it.boundsInRoot() },
                verticalAlignment = Alignment.CenterVertically,
            ) {
                // A weighted spacer can't live inside a horizontal scroll
                // (infinite width); packed-to-fit mode still needs it to hold
                // the tools against the launcher's end of the bar.
                if (!scrollable && toolsPackAtEnd) Spacer(modifier = Modifier.weight(1f))
                toolCells()
                if (!scrollable && !toolsPackAtEnd) Spacer(modifier = Modifier.weight(1f))
            }
        }
    }
    if (state.incognitoOn) {
        SlotIcon(
            IconSlots.CHROME_INCOGNITO,
            contentDescription = stringResource(R.string.ime_incognito_on_desc),
            modifier = Modifier
                .padding(end = 6.dp)
                .size(16.dp),
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
        )
    }
    // Same badge for power saving, whichever source switched it on: the
    // dropped animations, haptics and sounds otherwise read as the keyboard
    // being broken, since the trigger (the system's battery saver, a low
    // battery) is nowhere near the keyboard.
    if (state.powerSavingOn) {
        SlotIcon(
            IconSlots.CHROME_POWER_SAVING,
            contentDescription = stringResource(R.string.ime_power_saving_on_desc),
            modifier = Modifier
                .padding(end = 6.dp)
                .size(16.dp),
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
        )
    }
}

/**
 * A committed toolbox order the grid draws before storage has echoed it back.
 *
 * [before] is the visible list as it stood when the drop happened: the preview
 * is dropped the moment that list changes, which is the settings arriving —
 * with this order, or with another one that has better claim to the screen.
 */
private data class ToolboxOrderPreview(
    val order: List<ToolbarTool>,
    val before: List<ToolbarTool>,
) {
    /** Where [tool] sits in the committed order; unranked tools keep the tail. */
    fun rank(tool: ToolbarTool): Int =
        order.indexOf(tool).takeIf { it >= 0 } ?: Int.MAX_VALUE
}

/**
 * Gboard-style toolbox: every tool that is not on the toolbar, shown in a
 * labeled grid ordered by [KeyboardSettings.toolboxOrder] (most-used-first
 * until the user rearranges it). Tap to use a tool in place; hold and drag
 * it up onto the toolbar to pin it, or around the grid to reorder. Toolbar
 * tools drag down here to unpin — at the spot they're dropped.
 *
 * Two shapes, chosen by [ToolboxSettings.layout]: round icons with a caption,
 * or [ToolPill] rows. Either can scroll as one long grid or break into swiped
 * pages; that is [ToolboxSettings.paginate], and the cells are the same
 * [ToolboxGrid] either way.
 */
@Composable
private fun ToolboxPanel(
    state: KeyboardUiState,
    onToolTap: (ToolbarTool) -> Unit,
    onHintDismiss: () -> Unit,
    drag: ToolDragController,
) {
    val height = keyRowsHeight(state)
    // First open: always show the drag hint. After it was dismissed once,
    // resurface it only rarely as a reminder. Rolled once per panel open.
    val rareReminder = remember { Random.nextFloat() < 0.03f }
    var hintVisible by remember(state.settings.toolboxHintDismissed) {
        mutableStateOf(!state.settings.toolboxHintDismissed || rareReminder)
    }
    // The registered geometry outlives the panel unless cleared, and a
    // stale viewport would let a later drag "drop on the toolbox" with the
    // panel long gone.
    DisposableEffect(drag) {
        onDispose {
            drag.toolboxViewport = null
            drag.toolboxContentCoords = null
            drag.toolboxPageStart = 0
            drag.toolboxPageLength = Int.MAX_VALUE
        }
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .height(height)
            .onGloballyPositioned { drag.toolboxViewport = it.boundsInRoot() },
    ) {
        // A slim header carrying the drag hint until it's dismissed. Resetting
        // the pinned tools now lives in Settings → Appearance ("Reset pinned
        // tools"), so the toolbox no longer shows its own reset control.
        if (hintVisible) {
            val activeMode = state.settings.keyboardModes
                .firstOrNull { it.id == state.activeModeId }
                ?.takeIf { state.settings.modeToolOrderEdits && it.ownsToolOrder }
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 24.dp, end = 8.dp, top = 4.dp, bottom = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                // With a mode on, the arrangement being edited is that mode's
                // own — say so, or the same keyboard looking different in the
                // next app reads as the drag being lost.
                val dragHint = stringResource(R.string.ime_toolbox_hint_drag)
                Text(
                    if (activeMode != null) {
                        stringResource(R.string.ime_toolbox_hint_mode, activeMode.name) +
                            " " + dragHint
                    } else {
                        dragHint
                    },
                    fontSize = 12.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.weight(1f),
                )
                IconButton(
                    onClick = {
                        hintVisible = false
                        onHintDismiss()
                    },
                    modifier = Modifier.size(28.dp),
                ) {
                    Icon(
                        Icons.Outlined.Close,
                        contentDescription = stringResource(R.string.ime_toolbox_hint_dismiss_desc),
                        modifier = Modifier.size(16.dp),
                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }
        }
        // Toolbox order is a complete ranking over every tool; the grid
        // shows the available subset in that order.
        val settledTools = visibleToolboxTools(state)
        // The order the last drop committed, drawn until the settings flow
        // comes back with it.
        //
        // The commit is a suspend hop through DataStore, so for a frame or two
        // after the finger lifts the only order this composable can see is the
        // PRE-drag one: the tool snapped back to where it started, and then the
        // arriving settings moved it again. Two moves for one drop, the first
        // of them backwards, and the second landing as a rebuild of every cell
        // (see [ToolboxGrid]'s keys) — which is the jerk at the end of a drag.
        // Drawing the committed order at once makes the drop the only move.
        var preview by remember { mutableStateOf<ToolboxOrderPreview?>(null) }
        drag.onOrderPreview = { order -> preview = ToolboxOrderPreview(order, settledTools) }
        val available = preview
            ?.let { held -> settledTools.sortedBy { tool -> held.rank(tool) } }
            ?: settledTools
        // Let go of it the moment the settings say anything new, whether that
        // is this drop arriving or something else entirely (a mode switch, a
        // reset from the settings app) — the preview must never outlive the
        // list it was an early look at.
        LaunchedEffect(settledTools) {
            if (preview?.before != settledTools) preview = null
        }
        val toolbox = state.settings.toolbox
        val pills = toolbox.layout == ToolboxLayout.PILLS
        // The two layouts count their columns separately: a pill needs room for
        // a name, so its comfortable width is nothing like an icon's.
        val columns = if (pills) {
            toolbox.pillColumns.coerceAtLeast(1)
        } else {
            state.settings.toolboxColumns.coerceAtLeast(1)
        }
        drag.toolboxTools = available
        drag.toolboxOrder = state.settings.toolboxOrder
        drag.toolboxHidden = toolbox.hiddenTools
        drag.toolboxColumns = columns
        // The grid takes the ambient direction (it has no script of its own to
        // follow). The service pins the board to LTR (#336), but whatever the
        // ambient is, the cell maths has to mirror with it — the grid half of
        // issue #79.
        drag.boxRtl = LocalLayoutDirection.current == LayoutDirection.Rtl
        // Drop preview: the dragged tool LEAVES the list and a ghost marks the
        // slot it would land in. That is one hole, not two, and — the reason
        // it has to be done this way — it is a removal plus an insertion.
        //
        // A permutation does not work here. Keeping the tool in the list and
        // moving it to the target slot reads identically in the composition,
        // but Compose moves the composition groups without re-placing the
        // laid-out children, so the grid never reflowed: verified on device,
        // where a whole drag produced exactly one layout pass and every cell
        // kept its original x. The old code only appeared to shuffle because
        // inserting a ghost was a structural change.
        //
        // Removing the tool means its cell is disposed mid-gesture, which is
        // why the drag is no longer hosted there — see the pointerInput on the
        // grid below. The cells are pure visuals now.
        val dragTool = drag.dragging
        val boxSlot = drag.boxSlot
        // Identifies the settled order, and changes only when it does — never
        // during a drag, where the settings are untouched and `available` is
        // the same list frame after frame. See [ToolboxGrid]'s cell keys for
        // what it is for.
        val orderKey = available.hashCode()
        val display: List<ToolbarTool?> = if (dragTool != null && boxSlot != null) {
            // `available - dragTool` is a no-op when the drag came from the
            // toolbar, so both origins land on one ghost and one hole.
            val without = available - dragTool
            ArrayList<ToolbarTool?>(without).apply {
                add(boxSlot.coerceIn(0, without.size), null)
            }
        } else {
            available
        }
        if (display.isEmpty()) {
            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Text(
                    stringResource(R.string.ime_toolbox_empty),
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
            return@Column
        }
        // Indexed against `available`, never `display`: the drop preview inserts
        // a null ghost slot into `display`, which would shift every index past it
        // and open the wrong tool. The ring is hidden mid-drag anyway (below),
        // but the count published here must match what Enter will resolve.
        PanelFocusTarget(
            panel = PanelMode.TOOLBOX,
            count = available.size,
            columns = columns,
            onActivate = { index -> available.getOrNull(index)?.let(onToolTap) },
        )
        val focusedTool = state.focusedIndex().takeIf { drag.dragging == null }
        if (!toolbox.paginate) {
            // One long grid the user scrolls: every cell is at its absolute
            // slot, so the drop math needs no page offset.
            drag.toolboxPageStart = 0
            drag.toolboxPageLength = Int.MAX_VALUE
            ToolboxGrid(
                state = state,
                drag = drag,
                display = display,
                pageStart = 0,
                columns = columns,
                pills = pills,
                dragTool = dragTool,
                orderKey = orderKey,
                focusedSlot = focusedTool,
                registerGeometry = true,
                onToolTap = onToolTap,
            )
            return@Column
        }
        // Paginated: fixed pages to swipe through instead of a scroll. The
        // ghost takes a slot like anything else, so a drop preview near a page
        // boundary pushes the last tool onto the next page — which is what the
        // drop itself would do, so the preview stays honest.
        val pageSize = toolbox.pageSize.coerceIn(ToolboxPageSizeRange)
        val pageCount = toolboxPageCount(display.size, pageSize)
        val pager = rememberPagerState(pageCount = { pageCount })
        HorizontalPager(
            state = pager,
            modifier = Modifier.weight(1f),
            // A page is cheap to build, but building the ones nobody has
            // swiped towards is still work the first frame doesn't need.
            beyondViewportPageCount = 0,
        ) { page ->
            // Only the page in front publishes to the drag controller: its
            // neighbours stay composed through a swipe, and two pages claiming
            // the drop geometry would race over one set of coordinates.
            val current = page == pager.currentPage
            if (current) {
                drag.toolboxPageStart = page * pageSize
                drag.toolboxPageLength = pageSize
            }
            ToolboxGrid(
                state = state,
                drag = drag,
                display = toolboxPage(display, page, pageSize),
                pageStart = page * pageSize,
                columns = columns,
                pills = pills,
                dragTool = dragTool,
                orderKey = orderKey,
                focusedSlot = focusedTool.takeIf { current },
                registerGeometry = current,
                onToolTap = onToolTap,
            )
        }
        PageDots(count = pageCount, current = pager.currentPage)
        // The hardware focus ring walks the whole toolbox, so following it here
        // means turning to the page it walked onto.
        LaunchedEffect(focusedTool, pageSize, pageCount) {
            val index = focusedTool ?: return@LaunchedEffect
            val target = (index / pageSize).coerceIn(0, pageCount - 1)
            if (target != pager.currentPage) pager.animateScrollToPage(target)
        }
    }
}

/**
 * One screenful of toolbox cells — the whole grid when the toolbox scrolls,
 * a single page when it paginates — plus the one gesture handler that owns
 * every cell in it.
 *
 * The handler is hoisted above the cells rather than sitting on each one, and
 * that is what lets a cell be disposed mid-drag: the handler outlives any cell,
 * so the dragged tool can leave the list and the rest can close up behind it.
 * One FlowRow, so a part-full last line still lines up with the ones above it.
 */
@OptIn(ExperimentalLayoutApi::class)
@Composable
private fun ToolboxGrid(
    state: KeyboardUiState,
    drag: ToolDragController,
    /** This page's cells: tools, with a null where the drop ghost goes. */
    display: List<ToolbarTool?>,
    /** Absolute slot of this page's first cell; 0 for the scrolling toolbox. */
    pageStart: Int,
    columns: Int,
    pills: Boolean,
    dragTool: ToolbarTool?,
    /** Identifies the settled toolbox order; see the cell keys below. */
    orderKey: Int,
    /** Absolute slot the hardware focus ring is on, or null. */
    focusedSlot: Int?,
    /** Whether this grid is the one a drop should be measured against. */
    registerGeometry: Boolean,
    onToolTap: (ToolbarTool) -> Unit,
) {
    // The placement anchor is this scrolling content column, NOT the keyboard
    // body: relative to the body every icon "moves" on every scroll frame,
    // which made each one restart its placement spring per frame (a
    // coroutine-and-relayout storm that tanked scroll fps). Relative to the
    // content, scrolling is a no-op for the animation.
    var gridCoords by remember { mutableStateOf<LayoutCoordinates?>(null) }
    var gridOrigin by remember { mutableStateOf(Offset.Zero) }
    val feedback = LocalKeyPressFeedback.current
    // Once for the grid, not once per cell: this walks the tool lists and
    // builds two maps, and a forty-cell toolbox would have done it forty times
    // for one answer. Null with no picker armed, and during a drag — a drag
    // inserts a ghost into `display`, and every slot past it would then be
    // labelled with its neighbour's key.
    val hints = if (dragTool == null) armedHintPlan(state) else null
    val scope = rememberCoroutineScope()
    val tapTool by rememberUpdatedState(onToolTap)
    // Read through holders, and key the handler on nothing. `display` is a
    // fresh list on every recomposition and the drop preview recomposes this
    // panel on every frame of a drag, so keying pointerInput on it would tear
    // down and restart the very gesture it is running — the same trap the
    // per-cell handler documented.
    val cellsNow by rememberUpdatedState(display)
    val columnsNow by rememberUpdatedState(columns)
    val registerNow by rememberUpdatedState(registerGeometry)
    // Through a holder for the same reason, rather than as a pointerInput key:
    // the grid's handler is keyed on nothing at all, and a settings change is
    // not a reason to be the one thing that restarts it mid-gesture.
    val toolboxRepeatNow by rememberUpdatedState(state.settings.textEditing.toolboxRepeatTools)
    val repeatMsNow by rememberUpdatedState(state.settings.textEditing.repeatMs.toLong())
    val gridScroll = rememberScrollState()
    // No lazy state to scroll by index, so scroll by row: every cell reports
    // the same size, and the drag controller already collects it.
    ScrollFocusIntoView(focusedSlot) { index ->
        val rowHeight = drag.toolboxCellSize.height
        if (rowHeight > 0f) {
            val target = (((index - pageStart) / columns) * rowHeight).coerceAtLeast(0f)
            gridScroll.animateScrollTo(target.toInt().coerceIn(0, gridScroll.maxValue))
        }
    }
    FlowRow(
        modifier = Modifier
            .verticalScroll(gridScroll)
            .onGloballyPositioned {
                gridCoords = it
                gridOrigin = it.positionInRoot()
                if (registerNow) drag.toolboxContentCoords = it
            }
            .pointerInput(Unit) {
                val dragSlop = ToolDragSlop.toPx()
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false)
                    // Which tool was grabbed is resolved once, from where the
                    // finger landed. The grid is uniform, so this is the same
                    // arithmetic the drop target uses. Nothing has moved yet at
                    // this point: a drag is not live, so the list on screen is
                    // still the plain one, ghost-free.
                    val cell = drag.toolboxCellSize
                    if (cell.width <= 0f || cell.height <= 0f) return@awaitEachGesture
                    val cols = columnsNow
                    val across = (down.position.x / cell.width).toInt()
                    if (down.position.x < 0f || across !in 0 until cols) {
                        return@awaitEachGesture
                    }
                    // Same mirror the drop target applies: cell 0 of an RTL
                    // grid is the rightmost one.
                    val col = if (drag.boxRtl) cols - 1 - across else across
                    val row = (down.position.y / cell.height).toInt()
                    val tool = cellsNow.getOrNull(row * cols + col)
                        ?: return@awaitEachGesture
                    // Root coordinates throughout: the grid reflows around the
                    // drop preview while the finger is down, and a node that
                    // moves under a still finger reports deltas of its own.
                    val downRoot = gridOrigin + down.position
                    var rootPos = downRoot
                    var longPressed = false
                    var dragged = false
                    var released = false
                    var scrolled = false
                    // Resolved with the tool, from the set as it stands now. A
                    // tool the user opted in repeats here exactly as it does on
                    // the toolbar, and gives up this grid's hold-for-settings
                    // to do it; every other tool keeps it.
                    val holdRepeatMs =
                        repeatMsNow.takeIf { tool in toolboxRepeatNow && tool in HoldRepeatCursorTools }
                    val timer = scope.launch {
                        delay(viewConfiguration.longPressTimeoutMillis)
                        feedback()
                        longPressed = true
                        // Pick-up held back until the finger travels, as on the
                        // toolbar: starting it here parked a drag ghost and the
                        // scope pill under a finger that was only holding a
                        // cell down — for its settings page, or for a repeat.
                        if (holdRepeatMs != null) {
                            while (true) {
                                tapTool(tool)
                                delay(holdRepeatMs)
                            }
                        }
                    }
                    try {
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) {
                                released = true
                                if (longPressed) change.consume()
                                break
                            }
                            rootPos = gridOrigin + change.position
                            val travel = (rootPos - downRoot).getDistance()
                            if (!longPressed) {
                                // Drift before the hold registers is a scroll,
                                // or a page swipe — hand the gesture back.
                                if (travel > viewConfiguration.touchSlop) {
                                    scrolled = true
                                    break
                                }
                            } else {
                                change.consume()
                                if (travel > dragSlop && !dragged) {
                                    dragged = true
                                    // Travel means a reorder after all, so the
                                    // tool picks itself up from here (and a
                                    // repeating one stops repeating).
                                    timer.cancel()
                                    drag.start(tool, false, rootPos)
                                }
                                // Nothing to move until the finger has travelled:
                                // no drag has been started, and drag.move would
                                // tick the drop haptic anyway.
                                if (dragged) drag.move(rootPos)
                            }
                        }
                    } finally {
                        timer.cancel()
                        when {
                            !longPressed -> {
                                drag.cancel()
                                if (released && !scrolled) tapTool(tool)
                            }
                            dragged -> drag.end()
                            // A repeating hold has already done its work, and
                            // there is nothing to drop.
                            holdRepeatMs != null -> drag.cancel()
                            // A hold that never travelled past the slop is a
                            // distinct gesture: open the tool's settings.
                            else -> {
                                drag.cancel()
                                drag.onOpenSettings(tool)
                            }
                        }
                    }
                }
            },
        maxItemsInEachRow = columns,
    ) {
        display.forEachIndexed { slot, tool ->
            // The ghost's key encodes its slot so a move is a structural
            // remove+add, not a same-key reorder. FlowRow re-measures and
            // re-places its children on a structural change, but on a pure
            // reorder it moves the composition groups while leaving every
            // laid-out child at its old position — verified on device, where
            // the grid reflowed once (the dragged tool leaving) and then
            // froze for the rest of the drag: the ghost never moved and the
            // icons never made room. Re-keying per slot forces the reflow on
            // every step. (The toolbar is a Row, which re-places on reorder,
            // so its ghost keeps one stable key.)
            // The saved order rides in the key ([orderKey]) for the same reason
            // the ghost's slot does: FlowRow re-measures and re-places on a
            // structural change and does neither on a pure keyed reorder, and
            // the order arrives from settings a frame or two AFTER the drop —
            // by which time the ghost is gone and the list is nothing but a
            // reorder. So the drop saved, and the grid went on drawing the old
            // arrangement until the panel was closed and opened again. Re-keying
            // makes that arrival structural. Stable through the drag itself
            // (settings do not change mid-gesture), so the cells still slide
            // around the ghost; a settled reorder costs one rebuild of a cell
            // each, and lands with no animation, which is right — the drag has
            // already shown the move.
            key(tool?.let { "$it@$orderKey" } ?: "box-ghost-${pageStart + slot}") {
                Box(
                    modifier = Modifier
                        .toolboxCellWidth(columns)
                        // Every cell is the same size, so whichever reported
                        // last feeds the slot math. That is an invariant the
                        // tap and drop maths depend on, not an observation:
                        // width is fixed by toolboxCellWidth and height by the
                        // label's fixed line count. Anything put in a cell that
                        // can change its height breaks hit testing for every
                        // row below it.
                        .onGloballyPositioned { drag.toolboxCellSize = it.size.toSize() },
                    contentAlignment = Alignment.Center,
                ) {
                    // Pure visuals — the grid's own pointerInput owns the
                    // gesture, so nothing here has to survive the dragged
                    // tool leaving the list.
                    val ghost = tool == null
                    // dragTool is never null when a ghost entry exists.
                    val shown = tool ?: dragTool ?: return@Box
                    // `slot` indexes this page, which holds the plain tools
                    // whenever the ring is drawn at all — focusedSlot is null
                    // for the whole of a drag, and only a drag inserts a ghost.
                    val focused = focusedSlot == pageStart + slot
                    val paint = toolAccentPaint(shown, state.settings)
                    val hint = hints?.label(HintSurface.TOOLBOX, pageStart + slot)
                    // Anchored at the scrolling content (see gridCoords), NOT
                    // the keyboard body: body-relative, every scroll frame
                    // moved every icon and restarted its spring — a per-frame
                    // coroutine storm that tanked scroll fps. Content-relative,
                    // scrolling is a no-op; reorders still slide.
                    //
                    // The cap is the grid's own step, not the toolbar's fixed
                    // one — see [toolboxSlideCap] for why the fixed one snapped
                    // every reorder the grid ever made. Read from the live cell
                    // size inside the placement pass, so it is the size the row
                    // actually got rather than one guessed from the settings.
                    val placement = Modifier
                        .animatePlacement(
                            enabled = !state.settings.reduceMotion,
                            cap = { toolboxSlideCap(columns, drag.toolboxCellSize) },
                        ) { gridCoords }
                    if (pills) {
                        ToolPill(
                            tool = shown,
                            active = toolActive(shown, state),
                            labelSize = toolboxLabelSize(state),
                            paint = paint,
                            filled = state.settings.toolbox.pillFilled,
                            ghost = ghost,
                            hint = hint,
                            modifier = placement
                                .padding(horizontal = 3.dp, vertical = 3.dp)
                                .focusRing(focused, RoundedCornerShape(pillRadius())),
                        )
                        return@Box
                    }
                    Column(
                        modifier = placement
                            .focusRing(focused, RoundedCornerShape(12.dp))
                            .padding(vertical = 10.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                    ) {
                        if (ghost) {
                            GhostToolCircle(shown)
                        } else {
                            ToolCircle(
                                slot = IconSlots.forTool(shown),
                                description = toolLabel(shown),
                                active = toolActive(shown, state),
                                interactive = false,
                                tint = paint?.color,
                                tintBrush = paint?.brush,
                                hint = hint,
                            ) {}
                        }
                        Text(
                            toolLabel(shown),
                            // The name is what the grid is actually read by —
                            // the icons are close cousins of one another and
                            // the words are not — so it carries the same
                            // weight as a suggestion chip rather than the
                            // caption size it used to have.
                            fontSize = toolboxLabelSize(state),
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                .copy(alpha = if (ghost) 0.5f else 1f),
                            textAlign = TextAlign.Center,
                            // Always two lines, never one and never three, so
                            // every cell is the same height. The grid's tap and
                            // drop maths divide a touch by one cell size to get
                            // a slot, which is only true of a uniform grid: when
                            // a long name wrapped and a short one did not, rows
                            // differed in height, the error accumulated downwards
                            // and a tap landed on the tool below — further out
                            // the further down you were, until the index ran off
                            // the end and the last tools stopped opening at all.
                            minLines = 2,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier
                                .padding(top = 4.dp, start = 2.dp, end = 2.dp)
                                .fillMaxWidth(),
                        )
                    }
                }
            }
        }
    }
}

/**
 * A toolbox cell's share of the row: the grid width divided [columns] ways,
 * rounded DOWN.
 *
 * `fillMaxWidth(1f / columns)` rounds to nearest, so for every width where the
 * remainder crosses half a pixel each cell rounded up and the row overflowed by
 * a pixel or two — and FlowRow answered by wrapping a column early. Fixed width
 * that is invisible; live-resizing a floating keyboard it was the columns
 * snapping between 4 and 3 and back for every few pixels of drag. Integer
 * division cannot overflow the row, so the count only changes when the setting
 * does.
 */
private fun Modifier.toolboxCellWidth(columns: Int): Modifier = layout { measurable, constraints ->
    val width = if (constraints.hasBoundedWidth) {
        (constraints.maxWidth / columns).coerceAtLeast(1)
    } else {
        constraints.maxWidth
    }
    val placeable = measurable.measure(constraints.copy(minWidth = width, maxWidth = width))
    layout(placeable.width, placeable.height) { placeable.place(0, 0) }
}

/**
 * The size of a tool's name under its icon in the toolbox grid, when the user
 * has not set one. [ToolboxSettings.labelSizeOr] resolves the setting against
 * the toolbar's own label size.
 */
private val ToolLabelSize = 12.5.sp

/** The caption size for this toolbox, resolving the "follow the toolbar" default. */
@Composable
private fun toolboxLabelSize(state: KeyboardUiState): TextUnit {
    val chosen = state.settings.toolbox.labelSizeSp
    return if (chosen > 0) chosen.sp else ToolLabelSize
}

/** How tall a toolbox pill is. Half of it is the radius that makes the ends round. */
private val PillHeight = 44.dp

/**
 * The tool in flight under a dragging finger: [PillHeight] tall whichever shape
 * it is wearing, and that is the point — the circle it becomes over the toolbar
 * and the pill it becomes over a pill toolbox differ in width and corner only,
 * so one box can morph between them without ever changing height.
 */
private val GhostSize = PillHeight

/** The spring the drag ghost changes shape on; one tuning for every property. */
private fun <T> ghostMorphSpring() = spring<T>(
    dampingRatio = Spring.DampingRatioNoBouncy,
    stiffness = Spring.StiffnessMedium,
)

/**
 * A pill's corner radius, from the same "Tool circle radius" setting the round
 * tool buttons use. That slider is scaled for the 38 dp circle, so it is
 * stretched onto the taller pill: at the slider's top the ends are fully round,
 * at 0 the pill is a rectangle, and everything between tracks the circles.
 */
@Composable
private fun pillRadius(): Dp {
    val toolRadius = LocalKbTheme.current.toolRadiusDp
    return (PillHeight / 2) * (toolRadius / ToolCircleRadiusMax.toFloat()).coerceIn(0f, 1f)
}

/**
 * The top of the "Tool circle radius" slider (`appearance_tool_circle_title`).
 * The circles are 38 dp, so 20 already rounds them completely.
 */
private const val ToolCircleRadiusMax = 20

/**
 * One tool as a wide row: icon, name, and — for the tools that open a panel or
 * an activity rather than acting on the spot — a chevron on the trailing edge.
 * The chevron is the whole point of the layout: at a glance, "Themes" reads as
 * somewhere to go and "Flashlight" as something that just happens.
 *
 * With [filled] on, the tool's colour becomes the pill's background and the
 * icon and label flip to whatever reads on it. That is usually white, but not
 * always — a pale accent (the flashlight's amber) takes near-black instead,
 * because a white-on-amber label is a label nobody can read. With the gradient
 * tool colours on, the fill is the gradient and the contrast is worked out
 * against its near end.
 */
@Composable
private fun ToolPill(
    tool: ToolbarTool,
    active: Boolean,
    /** Caption size, resolved by the caller from the toolbox settings. */
    labelSize: TextUnit,
    /** The tool's colour, or null when colourful tool icons are off. */
    paint: ToolPaint?,
    filled: Boolean,
    ghost: Boolean,
    modifier: Modifier = Modifier,
    /** The physical key that opens this tool; see [ToolCircle]'s own `hint`. */
    hint: String? = null,
) {
    val kb = LocalKbTheme.current
    val shape = RoundedCornerShape(pillRadius())
    // Nothing to fill a pill with when the colours are switched off.
    val fill = paint?.takeIf { filled }
    val background = when {
        ghost -> kb.toolCircleActive.copy(alpha = 0.22f)
        fill != null -> fill.color
        active -> kb.toolCircleActive
        else -> kb.toolCircle
    }
    val backgroundBrush = if (ghost) null else fill?.brush
    val content = when {
        fill != null -> maxContrastOn(fill.color)
        active -> kb.toolCircleActiveIcon
        else -> kb.toolbarIcon
    }
    // Only the icon carries the accent in the unfilled pill; the label stays
    // the theme's text colour so a wall of coloured words never happens.
    val iconTint = when {
        fill != null -> content
        active -> kb.toolCircleActiveIcon
        else -> paint?.color ?: kb.toolbarIcon
    }
    // A filled pill already wears the gradient, so its icon is flat contrast
    // colour; an unfilled one is where the gradient has somewhere to go.
    val iconBrush = if (fill != null || active || ghost) null else paint?.brush
    val fade = if (ghost) 0.45f else 1f
    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(PillHeight)
            .clip(shape)
            .then(
                if (backgroundBrush != null) Modifier.background(backgroundBrush, shape)
                else Modifier.background(background, shape),
            )
            .then(
                if (ghost) {
                    Modifier.border(1.dp, kb.toolbarIcon.copy(alpha = 0.35f), shape)
                } else {
                    Modifier
                }
            )
            .padding(start = 10.dp, end = 6.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        SlotIcon(
            IconSlots.forTool(tool),
            contentDescription = null,
            modifier = Modifier.size(ToolIconSize),
            tint = iconTint.copy(alpha = fade),
            brush = iconBrush,
        )
        Text(
            toolLabel(tool),
            fontSize = labelSize,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            color = content.copy(alpha = if (ghost) 0.5f else 1f),
            modifier = Modifier
                .weight(1f)
                .padding(start = 8.dp),
        )
        // A pill is a row, so its badge sits at the end beside the chevron
        // rather than under an icon. Same footprint either way.
        if (hint != null) HintBadge(hint, modifier = Modifier.padding(end = 4.dp))
        if (toolOpensScreen(tool)) {
            Icon(
                Icons.AutoMirrored.Outlined.KeyboardArrowRight,
                contentDescription = null,
                modifier = Modifier.size(16.dp),
                tint = content.copy(alpha = if (ghost) 0.3f else 0.6f),
            )
        }
    }
}

/**
 * Which page of the paginated toolbox is in front. Deliberately not tappable:
 * dots this small are a poor target, and the pages are one swipe apart.
 */
@Composable
private fun PageDots(count: Int, current: Int) {
    if (count <= 1) return
    val kb = LocalKbTheme.current
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 6.dp),
        horizontalArrangement = Arrangement.Center,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        repeat(count) { page ->
            val on = page == current
            Box(
                modifier = Modifier
                    .padding(horizontal = 3.dp)
                    .size(if (on) 7.dp else 5.dp)
                    .clip(CircleShape)
                    .background(
                        if (on) kb.toolCircleActiveIcon else kb.toolbarIcon.copy(alpha = 0.3f),
                        CircleShape,
                    ),
            )
        }
    }
}

/**
 * Panels that take over the whole keyboard: the toolbar (plus any emoji or
 * symbol row) hides while they're open and the panel absorbs that height.
 * The right fit for tools that want the room and never involve typing or
 * hopping to another tool mid-use — sensors, reference views, converters.
 */
private val FullBleedPanels = setOf(
    PanelMode.OCR, PanelMode.QR_SCAN, PanelMode.CALCULATOR, PanelMode.CURRENCY,
    PanelMode.UNIT_CONVERT, PanelMode.CALENDAR, PanelMode.AI,
    PanelMode.TRANSLATE, PanelMode.WEB_SEARCH, PanelMode.IMAGE_SEARCH,
    PanelMode.DICTIONARY, PanelMode.SYMBOLS, PanelMode.MEDIA_CONTROL, PanelMode.KDE_CONNECT,
    PanelMode.VOCABULARY, PanelMode.LEARN_FROM_TEXT,
    PanelMode.APP_LAUNCHER, PanelMode.THEMES, PanelMode.SNIPPETS, PanelMode.WIKIPEDIA,
)

/**
 * Whether [panel] takes the whole keyboard right now. Emoji and the media
 * panels (GIF, stickers) are full-bleed by choice rather than by nature:
 * they can pay for the toolbar's row with their own header — category tabs
 * for emoji, the search box for media — so the setting is on by default but
 * can be turned off by anyone who wants the toolbar within reach.
 */
private fun isFullBleedPanel(panel: PanelMode, settings: KeyboardSettings): Boolean = when (panel) {
    PanelMode.EMOJI -> settings.emojiFullBleed
    PanelMode.GIF, PanelMode.STICKER -> settings.mediaFullBleed
    PanelMode.CLIPBOARD -> settings.clipboard.fullBleed
    else -> panel in FullBleedPanels
}

/**
 * Height of everything a full-bleed panel hides (toolbar plus any emoji or
 * symbol row) — the panel absorbs it so opening one never resizes the
 * keyboard window. Shared with the scanner panels, which draw their own
 * chrome instead of using [FullBleedTool].
 */
internal fun fullBleedHiddenRows(state: KeyboardUiState): Dp =
    // The strip, unless it has given its row up to the tools' (#302).
    (if (state.settings.toolbarBehavior.stripHidden) 0.dp else topBarHeight(state.settings)) +
        // An always-open tools row is one more strip's worth hidden under the
        // panel. An on-demand row is not counted: whether it was open is
        // composable-local state this function cannot see, and a row the user
        // opened by hand closing under a panel is a smaller surprise than the
        // keyboard growing by a row it never had.
        (
            if (state.settings.toolbarBehavior.placement == ToolbarPlacement.ALWAYS_ROW) {
                topBarHeight(state.settings)
            } else {
                0.dp
            }
            ) +
        (if (state.settings.emojiBarMode == EmojiBarMode.ALWAYS) EmojiBarHeight else 0.dp) +
        (if (state.settings.symbolRowEnabled) symbolRowHeight(state.settings.rows) else 0.dp) +
        // The fancy style strip hides under a full-bleed panel like the rows
        // above it, so its height rides along — it depends on the active
        // layout, which is why this takes the state and not just settings.
        (if (fancyStyleFor(state) != null) FancyRowHeight else 0.dp) +
        (if (state.settings.rows.dictionaryBarEnabled) DictionaryRowHeight else 0.dp) +
        // The macro row is state-driven, so unlike the on-demand tools row it
        // can be counted: whether it is on screen is in the ui state this
        // function already has.
        (
            if (state.settings.selectionMacros.placement == SelectionMacroPlacement.OWN_ROW &&
                selectionMacroBarVisible(state)
            ) {
                topBarHeight(state.settings)
            } else {
                0.dp
            }
            )

/**
 * Chrome for a full-bleed tool: a slim header (back button + tool name)
 * standing in for the hidden toolbar, then the tool filling everything
 * else. The wrapper's height is the key rows plus every row the full-bleed
 * mode hid, so opening one never resizes the keyboard window — the tool
 * gets the reclaimed space instead.
 */
@Composable
internal fun FullBleedTool(
    state: KeyboardUiState,
    title: String,
    onClose: () -> Unit,
    // Grows the keyboard window upward beyond the normal keyboard height —
    // for tools (AI, converters) whose content is worth more vertical room.
    extraHeight: Dp = 0.dp,
    // While the tool's search box is being typed into, the key rows render
    // below the panel; the panel collapses to [compactHeight] so the two
    // fit together (same trick as the media panels' search mode).
    compact: Boolean = false,
    compactHeight: Dp = 132.dp,
    // Fills the header's free width (after the back button + title) with the
    // tool's own controls, so the reclaimed toolbar row does real work.
    // With an empty [title] the actions own the whole row — search bars and
    // tab strips sit right next to the back button.
    headerActions: (@Composable RowScope.() -> Unit)? = null,
    // Off for the panels that are not really full-bleed: the toolbar is still
    // on screen above them and already carries a way back, so a second back
    // button in the header is just a duplicate eating header width.
    showBack: Boolean = true,
    content: @Composable () -> Unit,
) {
    val kb = LocalKbTheme.current
    val height = if (compact) {
        // A field of the keyboard's own draws a suggestion strip between this
        // panel and the keys (#161), and the row for it comes out of the
        // panel rather than out of the window: tapping a search box must not
        // make the keyboard grow a row. Never below the header, which is the
        // panel's own search bar and way back — a panel already collapsed to
        // just that has nothing left to give, and the strip costs height.
        toolPanelHeight(state, wanted = compactHeight - captureStripHeight(state), floor = FullBleedHeaderHeight)
    } else {
        val board = keyRowsHeight(state) + fullBleedHiddenRows(state)
        toolPanelHeight(state, wanted = board + extraHeight, floor = board)
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .height(height),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(FullBleedHeaderHeight)
                .padding(horizontal = 4.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            if (showBack) {
                ToolCircle(
                    slot = IconSlots.CHROME_PANEL_BACK,
                    description = stringResource(R.string.ime_panel_back_desc),
                    active = false,
                    onClick = onClose,
                )
            }
            if (title.isNotEmpty()) {
                Text(
                    title,
                    color = kb.secondaryText,
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Medium,
                    modifier = Modifier.padding(start = 8.dp),
                )
            }
            if (headerActions != null) {
                if (title.isNotEmpty()) Spacer(Modifier.weight(1f))
                headerActions()
            }
        }
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth(),
        ) { content() }
    }
}

/** The slim header every full-bleed tool draws, and the floor its height has. */
internal val FullBleedHeaderHeight = 40.dp

/**
 * The height a panel over the keyboard gets, fitted to the screen by
 * [fitToolPanelHeight]: what it [wanted], less whatever the window cannot
 * spare once everything else in it is paid for, and never below [floor].
 *
 * "Everything else" is the rows above the panel when it is not standing in
 * for them, the key rows and their strip when one of the keyboard's own
 * fields has them under the panel ([keyRowsUnderPanel]), and the padding
 * under the lot.
 */
@Composable
internal fun toolPanelHeight(state: KeyboardUiState, wanted: Dp, floor: Dp): Dp {
    val rowsStandIn = barFullBleed(state) || barClipboardSearching(state) ||
        (state.panel == PanelMode.EMOJI && state.emojiSearchActive)
    val around = (if (rowsStandIn) 0.dp else fullBleedHiddenRows(state)) +
        (if (keyRowsUnderPanel(state)) keyRowsHeight(state) + captureStripHeight(state) else 0.dp) +
        bottomPaddingDp(state.settings).dp
    return fitToolPanelHeight(wanted, floor, LocalConfiguration.current.screenHeightDp.dp, around)
}

/**
 * The height a [FullBleedTool] panel gets: the [wanted] height, cut down to
 * what is left of [ToolPanelMaxScreenShare] of the screen once everything
 * [around] it is paid for, and never below [floor].
 *
 * Issue #333. The panels ask in fixed dp — 180dp for Translate's box while it
 * is typed into, with the key rows back underneath, or 120–160dp on top of the
 * board for the converters, the calendar and the AI — which is a slice of a
 * phone held upright and nearly the whole of one turned sideways. The panel is
 * the first thing in the column and took its height whole; the key rows came
 * after and were measured against what was left, so on a landscape phone the
 * bottom row was squashed to a sliver and the board ran up under the status
 * bar. The panel is what gives now: the keys are the part being typed on.
 *
 * The floor wins over the budget. For a panel over the board it is the
 * board's own height, which opening the panel never changes the window from;
 * for a collapsed one it is the header, which holds the panel's search box and
 * its way back.
 */
internal fun fitToolPanelHeight(wanted: Dp, floor: Dp, screenHeight: Dp, around: Dp): Dp =
    minOf(wanted, screenHeight * ToolPanelMaxScreenShare - around).coerceAtLeast(floor)

/**
 * The most of the screen a tool panel may grow the keyboard to, with the keys
 * it types on counted: the resize mode's own ceiling, for the same reason —
 * the app the keyboard is over still shows something.
 */
private const val ToolPanelMaxScreenShare = 0.8f

/**
 * A phone held sideways: wide, and too short for a tool panel that stacks its
 * parts. Such a panel lays them side by side instead (issue #370) — Translate's
 * text beside its result, the calculator's functions beside its keypad —
 * because [fitToolPanelHeight] leaves it a strip a line or two tall once the
 * key rows are paid for, and a stack in that strip showed only its top part.
 */
@Composable
internal fun shortLandscape(): Boolean {
    val configuration = LocalConfiguration.current
    return configuration.orientation == Configuration.ORIENTATION_LANDSCAPE &&
        configuration.screenHeightDp < ShortLandscapeMaxHeightDp
}

/** Below this a sideways screen counts as [shortLandscape]; a tablet sideways stays above it. */
private const val ShortLandscapeMaxHeightDp = 480

/**
 * Whether a keyboard-owned field draws a suggestion strip of its own (#161).
 *
 * Asked of the *setting* rather than of whether any words are up, for the same
 * reason [octopusLane] is: every panel reserves the row from this, and a row
 * that came and went as the engine answered would resize the window mid-query.
 *
 * Two fields are excluded because they already own that row: the typing test
 * draws [TypingTestStrip] in it, and the word card's spelling bar *is* it.
 */
internal fun captureStripShown(state: KeyboardUiState): Boolean {
    val target = state.captureTarget() ?: return false
    return target.takesWords &&
        target != CaptureTarget.TYPING_TEST &&
        target != CaptureTarget.WORD_SPELL &&
        state.settings.suggestions
}

/**
 * The row [CaptureStrip] takes, which the panel above it gives up so that
 * tapping a search box does not grow the keyboard by a row.
 */
internal fun captureStripHeight(state: KeyboardUiState): Dp =
    if (captureStripShown(state)) state.settings.toolbarHeightDp.dp else 0.dp

/**
 * A keyboard-owned field's own suggestion strip (#161).
 *
 * The same chips, the same slots and the same size as the strip the field
 * behind the keyboard gets — practising in a search box should feel like
 * typing anywhere else — drawn here rather than by [TopBar] because the panel
 * has taken that bar, and because a word picked here belongs to the query and
 * must never reach the app behind the panel.
 */
@Composable
private fun CaptureStrip(state: KeyboardUiState, capture: CaptureCallbacks) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(state.settings.toolbarHeightDp.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        // Dictation into this field (#353): a microphone at the end of its
        // strip, and while the phrase is being said the strip says so.
        val dictation = state.captureTarget()?.takesDictation == true
        if (dictation && state.fieldVoiceSpeaks()) {
            FieldVoiceStatus(state.voice, capture.onVoice)
        } else {
            LatinSuggestionChips(
                candidates = state.captureSuggestions,
                enabled = true,
                alpha = { 1f },
                slotCount = state.settings.suggestionStrip.slotCount,
                textScale = state.settings.suggestionStrip.textScale,
                scrollable = state.settings.suggestionStrip.scrollable,
                textPadding = state.settings.suggestionStrip.chipPadding.dp,
                centerPrimaryEnabled = state.settings.suggestionStrip.suggestionPrimaryCenter,
                shiftState = state.shiftState,
                onSuggestion = capture.onSuggestion,
                overflow = state.settings.suggestionStrip.overflow,
            )
        }
        if (dictation) {
            FieldVoiceMic(state.voice, mine = state.voice.field == state.captureKey()) {
                capture.onVoice(CaptureVoiceAction.TOGGLE)
            }
        }
    }
}

/**
 * The typing test's suggestions, in the keyboard's own suggestion row.
 *
 * Deliberately the same chips [TopBar] draws, with the same slot count, text
 * scale and centred-primary rule: the point of the option is to practise the
 * strip the user actually types against, which a row of panel chips at a
 * different size in a different place is not. Only the destination differs —
 * a tap types the word into the test.
 */
@Composable
private fun TypingTestStrip(state: KeyboardUiState, onTypingTestAction: (TypingTestAction) -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            // The strip's own height, not [topBarHeight]: turning the toolbar
            // off collapses that to zero, and the test's row is not the
            // toolbar's row — it is the thing being practised.
            .height(state.settings.toolbarHeightDp.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        LatinSuggestionChips(
            candidates = state.typingTest.suggestions,
            enabled = true,
            alpha = { 1f },
            slotCount = state.settings.suggestionStrip.slotCount,
            textScale = state.settings.suggestionStrip.textScale,
            scrollable = state.settings.suggestionStrip.scrollable,
            textPadding = state.settings.suggestionStrip.chipPadding.dp,
            centerPrimaryEnabled = state.settings.suggestionStrip.suggestionPrimaryCenter &&
                !state.fixedPhoneticStrip(),
            shiftState = state.shiftState,
            onSuggestion = { onTypingTestAction(TypingTestAction.Suggestion(it)) },
            overflow = state.settings.suggestionStrip.overflow,
        )
    }
}

/**
 * Toolbar + panels + key rows, wrapped in a Box so the tool-drag ghost can
 * float over everything while the toolbox is open.
 */
@Composable
private fun KeyboardBody(
    state: KeyboardUiState,
    onDismissInlineSuggestions: () -> Unit,
    onPickerDismiss: () -> Unit,
    onSmartAccept: () -> Unit,
    onSmartOpen: () -> Unit,
    onStripOfferAction: (StripOfferAction) -> Unit,
    onToolPrefillConsumed: () -> Unit,
    onHideKeyboard: () -> Unit,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    onGesture: (List<GesturePoint>, List<KeyCenter>, Float, GlideVerdict) -> Unit,
    onGesturePreview: (List<GesturePoint>, List<KeyCenter>, Float, GlideCase) -> Unit,
    onGestureWords: (List<List<GesturePoint>>, List<KeyCenter>, Float, GlideVerdict) -> Unit,
    onKeyTouch: (Float, Float) -> Unit = { _, _ -> },
    onTouchKeys: (List<KeyCenter>) -> Unit = {},
    onCursorMove: (Int) -> Unit,
    onLayoutSelect: (String) -> Unit,
    onSuggestion: (String) -> Unit,
    /** A word on the strip was held: see [KeyboardScreen]'s own. */
    suggestionHold: SuggestionHoldCallbacks = SuggestionHoldCallbacks(),
    onJoinSuggestion: () -> Unit = {},
    onRevisionSuggestion: () -> Unit = {},
    /** A conversion candidate tapped, with its position — see Composer.consumedForIndex. */
    onCandidate: (String, Int) -> Unit = { text, _ -> onSuggestion(text) },
    /** Open the expanded candidate grid. */
    onCandidatesExpand: () -> Unit = {},
    onEmoji: (String) -> Unit,
    onEmojiVariant: (String, String) -> Unit,
    onEmojiFavourite: (String) -> Unit,
    onEmojiSuggestion: (String, Boolean) -> Unit,
    onPunctuation: (String) -> Unit,
    onEmojiQueryTap: () -> Unit,
    onEmojiRecentsClear: () -> Unit,
    onEmojiRecentRemove: (String) -> Unit,
    onEmojiFavouritesReorder: (List<String>) -> Unit,
    onEmojiLongPress: (String) -> Unit,
    onEmojiLongPressEnd: () -> Unit,
    onAnimatedEmojiSend: (String) -> Unit,
    onEmojiStickerSend: (String) -> Unit,
    onEmojiSearchFieldDelete: () -> Unit,
    onTextArt: (String) -> Unit,
    onPanelChange: (PanelMode) -> Unit,
    onClipboardItem: (ClipItem) -> Unit,
    onClipboardSticker: (ClipItem) -> Unit,
    onClipboardPin: (ClipItem) -> Unit,
    onClipboardDelete: (ClipItem) -> Unit,
    onClipboardSearchToggle: () -> Unit,
    onClipboardSuggestionDismiss: () -> Unit,
    onClipboardEntity: (ClipEntity) -> Unit,
    onOtpAccept: (NotificationOtp) -> Unit,
    onOtpDismiss: () -> Unit,
    onEmojiRowShown: () -> Unit,
    snippetPanel: SnippetPanelCallbacks,
    onToolTap: (ToolbarTool) -> Unit,
    onToolbarToolsChange: (List<ToolbarTool>) -> Unit,
    onToolboxOrderChange: (List<ToolbarTool>) -> Unit,
    toolHold: ToolHoldCallbacks,
    onToolboxHintDismiss: () -> Unit,
    onWeatherRefresh: () -> Unit,
    onCameraSend: (java.io.File, Boolean) -> Unit,
    onCameraPermissionRequest: () -> Unit,
    onCalendarPermissionRequest: () -> Unit,
    onScannedInsert: (String) -> Unit,
    onScannedUrlOpen: (String) -> Unit,
    onVoiceToggle: () -> Unit,
    onVoicePermissionRequest: () -> Unit,
    onVoiceUndo: () -> Unit,
    onVoiceModelDownload: () -> Unit,
    onWhisperTranslateToggle: () -> Unit,
    onOpenVoiceSettings: () -> Unit,
    onVoiceUseSystemEngine: () -> Unit,
    onVoiceRailKey: (VoiceBarAction) -> Unit,
    onMediaPlayPause: () -> Unit,
    onMediaNext: () -> Unit,
    onMediaPrevious: () -> Unit,
    onMediaSeek: (Long) -> Unit,
    onMediaAccessRequest: () -> Unit,
    onMediaResume: () -> Unit,
    onDictionaryLookup: (String) -> Unit,
    onDictionarySearchToggle: () -> Unit,
    onDictionaryInsert: (String) -> Unit,
    onThemeSelect: (String) -> Unit,
    onIconPackSelect: (String) -> Unit,
    onEmojiFontSelect: (EmojiFontChoice, String) -> Unit,
    onFontSelect: (ScriptId, String) -> Unit,
    onSoundHaptic: (SoundHapticAction) -> Unit,
    onHandwritingStroke: (HwStroke, IntSize) -> Unit,
    onKeyboardHandwritingStroke: (HwStroke, IntSize) -> Unit,
    onHandwritingUndo: () -> Unit,
    onHandwritingDownload: () -> Unit,
    onMediaQueryTap: () -> Unit,
    onMediaQueryClear: () -> Unit,
    onMediaRetry: () -> Unit,
    onGifSelect: (GifItem) -> Unit,
    onGifSourceSelect: (GifSource) -> Unit,
    onGifCategorySelect: (String) -> Unit,
    onMediaLongPress: (GifItem) -> Unit,
    onStickerPackFilter: (String?) -> Unit,
    onStickerSaveToPack: (GifItem, String?) -> Unit,
    onMediaCopy: (GifItem) -> Unit,
    onMediaReport: (GifItem) -> Unit,
    onMediaActionDismiss: () -> Unit,
    onWebResult: (WebResult) -> Unit,
    onWebResultOpen: (WebResult) -> Unit,
    onImageResult: (ImageResult) -> Unit,
    onImageResultLink: (ImageResult) -> Unit,
    translateCallbacks: TranslateCallbacks,
    grammarCallbacks: GrammarCallbacks,
    onWikiOpen: (String) -> Unit,
    onWikiBack: () -> Unit,
    onWikiLoadLinks: () -> Unit,
    onWikiLoadFull: () -> Unit,
    onSymbolInsert: (String) -> Unit,
    symbolRow: SymbolRowCallbacks,
    onFancyStyleSelect: (String) -> Unit,
    onModeSelect: (String?) -> Unit,
    onToolInsert: (String) -> Unit,
    converter: ConverterCallbacks,
    capture: CaptureCallbacks,
    onPwSetting: (PwSettingAction) -> Unit,
    onTypingTestAction: (TypingTestAction) -> Unit,
    onQrSend: () -> Unit,
    onAiAction: (com.wasimaster.wmkeyboard.core.tools.AiActionSpec) -> Unit,
    onAiReplace: () -> Unit,
    onAiInsert: () -> Unit,
    onAiRetry: () -> Unit,
    onAiRunCustom: () -> Unit,
    onAiPickModel: (com.wasimaster.wmkeyboard.core.settings.AiProvider, String?) -> Unit,
    onAiToggleStripMarkdown: () -> Unit,
    onAiSetShowDiff: (Boolean) -> Unit,
    onAiReport: () -> Unit,
    onOpenToolSettings: (ToolbarTool) -> Unit,
    onOpenRoute: (String) -> Unit = {},
    onPluginOpen: (String) -> Unit = {},
    onPluginBack: () -> Unit = {},
    onPluginEvent: (PluginEvent) -> Unit = {},
    onPluginInputFocus: (String?) -> Unit = {},
    onPluginPaste: (String) -> Unit = {},
    onPluginCopy: (String) -> Unit = {},
    launcher: LauncherPanelCallbacks = LauncherPanelCallbacks(),
) {
    val drag = remember { ToolDragController() }
    // Storage order in, storage order out. An RTL bar is drawn right-to-left
    // by the row itself and hit-tested the same way (see [ToolDragController.barRtl]),
    // so nothing here reverses any more — doing both was issue #79.
    drag.currentTools = state.settings.toolbarTools
    drag.onCommit = onToolbarToolsChange
    drag.onOrderCommit = onToolboxOrderChange
    drag.onSnap = LocalKeyPressFeedback.current
    drag.onOpenSettings = toolHold.onSettings
    drag.onSelectionHold = toolHold.onSelectionHold
    drag.onTrackpadHold = toolHold.onTrackpadHold
    drag.onVoiceModePick = toolHold.onVoiceModePick
    // A remapped hold runs the bound tool through the service's own dispatcher
    // rather than [onToolTap]: that one refuses any tool the toolbar does not
    // list, and the tool the user bound a hold to is very often one they never
    // put on the bar — that being the point of binding it (#31).
    drag.onHoldAction = toolHold.onHoldAction
    var bodyOrigin by remember { mutableStateOf(Offset.Zero) }
    // Kept alongside the origin so the drag-scope pill can park itself against
    // the bottom of the keyboard when the toolbar end is where the finger is.
    var bodyHeightPx by remember { mutableIntStateOf(0) }

    // The one text selection up (#352), and whether a tap elsewhere should end it.
    val selectionOverlay = LocalSelectionOverlay.current
    val selectionDismissable by remember(selectionOverlay) {
        androidx.compose.runtime.derivedStateOf { selectionOverlay?.session?.dismissOnOutsideTap == true }
    }
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .onGloballyPositioned {
                bodyOrigin = it.positionInRoot()
                bodyHeightPx = it.size.height
                drag.bodyCoords = it
            }
            .then(
                if (selectionOverlay == null) {
                    Modifier
                } else {
                    Modifier.selectionDismissObserver(selectionOverlay, selectionDismissable)
                },
            ),
    ) {
        Column {
            // The dedicated always-on emoji row (Gboard style) sits between
            // the strip and the keys — or on top of everything, per setting;
            // the emoji panel already is emojis, so it yields there.
            // Full-bleed panels swallow the toolbar row (and any emoji or
            // symbol row) too: the tool absorbs those rows' height, so it
            // gets every pixel the keyboard owns. OCR draws its own chrome;
            // the rest get the [FullBleedTool] back-header wrapper.
            // Lock-screen privacy: with the setting on and the keyguard up, drop
            // the whole top strip (suggestions + toolbar, so the clipboard tool
            // and paste chip go with it) and block the clipboard panel, keeping
            // copied text and pinned tools off a screen anyone can wake.
            val lockHidden = barLockHidden(state)
            // Same deal for the clipboard panel's search bar: the panel shrinks
            // to its search field plus a couple of result rows and the keys come
            // back underneath, so the query is actually typeable. Not while the
            // lock screen has blocked the panel — the keys are already up in its
            // place there, and a second set would double them.
            val clipboardSearching = barClipboardSearching(state)
            // The searching clipboard panel steps out of full-bleed: search
            // already owns the toolbar row's height, and the keys below need
            // their usual rows around them.
            val fullBleed = barFullBleed(state)
            // The symbols panel already is special characters — the row
            // would be redundant there, so it yields like the emoji row.
            val showEmojiRow = emojiRowVisible(state)
            val showSymbolRow = symbolRowVisible(state)
            // The rows stack in the user's chosen order (Rows settings).
            // While an emoji search is typing, the toolbar is dead weight —
            // hide it and let the panel spend the height on result rows.
            val emojiSearching = state.panel == PanelMode.EMOJI && state.emojiSearchActive
            // Tools on a row of their own (see [ToolbarPlacement]). The row is a
            // [BarRow.TOOLS] sibling of the strip rather than something TopBar
            // draws: each has its own height and slot, and the strip's
            // surface-swap machinery is switched off instead of being taught to
            // draw two things at once.
            //
            // ON_DEMAND_ROW is the same row behind the strip's chevron, so the
            // open/closed flag lives out here where both can reach it. It resets
            // whenever the placement changes, or a row opened under one
            // arrangement would still be open under another that has no way to
            // close it.
            val placement = state.settings.toolbarBehavior.placement
            var toolsRowOpen by remember(placement) { mutableStateOf(false) }
            // Whether the row has a place on screen at all, as distinct from
            // whether the chevron has it open. The first is a hard cut, like
            // every other row under a full-bleed panel; only the second animates.
            val toolsRowHost = placement.isOwnRow &&
                state.settings.toolbarBehavior.enabled &&
                !fullBleed && !emojiSearching && !clipboardSearching && !lockHidden
            // What the row measures to, from the settings alone: [ToolsRow] is
            // a [topBarHeight] Row and nothing else. The frame holds this much
            // open while the row is closed, so it has to be the row's height
            // exactly — a band that is short resizes the window on the way in,
            // one that is long leaves a gap over the board.
            val toolsRowPx = with(LocalDensity.current) { topBarHeight(state.settings).roundToPx() }
            // The macro row's own hard cut: the same panel and lock-screen
            // gates as every other row, plus the placement. Whether there is
            // anything to draw is the animated half, below.
            val macroRowHost = state.settings.selectionMacros.enabled &&
                state.settings.selectionMacros.placement == SelectionMacroPlacement.OWN_ROW &&
                // The panel carries Undo and the stepping itself; two rows
                // moving the same selection would fight over it.
                state.panel != PanelMode.FIND_REPLACE &&
                !fullBleed && !emojiSearching && !clipboardSearching && !lockHidden
            // Disabling the toolbar drops the whole strip — suggestions and
            // tools alike — so the keys claim its height.
            val topBarVisible = state.settings.toolbarBehavior.enabled && !fullBleed &&
                !emojiSearching && !clipboardSearching && !lockHidden
            // The other placement: the macros take the suggestion strip's own
            // row instead of asking for one.
            val stripMacros = state.settings.selectionMacros.placement == SelectionMacroPlacement.STRIP &&
                state.panel == PanelMode.NONE && selectionMacroBarVisible(state)
            // The Fancy Text style strip is a row like the others, but its
            // visibility follows the active layout rather than a setting.
            val fancyStyle = fancyStyleFor(state)
            // The fill a theme may give the bars, taken by every row in this
            // stack: the suggestion strip, the emoji, symbol, dictionary and
            // fancy-text rows, the macros and the tools' own row. They stack
            // against each other with nothing between them, so colouring one
            // and leaving the next on the board would read as a mistake rather
            // than as a choice. Null is the inherit case and paints nothing at
            // all, which is what lets a board gradient, image or animation run
            // through the bars as it always has (issue #109).
            val barFill = LocalKbTheme.current.suggestionBar
            // One row of the stack. A local composable so the two halves of the
            // order — above the keys and below them — draw through one `when`.
            // The fill rides on the slot rather than inside each row, so a row
            // that comes and goes takes it along with its own open animation,
            // and a row that draws nothing right now paints no band either. A
            // Column and not a Box, because the macros and the tools expand
            // through ColumnScope's own AnimatedVisibility.
            @Composable
            fun BarRowSlot(row: BarRow) {
                Column(modifier = Modifier.barRowFill(barFill)) {
                    when (row) {
                        BarRow.TOPBAR -> when {
                            // Before every other case, the toolbar's own
                            // visibility included: the word card has handed
                            // the keys to this bar, so it is the only thing
                            // on screen that says what they are typing (#138).
                            state.wordSpell != null -> WordSpellBar(state, suggestionHold.onCard)
                            !topBarVisible -> {}
                            // The strip placement swaps the whole bar rather than adding
                            // a surface to TopBar's own flip: with a selection live there
                            // are no word candidates to show (nothing is being typed), and
                            // the toolbar is one tap away under the macros' own gesture.
                            // Only with no panel open, because there the chevron on this
                            // row is the way back out of the panel.
                            stripMacros -> SelectionMacroBar(state, toolHold.selection)
                            // The strip given up for the tools' own row (#302).
                            // Compact dictation still takes it: that bar is the
                            // session's only status and its only way out.
                            state.settings.toolbarBehavior.stripHidden && !state.voice.strip -> {}
                            else -> WithNetActivityDot(
                                state.settings.networkLog.showOnKeyboard,
                                state.settings.toolColorOverrides,
                            ) { TopBar(
                                state,
                                toolsRowOpen = toolsRowOpen,
                                onToolsRowToggle = { toolsRowOpen = !toolsRowOpen },
                                onSuggestion = onSuggestion,
                                suggestionHold = suggestionHold,
                                onJoinSuggestion = onJoinSuggestion,
                                onRevisionSuggestion = onRevisionSuggestion,
                                onCandidate = onCandidate,
                                onCandidatesExpand = onCandidatesExpand,
                                onEmoji = onEmoji,
                                onEmojiSuggestion = onEmojiSuggestion,
                                onPunctuation = onPunctuation,
                                onPanelChange = onPanelChange,
                                onToolTap = onToolTap,
                                drag = drag,
                                onVoiceToggle = onVoiceToggle,
                                onVoiceUndo = onVoiceUndo,
                                onVoicePermissionRequest = onVoicePermissionRequest,
                                onOpenVoiceSettings = onOpenVoiceSettings,
                                onVoiceAction = onVoiceRailKey,
                                onDismissInlineSuggestions = onDismissInlineSuggestions,
                                onSmartAccept = onSmartAccept,
                                onSmartOpen = onSmartOpen,
                                vocab = toolHold.vocab,
                                stickerOffer = toolHold.stickerOffer,
                                onStripOfferAction = onStripOfferAction,
                                onClipboardSuggestion = onClipboardItem,
                                onClipboardSuggestionDismiss = onClipboardSuggestionDismiss,
                                onClipboardEntity = onClipboardEntity,
                                onOtpAccept = onOtpAccept,
                                onOtpDismiss = onOtpDismiss,
                                onEmojiRowShown = onEmojiRowShown,
                                onSwipeDownHide = onHideKeyboard,
                            ) }
                        }
                        BarRow.EMOJI -> if (showEmojiRow) {
                            EmojiBarStrip(
                                state = state,
                                onEmoji = onEmoji,
                                onOpenPanel = { onPanelChange(PanelMode.EMOJI) },
                            )
                        }
                        BarRow.SYMBOL -> if (showSymbolRow) {
                            SymbolRowStrip(
                                state = state,
                                onInsert = onToolInsert,
                                callbacks = symbolRow,
                            )
                        }
                        BarRow.FANCY -> if (!fullBleed && fancyStyle != null) {
                            FancyStyleStrip(
                                state = state,
                                active = fancyStyle,
                                onStyleSelect = onFancyStyleSelect,
                            )
                        }
                        // The dictionary bar (issue #51) is a setting-driven row like
                        // the symbol row; a full-bleed panel hides it like the rest.
                        BarRow.DICTIONARY -> if (!fullBleed && state.settings.rows.dictionaryBarEnabled) {
                            DictionaryBarStrip(state = state, callbacks = toolHold.dictionaryBar)
                        }
                        // The macro row comes and goes with the selection rather
                        // than with a setting, so unlike every other row here its
                        // gate is state and not settings. It animates for the same
                        // reason the tools row does: a row that appears the instant
                        // a selection is dragged out, at full height, reads as the
                        // keyboard jumping rather than as an offer arriving.
                        BarRow.MACROS -> if (macroRowHost) {
                            val motion = !state.settings.reduceMotion
                            // Grows inside a docked frame that holds still (see
                            // RowRevealHeadroom): resizing the IME window itself
                            // re-laid out the host app on every frame. Leaving is
                            // one step anyway, the bar's content going in the
                            // same update as its offer.
                            RevealingBarRow(
                                visible = selectionMacroBarVisible(state),
                                enter = if (motion) {
                                    expandVertically(tween(ToolbarMotionMs)) + fadeIn(tween(ToolbarMotionMs))
                                } else {
                                    EnterTransition.None
                                },
                                exit = if (motion) {
                                    shrinkVertically(tween(ToolbarMotionMs)) + fadeOut(tween(ToolbarMotionMs))
                                } else {
                                    ExitTransition.None
                                },
                            ) {
                                SelectionMacroBar(state, toolHold.selection)
                            }
                        }
                        // The chevron's open/close grows and shrinks the row over
                        // the same beat the chevron turns, so the tools arrive with
                        // the gesture instead of popping in a frame later. A
                        // full-bleed panel still cuts it, above: an animated shrink
                        // there would overshoot the keyboard height for a beat
                        // while the panel had already claimed the row's space.
                        // Both moves happen inside a docked frame that holds
                        // still, as the macro row's do (see RowRevealHeadroom).
                        BarRow.TOOLS -> if (toolsRowHost) {
                            val motion = !state.settings.reduceMotion
                            RevealingBarRow(
                                visible = placement == ToolbarPlacement.ALWAYS_ROW || toolsRowOpen,
                                // On demand, the frame holds the row's height
                                // even while it is closed, so the chevron
                                // resizes the IME window neither way (#217):
                                // the one resize left after the per-frame ones
                                // went was enough to blink the keyboard on some
                                // devices. The height is the row's own, known
                                // from the settings before it is ever measured.
                                // Not for ALWAYS_ROW, whose row is never out.
                                reserveWhenOutPx = if (placement == ToolbarPlacement.ON_DEMAND_ROW) {
                                    toolsRowPx
                                } else {
                                    0
                                },
                                enter = if (motion) {
                                    expandVertically(tween(ToolbarMotionMs)) + fadeIn(tween(ToolbarMotionMs))
                                } else {
                                    EnterTransition.None
                                },
                                exit = if (motion) {
                                    shrinkVertically(tween(ToolbarMotionMs)) + fadeOut(tween(ToolbarMotionMs))
                                } else {
                                    ExitTransition.None
                                },
                            ) {
                                ToolsRow(state, onPanelChange, onToolTap, drag)
                            }
                        }
                        // Stickers the text asked for (#329), in a row of
                        // their own: first in the default order, movable
                        // under Rows & bars. Drawn with the toolbar switched
                        // off too, since it is an offer about the text and
                        // not a part of the toolbar. The emoji panel keeps it
                        // even full-bleed, since an emoji picked there is
                        // what raises it.
                        BarRow.STICKERS -> {
                            val trayFitsPanel = !fullBleed || state.panel == PanelMode.EMOJI
                            if (trayFitsPanel && !lockHidden && !clipboardSearching && !emojiSearching) {
                                StickerTrayRow(state, toolHold.stickerOffer)
                            }
                        }
                        // Stands for the keys themselves: the split below draws
                        // them, so the entry itself is never a row.
                        BarRow.KEYBOARD -> {}
                    }
                }
            }
            // The keys sit where the KEYBOARD entry does (issue #83): the rows
            // before it stack above the keys, the rows after it go below — after
            // every key-row branch at the bottom of this column.
            val barOrder = state.settings.barOrder
            for (row in barRowsAboveKeys(barOrder)) BarRowSlot(row)
            // The panel swap below fades a panel in, and only a panel: see
            // [PanelEnterFade]. A fade over this whole subtree was tried first
            // and reverted — it covered the key rows too, so every panel close
            // briefly rendered a translucent keyboard with the app's own text
            // field showing through it, and its alpha landed a frame after the
            // new content was already on screen, flashing it at full strength.
        // A panel that has left the composition must stop claiming the focus
        // ring: its counts and its activate lambdas outlive it by a frame
        // otherwise, and the service would act on an item nothing is drawing.
        val focusController = LocalPanelFocus.current
        DisposableEffect(state.panel) {
            onDispose { focusController.reset() }
        }
        // The emoji, clipboard and text-editing panels are layouts (issue
        // #63), drawn by PanelLayoutHost. Their callbacks travel in one object
        // built here from the lambdas this body already has — the service
        // passes bound method references, so this rarely re-runs — rather than
        // as new parameters on KeyboardScreen, which sits under the method-size
        // ceiling.
        val panelCallbacks = remember(
            onKey, onText, onCursorMove, onLayoutSelect, onPanelChange,
            onEmoji, onEmojiVariant, onEmojiFavourite, onEmojiQueryTap, onEmojiRecentsClear,
            onEmojiRecentRemove, onEmojiFavouritesReorder, onEmojiLongPress, onEmojiLongPressEnd,
            onAnimatedEmojiSend, onEmojiStickerSend, onEmojiSearchFieldDelete, onTextArt,
            onClipboardItem, onClipboardSticker, onClipboardPin, onClipboardDelete,
            onClipboardSearchToggle, onClipboardEntity,
            toolHold,
        ) {
            PanelLayoutCallbacks(
                onKey = onKey,
                onText = onText,
                onCursorMove = onCursorMove,
                onLayoutSelect = onLayoutSelect,
                onPanelChange = onPanelChange,
                emoji = EmojiFieldCallbacks(
                    onEmoji = onEmoji,
                    onEmojiVariant = onEmojiVariant,
                    onEmojiFavourite = onEmojiFavourite,
                    onQueryTap = onEmojiQueryTap,
                    onClearRecents = onEmojiRecentsClear,
                    onRecentRemove = onEmojiRecentRemove,
                    onFavouritesReorder = onEmojiFavouritesReorder,
                    onLongPress = onEmojiLongPress,
                    onLongPressEnd = onEmojiLongPressEnd,
                    onAnimatedSend = onAnimatedEmojiSend,
                    onStickerSend = onEmojiStickerSend,
                    onSearchFieldDelete = onEmojiSearchFieldDelete,
                    onTextArt = onTextArt,
                ),
                clipboard = ClipboardFieldCallbacks(
                    onItem = onClipboardItem,
                    onSticker = onClipboardSticker,
                    onPin = onClipboardPin,
                    onDelete = onClipboardDelete,
                    onSearchToggle = onClipboardSearchToggle,
                    onEntity = onClipboardEntity,
                    actions = toolHold.clipboard,
                ),
                trackpad = TrackpadFieldCallbacks(
                    onKey = onKey,
                    onSelectionHold = toolHold.onSelectionHold,
                    onCaretDrag = { toolHold.caretMagnifier.onDrag(CaretDragSource.TRACKPAD, it) },
                ),
            )
        }
        val shownPanel = if (lockHidden && state.panel == PanelMode.CLIPBOARD) PanelMode.NONE else state.panel
        PanelEnterFade(shownPanel, state.settings.reduceMotion, roomBelow = panelRoomBelow(state, shownPanel)) {
        when (shownPanel) {
                PanelMode.EMOJI -> EmojiPanelHost(state, panelCallbacks)
                PanelMode.CLIPBOARD -> ClipboardPanelHost(state, panelCallbacks)
                // The snippet cards are two columns of wrapped text, so the
                // rows the toolbar gives up are worth a whole extra pair of
                // them. The editor lives in settings, so the header's action
                // slot carries the gear the panel used to draw itself.
                //
                // Inside a folder the header carries that folder's name and its
                // back button goes up a level rather than out of the panel —
                // the same back the hardware key and the system key perform.
                PanelMode.SNIPPETS -> {
                    val openFolder = state.openSnippetFolder()
                    FullBleedTool(
                        state,
                        openFolder?.name ?: stringResource(R.string.ime_tool_snippets),
                        onClose = {
                            if (openFolder == null) {
                                onPanelChange(PanelMode.SNIPPETS)
                            } else {
                                snippetPanel.onFolderOpen(null)
                            }
                        },
                        headerActions = {
                            ToolCircle(
                                slot = IconSlots.forTool(ToolbarTool.SETTINGS),
                                description = stringResource(R.string.ime_snippets_settings_desc),
                                active = false,
                                onClick = { onOpenToolSettings(ToolbarTool.SNIPPETS) },
                            )
                        },
                    ) {
                        SnippetsPanel(
                            state, snippetPanel,
                            onOpenSettings = { onOpenToolSettings(ToolbarTool.SNIPPETS) },
                        )
                    }
                }
                PanelMode.TEXT_EDIT -> TextEditPanelHost(state, panelCallbacks)
                PanelMode.TRACKPAD -> TrackpadPanelHost(state, panelCallbacks)
                PanelMode.TOOLBOX -> ToolboxPanel(state, onToolTap, onToolboxHintDismiss, drag)
                // Regular panels (toolbar stays visible): the sensors read
                // fine at keyboard height and the toolbar keeps tool-hopping
                // one tap away.
                PanelMode.COMPASS -> Box(
                    Modifier
                        .fillMaxWidth()
                        .height(keyRowsHeight(state)),
                ) { CompassPanel(state) }
                PanelMode.LEVEL -> Box(
                    Modifier
                        .fillMaxWidth()
                        .height(keyRowsHeight(state)),
                ) { LevelPanel(state) }
                PanelMode.MOON_PHASE -> MoonPhasePanel(state)
                PanelMode.CUSTOM_LAYOUTS -> CustomLayoutPanel(state, onKey)
                PanelMode.WEATHER -> WeatherPanel(
                    state = state,
                    onRefresh = onWeatherRefresh,
                    // The prompt is about the weather location, so land on the
                    // weather tool's own page rather than the settings root.
                    onOpenSettings = { onOpenToolSettings(ToolbarTool.WEATHER) },
                )
                // The month grid and the selected day's event list are fighting
                // over the same rows, so the calendar buys itself another band
                // of height the way the grammar strip and the typing test do.
                PanelMode.CALENDAR -> FullBleedTool(
                    state, stringResource(R.string.ime_tool_calendar),
                    onClose = { onPanelChange(PanelMode.CALENDAR) },
                    extraHeight = 140.dp,
                ) {
                    CalendarPanel(
                        state,
                        onRequestPermission = onCalendarPermissionRequest,
                        onPrefillConsumed = onToolPrefillConsumed,
                    )
                }
                PanelMode.THEMES -> ThemesPanel(
                    state,
                    onThemeSelect,
                    onIconPackSelect,
                    onEmojiFontSelect,
                    onFontSelect,
                    onOpenRoute = onOpenRoute,
                    onClose = { onPanelChange(PanelMode.THEMES) },
                )
                PanelMode.SOUND_HAPTICS -> SoundHapticsPanel(state, onSoundHaptic, onOpenRoute)
                PanelMode.NUMPAD -> NumpadPanelHost(state, panelCallbacks)
                PanelMode.CANDIDATES -> CandidateGridPanel(state, onCandidate)
                PanelMode.HANDWRITING -> if (BuildConfig.ENABLE_ML_KIT_HANDWRITING) {
                    HandwritingPanel(
                        state = state,
                        onStroke = onHandwritingStroke,
                        onUndoStroke = onHandwritingUndo,
                        onDownloadModel = onHandwritingDownload,
                        onKey = onKey,
                        onLayoutSelect = onLayoutSelect,
                        onClose = { onPanelChange(PanelMode.HANDWRITING) },
                    )
                } else {
                    onPanelChange(PanelMode.SNIPPETS)
                }
                PanelMode.CAMERA -> CameraPanel(
                    state = state,
                    onSend = onCameraSend,
                    onRequestPermission = onCameraPermissionRequest,
                    // Toggling the open panel closes it; opened from image
                    // search, back goes back there.
                    onClose = {
                        onPanelChange(if (state.cameraSearchOnly) PanelMode.IMAGE_SEARCH else PanelMode.CAMERA)
                    },
                )
                PanelMode.OCR -> if (BuildConfig.ENABLE_ML_KIT_SCANNERS) {
                    OcrPanel(
                        state = state,
                        onInsert = onScannedInsert,
                        onRequestPermission = onCameraPermissionRequest,
                        onClose = { onPanelChange(PanelMode.OCR) },
                    )
                } else {
                    onPanelChange(PanelMode.SNIPPETS)
                }
                PanelMode.QR_SCAN -> if (BuildConfig.ENABLE_ML_KIT_SCANNERS) {
                    QrScanPanel(
                        state = state,
                        onInsert = onScannedInsert,
                        onOpenUrl = onScannedUrlOpen,
                        onRequestPermission = onCameraPermissionRequest,
                        onClose = { onPanelChange(PanelMode.QR_SCAN) },
                    )
                } else {
                    onPanelChange(PanelMode.SNIPPETS)
                }
                PanelMode.VOICE -> VoicePanel(
                    state = state,
                    onToggle = onVoiceToggle,
                    onUndo = onVoiceUndo,
                    onRequestPermission = onVoicePermissionRequest,
                    onDownloadModel = onVoiceModelDownload,
                    onToggleTranslate = onWhisperTranslateToggle,
                    onOpenVoiceSettings = onOpenVoiceSettings,
                    onUseSystemEngine = onVoiceUseSystemEngine,
                    onRailKey = onVoiceRailKey,
                    onLayoutSelect = onLayoutSelect,
                    onClose = { onPanelChange(PanelMode.VOICE) },
                )
                PanelMode.PLUGINS -> FullBleedTool(
                    state,
                    title = (state.plugins as? PluginPanelUi.Running)?.plugin?.name
                        ?: stringResource(R.string.ime_tool_plugins),
                    // Back out one level at a time: from a running plugin to the
                    // installed list, and only from the list itself out of the
                    // panel. Closing outright left no way back to the list short
                    // of reopening the tool.
                    onClose = {
                        if (state.plugins is PluginPanelUi.Running) {
                            onPluginBack()
                        } else {
                            onPanelChange(PanelMode.PLUGINS)
                        }
                    },
                    // While a plugin's text box has the keys, the rows render
                    // below and the panel gives up the room for them. Taller
                    // than the search panels' default: a plugin draws its own
                    // header row of tabs above the box, and at 132dp the box
                    // being typed into was itself the thing that got cut off.
                    compact = state.pluginTypingActive,
                    compactHeight = 188.dp,
                ) {
                    PluginPanel(
                        state = state,
                        onOpenPlugin = onPluginOpen,
                        onEvent = onPluginEvent,
                        onInputFocus = onPluginInputFocus,
                        onToolInsert = onToolInsert,
                        onCopy = onPluginCopy,
                        onPaste = onPluginPaste,
                        onManage = { onOpenRoute("plugins") },
                    )
                }
                PanelMode.APP_LAUNCHER -> FullBleedTool(
                    state, title = "",
                    // Back out one level at a time, like the plugins panel:
                    // from an app's activity list to the grid, then out.
                    onClose = {
                        if (state.launcherDetail != null) launcher.onDetailClose()
                        else onPanelChange(PanelMode.APP_LAUNCHER)
                    },
                    compact = state.mediaSearchActive,
                    headerActions = {
                        MediaHeaderSearchBar(
                            state = state,
                            placeholder = stringResource(R.string.ime_launcher_search_hint),
                            onQueryTap = onMediaQueryTap,
                        )
                    },
                ) {
                    AppLauncherPanel(
                        state = state,
                        callbacks = launcher,
                        onQueryTap = onMediaQueryTap,
                    )
                }
                PanelMode.MEDIA_CONTROL -> FullBleedTool(
                    state,
                    title = stringResource(R.string.ime_tool_media_control),
                    onClose = { onPanelChange(PanelMode.MEDIA_CONTROL) },
                ) {
                    MediaControlPanel(
                        state = state,
                        onPlayPause = onMediaPlayPause,
                        onNext = onMediaNext,
                        onPrevious = onMediaPrevious,
                        onSeek = onMediaSeek,
                        onRequestAccess = onMediaAccessRequest,
                        onResume = onMediaResume,
                    )
                }
                // A paired computer (#285). While its keys are typing there, or
                // into the address box, the panel collapses over the key rows
                // the way the chat composer's does — and keeps enough height
                // for the key strip, the echo line and a sliver of touchpad.
                PanelMode.KDE_CONNECT -> FullBleedTool(
                    state,
                    title = stringResource(R.string.ime_tool_kde_connect),
                    onClose = { onPanelChange(PanelMode.KDE_CONNECT) },
                    compact = state.kdeTypingActive || state.kdeHostEntryActive,
                    compactHeight = if (state.kdeHostEntryActive) 96.dp else KdeTypingCompactHeight,
                    headerActions = { KdeHeaderActions(state, capture.onKde) },
                ) { KdeConnectPanel(state, capture) }
                PanelMode.DICTIONARY -> FullBleedTool(
                    state, title = "",
                    onClose = { onPanelChange(PanelMode.DICTIONARY) },
                    // While the query types on the key rows below, only the
                    // header (with its search bar) needs to stay visible.
                    compact = state.dictionarySearchActive,
                    compactHeight = 44.dp,
                    headerActions = {
                        DictionaryHeaderSearchBar(
                            state = state,
                            onSearchToggle = onDictionarySearchToggle,
                            onLookup = onDictionaryLookup,
                        )
                    },
                ) {
                    DictionaryPanel(
                        state = state,
                        onLookup = onDictionaryLookup,
                        onInsert = onDictionaryInsert,
                        onAddToVocab = toolHold.vocab.onDictionaryAddToVocab,
                    )
                }
                PanelMode.VOCABULARY -> VocabPanelHost(
                    state = state,
                    callbacks = toolHold.vocab,
                    onPanelChange = onPanelChange,
                    onQueryTap = onMediaQueryTap,
                    onOpenRoute = onOpenRoute,
                )
                PanelMode.TRANSLATE -> TranslateTool(
                    state = state,
                    callbacks = translateCallbacks,
                    onClose = { onPanelChange(PanelMode.TRANSLATE) },
                    onQueryTap = onMediaQueryTap,
                )
                PanelMode.GRAMMAR -> if (BuildConfig.ENABLE_GRAMMAR) {
                    GrammarPanel(state = state, callbacks = grammarCallbacks)
                } else {
                    onPanelChange(PanelMode.SNIPPETS)
                }
                PanelMode.GIF, PanelMode.STICKER -> {
                    val stickers = state.panel == PanelMode.STICKER
                    if (state.settings.mediaFullBleed) {
                        // Search moves up into the reclaimed toolbar row, next
                        // to the back button — same shape as the dictionary.
                        FullBleedTool(
                            state,
                            title = "",
                            onClose = { onPanelChange(state.panel) },
                            // Search collapses the panel so the key rows fit
                            // below it, keeping a band of live results up.
                            compact = state.mediaSearchActive,
                            headerActions = {
                                GifHeaderSearchBar(state, stickers, onMediaQueryTap)
                            },
                        ) {
                            GifPanel(
                                state = state,
                                stickers = stickers,
                                onQueryTap = onMediaQueryTap,
                                onRetry = onMediaRetry,
                                onSelect = onGifSelect,
                                onSourceSelect = onGifSourceSelect,
                                onOpenToolSettings = onOpenToolSettings,
                                fullBleed = true,
                                onCategorySelect = onGifCategorySelect,
                                onLongPress = onMediaLongPress,
                                onPackFilter = onStickerPackFilter,
                                onSaveToPack = onStickerSaveToPack,
                                onCopy = onMediaCopy,
                                onReport = onMediaReport,
                                onDismissAction = onMediaActionDismiss,
                                onOpenRoute = onOpenRoute,
                            )
                        }
                    } else {
                        GifPanel(
                            state = state,
                            stickers = stickers,
                            onQueryTap = onMediaQueryTap,
                            onRetry = onMediaRetry,
                            onSelect = onGifSelect,
                            onSourceSelect = onGifSourceSelect,
                            onOpenToolSettings = onOpenToolSettings,
                            onCategorySelect = onGifCategorySelect,
                            onLongPress = onMediaLongPress,
                            onPackFilter = onStickerPackFilter,
                            onSaveToPack = onStickerSaveToPack,
                            onCopy = onMediaCopy,
                            onReport = onMediaReport,
                            onDismissAction = onMediaActionDismiss,
                            onOpenRoute = onOpenRoute,
                        )
                    }
                }
                PanelMode.WEB_SEARCH -> FullBleedTool(
                    state, title = "",
                    onClose = { onPanelChange(PanelMode.WEB_SEARCH) },
                    compact = state.mediaSearchActive,
                    headerActions = {
                        MediaHeaderSearchBar(
                            state = state,
                            placeholder = stringResource(R.string.ime_web_search_hint),
                            onQueryTap = onMediaQueryTap,
                            onClear = onMediaQueryClear,
                            attribution = stringResource(R.string.ime_search_attribution_brave)
                                .takeIf { ToolApiKeys.hasSearchProvider(state.settings) },
                        )
                    },
                ) {
                    WebSearchPanel(
                        state = state,
                        onRetry = onMediaRetry,
                        onResult = onWebResult,
                        onOpen = onWebResultOpen,
                        onOpenToolSettings = onOpenToolSettings,
                    )
                }
                PanelMode.IMAGE_SEARCH -> FullBleedTool(
                    state, title = "",
                    onClose = { onPanelChange(PanelMode.IMAGE_SEARCH) },
                    compact = state.mediaSearchActive,
                    headerActions = {
                        MediaHeaderSearchBar(
                            state = state,
                            placeholder = stringResource(R.string.ime_image_search_hint),
                            onQueryTap = onMediaQueryTap,
                            onClear = onMediaQueryClear,
                            attribution = stringResource(R.string.ime_search_attribution_brave)
                                .takeIf { ToolApiKeys.hasSearchProvider(state.settings) },
                        )
                        SearchByPhotoButton { onPanelChange(PanelMode.CAMERA) }
                    },
                ) {
                    ImageSearchPanel(
                        state = state,
                        onRetry = onMediaRetry,
                        onResult = onImageResult,
                        onResultLink = onImageResultLink,
                        onOpenToolSettings = onOpenToolSettings,
                    )
                }
                PanelMode.WIKIPEDIA -> WikipediaPanelHost(
                    state = state,
                    onClose = { onPanelChange(PanelMode.WIKIPEDIA) },
                    onQueryTap = onMediaQueryTap,
                    onRetry = onMediaRetry,
                    onOpen = onWikiOpen,
                    onBack = onWikiBack,
                    onLoadLinks = onWikiLoadLinks,
                    onLoadFull = onWikiLoadFull,
                    onInsert = onToolInsert,
                )
                PanelMode.SYMBOLS -> {
                    // Category selection lives up here so the header chips
                    // and the grid share it.
                    val recents = state.settings.symbolRecents
                    // Tracked by id, never by the drawn name: the chips resolve
                    // their own wording, and a translated name would not match.
                    var symbolCategory by rememberSaveable(recents.isNotEmpty()) {
                        mutableStateOf(
                            if (recents.isNotEmpty()) SYMBOL_RECENTS_ID
                            else SymbolCatalog.categories.first().id
                        )
                    }
                    FullBleedTool(
                        state, title = "",
                        onClose = { onPanelChange(PanelMode.SYMBOLS) },
                        headerActions = {
                            SymbolCategoryChips(
                                state = state,
                                selected = symbolCategory,
                                onSelect = { symbolCategory = it },
                            )
                        },
                    ) {
                        SymbolsPanel(
                            state,
                            onSymbolInsert,
                            symbolCategory,
                            onSelectCategory = { symbolCategory = it },
                        )
                    }
                }
                PanelMode.CALCULATOR -> FullBleedTool(
                    state, stringResource(R.string.ime_tool_calculator),
                    onClose = { onPanelChange(PanelMode.CALCULATOR) },
                ) { CalculatorPanel(state, onToolInsert, converter) }
                PanelMode.UNIT_CONVERT -> FullBleedTool(
                    state, stringResource(R.string.ime_unit_convert_title),
                    onClose = { onPanelChange(PanelMode.UNIT_CONVERT) },
                    extraHeight = 120.dp,
                ) { UnitConverterPanel(state, onToolInsert, converter, onToolPrefillConsumed) }
                PanelMode.CURRENCY -> FullBleedTool(
                    state, stringResource(R.string.ime_tool_currency),
                    onClose = { onPanelChange(PanelMode.CURRENCY) },
                    extraHeight = 120.dp,
                ) {
                    CurrencyPanel(
                        state = state,
                        callbacks = converter,
                        onInsert = onToolInsert,
                        onPrefillConsumed = onToolPrefillConsumed,
                    )
                }
                PanelMode.QR_GEN -> QrGeneratorPanel(state, onQrSend)
                PanelMode.FIND_REPLACE -> FindReplacePanel(state, toolHold.findReplace)
                PanelMode.LEARN_FROM_TEXT -> LearnFromTextPanel(
                    state = state,
                    callbacks = toolHold.learnFromText,
                    onClose = { onPanelChange(PanelMode.LEARN_FROM_TEXT) },
                )
                PanelMode.PASSWORD_GEN -> FullBleedTool(
                    state, title = "",
                    onClose = { onPanelChange(PanelMode.PASSWORD_GEN) },
                    // Not full-bleed: the toolbar stays reachable above the
                    // panel, so it collapses to the key-rows height instead of
                    // swallowing the toolbar's rows.
                    compact = true,
                    compactHeight = keyRowsHeight(state),
                    // The toolbar above the panel already has the way back.
                    showBack = false,
                    headerActions = {
                        val passphraseMode = state.settings.passwordGenerator.pwPassphraseMode
                        // The ring's CHIPS region: the two mode tabs.
                        PanelFocusTarget(
                            panel = PanelMode.PASSWORD_GEN,
                            region = FocusRegion.CHIPS,
                            count = 2,
                            columns = 2,
                        ) { index ->
                            onPwSetting(PwSettingAction.PassphraseMode(index == 1))
                        }
                        val focusedTab = state.focusedIndex(FocusRegion.CHIPS)
                        Spacer(Modifier.width(4.dp))
                        ToolPanelChip(
                            stringResource(R.string.ime_tool_password_gen),
                            selected = !passphraseMode,
                            modifier = Modifier.focusRing(focusedTab == 0),
                        ) {
                            onPwSetting(PwSettingAction.PassphraseMode(false))
                        }
                        Spacer(Modifier.width(6.dp))
                        ToolPanelChip(
                            stringResource(R.string.ime_password_tab_passphrase),
                            selected = passphraseMode,
                            modifier = Modifier.focusRing(focusedTab == 1),
                        ) {
                            onPwSetting(PwSettingAction.PassphraseMode(true))
                        }
                        Spacer(Modifier.weight(1f))
                    },
                ) { PasswordPanel(state, onPwSetting, onToolInsert) }
                PanelMode.TYPING_TEST -> FullBleedTool(
                    state = state,
                    title = stringResource(R.string.ime_tool_typing_test),
                    onClose = { onPanelChange(PanelMode.TYPING_TEST) },
                    // A running test shares the window with the key rows —
                    // the user is typing on them — so the panel collapses
                    // the way the media search boxes do. The results screen
                    // needs no keys and takes the full height back.
                    compact = state.typingTest.result == null,
                    compactHeight = 156.dp,
                    headerActions = {
                        typingHeaderBest(
                            LocalContext.current,
                            state.settings.typingTest,
                            state.language.id,
                        )?.let { best ->
                            Text(
                                best,
                                color = LocalKbTheme.current.secondaryText,
                                fontSize = 11.sp,
                                modifier = Modifier.padding(end = 8.dp),
                            )
                        }
                        // Only on the results screen: during a run the keys
                        // *are* the test, and an arrow summoning a ring there
                        // would score as a miss.
                        PanelFocusTarget(
                            panel = PanelMode.TYPING_TEST,
                            region = FocusRegion.ACTIONS,
                            count = if (state.typingTest.result != null) 1 else 0,
                            columns = 1,
                        ) { onTypingTestAction(TypingTestAction.Restart) }
                        ToolPanelChip(
                            stringResource(R.string.ime_typing_test_restart),
                            modifier = Modifier.focusRing(
                                state.focusedIndex(FocusRegion.ACTIONS) == 0 &&
                                    state.typingTest.result != null,
                            ),
                        ) {
                            onTypingTestAction(TypingTestAction.Restart)
                        }
                    },
                ) { TypingTestPanel(state, onTypingTestAction) }
                PanelMode.AI -> FullBleedTool(
                    state = state,
                    // With the chat on offer the header holds the mode switch,
                    // and that is the panel's name: there is no room for both.
                    title = if (state.aiChat.available) "" else stringResource(R.string.ime_tool_ai),
                    onClose = { onPanelChange(PanelMode.AI) },
                    // Reasoning models stream their think block into the same
                    // box as the answer, so that mode needs the taller window,
                    // and so does a conversation, which is read more than it is
                    // glanced at (#280); otherwise the panel stays at the
                    // normal keyboard height.
                    extraHeight = when {
                        state.aiChatShown -> AiChatExtraHeight
                        state.settings.ai.showThinking -> 160.dp
                        else -> 0.dp
                    },
                    // The Custom instruction and the chat's composer both type
                    // on the key rows, so the panel collapses to leave room for
                    // them below. The chat keeps more: the newest messages stay
                    // in sight above the composer while the next one is typed.
                    compact = state.aiCustomInputActive || state.aiChatComposing,
                    compactHeight = if (state.aiChatComposing) AiChatCompactHeight else 132.dp,
                    headerActions = {
                        val ai = state.ai
                        val chatMode = state.aiChatShown
                        val ready = !chatMode && ai is AiUi.Ready && !ai.generating
                        // The mode switch takes the ring's first two slots
                        // whenever it is drawn, and everything after it moves up.
                        val base = if (state.aiChat.available) 2 else 0
                        val own = when {
                            chatMode -> AiChatHeaderActionCount
                            ready -> 3
                            else -> 0
                        }
                        // The ring's ACTIONS region: the switch, then the
                        // chat's three or Replace/Insert/Retry when there is a
                        // result, and always the settings circle last.
                        PanelFocusTarget(
                            panel = PanelMode.AI,
                            region = FocusRegion.ACTIONS,
                            count = base + own + 1,
                            columns = base + own + 1,
                        ) { index ->
                            val slot = index - base
                            when {
                                index < base -> capture.onAiChat(AiChatAction.SetMode(chat = index == 1))
                                slot >= own -> onOpenToolSettings(ToolbarTool.AI)
                                chatMode -> activateAiChatHeader(slot, capture.onAiChat)
                                slot == 0 -> onAiReplace()
                                slot == 1 -> onAiInsert()
                                slot == 2 -> onAiRetry()
                            }
                        }
                        val focusedAction = state.focusedIndex(FocusRegion.ACTIONS)
                        if (state.aiChat.available) AiModeSwitch(state, focusedAction, capture.onAiChat)
                        if (chatMode) {
                            AiChatHeaderActions(state, focusedAction, base, capture.onAiChat)
                        } else if (state.aiChat.available) {
                            // No title to push them there, so the actions'
                            // own controls are sent to the right by hand.
                            Spacer(Modifier.weight(1f))
                        }
                        if (ready) {
                            ToolPanelChip(
                                stringResource(R.string.ime_ai_replace),
                                selected = true,
                                modifier = Modifier.focusRing(focusedAction == base),
                            ) { onAiReplace() }
                            Spacer(Modifier.width(5.dp))
                            ToolPanelChip(
                                stringResource(R.string.ime_ai_insert),
                                modifier = Modifier.focusRing(focusedAction == base + 1),
                            ) { onAiInsert() }
                            Spacer(Modifier.width(5.dp))
                            ToolPanelChip(
                                "↻",
                                modifier = Modifier.focusRing(focusedAction == base + 2),
                            ) { onAiRetry() }
                            Spacer(Modifier.width(5.dp))
                        }
                        ToolCircle(
                            slot = IconSlots.forTool(ToolbarTool.SETTINGS),
                            description = stringResource(R.string.ime_ai_settings_desc),
                            active = false,
                            modifier = Modifier.focusRing(focusedAction == base + own, CircleShape),
                        ) { onOpenToolSettings(ToolbarTool.AI) }
                    },
                ) {
                    if (state.aiChatShown) {
                        AiChatPanel(state, capture.onAiChat, onOpenToolSettings)
                    } else AiPanel(
                        state = state,
                        onAction = onAiAction,
                        onRetry = onAiRetry,
                        onRunCustom = onAiRunCustom,
                        onPickModel = onAiPickModel,
                        onToggleStripMarkdown = onAiToggleStripMarkdown,
                        onSetShowDiff = onAiSetShowDiff,
                        onReport = onAiReport,
                        onOpenToolSettings = onOpenToolSettings,
                    )
                }
                PanelMode.MODES -> ModesPanel(
                    state, onModeSelect,
                    onOpenSettings = { onOpenToolSettings(ToolbarTool.MODES) },
                )
                // With a hardware keyboard and toolbar-only mode on, the keys
                // step aside and just the toolbar remains — tools stay one tap
                // away while the physical keyboard does the typing.
                PanelMode.NONE -> if (
                    !(state.hardwareKeyboardPresent && state.settings.toolbarBehavior.onlyWithHardwareKeyboard)
                ) {
                    KeyRows(
                        state, onKey, onText, onGesture, onGesturePreview, onCursorMove, onLayoutSelect,
                        onGestureWords = onGestureWords,
                        onKeyboardHandwritingStroke = onKeyboardHandwritingStroke,
                        onKeyTouch = onKeyTouch,
                        onTouchKeys = onTouchKeys,
                    )
                }
            }
        }
            // The key rows come back under a panel whenever one of the
            // keyboard's own fields has taken the keys — otherwise a focused
            // field would have nothing on screen to type into it — and with
            // them, that field's own suggestion strip (#161).
            //
            // One block, not the eight hand-copied ones this replaced: every
            // one of them passed the short argument list, so glide's multi-word
            // callback, the touch model's key centres and keyboard handwriting
            // all quietly stopped at the panel's edge. They are all here now,
            // exactly as [PanelMode.NONE] passes them.
            // …and always under the grammar strip, which follows the field live.
            if (keyRowsUnderPanel(state) || state.panel == PanelMode.GRAMMAR) {
                // The suggestions go where the keyboard's suggestions always
                // go — the row directly above the keys, in the same slots and
                // at the same size — so a word offered for a query reads
                // exactly like one offered for a sentence.
                if (state.typingTestActive && state.settings.typingTest.suggestions) {
                    TypingTestStrip(state, onTypingTestAction)
                } else if (captureStripShown(state)) {
                    CaptureStrip(state, capture)
                }
                KeyRows(
                    state, onKey, onText, onGesture, onGesturePreview, onCursorMove, onLayoutSelect,
                    onGestureWords = onGestureWords,
                    onKeyboardHandwritingStroke = onKeyboardHandwritingStroke,
                    onKeyTouch = onKeyTouch,
                    onTouchKeys = onTouchKeys,
                )
            }
            // The rows the user put under the keys. Every row's own gate
            // (full-bleed, lock screen, its setting) applies here exactly as
            // above, so a panel that absorbs the rows' height absorbs these
            // too and the keyboard never changes height.
            for (row in barRowsBelowKeys(barOrder)) BarRowSlot(row)
        }
        drag.dragging?.let { tool ->
            val kb = LocalKbTheme.current
            val ghost = drag.position - bodyOrigin
            // The thing under the finger is the thing that will land, in the
            // shape it will land in. Over a pill toolbox that is a full-width
            // pill; over the toolbar it is the bar's circle, because the bar
            // draws circles whatever the toolbox does. Between the two it
            // MORPHS — width, corner and name together — rather than swapping
            // shapes on the frame the finger crosses the bar's edge, which
            // read as the tool blinking into something else halfway through
            // one gesture.
            val pillToolbox = state.panel == PanelMode.TOOLBOX &&
                state.settings.toolbox.layout == ToolboxLayout.PILLS
            val asPill = pillToolbox && drag.barSlot == null
            // As wide as the cell it is heading for, so the preview is the real
            // footprint; the cell size is whatever the grid last measured, and
            // a fallback covers the frame before it has.
            val cellWidth = drag.toolboxCellSize.width
            val pillWidth = with(LocalDensity.current) {
                if (cellWidth > 0f) cellWidth.toDp() else 160.dp
            }
            val reduced = state.settings.reduceMotion
            val morphDp: AnimationSpec<Dp> = if (reduced) snap() else ghostMorphSpring()
            val morphFloat: AnimationSpec<Float> = if (reduced) snap() else ghostMorphSpring()
            // One box, two looks. The height never changes (the circle and the
            // pill are both [GhostSize] tall), so the whole morph is the width,
            // the corner radius and the name fading out as the room for it goes.
            val width by animateDpAsState(
                if (asPill) pillWidth else GhostSize,
                animationSpec = morphDp,
                label = "ghostWidth",
            )
            val corner by animateDpAsState(
                if (asPill) pillRadius() else GhostSize / 2,
                animationSpec = morphDp,
                label = "ghostCorner",
            )
            // The name goes first and comes back last, so it is never caught
            // half-clipped by a box that is still narrowing around it.
            val labelAlpha by animateFloatAsState(
                if (asPill) 1f else 0f,
                animationSpec = morphFloat,
                label = "ghostLabel",
            )
            Box(
                modifier = Modifier
                    .offset {
                        IntOffset(
                            (ghost.x - width.toPx() / 2f).roundToInt(),
                            (ghost.y - GhostSize.toPx() / 2f).roundToInt(),
                        )
                    }
                    .size(width = width, height = GhostSize)
                    .clip(RoundedCornerShape(corner))
                    .background(kb.toolCircleActive, RoundedCornerShape(corner)),
                contentAlignment = Alignment.CenterStart,
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxSize()
                        // The icon sits (GhostSize - ToolIconSize) / 2 from the
                        // start, which is dead centre once the box is a circle —
                        // so the icon holds still and the pill grows out from
                        // behind it rather than sliding under the finger.
                        .padding(start = (GhostSize - ToolIconSize) / 2),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    SlotIcon(
                        IconSlots.forTool(tool),
                        contentDescription = null,
                        modifier = Modifier.size(ToolIconSize),
                        tint = kb.toolCircleActiveIcon,
                    )
                    if (labelAlpha > 0.01f) {
                        Text(
                            toolLabel(tool),
                            fontSize = toolboxLabelSize(state),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            color = kb.toolCircleActiveIcon,
                            modifier = Modifier
                                .weight(1f)
                                .padding(start = 8.dp, end = 10.dp)
                                .graphicsLayer { alpha = labelAlpha },
                        )
                    }
                }
            }
        }
        // Names the scope a tool drag lands in — a mode's own arrangement or
        // the one shared by every app. It never clashes with the picker overlay
        // below: a picker cannot be armed mid-drag.
        if (drag.dragging != null) {
            DragScopeLabel(
                state = state,
                drag = drag,
                bodyOrigin = bodyOrigin,
                bodyHeightPx = bodyHeightPx,
                // Horizontally centred; the pill picks its own vertical spot.
                modifier = Modifier.align(Alignment.TopCenter),
            )
        }
        // Last in the Box, so the legend and its pill float over the keyboard
        // instead of pushing the keys down — arming must not resize it.
        ToolPickerOverlay(
            state,
            onClose = onPickerDismiss,
            modifier = Modifier.align(Alignment.TopCenter),
        )
        // Centred, not at the top: the browse is momentary and modal in
        // spirit, and the middle of the keys is where the eye already is.
        // Shares [onPickerDismiss] with the legend above — the service's
        // handler closes whichever hardware overlay is up, and only one
        // ever is.
        LanguageSwitchOverlay(
            state,
            onPick = { layoutId ->
                onLayoutSelect(layoutId)
                onPickerDismiss()
            },
            onDismiss = onPickerDismiss,
            modifier = Modifier.align(Alignment.Center),
        )
        // Down in the corner, not up by the strip: at the top it sat over the
        // first toolbar buttons and hid the very badges the arming had just put
        // there. The bottom-right of the key grid is the emptiest corner.
        PickerHelpPill(state, modifier = Modifier.align(Alignment.BottomEnd))
        // Last of all: a selection's handles and bar ride over everything,
        // the key rows included, since a field's handle can hang over them.
        selectionOverlay?.let { SelectionOverlay(it, Modifier.matchParentSize()) }
    }
}

/**
 * The body's panel slot: [panel]'s content, faded in over the board when a panel
 * opens or one panel gives way to another.
 *
 * Only a panel fades. The keys ([PanelMode.NONE]) come back at full strength the
 * instant a panel closes, because an alpha on them is exactly what was reverted
 * before: a see-through keyboard with the app's text showing through it. And the
 * fade starts from nothing in the very composition that brings the panel in
 * (the value is born with it, keyed on the panel), so its first frame is never
 * drawn at full strength and dimmed a frame later.
 *
 * A Column, so every panel keeps the ColumnScope it was written against and its
 * rows still stack exactly as they did straight in the body's own Column (none
 * of them takes a weight there). ModulateAlpha applies the fade to what is drawn
 * rather than through an offscreen buffer the size of the slot, which would clip
 * anything a panel draws past its own edge for the length of the fade.
 */
@Composable
private fun PanelEnterFade(
    panel: PanelMode,
    reduceMotion: Boolean,
    roomBelow: Dp = 0.dp,
    content: @Composable ColumnScope.() -> Unit,
) {
    key(panel) {
        val fades = panel != PanelMode.NONE && !reduceMotion
        val fade = remember { Animatable(if (fades) 0f else 1f) }
        LaunchedEffect(fade) {
            fade.animateTo(1f, tween(PanelEnterMs, easing = LinearOutSlowInEasing))
        }
        Column(
            modifier = if (panel == PanelMode.NONE) {
                Modifier
            } else {
                Modifier
                    .leaveRoomBelow(roomBelow)
                    .graphicsLayer {
                        alpha = fade.value
                        compositingStrategy = CompositingStrategy.ModulateAlpha
                    }
            },
            content = content,
        )
    }
}

/**
 * What the key rows under an open panel need below it: the rows, and the
 * strip over them. Zero when the panel has no keys under it.
 */
private fun panelRoomBelow(state: KeyboardUiState, panel: PanelMode): Dp {
    if (panel == PanelMode.NONE) return 0.dp
    if (!keyRowsUnderPanel(state) && state.panel != PanelMode.GRAMMAR) return 0.dp
    val strip = when {
        state.typingTestActive && state.settings.typingTest.suggestions -> state.settings.toolbarHeightDp.dp
        else -> captureStripHeight(state)
    }
    return keyRowsHeight(state) + strip
}

/**
 * Measures the panel against what is left of the window once [below] is
 * paid for, so a panel that asked for more than the screen has comes up
 * short, never the key rows under it (#352).
 *
 * The panels ask in fixed dp, fitted beforehand by [fitToolPanelHeight]
 * against a share of the screen. That guess cannot see everything the window
 * really has to hold — the key preview's band, the navigation bar, a big
 * font — and the column hands its children what is left in order: the panel
 * came first and took its height whole, so the keys were measured into
 * whatever remained. On the AI chat, which asks for the most, that was the
 * bottom rows squashed too thin to type on. The column already tells the
 * panel how much room remains; taking the rows off that is the whole fix.
 */
private fun Modifier.leaveRoomBelow(below: Dp): Modifier =
    if (below <= 0.dp) {
        this
    } else {
        layout { measurable, constraints ->
            val room = if (constraints.hasBoundedHeight) {
                (constraints.maxHeight - below.roundToPx()).coerceAtLeast(0)
            } else {
                constraints.maxHeight
            }
            val placeable = measurable.measure(
                constraints.copy(minHeight = constraints.minHeight.coerceAtMost(room), maxHeight = room),
            )
            layout(placeable.width, placeable.height) { placeable.place(0, 0) }
        }
    }

/** What a selection's bar can reach (#352): the AI chat's actions, and whether Ask AI is on offer. */
@Composable
private fun selectionTools(state: KeyboardUiState, onAiChat: (AiChatAction) -> Unit): SelectionTools {
    // Not on the lock screen, where the chat is not offered either.
    val askAi = !state.deviceLocked && ToolbarTool.AI in usableTools(state.settings)
    return remember(onAiChat, askAi) { SelectionTools(onAiChat, askAi) }
}

/** How long a panel takes to fade in over the board. */
private const val PanelEnterMs = 140

/** Gap the drag-scope pill keeps from the toolbar and from the keyboard's edge. */
private val DragScopeGap = 4.dp

/**
 * How close the finger may come to the pill before it moves out of the way.
 * Wide enough to clear the 44dp puck drawn under the finger.
 */
private val DragScopeDodgeMargin = 32.dp

/**
 * Floating pill shown for the whole of a tool drag, telling the user where
 * the new arrangement is saved: the active mode's own tool order (when mode
 * drag-edits are on and the mode carries one — the same rule as the
 * service's `toolOrderOwner`) or the global order every app shares.
 *
 * It parks itself immediately *below* the toolbar rather than over it. The
 * toolbar is the thing a tool drag is rearranging, and a pill sitting on top of
 * it hid the very slots the drop was aiming at — which tools were already
 * pinned, and in what order. So the row it names is the one row it never
 * covers. Below that it also dodges the finger: a drag working the top of the
 * toolbox grid would otherwise be dragging straight under the pill, so it
 * swaps to the far end of the keyboard until the finger leaves.
 *
 * "Below" is not always possible (#136): the row order can put the toolbar
 * under the keys, and there the spot below it is off the keyboard, so the
 * clamp to the keyboard's floor put the pill straight back over the bar. A
 * toolbar with no room under it gets the pill parked *above* it instead, and
 * the finger dodge then goes to the top of the keyboard rather than the
 * bottom — whichever end is not the toolbar's.
 */
@Composable
private fun DragScopeLabel(
    state: KeyboardUiState,
    drag: ToolDragController,
    /** Keyboard-body origin in root coordinates; the drag reports in root. */
    bodyOrigin: Offset,
    bodyHeightPx: Int,
    modifier: Modifier = Modifier,
) {
    val kb = LocalKbTheme.current
    val mode = state.settings.keyboardModes
        .firstOrNull { it.id == state.activeModeId }
        ?.takeIf { state.settings.modeToolOrderEdits && it.ownsToolOrder }
    var labelHeightPx by remember { mutableIntStateOf(0) }
    val density = LocalDensity.current
    val gapPx = with(density) { DragScopeGap.roundToPx() }
    val dodgePx = with(density) { DragScopeDodgeMargin.toPx() }
    // Resting spot: just clear of the toolbar's bottom edge, or of its top edge
    // when there is no keyboard left under it. Measured rather than assumed —
    // the toolbar is not always the top row (see barOrder), and its height is
    // a theme setting.
    val floorY = (bodyHeightPx - labelHeightPx - gapPx).coerceAtLeast(0)
    val bar = drag.toolbarBounds
    val below = bar?.let { (it.bottom - bodyOrigin.y).roundToInt() + gapPx }?.coerceAtLeast(0) ?: 0
    val above = bar?.let { (it.top - bodyOrigin.y).roundToInt() - gapPx - labelHeightPx }
    // Room under the bar for the whole pill; otherwise it goes over the bar,
    // and the dodge swaps ends with it.
    val fitsBelow = above == null || labelHeightPx == 0 || below <= floorY
    val restY = if (fitsBelow) below.coerceAtMost(floorY) else above.coerceAtLeast(0)
    val awayY = if (fitsBelow) floorY else 0
    val fingerY = drag.position.y - bodyOrigin.y
    val crowded = labelHeightPx > 0 &&
        fingerY > restY - dodgePx && fingerY < restY + labelHeightPx + dodgePx
    val targetY = if (crowded) awayY else restY
    // Which end the pill belongs at depends on its own height, and it cannot be
    // measured before it is laid out — so the first pass computes a spot with a
    // height of zero, and if the finger is up by the toolbar the pass after that
    // corrects it to the other end of the keyboard. Animating that correction is
    // what made the pill appear at the top and then travel down for no reason a
    // user could see. So it stays invisible and snaps until it has been measured
    // once, and fades in already where it belongs; the dodge animates only from
    // there on, when there is a real move to show.
    var placed by remember { mutableStateOf(false) }
    LaunchedEffect(labelHeightPx > 0) {
        if (labelHeightPx > 0) placed = true
    }
    val y by animateIntAsState(
        targetValue = targetY,
        animationSpec = if (!placed || state.settings.reduceMotion) {
            snap()
        } else {
            tween(ToolbarMotionMs)
        },
        label = "dragScopeY",
    )
    val appear by animateFloatAsState(
        targetValue = if (placed) 1f else 0f,
        animationSpec = if (state.settings.reduceMotion) snap() else tween(ToolbarMotionMs),
        label = "dragScopeAppear",
    )
    Text(
        text = if (mode != null) {
            stringResource(R.string.ime_toolbox_drag_scope_mode, mode.name)
        } else {
            stringResource(R.string.ime_toolbox_drag_scope_global)
        },
        fontSize = 11.sp,
        color = kb.toolCircleActiveIcon,
        maxLines = 1,
        modifier = modifier
            .offset { IntOffset(0, y) }
            .onSizeChanged { labelHeightPx = it.height }
            // Above the background so the pill fades as one piece, and outside
            // the offset so the fade's buffer travels with it (see the note on
            // the toolbar's tool cells).
            .graphicsLayer { alpha = appear }
            .background(kb.toolCircleActive, RoundedCornerShape(12.dp))
            .padding(horizontal = 10.dp, vertical = 3.dp),
    )
}

// ---- key grid ----

/**
 * The comet trail behind a gliding finger.
 *
 * The points live in plain arrays that Compose cannot observe, because a stroke
 * appends one every touch report — up to 240 a second. Holding them in snapshot
 * state and reading them from the composable body, which is what this replaced,
 * recomposed the whole key grid at that rate and allocated a fresh list per
 * sample. The rule the rest of the keyboard already follows applies here too:
 * gesture state is never read at composition scope.
 *
 * So the reads are split by phase:
 *
 *  - [revision] changes on every sample and every frame. Read it from a **draw**
 *    lambda and only the draw is invalidated. [sampleCount] takes it as an
 *    argument so a call site cannot forget to subscribe.
 *  - [headX]/[headY] follow the fingertip and are read from a **placement**
 *    lambda (`Modifier.offset`), so the floating word pill re-places without
 *    recomposing.
 *  - [visible] and [released] are ordinary snapshot state, but they flip twice
 *    a stroke rather than hundreds of times, so the body may read them to decide
 *    whether the trail and the pill exist at all.
 */
/**
 * The ambiguity picker's live state: which words are on offer, where they are on
 * screen, which one the finger is currently over, and whether it has dropped
 * out of the picker altogether.
 *
 * Split the same way [GlideTrail] is, and for the same reason. [words],
 * [hover] and [cancelling] are snapshot state because they change a handful of
 * times per stroke and the popup has to redraw when they do. [rects] is a plain
 * array written by the targets' own layout and read from the pointer loop,
 * because a rect that lived in snapshot state would recompose the keyboard at
 * touch-report rate for a hit test that never needed the composition to know
 * anything.
 *
 * The stroke is frozen from the moment the picker opens until the finger lifts
 * (#96), so there is no "opened earlier this stroke" to remember: [isOpen] is
 * the whole story, and [verdict] is what the lift commits.
 */
@Stable
internal class GlidePickerState {

    /** The words on offer, best first. Empty when the picker is not showing. */
    var words by mutableStateOf<List<String>>(emptyList())
        private set

    /** Index of the target the finger is over, or -1. */
    var hover by mutableIntStateOf(-1)
        private set

    /**
     * The finger has dropped more than a key below the anchor: the targets dim
     * and a lift now types nothing. Sliding back up clears it.
     */
    var cancelling by mutableStateOf(false)
        private set

    /** Where the targets landed, in the grid's coordinate space. */
    val rects = Array(MAX_TARGETS) { Rect.Zero }

    /** Where the picker is anchored: where the finger stopped when it opened. */
    var anchorX = 0f
        private set
    var anchorY = 0f
        private set

    /**
     * The height of the key the finger stopped on, which is the unit the
     * targets are spaced in: one of these above the finger for the near
     * targets, two for the middle one. Zero until the picker has opened over a
     * key, and the overlay falls back to a target's own height there.
     */
    var anchorKeyPx = 0f
        private set

    /** True while the picker is up, which is from its open until the lift. */
    val isOpen: Boolean
        get() = words.isNotEmpty()

    /**
     * Puts the first [limit] of [choices] on offer, anchored at [x], [y], on a
     * key [keyPx] tall — the spacing unit for the targets, and the same height
     * the cancel zone is measured in.
     */
    fun open(choices: List<String>, limit: Int, x: Float, y: Float, keyPx: Float = 0f) {
        words = choices.take(limit.coerceIn(MIN_TARGETS, MAX_TARGETS))
        anchorX = x
        anchorY = y
        anchorKeyPx = keyPx
        hover = -1
        cancelling = false
        rects.fill(Rect.Zero)
    }

    /** Ends the picker and forgets the stroke, ready for the next one. */
    fun close() {
        if (words.isNotEmpty()) words = emptyList()
        hover = -1
        cancelling = false
        rects.fill(Rect.Zero)
    }

    /** Records where target [index] was laid out. */
    fun place(index: Int, rect: Rect) {
        if (index in 0 until MAX_TARGETS) rects[index] = rect
    }

    /** The target containing [x], [y], or -1. Called from the pointer loop. */
    fun targetAt(x: Float, y: Float): Int {
        for (i in words.indices) {
            if (rects[i].contains(Offset(x, y))) return i
        }
        return -1
    }

    /**
     * One move while open. Keeps [hover] and [cancelling] current, writing
     * snapshot state only on a real change — this runs per touch report, and
     * crossing between targets should recompose the popup while moving within
     * one should not. Returns true when the finger has just *arrived* on a
     * target, which is when a haptic tick is due, and never for a move within
     * one. Below the cancel line nothing is hovered, however the rectangles
     * fall.
     */
    fun track(x: Float, y: Float, cancelBelowPx: Float): Boolean {
        val below = y - anchorY > cancelBelowPx
        if (below != cancelling) cancelling = below
        val over = if (below) -1 else targetAt(x, y)
        val entered = over >= 0 && over != hover
        if (over != hover) hover = over
        return entered
    }

    /** The word the finger is over, or null. */
    fun picked(): String? = words.getOrNull(hover)

    /**
     * What a lift commits: nothing from the cancel zone, the hovered word from
     * a target, and otherwise the decoder's own leader — which is also the
     * answer from a picker that never opened, so the lift asks unconditionally.
     */
    fun verdict(): GlideVerdict = when {
        cancelling -> GlideVerdict.Cancel
        else -> picked()?.let { GlideVerdict.Word(it) } ?: GlideVerdict.Leader()
    }

    companion object {
        /** Fewer than two words is nothing to choose between. */
        const val MIN_TARGETS = 2

        /** The setting's ceiling, so the rectangles never run out. */
        val MAX_TARGETS = GlidePickerChoicesRange.last
    }
}

@Stable
internal class GlideTrail {

    private var xs = FloatArray(INITIAL_CAPACITY)
    private var ys = FloatArray(INITIAL_CAPACITY)
    private var ts = LongArray(INITIAL_CAPACITY)
    private var count = 0

    /** Bumped by every append, expiry and frame tick. Draw-phase subscription. */
    var revision by mutableIntStateOf(0)
        private set

    /** Set while the trail has anything to draw; the body may read this. */
    var visible by mutableStateOf(false)
        private set

    /**
     * The trail is fading in place: the finger has lifted, or the ambiguity
     * picker has opened and frozen the stroke under it (#96). Idempotent, so
     * the lift's own release after a frozen stroke is harmless.
     */
    var released by mutableStateOf(false)
        private set

    /**
     * The trail is a rubber band from [startX], [startY] to the head rather
     * than the path the finger took — the modifier chord drag of issue #67.
     * Flips once per stroke, so the body may read it.
     */
    var straight by mutableStateOf(false)
        private set

    /**
     * The stroke still looks like an octopus flick, so the trail draws as one
     * even line straight up from where the finger landed (discussion #102).
     *
     * Unlike [straight] this flips *back*: a stroke is a flick until it leans
     * or wanders too far, and then it is a glide. That is the whole point of
     * drawing it — the line is the keyboard saying which of the two it thinks
     * is happening, while there is still time to change it. So the samples are
     * kept either way, and this only decides how they are drawn; a trail that
     * threw its path away would have nothing to become a comet from.
     *
     * Drawn vertical rather than to the fingertip, because the gesture is
     * judged inside a cone: a flick fifteen degrees off is the same flick, and
     * a line that leaned with the finger would suggest an accuracy the test
     * does not ask for.
     */
    var flick by mutableStateOf(false)
        private set

    /** Where a straight trail is anchored, in the key grid's own space. */
    var startX = 0f
        private set

    var startY = 0f
        private set

    /** When a straight trail was let go, which is the clock for its fade. */
    private var releasedAtMs = 0L

    /** Latest frame time, for the age fade. Plain — [revision] carries the invalidation. */
    var nowMs = 0L
        private set

    var headX by mutableFloatStateOf(0f)
        private set

    var headY by mutableFloatStateOf(0f)
        private set

    /**
     * How many live samples there are. Takes [revision] so that reading the
     * count forces a read of the snapshot state that actually changes — the
     * arrays behind it are invisible to Compose, so a call site that skipped
     * the subscription would draw once and then freeze.
     */
    @Suppress("UNUSED_PARAMETER")
    fun sampleCount(revision: Int): Int = count

    fun x(i: Int): Float = xs[i]

    fun y(i: Int): Float = ys[i]

    fun ageAt(i: Int): Long = nowMs - ts[i]

    /** A stroke has taken over from a tap; start a fresh trail. */
    fun begin() {
        count = 0
        released = false
        straight = false
        flick = false
        visible = true
        revision++
    }

    /**
     * A modifier chord drag has taken over: a straight band anchored at [x],
     * [y] rather than a comet (issue #67), which is how Gboard draws the same
     * gesture. It is also the honest picture of it — the chord is the key the
     * finger started on and the key it is over now, and the wandering in
     * between means nothing, so a trail that follows the path says something
     * the gesture does not.
     */
    fun beginLine(x: Float, y: Float) {
        begin()
        straight = true
        flick = false
        startX = x
        startY = y
        headX = x
        headY = y
    }

    /**
     * Whether the stroke still reads as a flick; see [flick].
     *
     * Not `setFlick`: [flick] is a `var` with a private setter, which already
     * claims that JVM signature, so the two are a platform declaration clash
     * and the module does not compile with both.
     */
    fun markFlick(on: Boolean) {
        if (flick == on) return
        flick = on
        revision++
    }

    /** Appends the sample and drops whatever has aged past [keepMs]. */
    fun add(x: Float, y: Float, timeMs: Long, keepMs: Long) {
        nowMs = timeMs
        headX = x
        headY = y
        // The first sample anchors a flick's line, the way beginLine anchors a
        // chord's. A comet never reads these, so recording them costs nothing.
        if (count == 0 && !straight) {
            startX = x
            startY = y
        }
        // A straight trail keeps no path: its two ends are the whole drawing,
        // and ageing samples out from under it would strand the anchor.
        if (straight) {
            revision++
            return
        }
        if (count == xs.size) grow()
        xs[count] = x
        ys[count] = y
        ts[count] = timeMs
        count++
        expire(timeMs, keepMs)
        revision++
    }

    fun release() {
        released = true
        releasedAtMs = nowMs
    }

    /**
     * Advances the fade clock to [now]. Returns false once a released trail has
     * fully expired, which is the frame loop's signal to stop.
     */
    fun tick(now: Long, keepMs: Long): Boolean {
        nowMs = now
        if (released) {
            // A straight band has no samples to expire; it fades whole, and
            // the release stamp is what times it out.
            val done = if (straight) {
                now - releasedAtMs >= keepMs
            } else {
                expire(now, keepMs)
                count == 0
            }
            if (done) {
                visible = false
                revision++
                return false
            }
        }
        revision++
        return true
    }

    /**
     * How alive a straight band is: 1 while the finger is down, fading to 0
     * across [keepMs] after the lift. Takes [revision] for the same reason
     * [sampleCount] does — the fade clock behind it is invisible to Compose.
     */
    @Suppress("UNUSED_PARAMETER")
    fun lineLife(revision: Int, keepMs: Long): Float =
        if (!released) {
            1f
        } else {
            (1f - (nowMs - releasedAtMs) / keepMs.toFloat()).coerceIn(0f, 1f)
        }

    /** Abandons the trail outright — the feature switched off, or the layout changed. */
    fun clear() {
        count = 0
        released = true
        straight = false
        visible = false
        revision++
    }

    private fun expire(now: Long, keepMs: Long) {
        var drop = 0
        while (drop < count && now - ts[drop] > keepMs) drop++
        if (drop == 0) return
        val kept = count - drop
        if (kept > 0) {
            System.arraycopy(xs, drop, xs, 0, kept)
            System.arraycopy(ys, drop, ys, 0, kept)
            System.arraycopy(ts, drop, ts, 0, kept)
        }
        count = kept
    }

    private fun grow() {
        val bigger = xs.size * 2
        xs = xs.copyOf(bigger)
        ys = ys.copyOf(bigger)
        ts = ts.copyOf(bigger)
    }

    private companion object {
        /** ~350 ms of samples at 120 Hz; longer trails grow once and stay grown. */
        const val INITIAL_CAPACITY = 64
    }
}

/** How alive sample [i] is: 1 at the head, 0 once it has aged past [trailMs]. */
internal fun GlideTrail.sampleLife(i: Int, trailMs: Long): Float =
    (1f - ageAt(i) / trailMs.toFloat()).coerceIn(0f, 1f)

/**
 * Half the ribbon's width at sample [i]: [head] under the finger, tapering to
 * [tail] as the sample ages out, which is the comet shape the trail has always
 * drawn — only as a width the geometry uses rather than a stroke width.
 */
internal fun GlideTrail.sampleHalfWidth(
    i: Int,
    trailMs: Long,
    head: Float,
    tail: Float,
): Float = (tail + (head - tail) * sampleLife(i, trailMs)) / 2f

/**
 * The offset from sample [i] to the ribbon's left edge there — negate it for the
 * right edge — placed [half] out along the normal to the path.
 *
 * The normal is taken from the *bisector* of the directions either side of the
 * sample rather than from one segment's own direction, and that is what lets the
 * ribbon be drawn as separate pieces at separate opacities without showing the
 * joins: two neighbouring pieces ask this for the same sample and get the same
 * answer, so they meet on one shared edge instead of overlapping.
 *
 * Neighbours closer than [TRAIL_MIN_STEP_PX] are stepped over rather than
 * normalised — a finger that has stopped reports a stream of samples a fraction
 * of a pixel apart, and dividing by that turns the digitizer's noise into a
 * normal pointing anywhere, which shows as the ribbon flaring sideways wherever
 * the hand paused.
 */
internal fun GlideTrail.sampleEdge(i: Int, count: Int, half: Float): Offset {
    val x = x(i)
    val y = y(i)
    var inX = 0f
    var inY = 0f
    for (j in i - 1 downTo 0) {
        val dx = x - x(j)
        val dy = y - y(j)
        val len = hypot(dx, dy)
        if (len > TRAIL_MIN_STEP_PX) {
            inX = dx / len
            inY = dy / len
            break
        }
    }
    var outX = 0f
    var outY = 0f
    for (j in i + 1 until count) {
        val dx = x(j) - x
        val dy = y(j) - y
        val len = hypot(dx, dy)
        if (len > TRAIL_MIN_STEP_PX) {
            outX = dx / len
            outY = dy / len
            break
        }
    }
    // The two ends of the trail have only one side; a stroke that never moved
    // has neither, and draws nothing.
    if (inX == 0f && inY == 0f) {
        inX = outX
        inY = outY
    }
    if (outX == 0f && outY == 0f) {
        outX = inX
        outY = inY
    }
    var midX = inX + outX
    var midY = inY + outY
    var len = hypot(midX, midY)
    // A path that doubles straight back cancels the pair out. There the
    // incoming direction decides alone, which draws the reversal as a fold
    // rather than as a spike off to one side.
    if (len < TRAIL_MIN_BISECTOR) {
        midX = inX
        midY = inY
        len = hypot(midX, midY)
    }
    if (len == 0f) return Offset.Zero
    return Offset(-midY / len * half, midX / len * half)
}

/**
 * Where every key of the live grid sits, in the compose root's coordinates.
 *
 * The board's gestures needed only the letter *centres* until now — glide
 * decodes against those, see [nearLetterKey] — but the modifier drag of issue
 * #67 has to answer "which key did the finger lift on" for keys that type
 * nothing at all: space, enter, backspace, an arrow. That takes whole cells.
 *
 * Root coordinates rather than the key box's, for the reason the spacebar's
 * rect is stored that way: a key can report its position before the box has
 * reported its own, and subtracting a still-zero origin would strand the rect
 * in absolute space. [keyAt] takes a root point, so the caller lifts the touch
 * with the live origin instead.
 *
 * The generation token is what keeps the table honest across a re-layout. Every
 * key re-reports when the grid changes shape, but nothing tells the table that
 * the rows it holds are the old ones — so the first record under a new token
 * wipes it. Clearing from a `LaunchedEffect` instead would race those
 * positioning callbacks, which is the trap the letter-centre map documents.
 */
internal class KeyRects {

    private val cells = LinkedHashMap<Rect, Key>()
    private var generation: Any? = null

    /** Files [key]'s cell, wiping the table when [gen] says the grid was rebuilt. */
    fun record(gen: Any, key: Key, rect: Rect) {
        if (gen !== generation) {
            cells.clear()
            generation = gen
        }
        cells[rect] = key
    }

    /** The key whose cell holds [point], or null outside the grid. */
    fun keyAt(point: Offset): Key? {
        for ((rect, key) in cells) {
            if (rect.contains(point)) return key
        }
        return null
    }

    /** The cell holding [point], or null outside the grid. Root space, like [keyAt]. */
    fun cellAt(point: Offset): Rect? {
        for (rect in cells.keys) {
            if (rect.contains(point)) return rect
        }
        return null
    }

    /**
     * The cell of the first key that does [action], or null when this grid has
     * none — a layout with no shift key, most of all.
     *
     * Read once as a stroke begins rather than per pointer sample: a glide asks
     * "am I over shift?" of every move it makes (#115), and walking the whole
     * table for that would put a linear scan on the gesture path. A split board
     * has two half-keys for some actions and this answers with the first, which
     * is the left-hand one — the shift key both halves of a split keyboard put
     * under the same thumb.
     */
    fun cellOf(action: KeyAction): Rect? {
        for ((rect, key) in cells) {
            if (key.action == action) return rect
        }
        return null
    }

    /**
     * Every cell the D-pad ring may sit on, in the order the grid reported them.
     *
     * A copy rather than the live map: [KeyGridFocus] walks it on each arrow
     * key, off the composition, while the grid may be filing a new layer's keys
     * into the same table.
     */
    fun focusCells(): List<Pair<Rect, Key>> = cells.map { (rect, key) -> rect to key }
}

/** The modifier this key latches, or null when it is not a Ctrl/Alt/Meta key. */
internal fun Key?.modifierKey(): ModifierKey? = (this?.action as? KeyAction.Mod)?.key

/**
 * Whether a drag off this key is a chord rather than a swipe (issue #67).
 *
 * The three latches and shift. Caps lock is deliberately not one of them: it is
 * a state you leave switched on, so "hold it for one key" is not a thing it
 * means, and it is one tap away from shift for anyone who wants it.
 */
internal fun Key?.startsChordDrag(): Boolean =
    this?.action is KeyAction.Mod || this?.action == KeyAction.Shift

/**
 * The key press [target] stands for while [mod] is held — what a drag from the
 * Ctrl key onto C means (issue #67) — or null when the target is something no
 * hardware keyboard could send under a modifier.
 *
 * The result is a [KeyAction.SendKey], which is the one action the service
 * already turns into a real down/up pair with a meta mask on it, so the chord
 * takes the route a layout's own `Ctrl+C` key takes rather than a private one.
 *
 * A text key names itself by its label and leaves the keycode as
 * `KEYCODE_UNKNOWN`: the character map that answers "which key writes a c" is
 * loaded by the service and has no business up here. The service reads the zero
 * as "work it out from the label", and drops the keystroke when it cannot — a
 * modifier press that quietly types the letter would be worse.
 *
 * Modes, tools, panels and the modifiers themselves return null. A chord is a
 * key press being sent to the app; there is nothing to send for a key whose
 * whole job is to change what this keyboard is showing.
 */
internal fun chordKey(target: Key, mod: ModifierKey): Key? =
    chordKey(target, Modifiers().with(mod, ModifierState.ARMED).metaFlags())

/**
 * The same, for a modifier that has no [ModifierKey] of its own: shift, whose
 * latch is [ShiftState] and whose mask is written out here.
 */
internal fun chordKey(target: Key, meta: Int): Key? {
    val action = target.action
    val code = when (action) {
        KeyAction.Text, is KeyAction.KeymanKey -> KeyEvent.KEYCODE_UNKNOWN
        is KeyAction.SendKey -> action.keyCode
        KeyAction.Space -> KeyEvent.KEYCODE_SPACE
        // The field's own action key sends Enter too; an app that reads the
        // editor action gets it either way, and one that reads Ctrl+Enter (a
        // send-message chord, most often) is exactly who this is for.
        KeyAction.Enter, KeyAction.Newline -> KeyEvent.KEYCODE_ENTER
        KeyAction.Delete -> KeyEvent.KEYCODE_DEL
        KeyAction.ForwardDelete -> KeyEvent.KEYCODE_FORWARD_DEL
        else -> return null
    }
    // A key that already carries modifiers of its own keeps them: dragging Ctrl
    // onto a layout's Alt+F4 key means all three.
    val own = (action as? KeyAction.SendKey)?.meta ?: 0
    return target.copy(action = KeyAction.SendKey(code, meta or own))
}

/**
 * What a drag from the *shift* key onto [target] commits.
 *
 * A text key takes the text route rather than the key-event route the other
 * modifiers take, and that difference is the whole reason this function exists.
 * A capital sent as a raw `KEYCODE_A` with the shift mask on it would arrive as
 * a letter the composing buffer never saw: the word would lose its suggestions,
 * its autocorrect and its learning, and a shift drag would quietly be a worse
 * way to type than the shift key it came from. So the key commits its own
 * shifted output instead — the very string `keyOutput` would have produced with
 * shift up — and every stage downstream carries on as though it had been armed.
 *
 * Passing it as [Key.output] rather than rewriting the label is what makes it
 * idempotent: a shift the user had already armed makes the service take the
 * shifted branch too, and uppercasing an uppercase letter (or reading the same
 * [Key.shiftLabel] twice) lands on the same character.
 *
 * Everything else is a real chord and goes the way Ctrl does, which is what
 * Shift+Enter, Shift+Tab and Shift+arrow have to be.
 */
internal fun shiftChordKey(target: Key): Key? = when (target.action) {
    KeyAction.Text -> target.copy(
        output = target.shiftLabel ?: (target.output ?: target.label).uppercase(),
    )
    else -> chordKey(target, KeyEvent.META_SHIFT_ON or KeyEvent.META_SHIFT_LEFT_ON)
}

/**
 * The layer a drag off [source] shows while the finger is down, or null when
 * that key is not one a drag can look through (issue #108).
 *
 * The mapping is the one a *tap* on the same key would take — see
 * `WMKeyboardService.toggleSymbols` — so a drag off the `?123` key of the first
 * symbol page reaches the second, and the gesture never lands somewhere the key
 * itself would not have gone.
 *
 * An `ABC` key on the letters layer looks through to nothing: there is no other
 * layer to show, and a drag that changed nothing would still commit the key it
 * happened to end on.
 */
internal fun layerDragMode(source: Key?, current: LayoutMode): LayoutMode? =
    when (source?.action) {
        KeyAction.Symbols ->
            if (current == LayoutMode.SYMBOLS) LayoutMode.SYMBOLS_SHIFTED else LayoutMode.SYMBOLS
        KeyAction.Letters -> LayoutMode.LETTERS.takeIf { current != LayoutMode.LETTERS }
        else -> null
    }

/**
 * Whether a drag off this key looks through to another layer (issue #108)
 * rather than gliding a word: the `?123` and `ABC` keys, wherever a layout puts
 * them.
 */
internal fun Key?.startsLayerDrag(): Boolean =
    this?.action == KeyAction.Symbols || this?.action == KeyAction.Letters

/**
 * Whether a drag off this key is a gesture the grid itself owns — a chord
 * (issue #67) or a layer peek (issue #108) — so glide typing, handwriting and
 * the octopus leave the stroke alone. Asked at the down, where the answer
 * cannot change again.
 */
internal fun Key?.ownsDrag(): Boolean = startsChordDrag() || startsLayerDrag()

/**
 * Whether a drag off this key is the possessive swipe's (#169) rather than a
 * glide: the key writes [possessiveChar], the one "Swipe to add 's" is set to.
 * Null when the setting is off, and then nothing is.
 *
 * Asked by glide typing and handwriting at the down, like [ownsDrag], because
 * the letter-distance test that normally keeps them off punctuation only works
 * when the punctuation sits away from the letters. A comma placed right beside
 * `s` is inside one key width of that letter's centre, so the half of it nearer
 * `s` started a glide and the swipe decoded as a word instead.
 */
internal fun Key?.startsPossessiveSwipe(possessiveChar: Char?): Boolean =
    possessiveChar != null && this?.action == KeyAction.Text &&
        (output ?: label).singleOrNull() == possessiveChar

/**
 * Whether a stroke that starts on this key belongs to it as a delete key
 * (#36, #226): backspace or forward delete, in either spelling. Refused at the
 * down by glide typing, handwriting and the octopus for the reason
 * [startsPossessiveSwipe] gives: backspace sits beside the bottom letter row,
 * so a stroke from its inner half was inside a letter's radius and started a
 * glide. The glide loop runs first, so both happened: the swipe deleted and the
 * glide typed a word on top of it (#243).
 *
 * Not gated on "Swipe to delete". With the swipe off, a held backspace is
 * repeating, and a finger that wanders off it mid-repeat glided a word in
 * among the deletions just the same (#274). No stroke from a delete key is
 * ever meant as a word.
 */
internal fun Key?.ownsDeleteStroke(): Boolean =
    this?.action?.let { it.deletesBackward() || it.deletesForward() } == true

/**
 * Whether a stroke that starts on this key belongs to it as the spacebar: its
 * swipes switch language, move the caret or hide the keyboard, and held with
 * none of them set it repeats. Refused at the down by glide typing,
 * handwriting and the octopus, like [ownsDeleteStroke] and for the same
 * reason: no word begins on the spacebar.
 *
 * The letter-distance test does not keep it out on its own (#333). It asks
 * for one key *width* of a letter's centre, and turned sideways a phone's keys
 * are twice as wide as its rows are tall, so the whole spacebar lay within
 * reach of the bottom letter row and a language swipe glided a word instead.
 * Upright, only a thin band along its top edge did.
 */
internal fun Key?.ownsSpaceStroke(): Boolean = this?.action == KeyAction.Space

/**
 * Whether a short flick down off this key types its corner hint (issue #178).
 *
 * Any key whose hold opens the popup and whose first entry is a character —
 * which is what the corner shows. The keys left out already own a drag of
 * their own: the spacebar's swipes, backspace's delete swipe (its hold is
 * spoken for, so [opensAlternatesPopup] refuses it), a kana key's four arms,
 * and the modifier and mode keys whose drags chord and peek.
 */
internal fun Key.takesHintFlick(): Boolean =
    longPress.isNotEmpty() && opensAlternatesPopup() && flick.isEmpty() &&
        action != KeyAction.Space && !ownsDrag()

/**
 * The key a hint flick beginning at [point] would type from, with its cell, or
 * null when nothing there takes one. Root space, like [KeyRects.keyAt].
 */
internal fun KeyRects.hintFlickTarget(point: Offset): Pair<Key, Rect>? {
    val key = keyAt(point)?.takeIf { it.takesHintFlick() } ?: return null
    val cell = cellAt(point) ?: return null
    return key to cell
}

/**
 * What a short flick up off this key types (the up-flick capital), or null when
 * it takes none: the shifted character the layout gave it, else its letter's
 * capital. A key whose shift changes nothing (a digit with no shifted twin, a
 * script without case) has nothing to flick for, and so do the keys that own a
 * drag of their own, as with [takesHintFlick].
 *
 * The same spelling [shiftChordKey] commits for a shift drag onto the key, so
 * the two gestures for "this key, shifted" always agree.
 */
internal fun Key.capitalFlickText(): String? {
    if (action != KeyAction.Text || flick.isNotEmpty() || ownsDrag()) return null
    val base = output ?: label
    if (base.isEmpty()) return null
    shiftLabel?.takeIf { it.isNotEmpty() && it != base }?.let { return it }
    return base.uppercase().takeIf { it != base }
}

/**
 * The key an up-flick beginning at [point] would type the capital of, with that
 * capital and the key's cell, or null when nothing there takes one. Root space,
 * like [KeyRects.keyAt].
 */
internal fun KeyRects.capitalFlickTarget(point: Offset): Pair<String, Rect>? {
    val text = keyAt(point)?.capitalFlickText() ?: return null
    val cell = cellAt(point) ?: return null
    return text to cell
}

/**
 * The least a hint flick may travel, as a multiple of the system touch slop:
 * the floor under [HINT_FLICK_MIN_TRAVEL_HEIGHTS] on a key too short for half
 * its height to mean anything.
 */
private const val HINT_FLICK_SLOP_FLOOR = 1.5f

/**
 * Whether lifting on this key during a layer peek types it (issue #108).
 *
 * A whitelist rather than a list of exceptions. The peek exists to reach one
 * character on another layer, and the keys left out of it are the ones that
 * would instead move the board — the mode and layout keys, shift, a tool, the
 * language switch — which have nothing to commit and would race the peek's own
 * restore on the way out. Braille dots are left out for a different reason:
 * they are a chord counted down and up, and this gesture delivers neither.
 */
internal fun Key.commitsFromLayerDrag(): Boolean = when (action) {
    KeyAction.Text,
    KeyAction.Space,
    KeyAction.Enter,
    KeyAction.Newline,
    KeyAction.Delete,
    KeyAction.ForwardDelete,
    is KeyAction.SendKey,
    is KeyAction.KeymanKey,
    -> true

    else -> false
}

/**
 * The layer a drag off [source] shows from a *panel* (issue #210), or null when
 * that key is not one a drag can look through.
 *
 * `?123` takes the step a tap would take, exactly as it does on the typing grid.
 * `ABC` always shows the letters: a panel is not a layer of the grid, so the
 * letters are somewhere else to look even while the board underneath is on
 * them — the case [layerDragMode] refuses.
 */
internal fun panelLayerDragMode(source: Key?, current: LayoutMode): LayoutMode? =
    when (source?.action) {
        KeyAction.Letters -> LayoutMode.LETTERS
        else -> layerDragMode(source, current)
    }

/**
 * The state a panel's peek (issue #210) resolves its layer from. A numeric
 * field draws its keypad in place of every layer, and the peek is for the
 * symbols or letters the panel's key names, so the field kind is set aside for
 * the look — as is the panel itself, which is not part of the typing grid.
 */
// ---- Copies of the two big state classes, kept out of the composables ----
//
// `KeyboardSettings.copy` takes 208 argument slots and `KeyboardUiState.copy`
// 169, and dex passes them in one contiguous run of registers. Written inside a
// composable, one call makes that composable's whole frame as wide as the call:
// DockedKeyboardFrame had 410 registers and 208 outs for two height copies,
// which is past the 3 KB frame ART's fast interpreter (nterp) takes, so until
// the JIT got to it — every keystroke right after an install or an update —
// it ran in the slow one. A plain function pays for the width on its own
// frame, once per call, and leaves the composable narrow. The dex method
// check in :app (`checkDexMethodsFullIntlFast`) is what notices a new one.

private fun KeyboardUiState.withSettings(settings: KeyboardSettings): KeyboardUiState = copy(settings = settings)

private fun KeyboardUiState.withLayoutMode(mode: LayoutMode): KeyboardUiState = copy(layoutMode = mode)

private fun KeyboardUiState.withShift(shift: ShiftState): KeyboardUiState = copy(shiftState = shift)

/**
 * Both row heights replaced, everything else as it was. Two functions, not
 * one nested copy: together the two calls would need one frame wide enough
 * for both, which is the frame this section exists to keep small.
 */
private fun KeyboardUiState.withKeyHeights(keyHeightDp: Int, numberRowHeightDp: Int): KeyboardUiState =
    withSettings(settings.withKeyHeights(keyHeightDp, numberRowHeightDp))

private fun KeyboardSettings.withKeyHeights(keyHeightDp: Int, numberRowHeightDp: Int): KeyboardSettings =
    copy(keyHeightDp = keyHeightDp, numberRowHeightDp = numberRowHeightDp)

/** What the resize overlay is showing, in place of the stored sizes. */
private fun KeyboardSettings.withResizePreview(preview: ResizeValues, scale: Float): KeyboardSettings = copy(
    keyHeightDp = (preview.keyHeightDp * scale).roundToInt(),
    numberRowHeightDp = (preview.numberRowHeightDp * scale).roundToInt(),
    bottomPaddingDp = preview.bottomPaddingDp,
    layoutBehavior = layoutBehavior.copy(
        sidePadLeftScale = preview.sidePadLeft,
        sidePadRightScale = preview.sidePadRight,
    ),
)

internal fun KeyboardUiState.peekedFromPanel(mode: LayoutMode): KeyboardUiState = copy(
    layoutMode = mode,
    fieldKind = if (fieldKind.isNumericPad) FieldKind.TEXT else fieldKind,
    panel = PanelMode.NONE,
)

/**
 * What a layer peek (issue #108) has on screen while its finger is down: the
 * layer showing through, the key a lift would type, and the alternates a still
 * finger opened. One per grid, written by [detectLayerPeek] and drawn by
 * [LayerPeekHighlight] and [LayerPeekPopup], so the typing grid and a panel
 * (issue #210) run the one gesture rather than two copies of it.
 */
internal class LayerPeek(
    /** The board-wide popup flag: a popup with a finger in it owns that finger. */
    val gate: AlternatesGate,
) {
    /** The layer the grid draws instead of its own, or null when no peek is up. */
    var mode by mutableStateOf<LayoutMode?>(null)

    /**
     * The key whose alternates the peek has open, and that key's cell in the
     * grid's own space for the popup to hang from. The grid owns the finger
     * throughout a peek, so the key under it never runs the press that would
     * have opened a popup of its own.
     */
    var popupKey by mutableStateOf<Key?>(null)
    var popupRect by mutableStateOf(Rect.Zero)

    /**
     * The cell the finger is over and would type, in the grid's space, or null
     * for none. Held as the state object and read in a draw lambda alone, the
     * way a key's own press is: crossing a key then repaints one overlay
     * instead of recomposing the whole grid under the finger.
     */
    val pressRect = mutableStateOf<Rect?>(null)

    /**
     * The finger steering the popup. One for the whole grid rather than one per
     * key, because the popup belongs to the gesture rather than to the key it
     * happens to be over — and unlike the keys' own holds it is never null: the
     * popup can only be chosen from by the finger holding it, since lifting is
     * what ends the peek, so [KeyPopupSettings.alternatesHoldToSelect] has no
     * say here.
     */
    val hold = AlternatesHold(gate)
}

@Composable
internal fun rememberLayerPeek(): LayerPeek {
    val gate = LocalAlternatesGate.current
    return remember(gate) { LayerPeek(gate) }
}

/**
 * The layer drag of issue #108, for any grid that can say which key is under a
 * point: a drag off `?123` or `ABC` shows that layer while the finger is down
 * and types the key it lifts on, and holding still over a key opens its
 * alternates.
 *
 * [rects] is read live, and must hand back a *new* table once the peeked layer
 * is laid out — see `rectsBefore`. Its cells are in the space [origin] is added
 * to; [window] is the grid's origin in the window, where the popup's entries
 * are. [peekFor] names the layer a key looks through to, or null for none;
 * [onPopupOpen] is the haptic, when the user has one.
 */
@Suppress("LongParameterList")
internal suspend fun PointerInputScope.detectLayerPeek(
    peek: LayerPeek,
    rects: () -> KeyRects,
    origin: () -> Offset,
    window: () -> Offset,
    peekFor: (Key?) -> LayoutMode?,
    trail: GlideTrail,
    trailMs: Long,
    dwellMs: Long,
    onPopupOpen: () -> Unit,
    onKey: (Key) -> Unit,
) {
    val reachPx = AlternatesReachDp.toPx()
    val steerPx = AlternatesSteerDp.toPx()
    val stillPx = LayerDragStillDp.toPx()
    awaitEachGesture {
        val down = awaitFirstDown(
            requireUnconsumed = false,
            pass = PointerEventPass.Initial,
        )
        val source = rects().keyAt(down.position + origin())
        if (!source.startsLayerDrag()) return@awaitEachGesture
        // Resolved at the down against the layer the board is really
        // on. A key with nowhere to look — `ABC` on the letters —
        // leaves the stroke alone rather than owning a gesture that
        // would show the same grid back.
        val layer = peekFor(source) ?: return@awaitEachGesture
        val anchor = rects().cellAt(down.position + origin())
            ?.let { it.center - origin() }
            ?: down.position
        val slop = viewConfiguration.touchSlop
        // The rect table as it is *before* the peek. A new layer
        // gets a new table (both are remembered on the layout), so
        // this is how the loop knows the grid under the finger is
        // still the one the finger left: reading a key out of the
        // old table would type one that is no longer on screen.
        val rectsBefore = rects()
        var dragging = false
        // The key under the finger now, and the popup it opened by
        // being held still on it. Read per sample, like the chord
        // drag's: the key that matters is the one it lifts on.
        var over: Key? = null
        var popupKey: Key? = null
        // Where the finger stopped and when, so a hold that never
        // moves still opens a popup — a finger genuinely still
        // sends no events at all, which is why this is a timer and
        // not a test run on the next move (#96 learned it the hard
        // way).
        val dwell = GlideDwell()
        // Everything the peek changes is undone in the `finally`,
        // and only there. A pointer loop can be cancelled outright
        // — the modifier restarting under it, the board recomposed
        // away — and a peek that leaked out of one would leave the
        // keyboard showing a layer with no finger on it and no way
        // back to the one the user was typing on.
        try {
            while (true) {
                val due = if (dragging && popupKey == null &&
                    over?.opensAlternatesPopup() == true
                ) {
                    dwell.stillSince + dwellMs
                } else {
                    null
                }
                val event = if (due == null) {
                    awaitPointerEvent(PointerEventPass.Initial)
                } else {
                    this.withTimeoutOrNull(
                        (due - SystemClock.uptimeMillis()).coerceAtLeast(0L),
                    ) { awaitPointerEvent(PointerEventPass.Initial) }
                }
                if (event == null) {
                    // Held long enough: the key under the finger opens
                    // its alternates, anchored on the cell rather than
                    // on the fingertip so the popup sits over the key
                    // the way a long press puts it there.
                    popupKey = over
                    peek.popupKey = over
                    val still = Offset(dwell.stillX, dwell.stillY)
                    rects().cellAt(still + origin())?.let {
                        peek.popupRect = it.translate(-origin())
                    }
                    peek.hold.open()
                    // The popup is what the finger is choosing in
                    // now; the key under it is not about to be
                    // typed.
                    peek.pressRect.value = null
                    // The trail's head stops following the finger: it is
                    // choosing in the popup now, and a stroke drawn
                    // across the entries is drawn over what it is
                    // reading.
                    trail.release()
                    onPopupOpen()
                    continue
                }
                val change = event.changes.firstOrNull { it.id == down.id } ?: break
                if (!change.pressed) {
                    if (dragging) change.consume()
                    break
                }
                if (!dragging &&
                    (change.position - down.position).getDistance() > slop
                ) {
                    // The key's own press and hold got there first and
                    // has its alternates open: that popup owns this
                    // finger, and the peek would be a second gesture
                    // reading the same travel.
                    if (peek.gate.open) return@awaitEachGesture
                    dragging = true
                    peek.mode = layer
                    trail.beginLine(anchor.x, anchor.y)
                    dwell.reset(change.position.x, change.position.y, change.uptimeMillis)
                }
                if (!dragging) continue
                change.consume()
                if (popupKey != null) {
                    // The popup owns the finger from here: its entries
                    // are laid out in the *window*, so the pointer has
                    // to arrive there too.
                    peek.hold.moveTo(
                        change.position + window() - peek.hold.cell.topLeft,
                        reachPx,
                        steerPx,
                    )
                    continue
                }
                trail.add(
                    change.position.x,
                    change.position.y,
                    change.uptimeMillis,
                    trailMs,
                )
                val rects = rects()
                // Nothing to read yet: the peeked layer has not been
                // laid out, and the table under the finger is still
                // the one it left.
                if (rects === rectsBefore) continue
                val now = rects.keyAt(change.position + origin())
                if (now !== over) {
                    over = now
                    // Lit only where a lift would type something,
                    // so the mode key the drag came off — which is
                    // now an `ABC` key under the same finger — reads
                    // as the way out that it is.
                    peek.pressRect.value = now
                        ?.takeIf { it.commitsFromLayerDrag() }
                        ?.let { rects.cellAt(change.position + origin()) }
                        ?.translate(-origin())
                    dwell.reset(change.position.x, change.position.y, change.uptimeMillis)
                } else {
                    dwell.sample(
                        change.position.x,
                        change.position.y,
                        change.uptimeMillis,
                        stillPx,
                    )
                }
            }
            // Never travelled: an ordinary press the mode key owns, and
            // it switches layer exactly as it always has.
            if (!dragging) return@awaitEachGesture
            trail.release()
            val target = over
            when {
                // The popup commits what it has highlighted, and never
                // the key underneath it. Before the `finally` clears the
                // key: [AlternatesHold.onCommit] reads it.
                popupKey != null -> peek.hold.commit()
                // Lifted off the grid, or on a key that only moves the
                // board (the `ABC` key now sitting where the drag began,
                // most often): the slide-away cancel every other key
                // has, and nothing is typed.
                target == null || !target.commitsFromLayerDrag() -> Unit
                else -> onKey(target)
            }
        } finally {
            peek.mode = null
            peek.popupKey = null
            peek.pressRect.value = null
            // Only a popup this gesture opened: the gate is the
            // board's, and a second finger may be holding one of the
            // keys' own popups open on it.
            if (popupKey != null) peek.hold.cancel()
        }
    }
}

/**
 * The key a layer peek is over, lit the way a press lights a key (issue #108).
 * The grid owns that finger, so the key itself never runs the press that would
 * have drawn it, and without this nothing on screen says which symbol the lift
 * is about to type. Composed only while a peek is up — the rect inside it is
 * read in the draw lambda, so the finger crossing keys repaints and never
 * recomposes.
 */
@Composable
internal fun BoxScope.LayerPeekHighlight(peek: LayerPeek, settings: KeyboardSettings) {
    if (peek.mode == null) return
    GridPressHighlight(peek.pressRect, settings)
}

/**
 * What a chord drag (issue #67) has on screen while its finger is down
 * (issue #345): whether one is under way, whether it came off shift, and the
 * cell a lift would fire on. Written by the chord loop in [KeyRows] and read
 * by the grid, which draws its letters shifted and lights that cell — the same
 * two things an armed shift and a key's own press would have shown, neither of
 * which runs while the grid owns the finger.
 */
internal class ChordDrag {
    /** A drag is under way; the highlight is composed only while it is. */
    var active by mutableStateOf(false)

    /**
     * The drag came off shift, so the letters draw as capitals. Display only:
     * the board's own [KeyboardUiState.shiftState] is never touched, for the
     * reasons [shiftChordKey] gives.
     */
    var shifted by mutableStateOf(false)

    /** The cell a lift would fire on, in the grid's space; read in a draw lambda. */
    val pressRect = mutableStateOf<Rect?>(null)
}

/**
 * Lights the cell in [pressRect] the way a press lights a key, for a gesture the
 * grid owns: a layer peek (issue #108) or a chord drag (issue #345). The rect is
 * read inside the draw lambda, so a finger crossing keys repaints this one
 * overlay and never recomposes the grid.
 *
 * The overlay sits above the keys, so a plain fill would paint over the label
 * of the very key it points at. It blends instead ([pressHighlightBlend]).
 */
@Composable
internal fun BoxScope.GridPressHighlight(pressRect: State<Rect?>, settings: KeyboardSettings) {
    val kbTheme = LocalKbTheme.current
    val gapH = keyGapH(settings)
    val gapV = keyGapV(settings)
    val faceShape = kbTheme.keyShape(bleedDp = gapH.value)
    val blend = remember(kbTheme.key, kbTheme.keyText, kbTheme.pressedKey) {
        pressHighlightBlend(kbTheme.key, kbTheme.keyText, kbTheme.pressedKey)
    }
    val fill = if (blend == BlendMode.SrcOver) kbTheme.pressedKey.copy(alpha = kbTheme.pressedKey.alpha * 0.5f) else kbTheme.pressedKey
    Canvas(modifier = Modifier.matchParentSize()) {
        val cell = pressRect.value ?: return@Canvas
        // The drawn face rather than the touch cell: the gap is padding
        // inside the cell, so lighting the whole of it would spill into
        // the keys either side.
        val face = Size(
            cell.width - gapH.toPx() * 2,
            cell.height - gapV.toPx() * 2,
        )
        if (face.width <= 0f || face.height <= 0f) return@Canvas
        val outline = faceShape.createOutline(face, layoutDirection, this)
        translate(cell.left + gapH.toPx(), cell.top + gapV.toPx()) {
            drawOutline(outline, fill, blendMode = blend)
        }
    }
}

/**
 * How [GridPressHighlight] lays the pressed colour over a key without hiding
 * its label. When the pressed colour moves the face toward the label's side
 * (lighter under light text, darker under dark text), Lighten or Darken tints
 * the face and leaves the label as it was, since the label is already the
 * extreme on that side. A theme whose press moves the other way would lose the
 * label to either, so it gets a half-strength plain fill instead.
 */
internal fun pressHighlightBlend(key: Color, keyText: Color, pressed: Color): BlendMode {
    val lightText = keyText.luminance() > key.luminance()
    val pressedLighter = pressed.luminance() > key.luminance()
    return when {
        pressedLighter != lightText -> BlendMode.SrcOver
        lightText -> BlendMode.Lighten
        else -> BlendMode.Darken
    }
}

/**
 * The alternates a layer peek is holding open (issue #108). Hung off a
 * stand-in the size of the key's own cell rather than off the key itself: the
 * grid owns this finger, so the key under it never ran the press that opens a
 * popup, and a popup places itself against whatever it is put inside. Same
 * position provider, same surface, same entries as a long press gets — only
 * the finger steering it is different.
 */
@Composable
internal fun LayerPeekPopup(
    peek: LayerPeek,
    popup: KeyPopupSettings,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    /** [shiftCasesText] for the board the peek is typing on. */
    shifted: Boolean,
) {
    // Assigned each composition, the way a key assigns its own: it closes over
    // the popup's key and the commit paths as they are now. Read at the lift,
    // so the peek must commit before it clears the key.
    peek.hold.onCommit = { index ->
        when (val entry = peek.popupKey?.alternateEntries()?.getOrNull(index)) {
            is AlternateEntry.Character -> onText(entry.text)
            is AlternateEntry.Action -> onKey(
                Key(label = entry.alternate.label, action = entry.alternate.action),
            )
            null -> Unit
        }
    }
    val key = peek.popupKey ?: return
    val density = LocalDensity.current
    val cell = peek.popupRect
    Box(
        modifier = Modifier
            .offset { IntOffset(cell.left.roundToInt(), cell.top.roundToInt()) }
            .size(
                with(density) { cell.width.toDp() },
                with(density) { cell.height.toDp() },
            )
            .onGloballyPositioned {
                peek.hold.cell = Rect(it.positionInWindow(), it.size.toSize())
            },
    ) {
        AlternatesPopup(
            key = key,
            popupPosition = rememberAboveAnchorPopup(),
            popup = popup,
            hold = peek.hold,
            shifted = shifted,
            onDismiss = { peek.popupKey = null },
            onText = { text ->
                peek.popupKey = null
                onText(text)
            },
            onAction = { alternateKey ->
                peek.popupKey = null
                onKey(alternateKey)
            },
        )
    }
}

/**
 * The alternates a *held centre button* has opened over the ring (a television
 * remote's long press).
 *
 * Built exactly like [LayerPeekPopup] and for the same reason: the popup hangs
 * off a stand-in the size of the ringed key's cell, because no key composable
 * is running the press that would normally open it. The difference is only the
 * driver — [KeyGridFocus] moves the selection from the arrow keys instead of a
 * finger moving it, through the same [AlternatesHold].
 *
 * [origin] converts the ring's root-space cell into this frame's own space, the
 * way the ring itself is drawn.
 */
@Composable
internal fun RingAlternatesPopup(
    focus: KeyGridFocus,
    popup: KeyPopupSettings,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    /** [shiftCasesText] for the board the ring is typing on. */
    shifted: Boolean,
    origin: () -> Offset,
) {
    val open = focus.alternates.value ?: return
    val key = open.key
    // Assigned each composition, the way a key and the layer peek both assign
    // their own: it closes over the commit paths as they are now, and the
    // centre button reads it through `hold.commit()`.
    focus.hold.onCommit = { index ->
        when (val entry = key.alternateEntries().getOrNull(index)) {
            is AlternateEntry.Character -> onText(entry.text)
            is AlternateEntry.Action -> onKey(
                Key(label = entry.alternate.label, action = entry.alternate.action),
            )
            null -> Unit
        }
    }
    val density = LocalDensity.current
    val cell = open.cell.translate(-origin())
    Box(
        modifier = Modifier
            .offset { IntOffset(cell.left.roundToInt(), cell.top.roundToInt()) }
            .size(
                with(density) { cell.width.toDp() },
                with(density) { cell.height.toDp() },
            ),
    ) {
        AlternatesPopup(
            key = key,
            popupPosition = rememberAboveAnchorPopup(),
            popup = popup,
            hold = focus.hold,
            shifted = shifted,
            onDismiss = { focus.cancelAlternates() },
            // The touch paths inside the popup still work — a hybrid device can
            // finish with a tap what the remote started.
            onText = { text ->
                focus.cancelAlternates()
                onText(text)
            },
            onAction = { alternateKey ->
                focus.cancelAlternates()
                onKey(alternateKey)
            },
        )
    }
}

/**
 * A trail drawn as one even line rather than a comet: a chord (issue #67) or a
 * layer peek (issue #108) runs from the key it started on to the fingertip, and
 * a flick (discussion #102) runs straight up from where the finger landed.
 */
internal fun DrawScope.drawTrailBand(
    trail: GlideTrail,
    color: Color,
    opacity: Float,
    widthPx: Float,
    keepMs: Long,
) {
    val life = trail.lineLife(trail.revision, keepMs)
    if (life <= 0f) return
    drawLine(
        color = color.copy(alpha = opacity * life),
        start = Offset(trail.startX, trail.startY),
        end = if (trail.straight) {
            Offset(trail.headX, trail.headY)
        } else {
            Offset(trail.startX, trail.headY)
        },
        strokeWidth = widthPx,
        cap = StrokeCap.Round,
    )
}

/**
 * Marks the key grid so a UI test can ask whether it is on screen at all.
 *
 * Several panels take the keys away from the user's field and are expected to
 * draw a set of their own underneath — a plugin's text box shipped doing the
 * first half and not the second, leaving a focused box with nothing to type
 * into it. `KeyRowsVisibilityTest` renders the real screen and checks this tag.
 */
const val KeyRowsTestTag: String = "wm:key-rows"

/**
 * The key-face colours a key is painted with, lifted off [KbTheme] so the
 * resolved keys depend on these eight values and not on the whole theme — a
 * background image, a toolbar colour or a radius changing then costs no key work.
 */
@Immutable
internal data class KeyPalette(
    val key: Color,
    val keyText: Color,
    val modifierKey: Color,
    val modifierKeyText: Color,
    val enterKey: Color,
    val enterKeyText: Color,
    val pressedKey: Color,
    val accent: Color,
    /** The theme's own corner-hint colour; null fades the label colour. */
    val hintText: Color? = null,
    /**
     * Single-key style overrides, carried on the palette so the resolved keys
     * still depend on this one object: the map changes only when the theme
     * does, exactly like the eight colours above.
     */
    val overrides: Map<String, KeyOverride> = emptyMap(),
    /** False when the theme's keys have no shape; see [KbTheme.keysHaveFaces]. */
    val keysHaveFaces: Boolean = true,
)

internal fun KbTheme.keyPalette(): KeyPalette = KeyPalette(
    key = key,
    keyText = keyText,
    modifierKey = modifierKey,
    modifierKeyText = modifierKeyText,
    enterKey = enterKey,
    enterKeyText = enterKeyText,
    pressedKey = pressedKey,
    accent = accent,
    hintText = hintText,
    overrides = keyOverrides,
    keysHaveFaces = keysHaveFaces,
)

/**
 * Everything one key draws, resolved out of [KeyboardUiState] once per layout,
 * shift, modifier or palette change instead of read out of the state per key.
 *
 * This type exists for skipping. The service publishes a fresh
 * [KeyboardUiState] on every keystroke — the suggestions and the composing
 * preview really do change — and strong skipping compares an unstable parameter
 * by instance, so a key handed the whole state can never skip: one keypress
 * re-ran every key body on the board, modifier chains and lambdas included.
 * Nothing a key draws is per-keystroke except the Bengali vowel form, so keys
 * take their resolved values instead and a mid-word keypress leaves every one of
 * these identical.
 */
@Immutable
internal data class KeyVisual(
    /** The key as authored: what it commits, its width, popups, flicks, hints. */
    val key: Key,
    /** [displayLabel] for the live shift state, numeral system and vowel form. */
    val label: String,
    /** [spokenLabel]: the TalkBack description, and what PASSTHROUGH announces. */
    val spoken: SpokenLabel,
    /** Latch of the modifier this key toggles; null when it is not a modifier. */
    val latch: ModifierState?,
    /** The key's face, and the colour a press paints over it. */
    val background: Color,
    val pressedBackground: Color,
    /** Label colour, and the one it flips to while pressed (Enter only). */
    val contentColor: Color,
    val pressedContentColor: Color,
    /**
     * Icon slot for the shift and enter keys, whose glyph tracks state; null for
     * every other key. The fixed-glyph keys (delete, globe, emoji) name their
     * own slot where they are drawn, since it cannot change.
     */
    val iconSlot: String?,
    /** Shift is on or locked, so its icon draws in the accent colour. */
    val iconActive: Boolean,
    /** Enter with an app-supplied actionLabel draws that wording, not an icon. */
    val enterLabel: String?,
    /**
     * The corner glyph on the Enter key: the *other* thing it can do right now
     * — the line break a shift would commit, or, once that shift is up and the
     * key has become the line break, the field's own action. Null on every
     * other key, and on Enter wherever there is no second thing to show.
     * See [enterHintSlot].
     */
    val enterHint: String? = null,
    /** Spacebar: its label, and whether the language-cycle arrows flank it. */
    val spaceText: String,
    val spaceArrows: Boolean,
    /** A per-key style's own border colour; null follows the theme border. */
    val borderColor: Color? = null,
    /** A per-key style's own bubble colours; null follows the theme. */
    val popupBackground: Color? = null,
    val popupText: Color? = null,
    /** The corner-hint colour — the key's own, or the theme's; null draws [contentColor] at 55%. */
    val hintColor: Color? = null,
    /**
     * This key's entry in the theme's single-key styles (`keyOverrideId`), or
     * null when it has none. Carried so the texture draw and the press burst
     * can ask for this key's own answer without recomputing the id per press.
     *
     * Derived from [key] alone, so it changes exactly when the layout does and
     * costs `rememberKeyGrid` no new dependency.
     */
    val overrideId: String? = null,
    /**
     * The label size the theme gave this one key, as a multiple of a letter's
     * size; null leaves [Key.labelScale] and the automatic rule to decide.
     */
    val labelScale: Float? = null,
    /** Whether the theme made this one key's label bold; null follows the board. */
    val bold: Boolean? = null,
    /**
     * The outline the theme gave this one key; null follows the board's own
     * shape. A round enter key on a grid of soft rectangles is a look a whole
     * family of imported themes is built on (issue #266).
     */
    val shapeKind: KeyShapeKind? = null,
    /**
     * The roman this key feeds a transliterating layout's buffer, shift
     * included ([transliterationRoman]), for the corner to ask the composer
     * what it will write. Null on every other board and every key that is not
     * a letter. The reading itself is not here: it follows the buffer, which
     * changes on every keystroke, and anything on [KeyVisual] that did would
     * rebuild the whole grid per letter. [KeyCornerHint] reads it instead.
     */
    val transliterationRoman: String? = null,
    /**
     * Shift is capitalising what this key's alternates type ([shiftCasesText]),
     * so its popup and corner hint draw the capitals (issue #211). False on a
     * key with no alternates whatever shift is doing, so a shift press leaves
     * those keys' parameters alone.
     */
    val alternatesShifted: Boolean = false,
    /**
     * The label-size multiplier the grid this key belongs to asked for: the
     * layer's own, or the layout's where the layer sets none. 1.0 for every
     * shipped grid.
     *
     * It rides the key rather than the settings because it is per *layer*, and
     * the settings are resolved once for the whole board — a board-level number
     * could not have moved when the user pressed `?123`, which was the whole
     * complaint (issue #18).
     */
    val fontScale: Float = 1f,
)

/**
 * One row as it is drawn: its keys resolved, already cut into halves for split
 * mode (the right half is empty when the keyboard is not split), with the row's
 * centring pad and key height.
 */
@Immutable
private data class KeyRowVisual(
    val left: List<KeyVisual>,
    val right: List<KeyVisual>,
    /** Half the row's slack to the grid width, as a layout weight. */
    val sidePad: Float,
    /**
     * The centre gap between the halves, as a layout weight. Per row rather than
     * per board because it is a percentage of the width the row was measured
     * against, and the number row is measured against its own key count.
     */
    val splitGapWeight: Float,
    val heightDp: Int,
)

/**
 * A run of rows that has to be drawn as one block because a key spans across
 * them — see [spanSlots] for the geometry.
 *
 * Rows are normally independent `Row`s, and that is what [KeyRowVisual] is for.
 * A key covering two rows cannot be one of their children: drawn in the upper
 * row it hangs outside that row's bounds, and Compose does not hit-test a child
 * outside its parent, so the lower half of the key would look pressable and do
 * nothing. The band is the parent both rows' keys share instead.
 */
@Immutable
private data class KeyBandVisual(
    /** Every key of the band, resolved and placed, in row-major order. */
    val slots: List<KeyBandSlot>,
    /** Grid units across the band — the unit [KeyBandSlot.x] is measured in. */
    val weight: Float,
    /** Key height in dp for each row of the band, top to bottom. */
    val rowHeights: List<Int>,
)

/** One key of a [KeyBandVisual], with where it sits and how far it reaches. */
@Immutable
private data class KeyBandSlot(
    val visual: KeyVisual,
    /** Left edge in grid units, already centred and flowed around the spans. */
    val x: Float,
    val width: Float,
    /** First row of the band this key covers, and how many it covers. */
    val row: Int,
    val span: Int,
)

/**
 * One block of the body grid: an ordinary row, or a band of rows joined by a
 * spanning key. Almost every layout is all [Row]s.
 */
private sealed interface KeyGridBlock {
    @Immutable
    data class Row(val row: KeyRowVisual) : KeyGridBlock

    @Immutable
    data class Band(val band: KeyBandVisual) : KeyGridBlock
}

/**
 * Resolves one key against [state].
 *
 * A plain function rather than a composable so the invariant the whole split
 * rests on — a keystroke changes nothing a key draws — is unit-testable.
 */
internal fun keyVisual(
    key: Key,
    state: KeyboardUiState,
    palette: KeyPalette,
    /** The grid's label-size multiplier; see [KeyVisual.fontScale]. */
    fontScale: Float = 1f,
): KeyVisual {
    val action = key.action
    // A latched modifier has to look held: it changes what the *next* key does,
    // so with no visible state the user finds out by pressing one.
    val latch = (action as? KeyAction.Mod)?.let { state.modifiers[it.key] }
    // The theme's own style for this one key, if it carries one. Applied over
    // the class colours below, but never over a latch — an armed modifier has
    // to look armed whatever colour its face was given.
    val overrideId = if (palette.overrides.isEmpty()) null else keyOverrideId(key)
    val override = overrideId?.let { palette.overrides[it] }
    val overrideBackground = override?.background
        ?.takeIf { latch == null || latch == ModifierState.OFF }
        ?.let { Color(it.toInt()) }
    // Samsung-style contrast: letter keys clearly lighter than the board,
    // modifier keys a shade darker than the letters.
    // The Select key of the text-editing pad is lit while selection mode is on,
    // whichever surface armed it — the old panel's one piece of state.
    val selectLit = action is KeyAction.Edit && action.op == TextEditAction.SELECT && state.selectingText
    // A theme with no key shape gives a key at rest no face, so its label sits on
    // the bare board. The latch and select states below still light theirs, and a
    // colour the theme gave this one key still paints it.
    // A per-key shape is also a per-key face: a theme whose board shape is NONE
    // still means this one key to be drawn when it names a shape for it.
    val overrideShape = keyShapeKindOrNull(override?.shape)
    val faceless = !palette.keysHaveFaces && overrideBackground == null && overrideShape == null
    val background = overrideBackground ?: when {
        latch == ModifierState.LOCKED -> palette.accent
        latch == ModifierState.ARMED -> palette.pressedKey
        selectLit -> palette.accent
        faceless -> Color.Transparent
        action == KeyAction.Enter -> palette.enterKey
        action != KeyAction.Text -> palette.modifierKey
        else -> palette.key
    }
    val contentColor = override?.text?.let { Color(it.toInt()) } ?: when {
        selectLit -> palette.enterKeyText
        // Enter's label colour is picked for its accent face. With no face it sits
        // on the board like the other modifier labels, so it takes their colour.
        action == KeyAction.Enter && !faceless -> palette.enterKeyText
        action != KeyAction.Text -> palette.modifierKeyText
        else -> palette.keyText
    }
    return KeyVisual(
        key = key.withEnterHoldFor(state),
        label = displayLabel(key, state),
        spoken = spokenLabel(key, state),
        latch = latch,
        background = background,
        // An overridden face derives its own pressed shade the way specKbTheme
        // derives the theme's: a quarter of the way toward the label colour.
        pressedBackground = if (overrideBackground != null) {
            lerp(overrideBackground, contentColor, 0.25f)
        } else {
            palette.pressedKey
        },
        contentColor = contentColor,
        // Enter is the one key that recolours under the finger: its text colour
        // is picked for its own accented face, which the press paints over.
        pressedContentColor =
            if (action == KeyAction.Enter) palette.modifierKeyText else contentColor,
        hintColor = override?.hint?.let { Color(it.toInt()) } ?: palette.hintText,
        overrideId = overrideId,
        // Clamped here rather than at the draw, the way every other value out
        // of a file is: the precedence against the layout's own scale lives in
        // `drawnLabelScale`, which is the one place both label paths read.
        labelScale = override?.labelScale
            ?.takeIf { it.isFinite() }
            ?.coerceIn(KEY_OVERRIDE_LABEL_SCALE_RANGE),
        bold = override?.bold,
        shapeKind = overrideShape,
        transliterationRoman = transliterationRoman(key, state),
        alternatesShifted = key.longPress.isNotEmpty() && state.shiftCasesText(),
        iconSlot = when {
            action == KeyAction.Shift -> when (state.shiftState) {
                ShiftState.CAPS_LOCK -> IconSlots.KEY_SHIFT_LOCK
                ShiftState.ON -> IconSlots.KEY_SHIFT_ON
                ShiftState.OFF -> IconSlots.KEY_SHIFT
            }
            // Always the lock glyph, lit when the lock is on: the key's face says
            // what it does, not what state the board happens to be in.
            action == KeyAction.CapsLock -> IconSlots.KEY_SHIFT_LOCK
            // CUSTOM is the one enter action with no slot: the app supplied its
            // own wording, so there is no icon to replace.
            action == KeyAction.Enter ->
                IconDefaults.enterActionSlot(state.effectiveEnterAction) ?: IconSlots.KEY_ENTER
            else -> null
        },
        iconActive = when (action) {
            KeyAction.Shift -> state.shiftState != ShiftState.OFF
            KeyAction.CapsLock -> state.shiftState == ShiftState.CAPS_LOCK
            else -> false
        },
        enterLabel = state.enterActionLabel?.takeIf {
            action == KeyAction.Enter && state.effectiveEnterAction == EnterAction.CUSTOM
        },
        enterHint = if (action == KeyAction.Enter) enterHintSlot(state) else null,
        spaceText = if (action == KeyAction.Space) spacebarText(state) else "",
        spaceArrows = action == KeyAction.Space && spacebarArrowsShown(state),
        borderColor = override?.border?.let { Color(it.toInt()) },
        popupBackground = override?.popupBackground?.let { Color(it.toInt()) },
        popupText = override?.popupText?.let { Color(it.toInt()) },
        fontScale = fontScale,
    )
}

/**
 * The label-size multiplier this key draws at, before the grid's own scale: the
 * layout's authored [Key.labelScale] where it has one, and otherwise the size
 * the theme gave this single key (issue #107). Null leaves the automatic rule
 * — a letter's size for a letter, a smaller one for a mode label — in charge.
 *
 * Resolved on [KeyVisual] rather than at each draw so the two label paths (the
 * text-editing word and the ordinary label) cannot answer differently.
 */
internal fun KeyVisual.drawnLabelScale(): Float? = key.drawnLabelScale() ?: labelScale

/**
 * The name a [ThemeSpec.keyOverrides] entry uses for this key: the lowercase
 * label for letter keys — so an override follows the letter across layouts —
 * and the action's name (`ENTER`, `SHIFT`, `SPACE`, `DELETE`, `SYMBOLS`,
 * `MOD_CTRL`, …) for everything else. Null for a letter key with no label.
 */
internal fun keyOverrideId(key: Key): String? = when (val action = key.action) {
    KeyAction.Text -> key.label.takeIf { it.isNotBlank() }?.lowercase()
    is KeyAction.Mod -> "MOD_${action.key.name}"
    else -> action::class.simpleName?.uppercase()
}

/**
 * Whether the spacebar's language-cycle arrows are drawn. They only mean
 * something when a swipe actually cycles languages and there is more than one
 * language to cycle.
 */
private fun spacebarArrowsShown(state: KeyboardUiState): Boolean {
    val swipeSwitchesLanguage = state.settings.spaceShortSwipe == SpaceSwipeAction.LANGUAGE ||
        state.settings.spaceLongSwipe == SpaceSwipeAction.LANGUAGE
    return state.settings.spacebarLanguageArrows &&
        swipeSwitchesLanguage &&
        state.settings.enabledLayoutIds.size > 1
}

/**
 * Every key on the board, resolved in one pass: the digit row (null when it is
 * not shown) and the body blocks, each with its own height and centring pad.
 *
 * Rebuilt only when something a key actually draws changes. Deliberately NOT
 * keyed on the suggestions, the composing preview or the open panel: those change
 * on every keystroke, and rebuilding here is exactly what used to re-run all ~40
 * key bodies per keypress. Every field this reads is a key below — read one more
 * without adding its key and the board goes stale.
 *
 * A block is one row unless the layout uses [Key.rowSpan], in which case the
 * rows a key reaches across come out as a single [KeyGridBlock.Band]. The blocks
 * still cover the body rows in order and still sum to the same height, so
 * `keyRowsHeight` and the reserved window are untouched by a span.
 */
@Composable
private fun rememberKeyGrid(
    state: KeyboardUiState,
    layout: KeyboardLayout,
    bodyRows: List<List<Key>>,
    extraRow: List<Key>?,
    palette: KeyPalette,
    gridWeight: Float,
): Pair<KeyRowVisual?, List<KeyGridBlock>> {
    val settings = state.settings
    val split = settings.splitKeyboard
    val splitGapPercent = settings.splitGapPercent
    // Optional taller (or shorter) bottom row — space / enter — set independently
    // of the other keys. Ignored when the layout carries its own per-row heights,
    // so a custom layout's bottom row wins and the height is never applied twice.
    // keyRowsHeight adds the same delta so the reserved height matches.
    val bottomRowHeightDp = settings.layoutBehavior.bottomRowHeightDp
    return remember(
        bodyRows, extraRow, layout, palette, settings, gridWeight,
        state.shiftState, state.modifiers, state.effectiveEnterAction,
        // The field's own action as well as the live one: the Enter key's
        // corner draws whichever of the two its face is not (see
        // [enterHintSlot]), so a board keyed on the live one alone kept a
        // stale corner through the shift press that swapped them.
        state.enterAction,
        state.enterActionLabel, state.language, state.script,
        state.composer.isClusterShaping, state.vowelForm, state.layoutId,
        // The fancy style rewrites every letter label via displayLabel. The
        // persisted pick rides in through `settings` (already a key); this is
        // the session override the strip flips for instant response.
        state.activeFancyStyleId,
        // A text-editing Select key on the grid lights with selection mode.
        state.selectingText,
        // Whether the corners read the transliteration at all. The reading
        // itself follows the buffer and is not a key here: [KeyCornerHint]
        // reads it through [LocalTransliterationPreview], so a letter typed
        // on a phonetic board recomposes the corners, not the grid.
        state.composer.isTransliterating,
    ) {
        // This layer's label size, or the layout's where the layer sets none —
        // already resolved into the compiled grid by `compile`. `layout` is
        // already a key of this remember, so pressing ?123 rebuilds the grid
        // with the symbol page's own size.
        val fontScale = layout.appearance.drawnFontScale()
        val digits = extraRow?.let { row ->
            keyRowVisual(
                row, split, splitGapPercent, row.size.toFloat(),
                settings.numberRowHeightDp, state, palette, fontScale,
            )
        }
        val heights = bodyRows.indices.map { index ->
            // Per-row height multiplier from the layout, if any. Rounded to whole
            // dp so the rendered height matches keyRowsHeight exactly (which sums
            // the same rounded values).
            val perRowHeight = rowScaledKeyHeight(
                settings.keyHeightDp, layout.rowHeights?.getOrNull(index),
            )
            val bottomRow = index == bodyRows.lastIndex && layout.rowHeights == null
            if (bottomRowHeightDp > 0 && bottomRow) bottomRowHeightDp else perRowHeight
        }
        // Split mode cuts every row at its own midpoint, which a key belonging to
        // two rows cannot survive: the halves would part company under it. So a
        // split board draws spans as ordinary one-row keys — the arrangement the
        // layout had before spans existed — rather than drawing them wrong.
        val banded = !split && hasRowSpans(bodyRows)
        val bands = if (banded) spanBands(bodyRows) else bodyRows.indices.map { it..it }
        val slots = if (banded) spanSlots(bodyRows, gridWeight) else emptyList()
        digits to bands.map { band ->
            if (band.first == band.last) {
                KeyGridBlock.Row(
                    keyRowVisual(
                        bodyRows[band.first], split, splitGapPercent, gridWeight,
                        heights[band.first], state, palette, fontScale,
                    ),
                )
            } else {
                KeyGridBlock.Band(
                    keyBandVisual(band, slots, gridWeight, heights, state, palette, fontScale),
                )
            }
        }
    }
}

/**
 * Resolves one band of rows: the slots that fall in it, re-based on the band's
 * own first row so the renderer can index [KeyBandVisual.rowHeights] directly.
 *
 * The band is laid out against one width for all its rows rather than each row's
 * own, because a spanning key has to sit on the same column pitch as the rows it
 * reaches into — that is the whole point of it. Only an over-wide row inside the
 * band moves that width, and then it moves it for the band as a whole.
 */
private fun keyBandVisual(
    band: IntRange,
    slots: List<KeySlot>,
    gridWeight: Float,
    heights: List<Int>,
    state: KeyboardUiState,
    palette: KeyPalette,
    fontScale: Float,
): KeyBandVisual {
    val inBand = slots.filter { it.row in band }
    val weight = maxOf(gridWeight, inBand.maxOfOrNull { it.end } ?: 0f)
    return KeyBandVisual(
        slots = inBand.map { slot ->
            KeyBandSlot(
                visual = keyVisual(slot.key, state, palette, fontScale),
                x = slot.x,
                width = slot.key.width,
                row = slot.row - band.first,
                span = slot.span,
            )
        },
        weight = weight,
        rowHeights = band.map { heights[it] },
    )
}

/** A key whose preview bubble is up, and where that key sits. */
@Immutable
internal data class KeyPreview(
    /**
     * Identity of the key that asked for this bubble. Two fingers down means two
     * bubbles, so every lookup is by token — lifting one finger must leave the
     * other's bubble alone.
     */
    val token: Any,
    val label: String,
    /** The key's place in the compose root, and its size. */
    val position: Offset,
    val size: IntSize,
    /** A per-key style's own bubble colours; null follows the theme. */
    val popupBackground: Color? = null,
    val popupText: Color? = null,
)

/**
 * The preview bubbles the whole board shares.
 *
 * Every key used to raise its own [Popup] on press, and a Popup is a real
 * window: typing a word added and removed one through WindowManager per letter,
 * with two timers per press to run it. The keys now only publish what they want
 * shown, and a single overlay draws all of it in the keyboard's own window —
 * see [KeyPreviewOverlay] for why that matters.
 *
 * Timing is held here rather than in the keys so one coroutine can run every
 * bubble: [expire] does the arithmetic, the overlay does the waiting.
 */
@Stable
internal class KeyPreviewState(
    /** Injected so the timing above can be driven by a test without a device. */
    private val now: () -> Long = { SystemClock.uptimeMillis() },
) {
    /** Bubbles on screen, in the order their keys were pressed. */
    val shown = mutableStateListOf<KeyPreview>()

    /** Bumped by every press and release, to wake the overlay's timer. */
    var revision by mutableIntStateOf(0)
        private set

    private val shownAt = HashMap<Any, Long>()
    private val releasedAt = HashMap<Any, Long>()

    fun press(preview: KeyPreview) {
        drop(preview.token)
        shown.add(preview)
        shownAt[preview.token] = now()
        revision++
    }

    fun release(token: Any) {
        // Only the first release counts: a second would push the minimum-duration
        // floor out and keep the bubble up longer than it asked for.
        if (token !in shownAt || token in releasedAt) return
        releasedAt[token] = now()
        revision++
    }

    /** The long-press alternates took over: that key's bubble goes at once. */
    fun cancel(token: Any) {
        if (drop(token)) revision++
    }

    /**
     * Drops every bubble whose time is up, and returns when the next one is due
     * (uptime millis), or null when nothing is waiting on a clock.
     *
     * A held key's bubble only answers to [maxMs]. A released one goes at
     * whichever comes first: that cap, or the minimum duration measured from
     * when it appeared — so a fast tap still shows a readable bubble instead of a
     * single-frame flash, and a release delivered late (commit lag, a new line
     * inserting) does not extend it.
     */
    fun expire(now: Long, minMs: Int, maxMs: Int): Long? {
        var next: Long? = null
        for (preview in shown.toList()) {
            val appeared = shownAt[preview.token] ?: continue
            val released = releasedAt[preview.token]
            val cap = appeared + maxMs
            val due = if (released == null) cap else minOf(cap, maxOf(released, appeared + minMs))
            if (due <= now) {
                drop(preview.token)
            } else {
                next = if (next == null) due else minOf(next, due)
            }
        }
        return next
    }

    private fun drop(token: Any): Boolean {
        shownAt.remove(token)
        releasedAt.remove(token)
        val index = shown.indexOfFirst { it.token === token }
        if (index < 0) return false
        shown.removeAt(index)
        return true
    }
}

/**
 * The board's bubbles, hoisted to the screen so the frame can draw them over
 * everything it holds. Null where no frame is composed — a grid on its own,
 * as in a test — and the grid then draws its own.
 */
internal val LocalKeyPreviewState = staticCompositionLocalOf<KeyPreviewState?> { null }

/**
 * Pins the overlay window over the key grid, [headroomPx] above it.
 *
 * Deliberately ignores everything it is passed except the anchor: the window
 * must not move. A window that repositions per press slides visibly from the
 * last key to the next one, and starts wherever it was parked — which is the bug
 * this replaced. The bubbles move inside it instead, which is ordinary layout.
 */
private class GridOverlayPositionProvider(private val headroomPx: Int) : PopupPositionProvider {
    override fun calculatePosition(
        anchorBounds: IntRect,
        windowSize: IntSize,
        layoutDirection: LayoutDirection,
        popupContentSize: IntSize,
    ): IntOffset = IntOffset(anchorBounds.left, anchorBounds.top - headroomPx)
}

/**
 * The band the docked frame keeps empty above the board for the bubbles: a
 * bubble over the top row plus the distance it keeps from its key. The
 * service keeps the band out of the host app's insets, so it is window, not
 * keyboard — the app is laid out to the board and a tap in the band reaches
 * it. Zero while previews are off, since the band is only worth having when
 * a bubble can appear in it.
 */
@Composable
internal fun keyPreviewHeadroomPx(settings: KeyboardSettings): Int {
    val popup = settings.popup
    if (!popup.enabled) return 0
    val kbTheme = LocalKbTheme.current
    val onKeyStyle = kbTheme.popupOnKey ?: popup.onKey
    val floatGap = if (onKeyStyle) KeyPopupGap else popup.floatingOffsetYDp.dp
    return with(LocalDensity.current) {
        // A floored on-key bubble rises past its key by at most the lane,
        // hence the second term; see [onKeyBubbleHeightPx].
        maxOf(kbTheme.popupHeightDp.dp.roundToPx(), if (onKeyStyle) onKeyLabelLanePx(popup) else 0) +
            floatGap.roundToPx() + KeyPopupGap.roundToPx()
    }
}

/**
 * The room an on-key label needs above the finger: its padding and its line.
 * An on-key bubble is floored at its key plus this ([onKeyBubbleHeightPx]), so
 * no height setting can sink it under the key.
 */
private fun Density.onKeyLabelLanePx(popup: KeyPopupSettings): Int =
    (OnKeyLabelTopPadding + OnKeyLabelBottomPadding).roundToPx() +
        (OnKeyLabelSp * popup.fontScale * LabelLineHeightRatio).sp.roundToPx()

/**
 * Draws every live key preview, and runs the one timer they share.
 *
 * A layout node in the keyboard's own window, not a window of its own. The
 * overlay was a [Popup] raised on the first press and torn down with the last
 * bubble, and a Popup is a real window: WindowManager gives it a surface and
 * a first frame of its own, so every burst of typing opened with a lit key
 * and no bubble for two frames (33–37 ms after the highlight on a 60 Hz
 * board, where Gboard's bubble lands in the touch's own frame), and the
 * bubble outlived the finger by the same lag. Kept alive instead, the window
 * sat over the host app, which is what Android 12 drops taps for. Drawn here
 * it is one more node in the frame's draw pass, up in the frame that lights
 * the key.
 *
 * [origin] and [size] are the overlay's own place and extent in the compose
 * root, which turn the keys' root-space rectangles into offsets inside it.
 * The frame gives the overlay its headroom — see [keyPreviewHeadroomPx] —
 * so a top-row bubble has somewhere to be. A host with no such band (a grid
 * composed on its own, as a test does) sets [virtualHeadroom]: the anchors
 * are lifted by the headroom and the bubbles dropped back, so the top row's
 * bubble lands above the grid rather than being pushed down into it.
 */
@Composable
internal fun KeyPreviewOverlay(
    state: KeyPreviewState,
    settings: KeyboardSettings,
    origin: Offset,
    size: IntSize,
    modifier: Modifier = Modifier,
    virtualHeadroom: Boolean = false,
) {
    val popup = settings.popup
    // The height and the placement come off the theme rather than the
    // settings: a theme may carry its own, and both the headroom above the
    // grid and the bubble itself have to agree on which one won.
    val kbTheme = LocalKbTheme.current
    val bubbleHeightDp = kbTheme.popupHeightDp
    // One coroutine for the board, in place of the two LaunchedEffects every key
    // ran per press. It sleeps until the nearest bubble is due or something is
    // pressed, whichever lands first; `expire` owns the arithmetic.
    LaunchedEffect(state, popup.minDurationMs, popup.maxDurationMs) {
        while (true) {
            // Read the revision *before* expiring, and wait for it to differ. A
            // press landing between the two would otherwise be missed — the flow
            // would start from the already-bumped value and sleep through it.
            val seen = state.revision
            val due = state.expire(SystemClock.uptimeMillis(), popup.minDurationMs, popup.maxDurationMs)
            if (due == null) {
                // Nothing on a clock: sleep until a key is pressed or released.
                snapshotFlow { state.revision }.first { it != seen }
            } else {
                withTimeoutOrNull(due - SystemClock.uptimeMillis()) {
                    snapshotFlow { state.revision }.first { it != seen }
                }
            }
        }
    }

    val density = LocalDensity.current
    val onKeyStyle = kbTheme.popupOnKey ?: popup.onKey
    // How far a floating bubble sits above its key. The user's own distance
    // when the bubble floats; the fixed gap otherwise, since an on-key bubble
    // grows out of the key rather than hovering over it.
    val floatGap = if (onKeyStyle) KeyPopupGap else popup.floatingOffsetYDp.dp
    val gapPx = with(density) { floatGap.roundToPx() }
    val offsetXPx = with(density) { popup.floatingOffsetXDp.dp.roundToPx() }
    val bubbleHeightPx = with(density) { bubbleHeightDp.dp.roundToPx() }
    val onKeyLabelLanePx = with(density) { onKeyLabelLanePx(popup) }
    val headroomPx = if (virtualHeadroom) keyPreviewHeadroomPx(settings) else 0
    val bubbles = state.shown.toList()
    // In the tree even while nothing is previewing, with no children. Taking
    // the node out on release and putting it back on the next press changed
    // the frame's own child list twice a keystroke, and the frame is sized by
    // its content, so each change was a layout pass over the whole window. An
    // empty Layout costs a node and nothing else.
    //
    // And inside a box of its own, which [modifier] (`matchParentSize`, at
    // both call sites) measures at one fixed size. Every press and release
    // still changes this Layout — its children, and its measure block, which
    // closes over the bubbles — and Compose walks such a change up to the
    // first parent whose size cannot depend on it. Straight under the frame
    // that was the window's root: a full measure of the whole keyboard,
    // every key's text included, twice a keystroke (traced on a CPH2481 with
    // a requestLayout probe). Under a fixed-size box the walk stops here.
    Box(modifier) {
        Layout(
            // Transient, and already spoken by the key: a screen reader has no
            // use for a bubble that is gone before the description finishes.
            modifier = Modifier.fillMaxSize().clearAndSetSemantics { },
            // Keyed by the pressing key, so a bubble expiring under a finger that
            // is still down removes that bubble rather than shuffling the rest up
            // into its slot.
            content = {
                for (preview in bubbles) {
                    key(preview.token) {
                        val heightPx = if (onKeyStyle) {
                            onKeyBubbleHeightPx(bubbleHeightPx, preview.size.height, onKeyLabelLanePx)
                        } else {
                            bubbleHeightPx
                        }
                        KeyPreviewBubble(preview, popup, onKeyStyle, heightPx)
                    }
                }
            },
        ) { measurables, constraints ->
            val laidOut = constraints.constrain(size)
            // The space the providers clamp into: the overlay, plus the band a
            // host without one is pretending to have above it.
            val room = IntSize(laidOut.width, laidOut.height + headroomPx)
            val placeables = measurables.map { it.measure(Constraints()) }
            layout(laidOut.width, laidOut.height) {
                placeables.forEachIndexed { index, placeable ->
                    val preview = bubbles[index]
                    // The key in the overlay's space, pushed down by the band.
                    val keyBounds = IntRect(
                        IntOffset(
                            (preview.position.x - origin.x).roundToInt(),
                            (preview.position.y - origin.y).roundToInt() + headroomPx,
                        ),
                        preview.size,
                    )
                    val provider = if (onKeyStyle) {
                        OnKeyPopupPositionProvider
                    } else {
                        AboveAnchorPopupPositionProvider(gapPx, offsetXPx)
                    }
                    val at = provider.calculatePosition(
                        keyBounds,
                        room,
                        layoutDirection,
                        IntSize(placeable.width, placeable.height),
                    )
                    placeable.place(at.x, at.y - headroomPx)
                }
            }
        }
    }
}

/**
 * One preview bubble. In on-key mode it is key-wide with a large label near the
 * top, clear of the finger (the stock-keyboard style where the bubble replaces
 * the key); otherwise it floats above the fingertip. [heightPx] is the
 * overlay's answer, floored for an on-key bubble — see [onKeyBubbleHeightPx].
 */
@Composable
private fun KeyPreviewBubble(
    preview: KeyPreview,
    popup: KeyPopupSettings,
    onKeyStyle: Boolean,
    heightPx: Int,
) {
    val kb = LocalKbTheme.current
    val density = LocalDensity.current
    val shape = kb.popupShape()
    val border = kb.popupSurfaceBorder()
    // A Box wearing a Surface's chain (shadow, border, fill, clip) rather than
    // a Surface: a Surface swallows the touches under it, and the bubble is
    // drawn in the keyboard's own window now, over the row above its key.
    // The next tap has to reach that row through it.
    Box(
        modifier = Modifier
            .shadow(elevationFor(kb.popupShapeKind, kb.popupElevation), shape, clip = false)
            .then(if (border != null) Modifier.border(border, shape) else Modifier)
            // A per-key style first, then the user's own bubble colour, then the
            // theme: narrowest wins, and the theme is the one nobody picked by hand.
            .background(
                preview.popupBackground ?: popup.backgroundColor?.let { Color(it.toInt()) } ?: kb.popup,
                shape,
            )
            .clip(shape)
            .height(with(density) { heightPx.toDp() })
            .widthIn(
                min = if (onKeyStyle) with(density) { preview.size.width.toDp() } + 8.dp else 0.dp,
            )
            .popupTexture(LocalKeyTextures.current, shape)
            .padding(horizontal = 14.dp),
        contentAlignment = if (onKeyStyle) Alignment.TopCenter else Alignment.Center,
    ) {
        Text(
            text = preview.label,
            modifier = if (onKeyStyle) Modifier.padding(top = OnKeyLabelTopPadding) else Modifier,
            fontSize = ((if (onKeyStyle) OnKeyLabelSp else FloatingLabelSp) * popup.fontScale).sp,
            color = preview.popupText
                ?: popup.textColor?.let { Color(it.toInt()) }
                ?: kb.popupText,
        )
    }
}

/**
 * Paints the theme's popup texture behind the bubble's label, clipped to the
 * bubble's shape. Built the way the key textures are: outline and paint in the
 * cache block, so the draw pass only issues the draw call.
 */
private fun Modifier.popupTexture(textures: KeyTextures, shape: Shape): Modifier {
    val bitmap = textures.popup ?: return this
    return drawWithCache {
        val outline = shape.createOutline(size, layoutDirection, this)
        val paint = KeyTexturePaint.of(bitmap, textures, outline, size)
        onDrawBehind { paint.draw(this, textures.opacity) }
    }
}

/** Resolves a whole row, splitting it first so the halves are what gets drawn. */
private fun keyRowVisual(
    row: List<Key>,
    split: Boolean,
    splitGapPercent: Int,
    gridWeight: Float,
    heightDp: Int,
    state: KeyboardUiState,
    palette: KeyPalette,
    fontScale: Float,
): KeyRowVisual {
    // Split before resolving: the cut rewrites a straddling spacebar's width and
    // blanks the left half's label, so the halves are the keys to resolve.
    val (left, right) = if (split) splitKeys(row) else row to emptyList()
    return KeyRowVisual(
        left = left.map { keyVisual(it, state, palette, fontScale) },
        right = right.map { keyVisual(it, state, palette, fontScale) },
        sidePad = sidePadFor(row, gridWeight),
        splitGapWeight = gridWeight * splitGapPercent / 100f,
        heightDp = heightDp,
    )
}

@Composable
private fun KeyRows(
    state: KeyboardUiState,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    onGesture: (List<GesturePoint>, List<KeyCenter>, Float, GlideVerdict) -> Unit =
        { _, _, _, _ -> },
    onGesturePreview: (List<GesturePoint>, List<KeyCenter>, Float, GlideCase) -> Unit = { _, _, _, _ -> },
    onCursorMove: (Int) -> Unit = {},
    onLayoutSelect: (String) -> Unit = {},
    onGestureWords: (List<List<GesturePoint>>, List<KeyCenter>, Float, GlideVerdict) -> Unit =
        { _, _, _, _ -> },
    onKeyboardHandwritingStroke: (HwStroke, IntSize) -> Unit = { _, _ -> },
    /** Down position of the tap that committed a letter, in key-width units
     * (keyboard space). Fired just before the matching onKey. */
    onKeyTouch: (Float, Float) -> Unit = { _, _ -> },
    /** Letter-key centres of the live layout in key-width units, for the
     * engine's touch-likelihood model. */
    onTouchKeys: (List<KeyCenter>) -> Unit = {},
) {
    // Issue #108: a drag off `?123` or `ABC` looks through to that layer for as
    // long as the finger is down. The layer drawn is the only thing it changes —
    // the board's own [KeyboardUiState.layoutMode] is untouched — so the number
    // row, the reserved row span and every height derived from them stay exactly
    // as they were, and nothing under the finger moves except the key faces.
    val layerPeek = rememberLayerPeek()
    val peeked = layerPeek.mode
    val layout = rememberCurrentLayout(
        if (peeked == null) state else state.withLayoutMode(peeked),
    )
    // Issue #345: a drag off shift draws the letters as the capitals a lift
    // would type, and lights the key under the finger. Like the peek, this is
    // the drawn grid only — the board's shift latch never moves, and the layout
    // is not rebuilt, so the cells under the finger stay exactly where they are.
    val chordDrag = remember { ChordDrag() }
    val gridState = if (chordDrag.shifted && state.shiftState == ShiftState.OFF) {
        state.withShift(ShiftState.ON)
    } else {
        state
    }
    // Letter-area swipes are drawing handwriting rather than gliding a word
    // (full builds only). Capture arms whenever the mode is selected; the
    // service decides whether the drawn ink recognizes or prompts a download.
    val handwriteSwipe = BuildConfig.ENABLE_ML_KIT_HANDWRITING &&
        state.settings.gestureTyping &&
        state.settings.letterSwipeAction == LetterSwipeAction.HANDWRITE &&
        state.layoutMode == LayoutMode.LETTERS &&
        state.panel == PanelMode.NONE
    // A typing test with its glide option on glides: the run is there to
    // compare tapping against gliding, so the test's own switch stands in for
    // the keyboard-wide setting while it is up.
    val glideInTest = state.typingTestActive && state.settings.typingTest.glide
    // Every other keyboard-owned field glides too (#161): the stroke spells a
    // word into that field's own buffer at its own caret, never into the app
    // behind the panel. `state.panel == PanelMode.NONE` used to be the whole
    // gate, which is why a panel's search box took taps only.
    val glideInCapture = state.captureTarget()?.takesWords == true &&
        state.captureTarget() != CaptureTarget.TYPING_TEST &&
        state.settings.gestureTyping
    val gestureEnabled = !handwriteSwipe &&
        (
            glideInTest || glideInCapture ||
                (state.settings.gestureTyping && state.panel == PanelMode.NONE)
            ) &&
        state.layoutMode == LayoutMode.LETTERS &&
        // Whether this language and layout can be glided at all — a word list
        // exists, the layout types letters rather than converting them, and its
        // keys cover enough of the language to decode honestly. Measured in the
        // service against the live word sources, because two of those three
        // questions need the dictionary to answer.
        state.glideReady
    // Read here so the gesture below can close over it: a popup with a finger in
    // it owns that finger, and this loop must not read the same travel as a word.
    val alternatesGate = LocalAlternatesGate.current

    // Letter-key centres and width, captured from layout in this Box's space.
    // Keyed on the layout: the map is written by onGloballyPositioned per key,
    // so a layout with fewer letters than the last one would otherwise keep the
    // previous grid's centres and anchor swipes on keys that are not on screen.
    // A LaunchedEffect that cleared it would race those positioning callbacks.
    val keyCenters = remember(layout) { mutableStateMapOf<Int, Offset>() }
    // Spacebar bounds in this Box's space, for the multi-word glide split.
    // Reset per layout alongside the key centres. A split keyboard positions
    // two half-spacebars into this one slot; the last one measured wins, which
    // covers the common (non-split) case and degrades to one half for split.
    val spaceRect = remember(layout) { mutableStateOf<Rect?>(null) }
    // Every key's cell, for the modifier drag (issue #67): the chord needs the
    // key the finger lifted on, and that is as often a mode or an arrow as a
    // letter. Per layout, like the centres above and for the same reason.
    val keyRects = remember(layout) { KeyRects() }
    // Each letter's whole cell in this Box's space, for the autopilot overlay:
    // it draws the area a favoured letter has claimed, and a centre alone does
    // not say how big a cell is. Per layout, like the centres above.
    val keyBounds = remember(layout) { mutableStateMapOf<Int, Rect>() }
    // The pointer loops below are keyed on the gesture settings, not on the
    // layout, so they outlive a layout change — and both the centres map and the
    // grid they read are per-layout values. Captured bare, a loop started under
    // the old layout keeps resolving letters against the map the old layout
    // filled, so a swipe drawn on a layout the user has just switched to decodes
    // against the previous layout's key positions: real words, none of them the
    // one that was drawn. Read them through a State, the way `keyWidth` is.
    val liveCenters = rememberUpdatedState(keyCenters)
    val liveRects = rememberUpdatedState(keyRects)
    val liveLayouts = rememberUpdatedState(state.layouts)
    // The bounds table, for the octopus tap, and the one that bites hardest:
    // [OctopusRects] stamps its rectangles with the very map they were measured
    // from and answers nothing against any other, so a loop holding the
    // previous layout's map does not hit-test the wrong word — it stops
    // resolving words at all, silently and for as long as the loop lives.
    // Every tap then falls through to the key underneath while the flick, which
    // reads the centres above, goes on working (#209).
    val liveBounds = rememberUpdatedState(keyBounds)
    // The spacebar's cell, for the glide's word split and its apostrophe key.
    // A State of a State, which reads oddly and is the point: the *holder* is
    // what a new layout replaces, so a loop that captured the holder keeps
    // reading the old layout's rectangle — filled, plausible and wrong — long
    // after that spacebar has gone. Only the outer read is live.
    val liveSpace = rememberUpdatedState(spaceRect)
    // The layer the board is really on, for the peek loop: it decides which
    // layer a drag looks through to (issue #108) and must not restart when the
    // user switches layer by tapping.
    val liveMode = rememberUpdatedState(state.layoutMode)
    var boxOrigin by remember { mutableStateOf(Offset.Zero) }
    // The same origin in *window* coordinates. The peek's alternates popup
    // reports its own geometry with `positionInWindow`, the way every other
    // alternates popup does, and a pointer position has to reach that space to
    // be compared with it — the two must not be measured from different roots.
    var boxWindow by remember { mutableStateOf(Offset.Zero) }
    var boxSize by remember { mutableStateOf(IntSize.Zero) }
    // Rows narrower than the grid (e.g. the 9-key QWERTY home row) keep the
    // standard key width and are centred with side gaps, instead of stretching
    // their keys to fill the full width.
    //
    // The grid is the width the most rows share, not the first row's — see
    // gridWeightOf. That keeps a lone narrow row (one inserted at the top) from
    // hijacking the reference and filling the width, and a lone wide row
    // (Dvorak's third) from padding every other row.
    //
    // A layout can arrive with no rows at all — the editor allows deleting them
    // and an imported file is untrusted — so gridWeightOf returns 0 for empty.
    //
    // On a tablet the width is *declared* rather than inferred: the expansion
    // widens the letters layer and leaves the symbols layers alone, so inferring
    // per layer would give letters twelve columns and symbols ten and visibly
    // resize every key on the way into ?123. Declaring it also makes `keyWidth`
    // below — the glide decoder's distance normaliser — the real drawn column
    // width on every layer rather than an approximation of the current one.
    val gridWeight = state.layouts.gridWidth
        ?: gridWeightOf(layout.rows).takeIf { it > 0f } ?: 10f
    // One key's width, for the gesture decoder's distance normalisation.
    // Derived from the grid rather than recorded by whichever letter key
    // happened to measure last, which made decoding depend on where a wide key
    // sat in the layout. The column's own horizontal padding is taken off first
    // so this is the real cell width rather than an approximation of it.
    //
    // Held in a State because the gesture detector below is keyed on
    // `gestureEnabled` and would otherwise capture the first frame's value,
    // before the box has been measured at all.
    val rowInsetPx = with(LocalDensity.current) { KeyRowsPadHorizontal.toPx() * 2 }
    val keyWidth = rememberUpdatedState(
        if (boxSize.width > 0) ((boxSize.width - rowInsetPx) / gridWeight).coerceAtLeast(0f) else 0f,
    )
    // Smart key-hit detection: a boundary tap can be claimed by a likelier
    // neighbour. Only the letters layer, and only while the field is composing.
    val smartHit = state.settings.layoutBehavior.smartHitDetection &&
        state.layoutMode == LayoutMode.LETTERS &&
        state.panel == PanelMode.NONE
    // Live next-letter distribution; read fresh inside the down-observer, which
    // must not restart on every keystroke.
    val nextBias = rememberUpdatedState(if (smartHit) state.nextLetterBias else emptyMap())
    // The user's autopilot strength, as the multiplier the hit test wants. Read
    // through a State for the same reason as the bias above: the down-observer
    // is keyed on `smartHit` alone and must not restart when the slider moves.
    val hitStrength = rememberUpdatedState(
        smartHitStrength(state.settings.layoutBehavior.autopilotStrength),
    )
    // Pointer → the letter its down chose to remap to, set at down time by the
    // observer and consumed by the owning key on release.
    val hitRemap = remember { HashMap<PointerId, Char>() }
    // Pointer → its down position in this Box's space, for the engine's
    // touch-likelihood model. Written by an always-on Initial-pass observer;
    // read when the owning key commits. Entries are not removed on lift (the
    // key's Main-pass handler reads after the observer has seen the up) —
    // the map is pruned wholesale instead, and ids never repeat within it.
    val downPositions = remember { HashMap<PointerId, Offset>() }
    val onKeyTouchNow = rememberUpdatedState(onKeyTouch)
    // Current-layer letter keys by lowercase char, so a remap resolves to the
    // correctly-cased Key to commit. Keyed on layout: rebuilt when it changes.
    val letterKeys = remember(layout) {
        buildMap<Char, Key> {
            for (row in layout.rows) {
                for (key in row) {
                    val ch = key.label.singleOrNull()
                        ?.takeIf { key.action == KeyAction.Text && it.isLetter() }
                        ?: continue
                    put(ch.lowercaseChar(), key)
                }
            }
        }
    }
    // Substitutes the committed key when the owning letter's down was remapped
    // toward a likelier neighbour, and reports the tap's down position to the
    // engine's touch model just before the commit. Stable across keystrokes
    // (depends only on the layout), so it never restarts a key's pointerInput.
    val smartResolve = remember(letterKeys) {
        { key: Key, id: PointerId ->
            downPositions[id]?.let { down ->
                val kw = keyWidth.value
                if (kw > 0f) onKeyTouchNow.value(down.x / kw, down.y / kw)
            }
            val target = hitRemap[id]
            val own = key.label.singleOrNull()
                ?.takeIf { key.action == KeyAction.Text && it.isLetter() }
                ?.lowercaseChar()
            if (target != null && own != null && target != own) {
                letterKeys[target] ?: key
            } else {
                key
            }
        }
    }
    // Publish the live layout's letter centres, normalised to key widths, so
    // the engine can turn tap positions into per-key likelihoods. snapshotFlow
    // coalesces the per-key positioning bursts during a layout change.
    LaunchedEffect(layout) {
        snapshotFlow { keyCenters.toMap() to keyWidth.value }
            .collect { (centers, kw) ->
                if (kw > 0f && centers.isNotEmpty()) {
                    // Letters only: the touch model turns a tap into per-letter
                    // likelihoods, and the punctuation keys the map also tracks
                    // (for the apostrophe setting) are not candidates for that.
                    onTouchKeys(
                        centers.entries
                            .filter { it.key !in GlidePunctuationCodePoints }
                            .map { (codePoint, c) -> KeyCenter(codePoint, c.x / kw, c.y / kw) },
                    )
                }
            }
    }
    // Drop any in-flight remap when the feature switches off or the layout
    // changes: a release arriving after such a change must not apply a decision
    // made against the old grid (the down-observer that would have cleared it is
    // gone once smartHit is false).
    LaunchedEffect(smartHit, layout) { hitRemap.clear() }
    val trail = remember { GlideTrail() }
    // The quad the trail is filled through, rewound per segment and kept across
    // frames: the draw below builds one per sample, and a 120 Hz stroke would
    // otherwise allocate a Path per sample per frame for the whole gesture.
    val trailQuad = remember { Path() }
    val picker = remember { GlidePickerState() }
    // Where the floating words ended up, for the pointer loop to hit-test
    // against. Not snapshot state: written by the overlay's layout and read at
    // touch-report rate, and a rectangle in snapshot state would recompose the
    // board every time a finger moved.
    val octopusRects = remember { OctopusRects() }
    val octopusSettings = state.settings.octopus
    val octopusPick = LocalOctopusPick.current
    val octopusTapHere = octopusSettings.enabled && octopusSettings.tapCommits
    // Issue #169: a short straight swipe from a punctuation key to `s` appends
    // `'s` to the word behind the caret. The key is read here, as a value, so
    // the loop below restarts when the choice changes and never otherwise.
    val possessiveFlickTaken = LocalPossessiveFlick.current
    val possessiveChar = state.settings.gesture.possessiveKey.sourceChar
    // The delete keys own their strokes the same way; see [ownsDeleteStroke].
    // With glide typing on, the stroke belongs to the glide loop, which asks
    // the same question at its own lift and calls the same function to answer
    // it. Only a board without glide needs its own flick detector.
    val octopusFlickHere = octopusSettings.enabled &&
        octopusSettings.flickCommits && !gestureEnabled
    val octopusArmed = octopusTapHere || octopusFlickHere
    // Whether the glide loop should hand short strokes on rather than dropping
    // them: true whenever a flick could be what is happening, glide or no.
    val octopusFlickWanted = octopusSettings.enabled && octopusSettings.flickCommits
    // Issue #178: a short flick down off a key types its corner hint. Asked at
    // the lift, like the octopus flick, and in two places for the same reason:
    // a stroke the glide loop claimed is judged inside it, and every stroke it
    // never claimed — glide off, a symbol layer, a punctuation key — by the
    // loop of its own further down.
    val hintFlickOn = state.settings.layoutBehavior.hintFlick
    // Its upward twin: a short flick up off a letter types the capital. Judged
    // at the same two places, and it gives way to an octopus word on the key,
    // whose flick is also upward.
    val capitalFlickOn = state.settings.layoutBehavior.capitalFlick
    // A drag off 🌐 onto one of the six shortcut letters runs its action. Read
    // live by the loops that must leave such a drag alone, so switching it
    // does not restart every gesture detector on the grid.
    val globeDragLive = rememberUpdatedState(state.settings.longPressLetterActions.globeDrag)
    val letterActionsLive = rememberUpdatedState(state.settings.longPressLetterActions)
    val globeHoldMs = rememberUpdatedState(state.settings.longPressDelayMs.toLong())
    val onGlobeShortcut = LocalClipboardKeyAction.current
    // Read live rather than captured: the words change on every keystroke, and
    // a pointer loop restarted that often would be a loop that misses touches.
    val octopusLive = rememberUpdatedState(state.octopus)
    // The keyboard's own haptic, which already routes through the service and
    // respects the user's feedback settings — not Compose's, whose name this
    // composition local deliberately shadows.
    val pickerHaptic = LocalHapticFeedback.current
    // Read inside the pointer loop, which outlives the composition that started
    // it — a captured value would be whatever the stroke began with. The
    // choices and the close-call flag change with every preview; the picker's
    // settings and the haptic switch can change under a finger too.
    val glideChoices = rememberUpdatedState(state.glideChoices)
    val glideCloseCall = rememberUpdatedState(state.glideCloseCall)
    val glideSettings = rememberUpdatedState(state.settings.gesture)
    val hapticOn = rememberUpdatedState(state.settings.haptics.enabled)
    val kbTheme = LocalKbTheme.current
    val trailColor = kbTheme.gestureTrail
    // The board's preview bubbles: the screen's, drawn by the frame over
    // everything it holds; or this grid's own when no frame is composed (a
    // grid on its own in a test), drawn here and lifted over the top row.
    val hoistedPreview = LocalKeyPreviewState.current
    val ownPreview = remember { KeyPreviewState() }
    val keyPreview = hoistedPreview ?: ownPreview
    // The eight colours the keys themselves are painted with. Remembered so the
    // resolved rows below compare it by identity rather than by value.
    val palette = remember(kbTheme) { kbTheme.keyPalette() }
    // The key-press particle burst. The field and its glyphs exist only while
    // the theme carries an effect (reduce motion and power saving both zero
    // the count); the spawn lambda is what the keys see, and it reads the box
    // origin live so a burst lands under the finger wherever the grid sits.
    val particleField = remember { ParticleField() }
    val particleGlyphs = rememberEffectGlyphs(kbTheme)
    val particleBurst = burstCount(kbTheme)
    val particlePhysics = rememberEffectPhysics(kbTheme)
    val onBurst: ((Rect, String?) -> Unit)? =
        if (particleBurst > 0 && !particleGlyphs.isEmpty) {
            remember(particleField, particleBurst, particleGlyphs, particlePhysics) {
                { bounds, overrideId ->
                    // The key's own particles when the theme gave it some, and
                    // the board's otherwise; an empty slice throws nothing.
                    val slice = particleGlyphs.sliceFor(overrideId)
                    particleField.spawn(
                        bounds.center.x - boxOrigin.x,
                        bounds.center.y - boxOrigin.y,
                        particleBurst,
                        slice.first,
                        slice.count(),
                        SystemClock.uptimeMillis(),
                        particlePhysics,
                    )
                }
            }
        } else {
            null
        }
    // Customisable glide-trail + start-sensitivity knobs (Settings → Gestures).
    val gesture = state.settings.gesture
    val trailMs = gesture.trailDurationMs.toLong()
    val trailOpacity = gesture.trailOpacity
    val trailHeadWidth = gesture.trailWidthDp
    val startSlop = gesture.startThresholdSlop
    val cooldownMs = gesture.postTypeCooldownMs
    // Which key a glide reads as an apostrophe. Read through a State because the
    // grid is built inside the pointer loop, which outlives this composition.
    val apostropheKey = rememberUpdatedState(gesture.apostropheKey)
    // The spacebar cannot both end a word mid-stroke and stand for an
    // apostrophe: one crossing, two readings. Choosing it as the apostrophe key
    // stands the multi-word split down for as long as that choice holds.
    val spaceGlide = gesture.spaceGlideMultiWord &&
        gesture.apostropheKey != GlideApostropheKey.SPACE
    // Drawing through the shift key capitalizes the word the stroke is writing
    // (#115). Read live for the same reason the apostrophe key is: the stroke's
    // loop outlives this composition.
    val capitalGlide = rememberUpdatedState(gesture.shiftGlideCapitals)
    // Whether each crossing names one letter rather than the word (#163).
    val letterGlide = rememberUpdatedState(gesture.shiftGlideMode == ShiftGlideMode.LETTER)
    // Stamp of the last tap-typed key (uptime ms). A glide starting within
    // [cooldownMs] of it has to travel further before it takes over, so a stray
    // slide off a key during fast tapping is not misread as a swipe-word. Held
    // in a State so the tap handlers below can write it without restarting the
    // gesture detector, which reads it live inside its pointer loop.
    val lastKeyPressTime = remember { mutableLongStateOf(0L) }
    val stampedOnKey = remember(onKey) {
        { k: Key -> lastKeyPressTime.longValue = SystemClock.uptimeMillis(); onKey(k) }
    }
    val stampedOnText = remember(onText) {
        { t: String -> lastKeyPressTime.longValue = SystemClock.uptimeMillis(); onText(t) }
    }
    // The D-pad ring (a television remote, or a hardware keyboard whose owner
    // asked for it): the service moves it, so the grid hands up the cell table
    // it is already keeping and the lambda that types a key. Published in a
    // SideEffect because the controller holds plain vars read from outside
    // Compose — the same reason [PanelFocusTarget] does.
    val keyGridFocus = LocalPanelFocus.current.keyGrid
    val dpadRing = state.settings.hardwareKeyboard.dpadKeyNavigation
    // The centre button spends the same click a finger would, in the key's own
    // role, so the spacebar and backspace still sound like themselves. It is
    // the only feedback a ring press gets: a television has speakers and no
    // vibrator, and `applyTelevision` has already switched the haptics off.
    val ringFeedback = LocalKeyRoleFeedback.current
    if (dpadRing) {
        val typeKey: (Key) -> Unit = remember(stampedOnKey, ringFeedback) {
            { key -> ringFeedback(key.keySoundRole()); stampedOnKey(key) }
        }
        SideEffect { keyGridFocus.publish(keyRects, typeKey) }
    }
    val dotCooldownMs = gesture.handwriteDotCooldownMs
    // Uptime of the last *drawn* handwriting stroke. For [dotCooldownMs] after
    // it, a tap over the letters is grabbed as an ink dot (the mark on an i/j/t)
    // instead of typing, so a two-part character can be completed without the
    // dot committing a letter.
    val lastHwStrokeTime = remember { mutableLongStateOf(0L) }
    // Whether ink is still waiting to be recognized. The dot window only means
    // anything while a character is unfinished: once the strokes have been
    // recognized and committed there is nothing for a dot to join, so grabbing
    // the tap would swallow it — neither typing the key nor adding to a glyph.
    // Read live inside the gesture loop, which must not restart per stroke.
    val hwPendingInk = rememberUpdatedState(state.handwriting.strokes.isNotEmpty())
    // Points of the handwriting stroke being drawn right now (box space); the
    // finished strokes waiting for recognition come back from service state.
    var hwActiveStroke by remember { mutableStateOf<List<Offset>>(emptyList()) }

    KeyGridPassthrough(state, boxOrigin, boxSize)

    // Drives the age fade. Keyed on `visible`, which flips twice a stroke, so
    // this restarts when a glide begins and ends — not when the finger moves.
    // After finger-up the trail is left in place to fade out on its own; tick
    // reports false once every point has expired.
    LaunchedEffect(trail.visible) {
        while (trail.visible) {
            withFrameMillis { now -> trail.tick(now, trailMs) }
        }
    }
    // A trail outlives the thing that drew it otherwise: switching the feature
    // off or changing the layout leaves the last stroke painted over the new
    // grid, because the pointer loop that would have released it is gone.
    //
    // A layer peek (#108) is the exception, on both of its edges. Its drag
    // draws the same band a chord does, and the peek *is* a layout change:
    // clearing on the way in wiped the band the moment the symbols appeared,
    // and clearing on the way out would cut its fade short at the lift. The
    // peek's own gesture releases the trail, so nothing is left behind.
    DisposableEffect(gestureEnabled, layout) {
        val drawnForPeek = peeked != null
        onDispose { if (!drawnForPeek && layerPeek.mode == null) trail.clear() }
    }

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .testTag(KeyRowsTestTag)
            .onGloballyPositioned {
                boxOrigin = it.positionInRoot()
                boxWindow = it.positionInWindow()
                boxSize = it.size
            }
            // Issue #67: a drag that starts on a modifier key and lifts on
            // another fires that chord — Ctrl+C, rather than a latched Ctrl and
            // then a typed "c", and a capital A from shift rather than an armed
            // shift and an a. The latch is untouched for anyone who taps; this is
            // the same thing done in one gesture, which is what a modifier key on
            // a touch keyboard is expected to do.
            //
            // Grid-level rather than on the modifier key itself, because the key
            // the finger *ends* on is the whole point and a key node knows only
            // its own cell. Consuming the drag is what tells the modifier key to
            // drop its press (see the `isConsumed` branch in [pointerInputKey]),
            // so a chord never leaves a latch armed behind it.
            //
            // First in the chain, and both detectors below refuse a touch that
            // began on a modifier: on the Initial pass the outermost handler
            // decides, and both shift and a Ctrl key sitting one row under the
            // letters are well inside the radius [nearLetterKey] would call a
            // glide start.
            //
            // A drag off 🌐 rides the same loop when its shortcut drag is on:
            // the key it lifts on runs that letter's shortcut (copy on `c`),
            // the way Ctrl onto C would, and for the same reason it is claimed
            // here, first, before a glide can take it.
            .pointerInput(stampedOnKey, trailMs, onGlobeShortcut) {
                awaitEachGesture {
                    val down = awaitFirstDown(
                        requireUnconsumed = false,
                        pass = PointerEventPass.Initial,
                    )
                    val source = liveRects.value.keyAt(down.position + boxOrigin)
                    val globe = source.startsGlobeDrag(globeDragLive.value)
                    if (!source.startsChordDrag() && !globe) return@awaitEachGesture
                    // The band is anchored on the key rather than on the
                    // fingertip: a chord is "from this key to that one", and
                    // the cell's centre says so however the press landed in it.
                    val anchor = liveRects.value.cellAt(down.position + boxOrigin)
                        ?.let { it.center - boxOrigin }
                        ?: down.position
                    val slop = viewConfiguration.touchSlop
                    var dragging = false
                    // The cell under the finger now; read per sample so the key
                    // it lifts on is the one it is actually over, and not the
                    // last one a hit test happened to land in.
                    var over: Key? = null
                    val mod = source.modifierKey()
                    // What a lift on [target] fires, or null for nothing. Asked
                    // per key crossed as well as at the lift, so the key lit
                    // under the finger is always one the lift would act on.
                    fun fires(target: Key): Boolean = when {
                        target === source -> true
                        globe -> globeDragAction(target, letterActionsLive.value) != null
                        mod != null -> chordKey(target, mod) != null
                        else -> shiftChordKey(target) != null
                    }
                    // Everything the drag puts on screen is undone here, and
                    // only here, the way the layer peek's is: a loop cancelled
                    // mid-drag would otherwise leave the letters drawn as
                    // capitals with no finger on shift.
                    try {
                        while (true) {
                            val event = awaitPointerEvent(PointerEventPass.Initial)
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) {
                                if (dragging) change.consume()
                                break
                            }
                            if (!dragging &&
                                (change.position - down.position).getDistance() > slop
                            ) {
                                // A 🌐 held still long enough has opened the
                                // language picker, and a drag from there is the
                                // picker's: the key's own press is left as it is.
                                if (globe && change.uptimeMillis - down.uptimeMillis >= globeHoldMs.value) {
                                    return@awaitEachGesture
                                }
                                dragging = true
                                trail.beginLine(anchor.x, anchor.y)
                                chordDrag.active = true
                                chordDrag.shifted = source?.action == KeyAction.Shift
                            }
                            if (dragging) {
                                change.consume()
                                trail.add(
                                    change.position.x,
                                    change.position.y,
                                    change.uptimeMillis,
                                    trailMs,
                                )
                                val rects = liveRects.value
                                val now = rects.keyAt(change.position + boxOrigin)
                                if (now !== over) {
                                    over = now
                                    chordDrag.pressRect.value = now
                                        ?.takeIf(::fires)
                                        ?.let { rects.cellAt(change.position + boxOrigin) }
                                        ?.translate(-boxOrigin)
                                }
                            }
                        }
                        // Never travelled: an ordinary press the modifier key owns,
                        // still unconsumed, and it latches exactly as it always has.
                        if (!dragging) return@awaitEachGesture
                        trail.release()
                        val target = over
                        when {
                            // Lifted off the grid: the slide-away cancel every other
                            // key already has, and nothing fires.
                            target == null -> Unit
                            // Wandered off and came back. The press was cancelled on
                            // the way out, so the tap it would have been is fired
                            // here rather than swallowed.
                            target === source -> stampedOnKey(target)
                            // Onto a key with no shortcut: nothing, like a chord
                            // onto a key no hardware keyboard could send.
                            globe -> globeDragAction(target, letterActionsLive.value)?.let(onGlobeShortcut)
                            else -> {
                                val fired =
                                    if (mod != null) chordKey(target, mod) else shiftChordKey(target)
                                fired?.let(stampedOnKey)
                            }
                        }
                    } finally {
                        chordDrag.active = false
                        chordDrag.shifted = false
                        chordDrag.pressRect.value = null
                    }
                }
            }
            // Issue #108: a drag off `?123` — or off the `ABC` key a symbol or
            // secondary layer carries — shows that layer for as long as the
            // finger is down and types the key it lifts on. One symbol without
            // leaving the letters, which is what the same gesture does on the
            // stock keyboards, and the way back for a layer whose own key is
            // the only way home.
            //
            // Beside the chord drag, and grid-level for the same two reasons:
            // the key the finger *ends* on is the whole point, and consuming
            // the drag is what tells the mode key to drop the press it would
            // otherwise have committed as a real layer switch. Nothing about
            // the board's own state is touched, so the lift puts the keys back
            // with nothing to undo.
            //
            // Holding still over a key opens that key's alternates, and the
            // finger steers them whether or not "choose without lifting" is on:
            // lifting is what ends the peek, so a popup that waited for a lift
            // to choose could never be chosen from at all.
            .pointerInput(stampedOnKey, trailMs, state.settings.longPressDelayMs) {
                detectLayerPeek(
                    peek = layerPeek,
                    rects = { liveRects.value },
                    origin = { boxOrigin },
                    window = { boxWindow },
                    peekFor = { source -> layerDragMode(source, liveMode.value) },
                    trail = trail,
                    trailMs = trailMs,
                    dwellMs = state.settings.longPressDelayMs.toLong(),
                    onPopupOpen = { if (hapticOn.value) pickerHaptic() },
                    onKey = stampedOnKey,
                )
            }
            // The octopus (discussion #102). Two gestures, one loop, sitting
            // above the glide loop because both of them have to answer before
            // it claims the stroke.
            //
            // The tap is decided at the down — a finger on a floating word is
            // unambiguous — so it consumes immediately. The flick cannot be:
            // it is only a flick once it is over, so this consumes *nothing*
            // until the finger lifts. That matters. A move consumed on
            // speculation would leave a stroke that turned out not to be a
            // flick with no owner, and slide-off-to-cancel would break with it.
            //
            // The flick half only runs with glide typing off. With it on, the
            // stroke belongs to the glide loop, which asks the same question at
            // its own lift and calls the same function to answer it.
            .pointerInput(
                octopusArmed, octopusTapHere, octopusFlickHere,
                octopusSettings.flickSensitivity, startSlop, cooldownMs,
            ) {
                if (!octopusArmed) return@pointerInput
                awaitEachGesture {
                    val down = awaitFirstDown(
                        requireUnconsumed = false,
                        pass = PointerEventPass.Initial,
                    )
                    // A drag off a modifier is a chord (#67) and one off a mode
                    // key looks through to its layer (#108) — the same refusal
                    // the glide loop makes and for the same reason: shift sits
                    // against the bottom letter row and `?123` sits beside the
                    // space, and a flick off either must not take the
                    // neighbouring key's word. A delete swipe is the same
                    // (#243): backspace sits against the bottom letter row.
                    // So is a spacebar swipe (#333).
                    val downKey = liveRects.value.keyAt(down.position + boxOrigin)
                    if (downKey.ownsDrag() || downKey.startsGlobeDrag(globeDragLive.value) ||
                        downKey.ownsDeleteStroke() || downKey.ownsSpaceStroke()
                    ) {
                        return@awaitEachGesture
                    }
                    val floating = octopusLive.value
                    if (floating.isEmpty()) return@awaitEachGesture
                    // Read through the State, never captured: this loop outlives
                    // a layout change and the table is per layout (#209).
                    val bounds = liveBounds.value
                    val tapped = if (octopusTapHere) {
                        octopusRects.wordAt(down.position, bounds)
                    } else {
                        null
                    }
                    if (tapped != null) {
                        down.consume()
                        var inside = true
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            change.consume()
                            // Slide off the word to change your mind, the way
                            // every other target on this keyboard behaves.
                            inside = octopusRects.wordAt(change.position, bounds) === tapped
                            if (!change.pressed) break
                        }
                        if (inside) octopusPick(tapped.word, OctopusSource.TAP)
                        return@awaitEachGesture
                    }
                    if (!octopusFlickHere) return@awaitEachGesture
                    // Live, like the bounds above and for the same reason: the
                    // centres are per layout, this loop is not, and a flick
                    // anchored on the previous layout's grid reaches for a key
                    // that is no longer under the finger.
                    val startKey =
                        nearestOctopusCentre(liveCenters.value, floating.keys, down.position)
                            ?: return@awaitEachGesture
                    // The nearest word of a stacked key (#136): a flick is aimed
                    // at the key, and the stack's best sits closest to it.
                    val word = floating.top(startKey.first) ?: return@awaitEachGesture
                    val points = ArrayList<GesturePoint>()
                    points.add(
                        GesturePoint(down.position.x, down.position.y, down.uptimeMillis),
                    )
                    var last = down
                    while (true) {
                        val event = awaitPointerEvent()
                        val change = event.changes.firstOrNull { it.id == down.id } ?: break
                        last = change
                        points.add(
                            GesturePoint(change.position.x, change.position.y, change.uptimeMillis),
                        )
                        if (!change.pressed) break
                    }
                    // The glide loop's own start slop grows for a moment after
                    // each keystroke; below it that loop does not consider a
                    // stroke to have begun at all, so a flick bar underneath it
                    // would leave the two answering about different gestures.
                    val sinceTap = down.uptimeMillis - lastKeyPressTime.longValue
                    val boost = if (cooldownMs > 0 && sinceTap in 0 until cooldownMs.toLong()) {
                        1f + POST_TYPE_SLOP_BOOST * (1f - sinceTap.toFloat() / cooldownMs)
                    } else {
                        1f
                    }
                    val slop = viewConfiguration.touchSlop * startSlop * boost
                    val width = keyWidth.value
                    val taken = octopusFlick(
                        points = points,
                        startX = startKey.second.x,
                        startY = startKey.second.y,
                        keyWidthPx = width,
                        startReachPx = width * OCTOPUS_START_REACH_WIDTHS,
                        minTravelPx = maxOf(
                            width * OCTOPUS_MIN_TRAVEL_WIDTHS,
                            slop * OCTOPUS_SLOP_CLEARANCE,
                        ),
                        sensitivity = octopusSettings.flickSensitivity,
                    )
                    if (taken) {
                        // Only now, and only the lift: the key's own handler
                        // reads a consumed up as "the grid took this pointer"
                        // and cancels its press, which is exactly right. A miss
                        // consumed nothing, so the key types its letter.
                        last.consume()
                        octopusPick(word.word, OctopusSource.FLICK)
                    }
                }
            }
            .pointerInput(
                gestureEnabled, spaceGlide, startSlop, cooldownMs, trailMs,
                possessiveChar,
            ) {
                if (!gestureEnabled) return@pointerInput
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false, pass = PointerEventPass.Initial)
                    // A drag off a modifier key is a chord (issue #67) and one
                    // off `?123`/`ABC` looks through to that layer (issue #108),
                    // neither of them a word. Answered at the down, where it
                    // cannot change again, and by leaving rather than by another
                    // term in the takeover test below: a pointer this loop never
                    // claims is a pointer it does nothing with.
                    //
                    // Shift is the one that costs something. It sits against the
                    // bottom letter row, so a stroke that began on its inner
                    // edge could start a glide before; now it capitalises the
                    // letter it is dragged to. Starting a word one key further
                    // in is the trade, and it is the gesture issue #67 asked for.
                    //
                    // The possessive key (#169) and the delete keys' swipes
                    // (#243) are the others: backspace sits beside the bottom
                    // letter row, and a layout may put the possessive key beside
                    // a letter, so the letter-distance test below would
                    // otherwise start a glide from either. The spacebar's
                    // swipes too (#333), which sideways lie wholly inside it.
                    val downKey = liveRects.value.keyAt(down.position + boxOrigin)
                    if (downKey.ownsDrag() || downKey.startsPossessiveSwipe(possessiveChar) ||
                        downKey.startsGlobeDrag(globeDragLive.value) ||
                        downKey.ownsDeleteStroke() || downKey.ownsSpaceStroke()
                    ) {
                        return@awaitEachGesture
                    }
                    // The key a flick down would type the hint of (#178), fixed
                    // at the down the way the octopus anchor is: the stroke is
                    // judged at the lift, but the key it began on cannot change.
                    val hintTarget = if (hintFlickOn) {
                        liveRects.value.hintFlickTarget(down.position + boxOrigin)
                    } else {
                        null
                    }
                    // And the capital an up-flick would type, fixed the same way.
                    val capitalTarget = if (capitalFlickOn) {
                        liveRects.value.capitalFlickTarget(down.position + boxOrigin)
                    } else {
                        null
                    }
                    val slop = viewConfiguration.touchSlop
                    // Post-typing cooldown: right after a tap, hold the glide back
                    // by requiring more travel, fading out across the window. A
                    // finger that lands long after the last keypress swipes as
                    // normal (boost 1×).
                    val sinceTap = down.uptimeMillis - lastKeyPressTime.longValue
                    val cooldownBoost = if (cooldownMs > 0 && sinceTap in 0 until cooldownMs.toLong()) {
                        1f + POST_TYPE_SLOP_BOOST * (1f - sinceTap.toFloat() / cooldownMs)
                    } else {
                        1f
                    }
                    val effectiveSlop = startSlop * cooldownBoost
                    var isGesture = false
                    // Completed word segments (multi-word glide) plus the one
                    // being drawn now. With spaceGlide off there is only ever
                    // one segment — the whole stroke, spacebar points included.
                    val segments = ArrayList<List<GesturePoint>>()
                    // What each closed segment's shift crossings asked for,
                    // parallel to [segments].
                    val segCases = ArrayList<GlideCase>()
                    // Reassigned wholesale whenever a word segment closes, so it
                    // is a `var` holding a mutable buffer on purpose.
                    @Suppress("DoubleMutabilityForCollection")
                    var seg = ArrayList<GesturePoint>()
                    var wasOverSpace = false
                    // The shift key's cell, read once as the stroke starts, and
                    // whether the finger is inside it now. Drawing through it
                    // capitalizes the word (#115): one crossing for a capital,
                    // two for a shout, counted on the way in so a slow drag
                    // across the key is still one crossing. Each crossing is
                    // also remembered as the index in `seg` the finger left
                    // for the key at, so the walk out and back can be cut from
                    // the word and, per letter, so the crossing can name the
                    // letter it followed (#163).
                    var shiftRect: Rect? = null
                    // Its centre in the stroke's own space, for the cut.
                    var shiftCenter: GesturePoint? = null
                    var wasOverShift = false
                    var shiftCrossings = 0
                    @Suppress("DoubleMutabilityForCollection")
                    var shiftCuts = ArrayList<Int>()
                    // The key whose word a flick off this stroke would take,
                    // and its centre. Null when nothing is floating there.
                    var flickAnchor: Pair<Int, Offset>? = null
                    // Wall-clock stamp of the last preview. Sample counting was
                    // digitizer-rate dependent — every sixth report is ten
                    // decodes a second at 60 Hz and forty at 240 Hz, so the
                    // same swipe cost four times as much on a better screen.
                    var lastPreviewMs = 0L
                    // The picker's clock: where the finger stopped and when.
                    // Measured against where it stopped rather than the last
                    // sample, so a slow drift never accumulates into a "hold".
                    val dwell = GlideDwell()
                    // Whether this segment has asked for a preview yet. The
                    // picker's choices are only ever the latest preview's, and
                    // arming the timer before this segment has one would open
                    // it on the previous stroke's words — or the previous
                    // word's, after a spacebar crossing.
                    var previewedSeg = false
                    // How far below the anchor the finger has to drop before a
                    // lift cancels the stroke: the anchor key's height, read
                    // when the picker opens.
                    var cancelBelowPx = 0f
                    // The letter grid, built once per stroke rather than per
                    // preview: it cannot change while a finger is down.
                    var keyList: List<KeyCenter>? = null
                    seg.add(GesturePoint(down.position.x, down.position.y, down.uptimeMillis))
                    dwell.reset(down.position.x, down.position.y, down.uptimeMillis)
                    // The finger has held still long enough: freeze the stroke
                    // and ask. From here to the lift nothing is drawn — no
                    // points, no previews, no trail — because the stroke is
                    // finished and the finger is only choosing. Sliding to a
                    // target used to keep feeding the decoder, so the word the
                    // picker showed was not the word the lift decoded (#96).
                    fun askHere() {
                        // The anchor key's height is both the cancel zone's
                        // depth and the unit the targets are spaced in, so it
                        // is read once and handed to the picker.
                        val keyHeight = liveRects.value
                            .cellAt(Offset(dwell.stillX, dwell.stillY) + boxOrigin)?.height
                            ?: keyWidth.value
                        picker.open(
                            glideChoices.value,
                            glideSettings.value.pickerChoices,
                            dwell.stillX,
                            dwell.stillY,
                            keyHeight,
                        )
                        cancelBelowPx = keyHeight
                        // The trail fades where it is; its head stops following
                        // the finger.
                        trail.release()
                        // Fired here rather than routed through the service:
                        // the picker is the composable's own event, and
                        // threading a callback for it would mean another
                        // KeyboardScreen parameter on a function already at
                        // the method-size limit.
                        if (hapticOn.value) pickerHaptic()
                    }
                    while (true) {
                        val dwellMs = glideSettings.value.pickerDwellMs.toLong()
                        val closeCall = previewedSeg && glideCloseCall.value
                        val holdToAsk = previewedSeg && glideSettings.value.ambiguityPicker &&
                            glideSettings.value.pickerHoldToAsk
                        // Only an unfrozen stroke off the spacebar is on a
                        // clock: a finger resting on the spacebar mid-phrase
                        // is thinking, not asking.
                        val timeout = if (isGesture && !picker.isOpen && !wasOverSpace) {
                            dwell.timeout(SystemClock.uptimeMillis(), closeCall, holdToAsk, dwellMs)
                        } else {
                            null
                        }
                        val event = if (timeout == null) {
                            awaitPointerEvent(PointerEventPass.Initial)
                        } else {
                            // The pointer scope's own withTimeoutOrNull, not
                            // kotlinx's: it resumes the pending await with a
                            // timeout and hands back null. A finger that is
                            // genuinely still sends no events at all, which is
                            // why the dwell is a timer and not a check on the
                            // next move — the old check never ran for the
                            // people holding stillest (#96).
                            this.withTimeoutOrNull(timeout) { awaitPointerEvent(PointerEventPass.Initial) }
                        }
                        if (event == null) {
                            val now = SystemClock.uptimeMillis()
                            val choices = glideChoices.value.size
                            when (dwell.onTimeout(now, closeCall, holdToAsk, dwellMs, choices)) {
                                GlideDwell.Action.OPEN -> askHere()
                                GlideDwell.Action.REARM -> dwell.reset(dwell.stillX, dwell.stillY, now)
                                GlideDwell.Action.WAIT -> Unit
                            }
                            continue
                        }
                        val change = event.changes.firstOrNull { it.id == down.id } ?: break
                        if (!change.pressed) {
                            if (isGesture) change.consume()
                            break
                        }
                        // The finger held long enough to open an alternates
                        // popup and is now sliding into it to choose. Left by
                        // returning rather than by another term in the takeover
                        // test below, which is already at detekt's condition
                        // limit — and a stroke this loop abandons is a stroke it
                        // consumes nothing of, so the key keeps its own gesture.
                        // A glide that had already started cancelled the key's
                        // long press on the way, so this can only be the popup.
                        if (!isGesture && alternatesGate.open) break
                        if (!isGesture && keyWidth.value > 0f &&
                            (change.position - down.position).getDistance() > slop * effectiveSlop &&
                            nearLetterKey(
                                down.position,
                                liveCenters.value,
                                keyWidth.value,
                            )
                        ) {
                            isGesture = true
                            dwell.reset(change.position.x, change.position.y, change.uptimeMillis)
                            trail.begin()
                            // Which key's word this stroke could still be
                            // reaching for, fixed at the down: the flick claims
                            // the key the finger landed on, and a stroke that
                            // wanders over another key has not changed its mind
                            // about that, it has stopped being a flick.
                            flickAnchor = if (octopusFlickWanted) {
                                nearestOctopusCentre(
                                    liveCenters.value, octopusLive.value.keys, down.position,
                                )
                            } else {
                                null
                            }
                            // Read with the grid, and only when the stroke could
                            // use it: one table walk per glide rather than one
                            // per pointer sample.
                            shiftRect = if (capitalGlide.value) {
                                liveRects.value.cellOf(KeyAction.Shift)
                            } else {
                                null
                            }
                            shiftCenter = shiftRect?.let {
                                GesturePoint(it.center.x - boxOrigin.x, it.center.y - boxOrigin.y)
                            }
                            // Built once per stroke, from the layout rather than
                            // the measured map alone: a key's shifted and
                            // long-pressed characters have no centre of their
                            // own and take the one their base label reported.
                            keyList = liveLayouts.value.glideKeys(
                                apostropheCenter = apostropheCenter(
                                    apostropheKey.value,
                                    liveCenters.value,
                                    liveSpace.value.value,
                                    boxOrigin,
                                ),
                            ) { codePoint ->
                                liveCenters.value[codePoint]?.let { it.x to it.y }
                            }
                        }
                        if (isGesture) {
                            change.consume()
                            if (picker.isOpen) {
                                // Frozen: the stroke is finished and the finger
                                // is only choosing. Hover and the cancel zone
                                // are all a move can change now.
                                val entered = picker.track(change.position.x, change.position.y, cancelBelowPx)
                                if (entered && hapticOn.value) pickerHaptic()
                                continue
                            }
                            // Crossing the spacebar ends the current word and
                            // begins the next, so a stroke can chain words
                            // without lifting. Spacebar points anchor no letter,
                            // so they are dropped from the word's shape rather
                            // than added to either side.
                            // spaceRect is in root space; lift the box-local
                            // touch point into root space to test it.
                            val overSpace = spaceGlide &&
                                liveSpace.value.value
                                    ?.contains(change.position + boxOrigin) == true
                            // Crossing the shift key asks for a capital. Its
                            // points are dropped from the word for the same
                            // reason the spacebar's are: the detour is an
                            // instruction, not letters, and decoding it would
                            // spell whatever lies between the word and the key.
                            val overShift =
                                shiftRect?.contains(change.position + boxOrigin) == true
                            if (overShift && !wasOverShift) {
                                shiftCrossings++
                                shiftCuts.add(seg.size)
                            }
                            wasOverShift = overShift
                            if (overSpace) {
                                if (!wasOverSpace && seg.size >= 3) {
                                    val (points, case) = glideSegment(
                                        seg, shiftCuts, shiftCenter, keyWidth.value, letterGlide.value,
                                        endedOnShift = false,
                                    )
                                    segments.add(points)
                                    segCases.add(case)
                                    shiftCuts = ArrayList()
                                    seg = ArrayList()
                                    previewedSeg = false
                                }
                            } else if (!overShift) {
                                seg.add(
                                    GesturePoint(
                                        change.position.x,
                                        change.position.y,
                                        change.uptimeMillis,
                                    ),
                                )
                            }
                            wasOverSpace = overSpace
                            // The picker's clock: a finger that stops moving is
                            // asking to be asked. Restarted only by a move past
                            // the still radius, so a finger resting on glass —
                            // never perfectly still — still counts as held.
                            dwell.sample(
                                change.position.x,
                                change.position.y,
                                change.uptimeMillis,
                                keyWidth.value * PICKER_STILL_WIDTHS,
                            )
                            // Appends and drops the aged tail in one go; only
                            // the draw phase ever reads it back.
                            trail.add(
                                change.position.x,
                                change.position.y,
                                change.uptimeMillis,
                                trailMs,
                            )
                            // Says which gesture the keyboard currently thinks
                            // this is, while there is still time to change it:
                            // an even line straight up for a flick, the comet
                            // for a glide. Asked per sample against the shape
                            // alone, so a stroke that has not travelled far
                            // enough yet still reads as the flick it may become.
                            flickAnchor?.let { (_, centre) ->
                                trail.markFlick(
                                    octopusFlickShape(
                                        points = seg,
                                        startX = centre.x,
                                        startY = centre.y,
                                        keyWidthPx = keyWidth.value,
                                        startReachPx = keyWidth.value * OCTOPUS_START_REACH_WIDTHS,
                                        sensitivity = octopusSettings.flickSensitivity,
                                    )
                                )
                            }
                            // Live preview of the word being drawn now, at a
                            // fixed wall-clock cadence.
                            val sincePreview = change.uptimeMillis - lastPreviewMs
                            if (sincePreview >= PREVIEW_INTERVAL_MS && seg.size >= PREVIEW_MIN_POINTS) {
                                lastPreviewMs = change.uptimeMillis
                                keyList?.let { keys ->
                                    previewedSeg = true
                                    val (points, case) = glideSegment(
                                        seg, shiftCuts, shiftCenter, keyWidth.value, letterGlide.value,
                                        endedOnShift = wasOverShift,
                                    )
                                    onGesturePreview(
                                        points, keys, keyWidth.value,
                                        wordCaseOr(case, letterGlide.value, shiftCrossings),
                                    )
                                }
                            }
                        }
                    }
                    if (isGesture) {
                        // A short flick down off the key it began on is its hint,
                        // not a word (#178). Asked before the picker's verdict and
                        // the decoder alike: a stroke this quick never froze the
                        // picker and crossed no spacebar, and there is nothing to
                        // decode. A preview it managed to send is retired the way
                        // a cancelled stroke's is, and the hint is typed as a
                        // popup's pick would be.
                        if (hintTarget != null && segments.isEmpty() && !picker.isOpen &&
                            hintFlick(
                                points = seg,
                                keyHeightPx = hintTarget.second.height,
                                minTravelPx = maxOf(
                                    hintTarget.second.height * HINT_FLICK_MIN_TRAVEL_HEIGHTS,
                                    slop * effectiveSlop * OCTOPUS_SLOP_CLEARANCE,
                                ),
                            )
                        ) {
                            trail.release()
                            if (previewedSeg) {
                                keyList?.let { onGesture(seg, it, keyWidth.value, GlideVerdict.Cancel) }
                            }
                            stampedOnText(hintTarget.first.longPress.first())
                            return@awaitEachGesture
                        }
                        // Its upward twin, the capital. Not over a key carrying
                        // an octopus word ([flickAnchor] is set only then): an
                        // upward flick there has always taken the word.
                        if (capitalTarget != null && flickAnchor == null && segments.isEmpty() &&
                            !picker.isOpen &&
                            keyFlick(
                                points = seg,
                                keyHeightPx = capitalTarget.second.height,
                                minTravelPx = maxOf(
                                    capitalTarget.second.height * HINT_FLICK_MIN_TRAVEL_HEIGHTS,
                                    slop * effectiveSlop * OCTOPUS_SLOP_CLEARANCE,
                                ),
                                direction = KeyFlickDirection.UP,
                            )
                        ) {
                            trail.release()
                            if (previewedSeg) {
                                keyList?.let { onGesture(seg, it, keyWidth.value, GlideVerdict.Cancel) }
                            }
                            stampedOnText(capitalTarget.first)
                            return@awaitEachGesture
                        }
                        // Lifting on a target takes that word; lifting in the
                        // cancel zone takes nothing; lifting anywhere else takes
                        // the decoder's own first choice, so an ignored picker
                        // costs nothing.
                        val wasOpen = picker.isOpen
                        // The shift crossings ride with the picker's answer
                        // rather than on a callback of their own: the lift has
                        // one more thing to say about the word, and
                        // ServiceKeyboardContent has no room for another
                        // parameter (see [GlideVerdict]).
                        val answer = picker.verdict()
                        picker.close()
                        // A picker opens on a preview, and a preview needs only
                        // three points, so a frozen last segment is committed
                        // at that floor rather than the four an ordinary lift
                        // asks for — or the service would never hear about the
                        // pick, or the cancel, and would keep the stroke's
                        // previews on screen.
                        // A flick is fast, and a fast stroke can be over in two
                        // or three samples. At the ordinary floor those never
                        // reached the service at all, so the word was not picked
                        // *and* nothing was typed — the stroke simply vanished.
                        // Two is enough to have a direction, which is all the
                        // flick test asks for; the decoder refuses a stroke this
                        // short by itself, so nothing is glided on the strength
                        // of it either.
                        val floor = when {
                            octopusFlickWanted -> OCTOPUS_MIN_POINTS
                            wasOpen -> PREVIEW_MIN_POINTS
                            else -> COMMIT_MIN_POINTS
                        }
                        if (seg.size >= floor) {
                            val (points, case) = glideSegment(
                                seg, shiftCuts, shiftCenter, keyWidth.value, letterGlide.value,
                                endedOnShift = wasOverShift,
                            )
                            segments.add(points)
                            segCases.add(case)
                        }
                        val words = ArrayList<List<GesturePoint>>(segments.size)
                        val cases = ArrayList<GlideCase>(segments.size)
                        segments.forEachIndexed { index, segment ->
                            if (segment.size >= floor) {
                                words.add(segment)
                                cases.add(segCases[index])
                            }
                        }
                        // Under the whole-word reading the stroke's crossings
                        // are counted together and land on its first word,
                        // the only one a held shift reaches either.
                        if (cases.isNotEmpty()) {
                            cases[0] = wordCaseOr(cases[0], letterGlide.value, shiftCrossings)
                        }
                        val verdict = answer.withCases(cases)
                        val keys = keyList
                        if (words.isNotEmpty() && keys != null) {
                            if (words.size > 1) {
                                onGestureWords(words, keys, keyWidth.value, verdict)
                            } else {
                                onGesture(words.first(), keys, keyWidth.value, verdict)
                            }
                        }
                        trail.release()
                    }
                }
            }
            // Handwriting: a drag over the keys is one ink stroke instead of a
            // glide. Only one of the two detectors is ever live — glide's
            // `gestureEnabled` is false whenever `handwriteSwipe` is true. A
            // press that never travels past the slop stays unconsumed and
            // falls through to the key, so taps still type.
            .pointerInput(handwriteSwipe, dotCooldownMs, possessiveChar) {
                if (!handwriteSwipe) return@pointerInput
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false, pass = PointerEventPass.Initial)
                    // A drag off a modifier or shift key is a chord (issue
                    // #67), one off a mode key is a layer peek (issue #108),
                    // one off the possessive key is its swipe (#169), one off
                    // a delete key deletes (#243), and one off the spacebar is
                    // its own swipe (#333); none of them must be drawn as ink
                    // either.
                    val downKey = liveRects.value.keyAt(down.position + boxOrigin)
                    if (downKey.ownsDrag() || downKey.startsPossessiveSwipe(possessiveChar) ||
                        downKey.startsGlobeDrag(globeDragLive.value) ||
                        downKey.ownsDeleteStroke() || downKey.ownsSpaceStroke()
                    ) {
                        return@awaitEachGesture
                    }
                    val slop = viewConfiguration.touchSlop
                    // Dot window: for a short spell after a drawn stroke, a tap
                    // over the letters is taken as another stroke of the same
                    // character (the dot/cross) rather than typing a key. Only
                    // over a letter, so space/enter still work; captured from the
                    // down so even a stationary tap is grabbed as ink.
                    val dotWindow = dotCooldownMs > 0 && keyWidth.value > 0f &&
                        hwPendingInk.value &&
                        down.uptimeMillis - lastHwStrokeTime.longValue in 0 until dotCooldownMs.toLong() &&
                        nearLetterKey(down.position, liveCenters.value, keyWidth.value)
                    var isStroke = dotWindow
                    // Whether the finger actually travelled — only a real drawn
                    // stroke reopens the dot window, so a dot-tap does not keep
                    // swallowing later taps.
                    var moved = false
                    val pts = ArrayList<HwPoint>()
                    val live = ArrayList<Offset>()
                    pts.add(HwPoint(down.position.x, down.position.y, down.uptimeMillis))
                    live.add(down.position)
                    if (isStroke) down.consume()
                    while (true) {
                        val event = awaitPointerEvent(PointerEventPass.Initial)
                        val change = event.changes.firstOrNull { it.id == down.id } ?: break
                        if (!change.pressed) {
                            if (isStroke) change.consume()
                            break
                        }
                        if ((change.position - down.position).getDistance() > slop * 2) {
                            isStroke = true
                            moved = true
                        }
                        if (isStroke) {
                            change.consume()
                            pts.add(HwPoint(change.position.x, change.position.y, change.uptimeMillis))
                            live.add(change.position)
                            hwActiveStroke = live.toList()
                        }
                    }
                    // A dot tap is a single-point stroke; a drawn stroke needs at
                    // least two points to have a shape.
                    if (isStroke && pts.size >= (if (moved) 2 else 1)) {
                        onKeyboardHandwritingStroke(HwStroke(pts.toList()), boxSize)
                        // Only a drawn stroke arms the dot window for the next tap.
                        if (moved) lastHwStrokeTime.longValue = SystemClock.uptimeMillis()
                    }
                    hwActiveStroke = emptyList()
                }
            }
            // Issue #178: a short flick down off a key types its corner hint.
            // Below the glide and handwriting loops on purpose, and on the same
            // Initial pass: a stroke either of them took arrives here consumed
            // and is theirs — the glide loop asks this same question at its own
            // lift. What reaches this loop unconsumed is every stroke they never
            // claimed: a board with glide typing off, a symbol layer, a
            // punctuation key. Judged at the lift and consuming only the lift,
            // exactly as the octopus flick does, so a stroke that turns out not
            // to be a flick still lands on the key it began on; a consumed lift
            // is what tells that key to drop the press it would have typed.
            //
            // The up-flick capital shares the loop: one stroke, judged at the
            // lift against whichever of the two its key takes. An upward stroke
            // off a key carrying an octopus word is left for the octopus loop,
            // which runs on the Main pass after this one.
            .pointerInput(hintFlickOn, capitalFlickOn, octopusFlickWanted) {
                if (!hintFlickOn && !capitalFlickOn) return@pointerInput
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false, pass = PointerEventPass.Initial)
                    val at = down.position + boxOrigin
                    val hint = if (hintFlickOn) liveRects.value.hintFlickTarget(at) else null
                    val capital = if (capitalFlickOn) {
                        liveRects.value.capitalFlickTarget(at)?.takeUnless {
                            octopusFlickWanted &&
                                nearestOctopusCentre(liveCenters.value, octopusLive.value.keys, down.position) != null
                        }
                    } else {
                        null
                    }
                    val cell = hint?.second ?: capital?.second ?: return@awaitEachGesture
                    // Floored at the system slop with room to spare, so a tiny
                    // key cannot turn a sloppy tap into a flick.
                    val minTravel = maxOf(
                        cell.height * HINT_FLICK_MIN_TRAVEL_HEIGHTS,
                        viewConfiguration.touchSlop * HINT_FLICK_SLOP_FLOOR,
                    )
                    val points = ArrayList<GesturePoint>()
                    points.add(GesturePoint(down.position.x, down.position.y, down.uptimeMillis))
                    while (true) {
                        val event = awaitPointerEvent(PointerEventPass.Initial)
                        val change = event.changes.firstOrNull { it.id == down.id }
                            ?: return@awaitEachGesture
                        // Another loop took the stroke, or the hold opened the
                        // key's popup and the finger is choosing in it.
                        if (change.isConsumed || alternatesGate.open) return@awaitEachGesture
                        points.add(GesturePoint(change.position.x, change.position.y, change.uptimeMillis))
                        if (!change.pressed) {
                            val typed = when {
                                hint != null && hintFlick(points, cell.height, minTravel) ->
                                    hint.first.longPress.first()
                                capital != null &&
                                    keyFlick(points, cell.height, minTravel, KeyFlickDirection.UP) ->
                                    capital.first
                                else -> null
                            }
                            if (typed != null) {
                                change.consume()
                                stampedOnText(typed)
                            }
                            return@awaitEachGesture
                        }
                    }
                }
            }
            // Issue #169: a short straight swipe from the chosen punctuation
            // key to `s` appends `'s` to the word behind the caret; to `t`,
            // `d`, `m`, `l`, `r` or `v` the matching contraction (#243). The
            // glide loop never claims a stroke that begins on a punctuation
            // key, so every one of them — glide typing on or off, after a
            // glided word or a tapped one — arrives here unconsumed.
            //
            // Owned the way the modifier chord drag owns its stroke (#67), and
            // for the two reasons #243 found: a slow swipe let the key's hold
            // timer open its popup mid-stroke, which then committed the comma's
            // first alternate, `!`; and nothing on screen said the swipe was
            // being read at all. So once the finger leaves the slop the stroke
            // is claimed — every move consumed, which is what tells the key to
            // drop its press and its timer — and a rubber band runs from the key
            // to the fingertip. A hold that opened the popup *before* the finger
            // moved is still the popup's.
            //
            // Judged at the lift. A stroke that is not the swipe and lifts back
            // on the key it began on types that key, as the chord drag does; one
            // that lifts anywhere else types nothing, the slide-off cancel every
            // key has. The hint flick sits above this loop on the same pass, so
            // a flick down off the comma is still its hint: it consumes the lift
            // before this loop sees it.
            .pointerInput(possessiveChar, trailMs) {
                if (possessiveChar == null) return@pointerInput
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false, pass = PointerEventPass.Initial)
                    val width = keyWidth.value
                    if (width <= 0f) return@awaitEachGesture
                    val centers = liveCenters.value
                    val from = centers[possessiveChar.code] ?: return@awaitEachGesture
                    // Only a stroke that begins on the chosen key is worth
                    // following; every other one is some other loop's.
                    if ((down.position - from).getDistance() > width * POSSESSIVE_REACH_WIDTHS) {
                        return@awaitEachGesture
                    }
                    val targets = CONTRACTION_SUFFIXES.keys.mapNotNull { letter ->
                        centers[letter.code]?.let { KeyCenter(letter, it.x, it.y) }
                    }
                    if (targets.isEmpty()) return@awaitEachGesture
                    val source = liveRects.value.keyAt(down.position + boxOrigin)
                    // The key's own lift test, half a key beyond each edge, so
                    // a tap that wobbled past the slop still types the key.
                    val sourceCell = liveRects.value.cellAt(down.position + boxOrigin)?.let {
                        it.inflate(minOf(it.width, it.height) / 2f)
                    }
                    val slop = viewConfiguration.touchSlop
                    var dragging = false
                    val points = ArrayList<GesturePoint>()
                    points.add(GesturePoint(down.position.x, down.position.y, down.uptimeMillis))
                    while (true) {
                        val event = awaitPointerEvent(PointerEventPass.Initial)
                        val change = event.changes.firstOrNull { it.id == down.id }
                        // Another loop took the stroke, or the hold opened the
                        // key's popup and the finger is choosing in it.
                        if (change == null || change.isConsumed || alternatesGate.open) {
                            if (dragging) trail.release()
                            return@awaitEachGesture
                        }
                        points.add(GesturePoint(change.position.x, change.position.y, change.uptimeMillis))
                        if (!change.pressed) {
                            if (!dragging) return@awaitEachGesture
                            change.consume()
                            trail.release()
                            val letter = contractionFlick(
                                points,
                                from = KeyCenter(possessiveChar, from.x, from.y),
                                targets = targets,
                                keyWidthPx = width,
                            )
                            val taken = letter != null && possessiveFlickTaken(letter)
                            if (!taken && source != null &&
                                sourceCell?.contains(change.position + boxOrigin) == true
                            ) {
                                stampedOnKey(source)
                            }
                            return@awaitEachGesture
                        }
                        if (!dragging && (change.position - down.position).getDistance() > slop) {
                            dragging = true
                            trail.beginLine(from.x, from.y)
                        }
                        if (dragging) {
                            change.consume()
                            trail.add(change.position.x, change.position.y, change.uptimeMillis, trailMs)
                        }
                    }
                }
            }
            // Smart key-hit detection: watch every pointer-down on the Initial
            // pass (before the keys see it), and if a likelier neighbour should
            // claim this touch, record the remap for the owning key to consume
            // on release. Never consumes — taps, glides and long-presses are all
            // untouched; only which letter finally commits can change.
            .pointerInput(smartHit) {
                if (!smartHit) return@pointerInput
                awaitPointerEventScope {
                    while (true) {
                        val event = awaitPointerEvent(PointerEventPass.Initial)
                        for (change in event.changes) {
                            when {
                                change.changedToDownIgnoreConsumed() -> {
                                    val target = smartHitTarget(
                                        change.position,
                                        liveCenters.value,
                                        keyWidth.value,
                                        nextBias.value,
                                        hitStrength.value,
                                    )
                                    if (target != null) {
                                        hitRemap[change.id] = target
                                    } else {
                                        hitRemap.remove(change.id)
                                    }
                                }
                                // Any lift OR cancel (glide steals the pointer):
                                // once it is no longer pressed the remap is spent.
                                !change.pressed -> hitRemap.remove(change.id)
                            }
                        }
                    }
                }
            }
            // Touch-position capture for the engine's typo model: record every
            // down, always on (unlike smart hit above). Never consumes; the
            // committed key reads the position via smartResolve on release.
            .pointerInput(Unit) {
                awaitPointerEventScope {
                    while (true) {
                        val event = awaitPointerEvent(PointerEventPass.Initial)
                        for (change in event.changes) {
                            if (change.changedToDownIgnoreConsumed()) {
                                // Ids increase monotonically, so entries are
                                // never overwritten — prune wholesale instead
                                // of on lift (see downPositions above).
                                if (downPositions.size > 32) downPositions.clear()
                                downPositions[change.id] = change.position
                            }
                        }
                    }
                }
            },
    ) {
        // No spacing between cells: each key's touch target fills its whole
        // grid cell (gaps included) so a press landing between two keys
        // still hits the nearest one. The visual gap comes from per-key
        // padding inside KeyButton.
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = KeyRowsPadHorizontal, vertical = KeyRowsPadVertical),
        ) {
            // Records the spacebar's rect in *root* coordinates for the
            // multi-word split. Stored root-relative rather than box-relative on
            // purpose: this callback can fire before the Box's own
            // onGloballyPositioned has set `boxOrigin`, and unlike the letter
            // centres (a state map the keys keep re-reporting) it fires only
            // once, so subtracting a still-zero `boxOrigin` here would leave the
            // rect stuck in absolute space and the containment test — which runs
            // in box space — would never hit. The gesture loop adds the live
            // `boxOrigin` at test time instead, when the Box is laid out.
            val onSpacePositioned: (LayoutCoordinates) -> Unit = remember(spaceRect) {
                { coords -> spaceRect.value = coords.boundsInRoot() }
            }
            val settings = state.settings
            val split = settings.splitKeyboard
            val splitGapPercent = settings.splitGapPercent
            // The focused field wants a keypad, which suppresses the preview
            // bubble unless the user opted back in.
            val numericField = state.fieldKind.isNumericPad
            // The layer the grid is *drawing*, which a peek (issue #108) moves
            // and the board's own state does not follow. Everything else here
            // reads [KeyboardUiState.layoutMode] directly, so the row keeps its
            // digits and the board keeps its height while a peek is up.
            val mode = layerPeek.mode ?: state.layoutMode
            // The digits keep the same slot on every layer, so switching
            // layers moves neither the row nor the pad below it. The `?123`
            // layer leads with its own digit row, which would be a second
            // copy directly underneath — `bodyRows` swaps that one out for
            // the symbols the layer otherwise has no room for.
            val numberRow = numberRowShown(state)
            // Whether the `?123` layer gives its digit row away. Keyed off the
            // *global* number row rather than [numberRowShown], because the
            // digits are already up on the letters layer whenever that switch
            // is on — including when the user has kept the row off the symbol
            // layers. That is what makes "number row in symbols" hide the
            // digits and nothing else. Reading the visible row instead put the
            // digit row back on top of ?123 and took the fill row away with
            // it, so the option looked like it deleted a row of symbols
            // (issue #93).
            val symbolsGiveUpDigits = state.settings.numberRow &&
                state.layoutMode != LayoutMode.SECONDARY
            // Remembered, not written inline: this and the spacebar's callback
            // above are parameters of every row and every key, so a fresh
            // instance per composition would be enough on its own to stop the
            // whole grid from skipping. It reads what it writes to — the centres
            // map, the rect table, the box origin — when the layout calls it, so
            // holding one instance changes nothing it sees.
            //
            // The token is how the rect table learns that the rows it holds are
            // the old ones: everything that can move a key is in it, and the
            // first key to report under a new one wipes the table. Identity
            // rather than a value, so two grids that compare equal still count
            // as two (see [KeyRects.record]).
            val gridToken = remember(
                layout, boxOrigin, boxSize, split, mode, numberRow, symbolsGiveUpDigits,
            ) { Any() }
            // Read live rather than captured, so a grid that moves does not also
            // hand every key a new lambda and cost the whole board a skip.
            val liveToken = rememberUpdatedState(gridToken)
            val onKeyPositioned: (Key, LayoutCoordinates) -> Unit =
                remember(keyCenters, keyRects, keyBounds) {
                    { key, coords ->
                        keyRects.record(liveToken.value, key, coords.boundsInRoot())
                        // The key's centre is reported under the first character
                        // it writes, which is the same character the glide grid
                        // anchors it by. Not `singleOrNull`: a Bengali nukta key
                        // (ড়, ঢ়, য়) writes two characters, and keying it by
                        // "exactly one" drops the key — and its shifted twin —
                        // off the grid.
                        //
                        // The comma, full stop and apostrophe keys report too,
                        // because the apostrophe-in-a-glide setting needs to know
                        // where they are. They are not letters and nothing treats
                        // them as letters: both consumers of the map that are
                        // about letters filter them back out (see
                        // [GlidePunctuationCodePoints]).
                        val letter = key.glideAnchor() ?: key.glidePunctuationCodePoint()
                        if (letter != null) {
                            val topLeft = coords.positionInRoot() - boxOrigin
                            val center = Offset(
                                topLeft.x + coords.size.width / 2f,
                                topLeft.y + coords.size.height / 2f,
                            )
                            val bounds = Rect(
                                topLeft,
                                Size(
                                    coords.size.width.toFloat(),
                                    coords.size.height.toFloat(),
                                ),
                            )
                            keyCenters[Character.toLowerCase(letter)] = center
                            keyBounds[Character.toLowerCase(letter)] = bounds
                            // Every letter of an ambiguous key reports the same
                            // centre and the same rect, because they are the
                            // same key. That is what puts all of `abc` into the
                            // touch model — so the decoder can price a reading
                            // through any of them — and it costs nothing on the
                            // 1:1 boards, where the set is the anchor alone.
                            for (extra in key.letterSet()) {
                                val code = Character.toLowerCase(extra.code)
                                if (code == Character.toLowerCase(letter)) continue
                                keyCenters[code] = center
                                keyBounds[code] = bounds
                            }
                        }
                    }
                }
            val fillRow = state.layouts.symbolsFillRow ?: BuiltInLayouts.SYMBOLS_FILL_ROW
            val bodyRows = remember(layout, mode, symbolsGiveUpDigits, fillRow) {
                // Only when that first row really is the digits. A custom
                // symbols layer that leads with something else would otherwise
                // lose its top row outright, with nothing on screen to explain
                // where it went.
                if (symbolsGiveUpDigits && mode == LayoutMode.SYMBOLS && leadsWithDigitRow(layout.rows)) {
                    listOf(fillRow) + layout.rows.drop(1)
                } else {
                    layout.rows
                }
            }
            // Hoisted out of the render loop so the digit row resolves in the
            // same pass as the body rows below; null when it is not shown.
            val extraRow = if (numberRow) rememberExtraRow(state, fillRow) else null
            val (numberRowVisual, bodyBlocks) =
                rememberKeyGrid(gridState, layout, bodyRows, extraRow, palette, gridWeight)
            if (numberRowVisual != null) {
                KeyRow(
                    row = numberRowVisual,
                    settings = settings,
                    split = split,
                    numericField = numericField,
                    layoutId = state.layoutId,
                    keyPreview = keyPreview,
                    onKey = stampedOnKey,
                    onText = stampedOnText,
                    onCursorMove = onCursorMove,
                    onLayoutSelect = onLayoutSelect,
                    onKeyPositioned = onKeyPositioned,
                    smartResolve = smartResolve,
                    onBurst = onBurst,
                )
            }
            // Layers shorter than the reserved span pad at the top rather than
            // stretching. The bottom row — space and enter — has to stay under
            // the thumb at the same height on every layer, and growing the keys
            // to fill instead would change a target size the user has learned,
            // mid-sentence. Without this the panels, sized to rowSpan, would be
            // taller than the keys.
            val padRows = reservedRowSpan(state) - bodyRows.size
            val lane = octopusLane(state)
            if (padRows > 0) {
                Spacer(
                    modifier = Modifier.height(
                        (state.settings.keyHeightDp.dp + keyGapV(state.settings) * 2 + lane) *
                            padRows,
                    ),
                )
            }
            for (block in bodyBlocks) {
                if (lane > 0.dp) {
                    // A band stands for several rows, so it reserves several
                    // lanes — the words above its second row need somewhere to
                    // go as much as the ones above its first.
                    val rows = when (block) {
                        is KeyGridBlock.Row -> 1
                        is KeyGridBlock.Band -> block.band.rowHeights.size.coerceAtLeast(1)
                    }
                    Spacer(modifier = Modifier.height(lane * rows))
                }
                when (block) {
                    is KeyGridBlock.Row -> KeyRow(
                        row = block.row,
                        settings = settings,
                        split = split,
                        numericField = numericField,
                        layoutId = state.layoutId,
                        keyPreview = keyPreview,
                        onKey = stampedOnKey,
                        onText = stampedOnText,
                        onCursorMove = onCursorMove,
                        onLayoutSelect = onLayoutSelect,
                        onKeyPositioned = onKeyPositioned,
                        onSpacePositioned = onSpacePositioned,
                        smartResolve = smartResolve,
                        onBurst = onBurst,
                    )

                    is KeyGridBlock.Band -> KeyBand(
                        band = block.band,
                        settings = settings,
                        numericField = numericField,
                        layoutId = state.layoutId,
                        keyPreview = keyPreview,
                        onKey = stampedOnKey,
                        onText = stampedOnText,
                        onCursorMove = onCursorMove,
                        onLayoutSelect = onLayoutSelect,
                        onKeyPositioned = onKeyPositioned,
                        onSpacePositioned = onSpacePositioned,
                        smartResolve = smartResolve,
                        onBurst = onBurst,
                    )
                }
            }
        }

        // The theme's stickers, laid over the keys and under the transient
        // layers (trail, ink, popups). A plain Canvas takes no touches, so
        // typing goes straight through a decal; it draws only when the board
        // draws, with no clock of its own.
        BoardDecalsOverlay(kbTheme)

        // The key a layer peek is over, lit the way a press lights a key
        // (issue #108). The grid owns that finger, so the key itself never runs
        // the press that would have drawn it, and without this nothing on
        // screen says which symbol the lift is about to type. Composed only
        // while a peek is up — the rect inside it is read in the draw lambda,
        // so the finger crossing keys repaints and never recomposes.
        LayerPeekHighlight(layerPeek, state.settings)
        // The key a chord drag would fire on, lit for the same reason (#345).
        if (chordDrag.active) GridPressHighlight(chordDrag.pressRect, state.settings)

        // Autopilot's drawn letters and the octopus words over the keys.
        KeyGridWordOverlays(
            state = state,
            smartHit = smartHit,
            keyCenters = keyCenters,
            keyBounds = keyBounds,
            hitStrength = hitStrength.value,
            keyWidth = keyWidth.value,
            boxSize = boxSize,
            glideActive = trail.visible,
            lastKeyPressTime = lastKeyPressTime,
            letterKeys = letterKeys,
            palette = palette,
            kbTheme = kbTheme,
            pickerOpen = picker.words.isNotEmpty(),
            octopusRects = octopusRects,
        )

        // The press bursts, over the decals and under the trail. Composed only
        // while particles live; the frame loop dies with them.
        KeyPressEffectsOverlay(particleField, particleGlyphs)

        // Only a grid with no frame above it draws its own bubbles — see
        // [KeyPreviewOverlay] and [LocalKeyPreviewState].
        if (hoistedPreview == null) {
            KeyPreviewOverlay(
                keyPreview, state.settings, boxOrigin, boxSize,
                modifier = Modifier.matchParentSize(),
                virtualHeadroom = true,
            )
        }

        // `visible` flips twice a stroke, so this composes and decomposes once
        // per glide. Everything that changes per sample is read inside the draw
        // lambda below, where it invalidates the draw alone.
        if (trail.visible) {
            Canvas(modifier = Modifier.matchParentSize()) {
                // Comet-style trail: each segment fades and thins with age,
                // so the tail dissolves behind the finger instead of leaving
                // the whole path on screen. Head width, life span and peak
                // opacity all come from the gesture settings.
                val count = trail.sampleCount(trail.revision)
                val headWidth = trailHeadWidth.dp.toPx()
                val tailWidth = headWidth * 0.3f
                // A modifier chord drag is a rubber band, not a comet: one
                // even line from the key it started on to the fingertip, so
                // what it draws is the pair of keys it will fire (issue #67).
                // Two gestures draw one even line rather than a comet, for the
                // same reason: the path the finger wandered says something
                // neither of them means. A chord runs to the fingertip, because
                // its far end *is* the second key. A flick runs straight up
                // from where the finger landed however far off vertical the
                // finger actually is, because the gesture is judged inside a
                // cone and a line that leaned with the finger would promise a
                // precision the test never asks for (discussion #102).
                if (trail.straight || trail.flick) {
                    drawTrailBand(trail, trailColor, trailOpacity, headWidth, trailMs)
                    return@Canvas
                }
                // The comet is *filled* as a ribbon rather than stroked as a
                // chain of round-capped lines, in one piece per sample.
                //
                // A round cap put a whole disc at both ends of every segment,
                // so each interior sample was painted twice — and translucent
                // paint over translucent paint composites: 0.55 over 0.55 is
                // 0.80. Every sample showed as a brighter bead, worst at the
                // head where the stroke is widest, which read as the trail
                // stuttering rather than flowing.
                //
                // A piece runs from the midpoint of the edge behind it to the
                // midpoint of the edge ahead, curving through the sample's own
                // edge point as the control. Neighbours therefore meet at that
                // midpoint sharing a tangent as well as a point: no pixel is
                // covered twice (no beads), no pixel is left uncovered (no
                // seam), and the ribbon reads as a curve rather than as the
                // polygon the raw samples spell. It also closes the gaps the
                // old draw left when a fast flick spaced the samples further
                // apart than the stroke was thick.
                //
                // Per-piece rather than one path for the whole trail because
                // the age fade is per sample, and one path can carry only one
                // opacity. The cost is a drawPath per sample where the old one
                // cost a drawLine.
                fun edgeAt(i: Int): Offset = trail.sampleEdge(
                    i,
                    count,
                    trail.sampleHalfWidth(i, trailMs, headWidth, tailWidth),
                )
                var prevEdge = edgeAt(0)
                var edge = prevEdge
                for (i in 0 until count) {
                    val nextEdge = if (i + 1 < count) edgeAt(i + 1) else edge
                    val life = trail.sampleLife(i, trailMs)
                    if (life > 0f) {
                        val here = Offset(trail.x(i), trail.y(i))
                        val back = if (i > 0) Offset(trail.x(i - 1), trail.y(i - 1)) else here
                        val ahead =
                            if (i + 1 < count) Offset(trail.x(i + 1), trail.y(i + 1)) else here
                        // The tail end and the head end have no neighbour to
                        // meet halfway, so they take the sample itself and the
                        // ribbon simply stops there.
                        val fromLeft = (back + prevEdge + here + edge) / 2f
                        val toLeft = (here + edge + ahead + nextEdge) / 2f
                        val fromRight = (back - prevEdge + here - edge) / 2f
                        val toRight = (here - edge + ahead - nextEdge) / 2f
                        trailQuad.reset()
                        trailQuad.moveTo(fromLeft.x, fromLeft.y)
                        trailQuad.quadraticTo(here.x + edge.x, here.y + edge.y, toLeft.x, toLeft.y)
                        if (i == count - 1) {
                            // The head would be cut square otherwise, which
                            // shows as soon as the finger lifts and the trail
                            // is left on screen to fade. One quadratic bulging
                            // forward by the half width rounds it off, inside
                            // the same fill so it costs no second coverage.
                            // The forward direction is the edge offset turned a
                            // quarter turn, so it needs no second derivation.
                            trailQuad.quadraticTo(
                                here.x + edge.y * 2f,
                                here.y - edge.x * 2f,
                                toRight.x,
                                toRight.y,
                            )
                        } else {
                            trailQuad.lineTo(toRight.x, toRight.y)
                        }
                        trailQuad.quadraticTo(
                            here.x - edge.x,
                            here.y - edge.y,
                            fromRight.x,
                            fromRight.y,
                        )
                        trailQuad.close()
                        drawPath(
                            trailQuad,
                            color = trailColor.copy(alpha = trailOpacity * life),
                        )
                    }
                    prevEdge = edge
                    edge = nextEdge
                }
            }
        }

        // Handwriting ink drawn over the keys: the finished strokes still
        // waiting to be recognized (service state) plus the one under the
        // finger. Unlike the glide trail these stay put until they commit,
        // so the user can see the whole letter or word taking shape.
        if (handwriteSwipe && state.handwriting.status == HandwritingStatus.READY) {
            val inkColor = LocalKbTheme.current.accent
            Canvas(modifier = Modifier.matchParentSize()) {
                val inkWidth = 5.dp.toPx()
                for (stroke in state.handwriting.strokes) {
                    val pts = stroke.points
                    // A tapped dot or cross is a one-point stroke: it has no
                    // segment to draw, so it needs a blob of its own or the
                    // mark on an i/j/t is invisible until the glyph commits.
                    if (pts.size == 1) {
                        drawCircle(
                            color = inkColor,
                            radius = inkWidth / 2f,
                            center = Offset(pts[0].x, pts[0].y),
                        )
                    }
                    for (i in 1 until pts.size) {
                        drawLine(
                            color = inkColor,
                            start = Offset(pts[i - 1].x, pts[i - 1].y),
                            end = Offset(pts[i].x, pts[i].y),
                            strokeWidth = inkWidth,
                            cap = StrokeCap.Round,
                        )
                    }
                }
                for (i in 1 until hwActiveStroke.size) {
                    drawLine(
                        color = inkColor,
                        start = hwActiveStroke[i - 1],
                        end = hwActiveStroke[i],
                        strokeWidth = inkWidth,
                        cap = StrokeCap.Round,
                    )
                }
            }
        }

        // The stroke's floating layer: the word pill and the picker.
        GlideStrokeOverlay(state, trail, picker, boxSize)

        // The alternates a layer peek is holding open (issue #108). Hung off a
        // stand-in the size of the key's own cell rather than off the key
        // itself: the grid owns this finger, so the key under it never ran the
        // press that opens a popup, and a popup places itself against whatever
        // it is put inside. Same position provider, same surface, same entries
        // as a long press gets — only the finger steering it is different.
        LayerPeekPopup(
            layerPeek, state.settings.popup, stampedOnKey, stampedOnText,
            shifted = state.shiftCasesText(),
        )
    }
}

/**
 * The row in the number-row slot for [state]'s layer and field, or the digits.
 *
 * Its own function rather than inline in [KeyRows] for ART's sake: the board's
 * grid runs on every keystroke, and inlined this pushed [KeyRows] past the
 * 10,000-instruction limit above which ART compiles nothing, AOT or JIT.
 */
@Composable
private fun rememberExtraRow(state: KeyboardUiState, fillRow: List<Key>): List<Key> {
    // Follows the same guard as the pad itself, so a search box
    // opened over a number field gets its digit row back.
    val kind = if (numericPadActive(state)) state.fieldKind else FieldKind.TEXT
    val authored = state.authoredNumberRow(state.layoutMode)
    // The digit row tracks the active layer (and, optionally, shift)
    // so the same slot serves more symbols the deeper the user goes:
    // digits on letters/symbols-1, extra symbols on symbols-2, and —
    // when the option is on — the symbol fill row while shift is held
    // on the letters layer.
    val shiftSymbols = state.settings.layoutBehavior.numberRowShiftSymbols
    // On an expanded tablet grid this row also carries backspace,
    // which the body gave up to make room for the mirrored shift —
    // so the two answers have to come from the same condition, or
    // the keyboard has no backspace on it anywhere. Never over a
    // numeric field: that path keeps the four-column keypad, so
    // nothing was given up and a stray ⌫ would just be litter.
    val tabletRow = state.layouts.gridWidth != null && !numericPadActive(state)
    val otherDigits = otherNumeralDigits(state)
    return remember(
        kind,
        authored,
        state.layoutMode,
        state.shiftState,
        shiftSymbols,
        fillRow,
        tabletRow,
        otherDigits,
    ) {
        // The field's own rows and the shift-symbols option come
        // before a row the layout authored: a number row edited in
        // the layout editor is for typing text, and must not put a
        // second set of digits over a keypad or turn the option off.
        val base = when {
            // A keypad already leads with digits, so the row
            // carries what the pad lacks rather than a second set
            // of the same numbers.
            kind == FieldKind.PHONE ->
                listOf("+", "*", "#", ",", ";", "(", ")", "-", "/", ".")
                    .map { Key(it) }
            kind.isNumericPad ->
                listOf("+", "-", "*", "/", "=", "(", ")", "%", ":", ".")
                    .map { Key(it) }
            // Opt-in: holding shift on the letters layer turns the
            // digits into the symbol layer's bracket/math fill row,
            // so symbols are reachable without switching layers.
            state.layoutMode == LayoutMode.LETTERS &&
                state.shiftState != ShiftState.OFF && shiftSymbols -> fillRow
            // A layout can supply its own row for this layer.
            authored != null -> authored
            // Symbols-2 reuses the number-row slot for the arrow and
            // comparison symbols it has nowhere else to put.
            state.layoutMode == LayoutMode.SYMBOLS_SHIFTED ->
                BuiltInLayouts.defaultNumberRow(LayoutLayer.SYMBOLS_SHIFTED)
            // The digits, with the symbol layer's long-presses.
            else -> BuiltInLayouts.defaultNumberRow(LayoutLayer.LETTERS)
        }.withOtherNumerals(otherDigits)
        if (tabletRow) base.expandNumberRowForTablet() else base
    }
}

/**
 * Autopilot's drawn letters and the octopus words over the grid, with the
 * occupancy flags the corner hints read.
 *
 * Split out of [KeyRows] only to keep that function under ART's
 * 10,000-instruction huge-method limit: it runs on every keystroke, and above
 * the limit ART compiles nothing, AOT or JIT.
 */
@Composable
private fun BoxScope.KeyGridWordOverlays(
    state: KeyboardUiState,
    smartHit: Boolean,
    keyCenters: Map<Int, Offset>,
    keyBounds: Map<Int, Rect>,
    hitStrength: Float,
    keyWidth: Float,
    boxSize: IntSize,
    glideActive: Boolean,
    lastKeyPressTime: MutableLongState,
    letterKeys: Map<Char, Key>,
    palette: KeyPalette,
    kbTheme: KbTheme,
    pickerOpen: Boolean,
    octopusRects: OctopusRects,
) {
    // Autopilot, made visible: the letters the dictionary expects next drawn
    // at the size their touch area has grown to, and the boundary each one
    // claimed. Both halves are off by default — the feature is meant to be
    // quiet — so this composes to nothing for most people.
    val autopilotShow = smartHit && state.settings.layoutBehavior.autopilotShowEffect
    val autopilotOutline = smartHit && state.settings.layoutBehavior.autopilotOutline
    if (autopilotShow || autopilotOutline) {
        AutopilotOverlay(
            centers = keyCenters,
            bounds = keyBounds,
            bias = state.nextLetterBias,
            strength = hitStrength,
            keyWidth = keyWidth,
            boardSize = Size(boxSize.width.toFloat(), boxSize.height.toFloat()),
            glideActive = glideActive,
            lastKeyPress = lastKeyPressTime,
            label = { ch ->
                letterKeys[ch]?.let { displayLabel(it, state) } ?: ch.toString()
            },
            settings = state.settings,
            palette = palette,
            kb = kbTheme,
            showEffect = autopilotShow,
            visualScale = state.settings.layoutBehavior.autopilotVisualScale,
            outline = autopilotOutline,
        )
    }

    // The octopus (discussion #102): the word each key is on its way to,
    // floating over that key. Above autopilot, because a key face grown
    // over a word would hide it, and below everything a finger owns.
    OctopusOverlay(
        // A stroke's own alternates while one is being drawn, the buffer's
        // words otherwise. Two fields rather than one because the flick
        // asks, at the lift, what was over the key the finger went down on.
        words = if (glideActive) state.octopusGlide else state.octopus,
        bounds = keyBounds,
        keyWidth = keyWidth,
        boardSize = Size(boxSize.width.toFloat(), boxSize.height.toFloat()),
        // A stroke does *not* hide these: mid-glide they carry the
        // alternates, hung off the keys that reach them, which is the whole
        // of Mokhyy's idea on the thread. The picker does hide them —
        // it is already asking the user a question, and a second set of
        // offers on the board would be answering a different one.
        hidden = pickerOpen,
        // The widest setting of [GlideCommitColorScope]: the promised word
        // drawn on its own key in the strip's colour, so the board answers
        // at a glance. Only while a stroke is being drawn, since between
        // strokes these words are the buffer's and no lift is pending.
        promised = state.autocorrectWord?.takeIf {
            glideActive &&
                state.settings.gesture.commitColorScope ==
                GlideCommitColorScope.EVERYWHERE
        },
        promiseColor = state.settings.suggestionStrip.primaryColor
            ?.let { Color(it.toInt()) },
        settings = state.settings,
        palette = palette,
        kb = kbTheme,
        rects = octopusRects,
    )
    // Which keys are carrying a word, pushed to the draw-time flags the
    // hints read. A SideEffect rather than a LaunchedEffect: no coroutine
    // per keystroke, and it runs after the composition it belongs to has
    // been applied, which is where a write for draw-time readers belongs.
    val occupancy = LocalOctopusOccupancy.current
    val suppressing = state.settings.octopus.enabled &&
        state.settings.octopus.suppressHints
    SideEffect {
        occupancy.set(if (suppressing) state.octopus.keys else emptySet())
    }
}

/**
 * The stroke's floating layer for [KeyRows]: the word pill riding above the
 * finger and, when a stroke stops to ask, the picker's targets. Its own
 * function to keep [KeyRows] under ART's huge-method limit.
 */
@Composable
private fun GlideStrokeOverlay(
    state: KeyboardUiState,
    trail: GlideTrail,
    picker: GlidePickerState,
    boxSize: IntSize,
) {
    // The stroke's floating layer: the word pill riding above the finger
    // and, when a stroke stops to ask, the picker's targets. Its own
    // window, with room above the grid — see [GlideOverlay]. The pill
    // stands down while the picker is up: it would be answering a question
    // the picker is still asking, and with the same word.
    val glide = state.settings.gesture
    // Cased through the commit's own ladder, so a stroke drawn through the
    // shift key previews "That" and not the "that" it used to (#162): the
    // board's shift never changes for a drawn gesture, and the crossings
    // ride in on the preview instead.
    val pillWord = state.glideWord
        ?.takeIf { glide.wordPreview && trail.visible && !trail.released && picker.words.isEmpty() }
        ?.let { word ->
            state.glideCased[word]
                ?: displayCaseForShift(word, shiftForGlide(state.shiftState, state.glideCase))
        }
    // The pill carries the strip's promise when the user has asked for it
    // there (#121). It is the surface the eye is actually on while a stroke
    // is being drawn, so a colour shown only on the strip is a colour
    // mostly unread. Null keeps the pill's own text colour.
    val pillPromise = state.settings.suggestionStrip.primaryColor
        ?.takeIf {
            glide.commitColorScope != GlideCommitColorScope.STRIP &&
                state.glideWord != null &&
                state.glideWord.equals(state.autocorrectWord, ignoreCase = true)
        }
        ?.let { Color(it.toInt()) }
    // A trigger the lift will expand shows what it expands to (#205).
    val pillExpansion = pillWord?.let { shown ->
        state.glideWord?.let(state.glideExpansions::get)?.previewFor(shown)
    }
    if (pillWord != null || picker.words.isNotEmpty()) {
        GlideOverlay(trail, picker, pillWord, glide, boxSize, pillPromise, pillExpansion, state.glideExpansions)
    }
}

/**
 * Publishes the key grid's rectangle for touch-exploration pass-through, and
 * takes it back. Its own function to keep [KeyRows] under ART's huge-method
 * limit.
 */
@Composable
private fun KeyGridPassthrough(state: KeyboardUiState, boxOrigin: Offset, boxSize: IntSize) {
    // Touch-exploration pass-through: while a screen reader is running and the
    // user picked that mode, the app's own accessibility service hands the key
    // grid's rectangle back to the keyboard so its gestures (spacebar cursor
    // slide, backspace word swipe, glide, handwriting) still see real touches.
    //
    // Only the grid, never the whole window: the suggestion strip, the toolbar
    // and every panel stay outside it, so TalkBack keeps exploring those
    // normally. A panel replacing the keys takes this composable with it,
    // which retracts the carve-out on its own.
    val passthroughKeys = LocalTouchExploration.current &&
        state.settings.accessibility.screenReader == ScreenReaderMode.PASSTHROUGH &&
        LocalPassthroughService.current
    val hostView = LocalView.current
    // A board drawn as a picture in the settings app (the theme editor, the
    // layout cards) is not the keyboard: it must neither carve a pass-through
    // hole in the app nor clear the one the real keyboard holds, which lives in
    // the same process and publishes to the same place.
    val ownsPassthrough = !LocalKeyboardPreviewHost.current
    LaunchedEffect(passthroughKeys, boxOrigin, boxSize, hostView, ownsPassthrough) {
        if (!ownsPassthrough) return@LaunchedEffect
        if (!passthroughKeys || boxSize.width == 0 || boxSize.height == 0) {
            KeyboardPassthrough.publishRegion(null)
        } else {
            // boxOrigin is relative to the compose root (the IME's input
            // view); the framework wants display coordinates.
            val origin = IntArray(2).also { hostView.getLocationOnScreen(it) }
            val left = origin[0] + boxOrigin.x.roundToInt()
            val top = origin[1] + boxOrigin.y.roundToInt()
            KeyboardPassthrough.publishRegion(
                android.graphics.Rect(left, top, left + boxSize.width, top + boxSize.height),
            )
        }
    }
    DisposableEffect(ownsPassthrough) {
        onDispose { if (ownsPassthrough) KeyboardPassthrough.publishRegion(null) }
    }
}

/**
 * The glide stroke's floating layer: the word pill riding above the fingertip
 * and, when a stroke stops to ask, the picker's targets (issues #65 and #86).
 *
 * Its own window rather than the grid, because the grid ends where the keys
 * do. Drawn inside it, a pill over a top-row stroke could only clamp to the
 * grid's top edge and sit on the keys under the finger drawing it, and the
 * targets for that stroke had nowhere to go at all. The window is the grid
 * plus [headroomPx] above it — pinned and sized the way [KeyPreviewOverlay]'s
 * is, so grid-space geometry places things in it with one added offset — and
 * it exists only while there is something to draw: a window with nothing in it
 * would still sit over the host app, whose taps Android 12 then drops, and this
 * one is only ever up while the finger is on the keyboard.
 *
 * The one [Layout] reports the full window size and places everything itself.
 * The picker used to put an offset `Row` straight into the popup, which sized
 * the window to the row and then moved the row out of it: the targets showed
 * as clipped tops at the bottom of the suggestion strip, or not at all.
 * Placing the targets here also gives their rectangles for free, in the grid's
 * space, which is what the pointer loop hit-tests — `positionInRoot` inside a
 * popup is the popup's root, not the keyboard's, so reading them back through
 * `onGloballyPositioned` was never in the right space either.
 *
 * The finger is already held by the glide detector, so no key can fire under
 * the targets: sliding onto one highlights it and lifting there commits it.
 *
 * [word] is the pill's text, already cased for display, or null for no pill.
 * [promise] colours it when the keyboard is telling the user that this is the
 * word a lift types rather than merely the word in front; null draws the pill
 * in its own colours.
 */
@Composable
private fun GlideOverlay(
    trail: GlideTrail,
    picker: GlidePickerState,
    word: String?,
    glide: GestureSettings,
    gridSize: IntSize,
    promise: Color? = null,
    expansion: String? = null,
    /** The stroke's triggers and what they expand to, for the picker's targets (#205). */
    expansions: Map<String, GlideExpansion> = emptyMap(),
) {
    val theme = LocalKbTheme.current
    val density = LocalDensity.current
    // How far above the fingertip the pill rides, and how far to one side of
    // it. Both are the user's, since the hand that covers the pill is not the
    // one the old fixed 56dp was measured against.
    val gapPx = with(density) { glide.wordPreviewOffsetYDp.dp.roundToPx() }
    val shiftPx = with(density) { glide.wordPreviewOffsetXDp.dp.roundToPx() }
    val pickerGapPx = with(density) { GlidePickerGap.roundToPx() }
    // Room above the grid: the pill at the user's distance over a top-row
    // stroke, or the picker's row over one, whichever needs more. The window's
    // position and its size have to agree before anything is measured, so the
    // pill's height is estimated from its font rather than measured — and
    // estimated high, since a few dp of transparent window cost nothing and a
    // short one clips the pill.
    val words = picker.words
    val cancelling = picker.cancelling
    // The targets are spaced in the anchor key's heights, so a picker that
    // opened off the grid falls back to a target's own height.
    val keyPx = picker.anchorKeyPx.takeIf { it > 0f }
        ?: with(density) { GlidePickerHeight.toPx() }
    // Four or five words may need a second row; estimated from the count
    // rather than measured, for the same reason the pill's height is.
    val pickerRows = if (words.size <= GlidePickerRowMax) 1 else 2
    val headroomPx = with(density) {
        val pillHeight = glide.wordPreviewFontSp.sp.toPx() * GlidePillLineHeightRatio +
            (GlidePillPaddingV * 2).toPx()
        val targetPx = GlidePickerHeight.toPx()
        // The arc's peak — the far slot's centre, plus half a target — and a
        // second row stacked above it.
        val pickerPx = GlidePickerFarLift * keyPx + targetPx / 2 +
            if (pickerRows > 1) GlidePickerGap.toPx() + targetPx else 0f
        maxOf(pillHeight.roundToInt() + gapPx, pickerPx.roundToInt())
    }
    Popup(
        popupPositionProvider = remember(headroomPx) { GridOverlayPositionProvider(headroomPx) },
        properties = PreviewPopupProperties,
    ) {
        Layout(
            content = {
                if (word != null) {
                    GlideWordPill(word, glide, theme, promise, Modifier.layoutId(GlidePillId), expansion)
                }
                words.forEachIndexed { index, target ->
                    GlidePickerTarget(
                        word = target,
                        expansion = expansions[target]?.previewFor(target),
                        hovered = picker.hover == index,
                        leader = index == 0,
                        dimmed = cancelling,
                        theme = theme,
                        modifier = Modifier.layoutId(index),
                    )
                }
                if (cancelling) {
                    GlideHintPill(
                        stringResource(R.string.ime_glide_picker_cancel_hint),
                        theme,
                        Modifier.layoutId(GlideHintId),
                    )
                }
            },
        ) { measurables, constraints ->
            val width = if (gridSize.width > 0) gridSize.width else constraints.maxWidth
            val height = gridSize.height + headroomPx
            val pill = measurables.firstOrNull { it.layoutId == GlidePillId }?.measure(Constraints())
            val hint = measurables.firstOrNull { it.layoutId == GlideHintId }?.measure(Constraints())
            // Each target is capped at a third of the window less the gaps, so
            // three always share a row and five split three and two; a long
            // word ellipsizes rather than pushing its neighbours off the edge.
            val targetMax = ((width - 2 * pickerGapPx) / GlidePickerRowMax).coerceAtLeast(0)
            val targets = measurables
                .filter { it.layoutId is Int }
                .map { it.measure(Constraints(maxWidth = targetMax)) }
            layout(width, height) {
                if (pill != null) {
                    // The fingertip is read here, in placement, so following
                    // it costs a re-place rather than a recomposition. Shifted
                    // before the clamp, so a pill pushed toward an edge stops
                    // at the edge rather than leaving the window.
                    val x = ((trail.headX - pill.width / 2f).toInt() + shiftPx)
                        .coerceIn(0, (width - pill.width).coerceAtLeast(0))
                    val y = (trail.headY + headroomPx - gapPx - pill.height).toInt()
                        .coerceAtLeast(0)
                    pill.place(x, y)
                }
                if (targets.isNotEmpty()) {
                    val rowHeight = targets.maxOf { it.height }
                    val widths = IntArray(targets.size) { targets[it].width }
                    val leaderRow = pickerLeaderRowCount(widths, pickerGapPx, width)
                    val rows = listOf(0 until leaderRow, leaderRow until targets.size)
                        .filter { !it.isEmpty() }
                    // Where a row's slots sit, given the widths that end up in
                    // it. The leader's row arcs around the fingertip — its
                    // middle slot a whole second key clear, so the word a
                    // straight flick up reaches is never the one a short
                    // diagonal does — and a second row is flat above the arc's
                    // peak. The headroom already covers both, so the clamps
                    // only ever catch a stroke that stopped near the top edge.
                    fun rowLeft(range: IntRange, of: (Int) -> Int): Int {
                        val rowWidth = range.sumOf(of) + pickerGapPx * (range.count() - 1)
                        return (picker.anchorX - rowWidth / 2f).toInt()
                            .coerceIn(0, (width - rowWidth).coerceAtLeast(0))
                    }
                    fun slotTop(row: Int, lift: Float): Int {
                        val centre = if (row == 0) {
                            picker.anchorY - lift * keyPx
                        } else {
                            picker.anchorY - GlidePickerFarLift * keyPx - rowHeight - pickerGapPx
                        }
                        return (centre + headroomPx - rowHeight / 2f).toInt()
                            .coerceIn(0, (height - rowHeight).coerceAtLeast(0))
                    }
                    // Pass one: where the slots are, measured with the words
                    // still in decoder order. Only the ranking below decides
                    // which word lands in which of them, so these centres are
                    // an estimate — a slot's own width changes with its word —
                    // and an estimate is all the ranking needs.
                    val slotX = FloatArray(targets.size)
                    val slotY = FloatArray(targets.size)
                    rows.forEachIndexed { r, range ->
                        val lifts = pickerRowLifts(range.count())
                        var x = rowLeft(range) { widths[it] }
                        range.forEachIndexed { p, slot ->
                            slotX[slot] = x + widths[slot] / 2f
                            slotY[slot] = slotTop(r, lifts[p]) + rowHeight / 2f - headroomPx
                            x += widths[slot] + pickerGapPx
                        }
                    }
                    // Pass two: the best word into the slot nearest the finger,
                    // the next into the next nearest, and so on — so whichever
                    // way the stroke ended, the shortest move commits the
                    // likeliest word, with the straight-up middle slot favoured
                    // as long as it is anywhere near the closest.
                    val middleSlot = pickerRowLifts(rows[0].count())
                        .indexOfFirst { it > GlidePickerNearLift }
                    val wordAt = pickerWordAtSlot(
                        slotX,
                        slotY,
                        picker.anchorX,
                        picker.anchorY,
                        middleSlot,
                    )
                    rows.forEachIndexed { r, range ->
                        val lifts = pickerRowLifts(range.count())
                        var x = rowLeft(range) { targets[wordAt[it]].width }
                        range.forEachIndexed { p, slot ->
                            val index = wordAt[slot]
                            val target = targets[index]
                            val y = slotTop(r, lifts[p])
                            target.place(x, y)
                            // The grid's space is this window's, less the
                            // headroom on top. The rectangle is filed under the
                            // word's own index, not the slot's, because that is
                            // what the pointer loop hit-tests and what a lift
                            // commits.
                            val top = (y - headroomPx).toFloat()
                            picker.place(
                                index,
                                Rect(x.toFloat(), top, (x + target.width).toFloat(), top + target.height),
                            )
                            x += target.width + pickerGapPx
                        }
                    }
                }
                if (hint != null) {
                    // Over the anchor: the finger has left it, heading down, so
                    // nothing covers it there.
                    val x = (picker.anchorX - hint.width / 2f).toInt()
                        .coerceIn(0, (width - hint.width).coerceAtLeast(0))
                    val y = (picker.anchorY + headroomPx - hint.height / 2f).toInt()
                        .coerceIn(0, (height - hint.height).coerceAtLeast(0))
                    hint.place(x, y)
                }
            }
        }
    }
}

/**
 * The picker's one word of guidance, shown where the finger stopped once it
 * has dropped into the cancel zone: lifting now types nothing.
 */
@Composable
private fun GlideHintPill(text: String, theme: KbTheme, modifier: Modifier) {
    Surface(
        modifier = modifier,
        color = theme.popup,
        contentColor = theme.popupText.copy(alpha = GlideHintTextAlpha),
        shape = theme.popupShape(),
        shadowElevation = elevationFor(theme.popupShapeKind, 2.dp),
    ) {
        Text(
            text = text,
            modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp),
            fontSize = 13.sp,
            maxLines = 1,
        )
    }
}

/**
 * "fk = FUTO Keyboard": a glided [trigger] dimmed ahead of the [expansion] a
 * lift types in its place (#205), so the eye lands on the text that will land.
 */
private fun glideExpansionLabel(trigger: String, expansion: String, color: Color): AnnotatedString =
    buildAnnotatedString {
        withStyle(SpanStyle(color = color.copy(alpha = color.alpha * GlideTriggerAlpha))) {
            append(trigger)
        }
        append(" = ")
        append(expansion)
    }

/** How much of its colour a glided trigger keeps beside its expansion. */
private const val GlideTriggerAlpha = 0.5f

/**
 * The floating word: what the stroke decodes to so far, hovering above the
 * finger like a key popup.
 */
@Composable
private fun GlideWordPill(
    word: String,
    glide: GestureSettings,
    theme: KbTheme,
    promise: Color?,
    modifier: Modifier,
    /** What [word] expands to when it is a trigger (#205), drawn after it. */
    expansion: String? = null,
) {
    // The promise wins the text: it is the whole reason it was passed, and
    // a pill drawn in the user's chosen preview colour would say nothing
    // the bold on the strip does not already say.
    val textColor = promise
        ?: glide.wordPreviewTextColor?.let { Color(it.toInt()) }
        ?: theme.popupText
    Surface(
        modifier = modifier,
        color = glide.wordPreviewBackground?.let { Color(it.toInt()) } ?: theme.popup,
        contentColor = textColor,
        shape = theme.popupShape(),
        shadowElevation = elevationFor(theme.popupShapeKind, 4.dp),
    ) {
        Text(
            text = if (expansion == null) {
                AnnotatedString(word)
            } else {
                glideExpansionLabel(word, expansion, textColor)
            },
            modifier = Modifier.padding(horizontal = 12.dp, vertical = GlidePillPaddingV),
            fontSize = glide.wordPreviewFontSp.sp,
            fontWeight = FontWeight.Medium,
            maxLines = 1,
        )
    }
}

/**
 * One of the words an ambiguous stroke is choosing between.
 *
 * Highlighted the way a held alternates entry is — the pressed-key colour
 * under the popup's own text — rather than the accent under the key text,
 * which on a theme with a light accent went solid white with the word lost in
 * it (issue #86). The [leader] is outlined rather than filled: it is what a
 * lift anywhere else types, and the user should be able to see that without
 * it looking already chosen. [dimmed] is the cancel zone: every target fades
 * together, because none of them is about to be typed.
 */
@Composable
private fun GlidePickerTarget(
    word: String,
    hovered: Boolean,
    leader: Boolean,
    dimmed: Boolean,
    theme: KbTheme,
    modifier: Modifier,
    /** What [word] expands to when it is a trigger (#205), drawn after it. */
    expansion: String? = null,
) {
    Surface(
        modifier = modifier
            .height(GlidePickerHeight)
            .alpha(if (dimmed) GlidePickerDimmedAlpha else 1f),
        color = if (hovered) theme.pressedKey else theme.popup,
        contentColor = theme.popupText,
        shape = theme.popupShape(),
        border = if (leader && !hovered) {
            BorderStroke(1.dp, theme.accent.copy(alpha = GlidePickerLeaderOutlineAlpha))
        } else {
            null
        },
        shadowElevation = elevationFor(theme.popupShapeKind, if (hovered) 8.dp else 4.dp),
    ) {
        Box(contentAlignment = Alignment.Center) {
            Text(
                text = if (expansion == null) {
                    AnnotatedString(word)
                } else {
                    glideExpansionLabel(word, expansion, theme.popupText)
                },
                modifier = Modifier.padding(horizontal = 14.dp, vertical = 6.dp),
                fontSize = 18.sp,
                fontWeight = if (hovered) FontWeight.Bold else FontWeight.Medium,
                maxLines = 1,
                softWrap = false,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

/**
 * One row of keys. In split mode the row is cut near its midpoint and the
 * halves are pushed apart by a center gap sized as a percentage of the
 * keyboard width; a spacebar straddling the cut is divided between the halves.
 */
@Composable
private fun KeyRow(
    row: KeyRowVisual,
    settings: KeyboardSettings,
    split: Boolean,
    numericField: Boolean,
    layoutId: String,
    keyPreview: KeyPreviewState,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    onCursorMove: (Int) -> Unit,
    onLayoutSelect: (String) -> Unit,
    onKeyPositioned: (Key, LayoutCoordinates) -> Unit,
    onSpacePositioned: (LayoutCoordinates) -> Unit = {},
    smartResolve: (Key, PointerId) -> Key = { k, _ -> k },
    /** Spawns the theme's press burst at the key's bounds; null when off. */
    onBurst: ((Rect, String?) -> Unit)? = null,
) {
    Row {
        if (row.sidePad > 0.01f) Spacer(modifier = Modifier.weight(row.sidePad))
        for (visual in row.left) {
            KeyCell(
                visual,
                Modifier.weight(visual.key.width),
                row.heightDp,
                settings,
                numericField,
                layoutId,
                keyPreview,
                onKey,
                onText,
                onCursorMove,
                onLayoutSelect,
                onKeyPositioned,
                onSpacePositioned,
                smartResolve,
                onBurst,
            )
        }
        // Split mode only: the halves are cut where the row was resolved, so an
        // unsplit row has nothing on the right and needs no gap.
        if (split) {
            Spacer(modifier = Modifier.weight(row.splitGapWeight))
            for (visual in row.right) {
                KeyCell(
                    visual,
                    Modifier.weight(visual.key.width),
                    row.heightDp,
                    settings,
                    numericField,
                    layoutId,
                    keyPreview,
                    onKey,
                    onText,
                    onCursorMove,
                    onLayoutSelect,
                    onKeyPositioned,
                    onSpacePositioned,
                    smartResolve,
                    onBurst,
                )
            }
        }
        if (row.sidePad > 0.01f) Spacer(modifier = Modifier.weight(row.sidePad))
    }
}

/**
 * A run of rows drawn as one block, because a key of it covers more than one —
 * see [KeyBandVisual].
 *
 * Placed by hand rather than by nested `Row`s: the band is the only parent every
 * key of it shares, so it is the only node that can hold a two-row key inside
 * its own bounds, which is what makes the whole key tappable rather than just
 * the half that overlaps its own row.
 *
 * Each edge is rounded independently off the same unit width, so neighbours stay
 * flush the way `Row`'s weights keep them — rounding widths instead would leave a
 * sub-pixel seam that accumulates across the row.
 */
@Composable
private fun KeyBand(
    band: KeyBandVisual,
    settings: KeyboardSettings,
    numericField: Boolean,
    layoutId: String,
    keyPreview: KeyPreviewState,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    onCursorMove: (Int) -> Unit,
    onLayoutSelect: (String) -> Unit,
    onKeyPositioned: (Key, LayoutCoordinates) -> Unit,
    onSpacePositioned: (LayoutCoordinates) -> Unit = {},
    smartResolve: (Key, PointerId) -> Key = { k, _ -> k },
    onBurst: ((Rect, String?) -> Unit)? = null,
) {
    // Row pitch in px: the key height the row was given, plus the gap above and
    // below it, exactly as an ordinary KeyCell measures itself.
    val gap = keyGapV(settings)
    val rowPitch = with(LocalDensity.current) {
        band.rowHeights.map { (it.dp + gap * 2).roundToPx() }
    }
    // Row tops, and the band's own height as the last entry.
    val tops = IntArray(rowPitch.size + 1).also {
        for (i in rowPitch.indices) it[i + 1] = it[i] + rowPitch[i]
    }
    Layout(
        content = {
            for (slot in band.slots) {
                // heightDp is what this key would be on a row of its own; the
                // measure policy below hands it the real height, spanned rows
                // and the gaps between them included.
                KeyCell(
                    slot.visual,
                    Modifier,
                    band.rowHeights[slot.row],
                    settings,
                    numericField,
                    layoutId,
                    keyPreview,
                    onKey,
                    onText,
                    onCursorMove,
                    onLayoutSelect,
                    onKeyPositioned,
                    onSpacePositioned,
                    smartResolve,
                    onBurst,
                )
            }
        },
    ) { measurables, constraints ->
        val width = constraints.maxWidth
        val unit = if (band.weight > 0f) width / band.weight else 0f
        val lefts = IntArray(measurables.size)
        val placeables = measurables.mapIndexed { index, measurable ->
            val slot = band.slots[index]
            val left = (unit * slot.x).roundToInt()
            val right = (unit * (slot.x + slot.width)).roundToInt()
            lefts[index] = left
            measurable.measure(
                Constraints.fixed(
                    width = (right - left).coerceIn(0, width),
                    height = tops[slot.row + slot.span] - tops[slot.row],
                ),
            )
        }
        layout(width, tops.last()) {
            placeables.forEachIndexed { index, placeable ->
                placeable.placeRelative(lefts[index], tops[band.slots[index].row])
            }
        }
    }
}

/**
 * One key in its grid cell. [sizeModifier] is how the cell gets its width: a
 * `Row`'s weight for an ordinary row, nothing at all inside a [KeyBand], whose
 * measure policy sizes its children itself. Taken as a parameter rather than
 * applied here so this is not tied to `RowScope`, which a band has no way to be.
 */
@Composable
private fun KeyCell(
    visual: KeyVisual,
    sizeModifier: Modifier,
    keyHeightDp: Int,
    settings: KeyboardSettings,
    numericField: Boolean,
    layoutId: String,
    keyPreview: KeyPreviewState,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    onCursorMove: (Int) -> Unit,
    onLayoutSelect: (String) -> Unit,
    onKeyPositioned: (Key, LayoutCoordinates) -> Unit,
    onSpacePositioned: (LayoutCoordinates) -> Unit = {},
    smartResolve: (Key, PointerId) -> Key = { k, _ -> k },
    onBurst: ((Rect, String?) -> Unit)? = null,
) {
    val key = visual.key
    KeyButton(
        visual = visual,
        settings = settings,
        // Every key reports, not only the ones that write a letter: the rect
        // table behind [onKeyPositioned] answers "which key is under the
        // finger" for the modifier drag, and a mode key or an arrow is as
        // likely an answer as a letter.
        modifier = sizeModifier.onGloballyPositioned { coords ->
            onKeyPositioned(key, coords)
            // The spacebar has a second reader — the multi-word glide split —
            // which needs its whole rect rather than a centre.
            if (key.action == KeyAction.Space) onSpacePositioned(coords)
        },
        heightDp = keyHeightDp,
        numericField = numericField,
        layoutId = layoutId,
        keyPreview = keyPreview,
        onKey = onKey,
        onText = onText,
        onCursorMove = onCursorMove,
        onLayoutSelect = onLayoutSelect,
        smartResolve = smartResolve,
        onBurst = onBurst,
    )
}

/**
 * Cuts a row for split mode. A spacebar spanning the midpoint is divided
 * into a half per side (the left half loses its label so the language name
 * is not shown twice); otherwise the cut lands on the key boundary nearest
 * the midpoint, with ties going right so QWERTY splits asdfg | hjkl.
 */
internal fun splitKeys(keys: List<Key>): Pair<List<Key>, List<Key>> {
    // A custom layout can hand us an empty or one-key row: the cut search below
    // starts at index 1, and subList would throw on an empty one — a deleted row
    // would take the whole keyboard down in split mode.
    if (keys.size < 2) return keys to emptyList()
    val boundaries = FloatArray(keys.size + 1)
    for (i in keys.indices) boundaries[i + 1] = boundaries[i] + keys[i].width
    val mid = boundaries[keys.size] / 2f
    for (i in keys.indices) {
        if (keys[i].action == KeyAction.Space &&
            boundaries[i] < mid - 0.01f && boundaries[i + 1] > mid + 0.01f
        ) {
            val left = keys.subList(0, i) + keys[i].copy(label = "", width = mid - boundaries[i])
            val right = listOf(keys[i].copy(width = boundaries[i + 1] - mid)) +
                keys.subList(i + 1, keys.size)
            return left to right
        }
    }
    var cut = 1
    for (b in 2 until keys.size) {
        if (abs(boundaries[b] - mid) <= abs(boundaries[cut] - mid) + 0.001f) cut = b
    }
    return keys.subList(0, cut) to keys.subList(cut, keys.size)
}

/**
 * The punctuation keys that report a centre alongside the letters, for the
 * apostrophe-in-a-glide setting to find. Kept out of everything that means
 * "letter key" — the engine's touch model and [nearLetterKey] — so tracking them
 * cannot change where a tap lands or what starts a glide.
 */
private val GlidePunctuationCodePoints = setOf(','.code, '.'.code, '\''.code)

/** The character this key contributes to the centres map if it is punctuation. */
private fun Key.glidePunctuationCodePoint(): Int? =
    if (action == KeyAction.Text) {
        (output ?: label).singleOrNull()?.code?.takeIf { it in GlidePunctuationCodePoints }
    } else {
        null
    }

/**
 * True when [position] falls within roughly one key of a tracked letter key.
 *
 * Letters only, which is why the punctuation keys the centres map also holds are
 * skipped: they are tracked for the apostrophe setting to find, and a slide off
 * the comma key must keep meaning exactly what it meant before. It measures
 * distance to letters, not the key under the finger, so a punctuation key set
 * right beside a letter is partly inside that letter's radius; the possessive
 * swipe (#169) is kept out of glide typing by [startsPossessiveSwipe] at the
 * down, not by this.
 */
private fun nearLetterKey(
    position: Offset,
    centers: Map<Int, Offset>,
    keyWidth: Float,
): Boolean = centers.any { (codePoint, center) ->
    codePoint !in GlidePunctuationCodePoints &&
        (center - position).getDistance() < keyWidth
}

/**
 * Where the glide grid should put the apostrophe, in this box's space, or null
 * when the feature is off or the chosen key is not on the current layer.
 *
 * The punctuation keys report their centres under their own character, the same
 * way letters do, so three of the four choices are a map lookup. The spacebar is
 * the exception: it reports a rect in *root* space (the multi-word split needs
 * it there), so it is lifted back into box space here with the live origin.
 *
 * Null on a layout with no such key is the honest answer rather than a fallback
 * to some other key: a stroke aimed at a key that is not there would otherwise
 * spell an apostrophe the user never drew.
 */
private fun apostropheCenter(
    choice: GlideApostropheKey,
    centers: Map<Int, Offset>,
    spaceRect: Rect?,
    boxOrigin: Offset,
): Pair<Float, Float>? = when (choice) {
    GlideApostropheKey.OFF -> null
    GlideApostropheKey.SPACE -> spaceRect?.let {
        (it.center.x - boxOrigin.x) to (it.center.y - boxOrigin.y)
    }
    else -> choice.sourceChar
        ?.let { centers[it.code] }
        ?.let { it.x to it.y }
}

/**
 * How hard a likely next letter pulls a boundary tap, for the autopilot
 * strength the user set (1..10). Higher = wider steal. 5 is what the feature
 * shipped at, and lands on the 0.5 it was a constant for.
 */
internal fun smartHitStrength(setting: Int): Float = setting.coerceIn(1, 10) * 0.1f

/** A favoured letter never claims a tap more than this many key-widths away. */
private const val SMART_HIT_MAX_REACH = 1.3f

/**
 * Smart key-hit detection. Given a touch [pos], the tracked letter [centers]
 * and the live next-letter [bias] (0..1 per letter), returns the letter whose
 * hitbox should claim this touch, or null to leave the plain-nearest key alone.
 *
 * Each centre's effective distance is shortened in proportion to how likely
 * that letter is next, so a likely neighbour can win a touch that landed just
 * inside the nominal key. The shortening is a fixed fraction of distance, so it
 * only ever flips the outcome near a shared edge — a press deep inside a key
 * stays with that key — and a favoured letter out of reach is ignored outright.
 */
private fun smartHitTarget(
    pos: Offset,
    centers: Map<Int, Offset>,
    keyWidth: Float,
    bias: Map<Char, Float>,
    strength: Float,
): Char? {
    if (keyWidth <= 0f || centers.isEmpty() || bias.isEmpty()) return null
    var nominal: Char? = null
    var nominalDist = Float.MAX_VALUE
    var best: Char? = null
    var bestScore = Float.MAX_VALUE
    for ((codePoint, center) in centers) {
        // The remap resolves to a single-Char letter key (see `letterKeys`),
        // so a letter outside the BMP is never a target and never a rival.
        if (codePoint > 0xFFFF) continue
        val ch = codePoint.toChar()
        val d = (center - pos).getDistance()
        if (d < nominalDist) {
            nominalDist = d
            nominal = ch
        }
        val score = d / (1f + strength * (bias[ch] ?: 0f))
        if (score < bestScore) {
            bestScore = score
            best = ch
        }
    }
    // The plain-nearest key already wins: nothing to remap.
    if (best == null || best == nominal) return null
    // Never yank a tap onto a key the finger is nowhere near.
    val target = centers[best.code] ?: return null
    if ((target - pos).getDistance() > keyWidth * SMART_HIT_MAX_REACH) return null
    return best
}

/**
 * [currentLayout], memoized on everything it reads.
 *
 * Worth a memo because the rewrite pass below is not free — with any of the
 * key-rewriting preferences on (an emoji comma, the clipboard long-presses,
 * the full accent popups, a number row stripping duplicate digits) it copies
 * every key of every row — and it ran on each recomposition of the key grid,
 * which is to say on every keystroke. Handing back the *same* layout instance
 * also turns the `remember(layout)` keys downstream from a deep structural
 * comparison of the whole grid into a reference check.
 *
 * The keys are the whole read set of [currentLayout] and [numericPadActive]:
 * the layer objects, the layer being shown, the settings (every preference it
 * consults lives in there), the composer, the field's kind, and the flag for
 * the search boxes that suppress the numeric pad. **A read added to either
 * function has to be covered here**, or the grid will keep drawing the layout
 * from before it changed.
 */
@Composable
internal fun rememberCurrentLayout(state: KeyboardUiState): KeyboardLayout = remember(
    state.layouts,
    state.layoutMode,
    state.settings,
    state.composer,
    state.fieldKind,
    // The field's declared action, which is what `newlineAlternate` below reads
    // to decide whether the enter key carries the line break. The *field's*, not
    // [effectiveEnterAction] — that one moves with the shift key and would
    // rebuild the whole grid mid-word.
    state.enterAction,
    state.secondaryLayoutId,
    state.namedLayer,
    // Only a layout with its own shift page redraws on shift; for every other
    // one the key stays out, so shift does not rebuild the grid.
    state.shiftState.takeIf { state.layouts.keymanShift != null || state.layouts.keymanCaps != null },
    numericPadActive(state),
    // Issue #340: only ever true on a board with a key that becomes 小゛゜, so
    // no other board rebuilds on it.
    state.kanaVariantReady,
) {
    currentLayout(state)
}

/**
 * The capital this key would type under shift, as a long-press alternate, or
 * null when it has none to add (issue #108).
 *
 * The layout's own [Key.shiftLabel] wins, which is what gets the scripts whose
 * shifted form is a different character altogether — and the Bengali keys that
 * write two code points, where uppercasing would be nonsense. Otherwise a
 * single letter uppercases itself, and everything else (digits, punctuation, a
 * multi-character output) has no capital and adds nothing.
 *
 * Null too when the key already offers it: a layout that listed its own capital
 * keeps that entry in the place it put it.
 */
internal fun shiftedAlternate(key: Key): String? {
    val base = key.output ?: key.label
    val shifted = key.shiftLabel
        ?: base.takeIf { it.length == 1 && it[0].isLetter() }?.uppercase()
        ?: return null
    return shifted.takeIf { it != base && it !in key.longPress }
}

internal fun currentLayout(state: KeyboardUiState): KeyboardLayout {
    if (numericPadActive(state)) {
        state.layouts.numeric?.let { return it }
    }
    val grid = when (state.layoutMode) {
        LayoutMode.SYMBOLS -> state.layouts.symbols
        LayoutMode.SYMBOLS_SHIFTED -> state.layouts.symbolsShifted
        // Falls back to the letters when the layout has no Fn layer: a stored
        // Fn key can outlive the layer it points at, and onFn already refuses to
        // switch, so this only ever fires on a state built out of order.
        LayoutMode.FN -> state.layouts.fn ?: state.layouts.letters
        // A converted Keyman layout draws its author's own shift and caps pages
        // while shift is on, rather than re-casing the letters: those pages are
        // keys of their own, not the letters in capitals.
        LayoutMode.LETTERS -> when {
            state.shiftState == ShiftState.CAPS_LOCK && state.layouts.keymanCaps != null ->
                state.layouts.keymanCaps
            state.shiftState != ShiftState.OFF && state.layouts.keymanShift != null ->
                state.layouts.keymanShift
            else -> state.layouts.letters
        }
        // Same fallback as Fn, for the same reason: the layout named can have
        // been deleted between the state being set and this draw.
        LayoutMode.SECONDARY ->
            state.secondaryLayoutId?.let { state.layouts.secondaries[it] } ?: state.layouts.letters
        LayoutMode.NAMED ->
            state.namedLayer?.let { state.layouts.named[it] } ?: state.layouts.letters
    }
    // Issue #139: a hidden 🌐 key leaves the bottom row before anything below
    // reads the grid. The emoji rewrite finds the key by its action and the
    // comma swap reads positions off this grid, so taking the key out any later
    // would mean undoing both. A secondary layout is drawn as its author made
    // it, since a 🌐 key there can be the only way back out of it.
    val shown = if (state.settings.showGlobeKey || state.layoutMode == LayoutMode.SECONDARY) {
        grid
    } else {
        grid.withoutGlobeKey()
    }
    // Issue #310: the 🌐 key moved to the one slot every layout shares. Early,
    // for the same reason as the hiding above: the emoji rewrite and the comma
    // swap below find the key by where it is. Not on a secondary layout, whose
    // author placed every key on purpose, nor on an expanded tablet grid, which
    // arranges its own bottom row.
    val swapCommaGlobe = state.settings.swapCommaAndGlobe
    val placed = if (
        state.settings.layoutBehavior.globeInOnePlace &&
        state.layoutMode != LayoutMode.SECONDARY &&
        state.layouts.gridWidth == null
    ) {
        shown.withGlobeInPlace(outer = swapCommaGlobe)
    } else {
        null
    }
    val base = placed ?: shown
    // Email and URI fields keep the letter layouts but put the character they
    // are full of on the bottom-row comma slot, and domain endings on the
    // period key's long press. Both are otherwise a trip through the symbols
    // layer for every address. An email box has no use for the comma, so "@"
    // takes the key outright; a browser's address bar is its search box too,
    // so there the comma stays and "/" leads its popup instead.
    val lettersLayer = state.layoutMode == LayoutMode.LETTERS
    // The character and its popup, not a finished key: the key is built by
    // copying the slot it replaces, so a comma the layout drew wide stays wide.
    // A fresh Key here reset the width, and the bottom row jumped on the way
    // into a URL field (issue #25) — the same trap `commaAsEmoji` fell into.
    val fieldKey: Pair<String, List<String>>? = when {
        !lettersLayer -> null
        state.fieldKind == FieldKind.EMAIL -> "@" to emptyList()
        state.fieldKind == FieldKind.URI -> "," to listOf("/", "?", "#", "&", "=")
        else -> null
    }
    val domainAlternates = when {
        !lettersLayer -> emptyList()
        state.fieldKind == FieldKind.EMAIL -> listOf(".com", ".net", ".org", ".edu", ".co")
        state.fieldKind == FieldKind.URI ->
            listOf(".com", ".org", ".net", "www.", "https://", "/")
        else -> emptyList()
    }
    // Bengali (and any other script that ends a sentence with something other
    // than a full stop) types its own mark from the key next to the spacebar,
    // with "." kept on the long press for numbers, file names and URLs. Only
    // where the layout has not already put the mark there itself — the fixed
    // Bengali layouts carry দাঁড়ি on their own keys.
    val fullStop = state.script.fullStop.takeIf { it != "." }
    // The script's own punctuation, on the shared symbol key that types the
    // nearest ASCII mark: Bengali's ঃ on the colon. Every layer, since that key
    // is on the symbols one.
    val punctuationAlternates = state.script.punctuationAlternates
    // Both emoji-key preferences exist because a phone's bottom row has no spare
    // slot, so one of the keys already there has to give it up. An expanded
    // tablet grid has a real emoji key of its own, and applying either here would
    // draw a second one — and `globeAsEmoji`, which ships on, would take language
    // switching off the board entirely to do it.
    val tabletGrid = state.layouts.gridWidth != null
    // Optional Gboard-style emoji key: the letter layouts' comma key becomes
    // an emoji-panel key, with comma demoted to its long-press alternates.
    val commaAsEmoji = state.settings.commaAsEmoji && !tabletGrid &&
        state.layoutMode == LayoutMode.LETTERS
    // 🌐 → emoji key: language switching lives on spacebar swipes instead.
    val globeAsEmoji = state.settings.globeAsEmoji && !tabletGrid
    // The two keys either side of the spacebar trade places, so whichever one
    // is the emoji key sits in the outer slot and the comma next to the space.
    // Not scoped to the letter layers: the row would otherwise reshuffle on the
    // way into ?123, which is worse than either order. A bottom row the
    // placement above has arranged is already in that order, and swapping it
    // again would undo it.
    val swapBottom = swapCommaGlobe && placed == null
    // With the dedicated number row on, the digits duplicated on the top-row
    // letters' long press are redundant — drop them so those keys go straight
    // to their accents (or lose their popup entirely).
    val stripDigits = state.settings.numberRow && state.layoutMode == LayoutMode.LETTERS
    // A44: user-chosen currency glyphs replace the $ key's built-in popup.
    val currencyKeys = state.settings.layoutBehavior.currencyKeys
    // Issue #57: the spacebar's long press, for a user who has no use for the
    // language picker there. Applies on every layer, because a hold that works
    // on the letters and does nothing on the symbols is worse than neither.
    val spaceHoldKeys = state.settings.layoutBehavior.spaceHoldKeys
    // A43: merge the full accent set into each Latin letter's long-press popup.
    val allAccents = state.settings.layoutBehavior.showAllPopupKeys &&
        state.layoutMode == LayoutMode.LETTERS && !state.composer.isClusterShaping
    // Issue #108: each letter key's shifted form joins its popup, so a capital
    // can be typed from a hold — including from the hold a layer peek opens,
    // where the shift key is on the layer the finger has left behind. Every
    // layer, unlike the accents: a secondary layout of letters is as much a
    // place to want a capital as the letters layer is.
    val shiftedKeys = state.settings.layoutBehavior.shiftedPopupKeys
    // The clipboard/undo/redo hold shortcuts, on whichever keys the user has
    // bound them to. The keys are settings rather than the literal a/c/v/x/z/y
    // they used to be: on a layout with no Latin letters there was no `a` to
    // hold, so all six switches did nothing and said nothing about why.
    val clipboardKeys: Map<String, ClipboardKeyAction> =
        if (state.layoutMode == LayoutMode.LETTERS && !state.composer.isClusterShaping) {
            val longPress = state.settings.longPressLetterActions
            buildMap {
                fun bind(on: Boolean, slot: Int, action: ClipboardKeyAction) {
                    if (!on) return
                    longPress.letterFor(slot)?.let { put(it.toString(), action) }
                }
                bind(longPress.selectAll, 0, ClipboardKeyAction.SELECT_ALL)
                bind(longPress.copy, 1, ClipboardKeyAction.COPY)
                bind(longPress.paste, 2, ClipboardKeyAction.PASTE)
                bind(longPress.cut, 3, ClipboardKeyAction.CUT)
                bind(longPress.undo, 4, ClipboardKeyAction.UNDO)
                bind(longPress.redo, 5, ClipboardKeyAction.REDO)
            }
        } else {
            emptyMap()
        }
    // Whether those shortcuts sit at the front of their key's popup, where a
    // plain hold commits them, instead of after the accents. Read once here
    // rather than per key: it is one setting for the whole board.
    val clipboardActionFirst = state.settings.longPressLetterActions.actionFirst
    // A field that declares Send/Go/Search takes the enter key over, and the
    // line break it displaces has nowhere else to go — so it moves to the key's
    // long press, the way Gboard offers it. Only where the key is actually
    // showing the app's action: on an ordinary multi-line box Enter already
    // types the break and an alternate offering the same thing is noise.
    //
    // Keyed on the field's own action rather than [effectiveEnterAction], which
    // folds in the live shift: reading that here would rebuild the whole grid on
    // every shift press, and the entry belongs in the popup either way.
    val newlineAlternate = state.enterAction != EnterAction.DEFAULT
    // Opt-in: the emoji panel under a hold on enter, for a bottom row with no
    // emoji key. See [LayoutBehaviorSettings.enterLongPressEmoji].
    val emojiAlternate = state.settings.layoutBehavior.enterLongPressEmoji
    // Issue #340: the keys that stand in for 小゛゜ while the reading ends in a
    // kana that has one of those forms.
    val kanaVariantKeys = state.kanaVariantReady
    if (!commaAsEmoji && !globeAsEmoji && !swapCommaGlobe && !stripDigits &&
        clipboardKeys.isEmpty() && fieldKey == null && domainAlternates.isEmpty() &&
        currencyKeys.isEmpty() && !allAccents && !shiftedKeys && fullStop == null &&
        !newlineAlternate && !emojiAlternate && spaceHoldKeys.isEmpty() &&
        punctuationAlternates.isEmpty() && !kanaVariantKeys
    ) {
        return base
    }
    val bottom = base.rows.lastIndex
    // copy rather than KeyboardLayout(name, rows): a positional rebuild
    // silently drops any field later added to the class.
    val rewritten = base.rows.mapIndexed { rowIndex, row ->
        row.map { rowKey ->
            val role = rowKey.roleIn(rowIndex, bottom)
            // Ahead of the field/emoji rewrites below, which may replace the
            // period key outright or hang domain endings off it — the script's
            // own mark and the "." it displaces travel together either way. A
            // layout that already types the mark is left alone.
            val key = if (
                fullStop != null && role == KeyRole.Period &&
                (rowKey.output ?: rowKey.label) == "."
            ) {
                rowKey.copy(
                    label = fullStop,
                    output = null,
                    longPress = listOf(".") + rowKey.longPress.filterNot { it == fullStop },
                )
            } else {
                rowKey
            }
            var mapped = when {
                // Field adaptation outranks the emoji-key preference: an
                // email box needs its @ more than a shortcut to emoji.
                // Everything the slot decides about itself — width, span, label
                // scale — survives; everything about the character it used to
                // type is replaced, icons and flicks included.
                fieldKey != null && role == KeyRole.Comma -> key.copy(
                    label = fieldKey.first,
                    output = null,
                    shiftLabel = null,
                    longPress = fieldKey.second,
                    actionAlternates = emptyList(),
                    icon = null,
                    iconHint = null,
                    flick = emptyMap(),
                )
                domainAlternates.isNotEmpty() && role == KeyRole.Period ->
                    key.copy(longPress = domainAlternates + key.longPress)
                commaAsEmoji && role == KeyRole.Comma ->
                    // copy, not a fresh Key: building one from scratch here
                    // discarded a custom width, so the bottom row jumped
                    // whenever the preference was on.
                    key.copy(
                        action = KeyAction.Emoji,
                        longPress = listOf(key.output ?: key.label) + key.longPress,
                    )
                globeAsEmoji && key.action == KeyAction.LanguageSwitch ->
                    key.copy(action = KeyAction.Emoji)
                else -> key
            }
            if (stripDigits && mapped.longPress.any { it.isSingleDigit() }) {
                mapped = mapped.copy(longPress = mapped.longPress.filterNot { it.isSingleDigit() })
            }
            // A44: the $ key takes the user's currency glyphs as its popup.
            if (currencyKeys.isNotEmpty() && (mapped.output ?: mapped.label) == "$") {
                mapped = mapped.copy(longPress = currencyKeys)
            }
            // Issue #57: the spacebar takes the user's hold keys. Prepended, so
            // a layout that authored its own space alternates keeps them, and
            // the ones the user typed into the setting come first.
            if (spaceHoldKeys.isNotEmpty() && mapped.action == KeyAction.Space) {
                mapped = mapped.copy(
                    longPress = spaceHoldKeys + mapped.longPress.filterNot { it in spaceHoldKeys },
                )
            }
            // The script's own marks on the punctuation key they belong to.
            // Appended rather than prepended, so the key keeps whatever it
            // already offered and in the order it wrote it; distinct() covers a
            // layout that lists the mark on that key itself.
            if (punctuationAlternates.isNotEmpty() && mapped.action == KeyAction.Text) {
                punctuationAlternates[mapped.output ?: mapped.label]?.let { extra ->
                    mapped = mapped.copy(longPress = (mapped.longPress + extra).distinct())
                }
            }
            // A43: merge the full accent variant set for this Latin letter,
            // on top of whatever the layout already lists. Lowercase glyphs,
            // matching the built-in accent popups; non-letters have no entry.
            if (allAccents && mapped.action == KeyAction.Text) {
                val letter = mapped.output ?: mapped.label
                if (letter.length == 1) {
                    LatinAccents[letter.lowercase().first()]?.let { extra ->
                        mapped = mapped.copy(longPress = (mapped.longPress + extra).distinct())
                    }
                }
            }
            // Issue #108: the shifted form last of all, so it sits after the
            // accents and after whatever the layout itself listed — the first
            // entry is what a plain hold-and-release commits, and that has
            // always belonged to the layout. A key that already offers its
            // capital keeps the one it authored.
            if (shiftedKeys && mapped.action == KeyAction.Text) {
                shiftedAlternate(mapped)?.let { extra ->
                    mapped = mapped.copy(longPress = mapped.longPress + extra)
                }
            }
            // Keyed on what the key types, not what it is labelled: a layout
            // that shows "A" and outputs "a" was silently skipped. A key the
            // layout gave a clipboard shortcut of its own is left alone: that
            // one owns the hold outright and has no popup to join.
            //
            // Appended by default, never prepended: the accents are what the key
            // has always offered under a hold, and with hold-to-select on the
            // first entry is the one a plain hold-and-release commits. An edit
            // action landing there would take a as select-all instead of as à.
            //
            // `actionFirst` is the user asking for exactly that trade, because
            // they hold c to copy far more often than to type ç. It moves the
            // whole action block in front of the characters rather than only
            // this entry — see [Key.actionAlternatesFirst] — so a key that
            // already carried authored actions keeps them in their own order.
            if (mapped.action == KeyAction.Text && mapped.clipboardAction == null) {
                clipboardKeys[mapped.output ?: mapped.label]?.let {
                    mapped = mapped.copy(
                        actionAlternates = mapped.actionAlternates + clipboardAlternate(it),
                        actionAlternatesFirst = clipboardActionFirst,
                    )
                }
            }
            // Appended rather than prepended, so a layout that authored its own
            // alternates onto the enter key keeps them in the order it wrote
            // them and this one lands at the end. Skipped outright if the layout
            // already offers a newline of its own.
            if (newlineAlternate && mapped.action == KeyAction.Enter &&
                mapped.actionAlternates.none { it.action == KeyAction.Newline }
            ) {
                mapped = mapped.copy(
                    actionAlternates = mapped.actionAlternates +
                        KeyAlternate(action = KeyAction.Newline, icon = "enter"),
                )
            }
            // Prepended, unlike the line break above: the user switched this on
            // to get emoji from a plain hold, and with hold to select that is the
            // first entry. Everything else the popup offered stays, one slide on.
            if (emojiAlternate && mapped.action == KeyAction.Enter &&
                mapped.actionAlternates.none { it.action == KeyAction.Emoji }
            ) {
                mapped = mapped.copy(
                    actionAlternates = listOf(KeyAlternate(action = KeyAction.Emoji, icon = "emoji")) +
                        mapped.actionAlternates,
                )
            }
            // Last, so it covers whatever the passes above made of the key: a
            // 🌐 the emoji preference already turned into the emoji key is still
            // the 小゛゜ key while there is a kana to change.
            if (kanaVariantKeys && rowKey.kanaVariantWhileComposing) {
                mapped = mapped.asKanaVariantKey()
            }
            mapped
        }
    }
    return base.copy(
        rows = if (!swapCommaGlobe) {
            rewritten
        } else {
            rewritten.mapIndexed { rowIndex, row ->
                if (rowIndex == bottom && !swapBottom) {
                    row
                } else {
                    swapCommaAndGlobe(base.rows[rowIndex], row, rowIndex, bottom)
                }
            }
        },
    )
}

/**
 * Trades the comma key and the 🌐 key's places in one row, leaving every other
 * key where it was. No-op for a row that hasn't got both.
 *
 * The positions are read off [source] rather than [rewritten] because the pass
 * above may already have turned either one into the emoji key (or the comma
 * into an @ for an email field) — by then there is nothing left to identify
 * them by.
 */
private fun swapCommaAndGlobe(
    source: List<Key>,
    rewritten: List<Key>,
    rowIndex: Int,
    lastRow: Int,
): List<Key> {
    val comma = source.indexOfFirst { it.roleIn(rowIndex, lastRow) == KeyRole.Comma }
    val globe = source.indexOfFirst { it.action == KeyAction.LanguageSwitch }
    if (comma < 0 || globe < 0) return rewritten
    return rewritten.toMutableList().also {
        val held = it[comma]
        it[comma] = it[globe]
        it[globe] = held
    }
}

/**
 * This grid with its 🌐 key in the slot the built-in bottom row gives it
 * (#310), or null when the bottom row cannot take that without damage — in
 * which case it is drawn as its author made it.
 *
 * The slot is a share of the row, not a count of keys, because rows differ in
 * both: `?123 , 🌐 ␣ . ⏎` puts the key's left edge at 25% of the row and makes
 * it 10% wide. With [outer] (the comma swap, on by default) the key and the
 * comma trade, so the key starts at 15% and the comma follows it. Everything
 * before the spacebar other than those two is scaled to fill what is left of
 * the slot's start; the spacebar gives or takes whatever the row's width needs,
 * and the keys after it keep their widths. The row keeps its total and the
 * order of every other key.
 *
 * A row with nothing before the 🌐 key widens the key to fill the space up to
 * the slot, so a thumb aimed where the key is on every other layout lands on
 * it here too, rather than on the spacebar.
 *
 * Returns null, leaving the grid alone, when:
 * - the bottom row has no spacebar, or more or fewer than one 🌐 key;
 * - any key spans rows, since moving keys would slide them under it;
 * - the keys before the slot would shrink below half or grow past two and a
 *   half times their width (a row with a long run of keys by the spacebar);
 * - the spacebar would end up under a fifth of the row.
 *
 * A row already in place comes back as the same grid. The built-in row is
 * already in place, and under [outer] it comes out exactly as the comma swap
 * would have left it, so the built-in layouts look as they always did. Null
 * is only for the rows it will not touch, which the caller then swaps the
 * old way.
 */
internal fun KeyboardLayout.withGlobeInPlace(outer: Boolean): KeyboardLayout? {
    val bottom = rows.lastOrNull() ?: return null
    if (rows.any { row -> row.any { it.rowSpan > 1 } }) return null
    if (bottom.count { it.action == KeyAction.LanguageSwitch } != 1) return null
    val globe = bottom.first { it.action == KeyAction.LanguageSwitch }
    val others = bottom.filterNot { it.action == KeyAction.LanguageSwitch }
    val space = others.indexOfFirst { it.action == KeyAction.Space }
    if (space < 0) return null
    val lastRow = rows.lastIndex
    val before = others.subList(0, space)
    val after = others.subList(space + 1, others.size)
    // Under the swap the comma is the key that follows the globe, so it leaves
    // the run before the slot. The last one, the one nearest the spacebar.
    val commaIndex = if (outer) {
        before.indexOfLast { it.roleIn(lastRow, lastRow) == KeyRole.Comma }
    } else {
        -1
    }
    val comma = before.getOrNull(commaIndex)
    val lead = if (comma == null) before else before.filterIndexed { i, _ -> i != commaIndex }

    val total = bottom.sumOf { it.width.toDouble() }.toFloat()
    val slotStart = total * (if (outer) GLOBE_SLOT_OUTER else GLOBE_SLOT_INNER)
    val slotWidth = total * GLOBE_SLOT_WIDTH
    val leadWidth = lead.sumOf { it.width.toDouble() }.toFloat()
    val leadScale = if (lead.isEmpty()) 1f else slotStart / leadWidth
    if (leadScale < GLOBE_LEAD_MIN_SCALE || leadScale > GLOBE_LEAD_MAX_SCALE) return null
    val globeWidth = if (lead.isEmpty()) slotStart + slotWidth else slotWidth
    val commaWidth = if (comma == null) 0f else slotWidth
    val afterWidth = after.sumOf { it.width.toDouble() }.toFloat()
    val spaceWidth = total - slotStart - slotWidth - commaWidth - afterWidth
    if (spaceWidth < total * GLOBE_MIN_SPACE_SHARE) return null

    val row = buildList {
        lead.forEach { add(it.copy(width = it.width * leadScale)) }
        add(globe.copy(width = globeWidth))
        comma?.let { add(it.copy(width = commaWidth)) }
        add(others[space].copy(width = spaceWidth))
        addAll(after)
    }
    // Already there, give or take float rounding: hand back the grid itself, so
    // an unchanged layout stays the same object and nothing downstream redraws.
    val same = row.size == bottom.size && row.indices.all { i ->
        row[i].copy(width = bottom[i].width) == bottom[i] &&
            kotlin.math.abs(row[i].width - bottom[i].width) < GLOBE_WIDTH_EPSILON
    }
    return if (same) this else copy(rows = rows.dropLast(1) + listOf(row))
}

/** Where the 🌐 key starts in the built-in row, as a share of it: after `?123 ,`. */
private const val GLOBE_SLOT_INNER = 0.25f

/** The same under the comma swap: after `?123`, with the comma after the key. */
private const val GLOBE_SLOT_OUTER = 0.15f

/** The 🌐 key's width in the built-in row, as a share of it. */
private const val GLOBE_SLOT_WIDTH = 0.10f

/** The keys before the slot may not be squeezed below half their width… */
private const val GLOBE_LEAD_MIN_SCALE = 0.5f

/** …or stretched past two and a half times it (a lone `?123` at 1.0 just fits). */
private const val GLOBE_LEAD_MAX_SCALE = 2.5f

/** The spacebar keeps at least this share of the row, or the row is left alone. */
private const val GLOBE_MIN_SPACE_SHARE = 0.2f

/** Width differences below this are float noise, not a move. */
private const val GLOBE_WIDTH_EPSILON = 0.001f

/**
 * This grid with the 🌐 key taken off its bottom row, and the width the key
 * used given to the spacebar (issue #139).
 *
 * The spacebar gets all of it rather than every key a share: a bigger spacebar
 * is what the setting is for, and an even share would also widen `?123` and
 * enter. A row with no spacebar shares the width out instead, so it still fills
 * the board rather than leaving a gap at one end. Either way the row keeps its
 * total, which is what leaves a key spanning down into it where it was.
 *
 * Only the bottom row, because that is the key the setting names; a 🌐 key an
 * author placed anywhere else was placed on purpose. A row of nothing but 🌐
 * keys is left alone, since removing them would leave a row with no keys.
 */
internal fun KeyboardLayout.withoutGlobeKey(): KeyboardLayout {
    val bottom = rows.lastOrNull() ?: return this
    val globes = bottom.count { it.action == KeyAction.LanguageSwitch }
    if (globes == 0 || globes == bottom.size) return this
    val freed = bottom.filter { it.action == KeyAction.LanguageSwitch }
        .sumOf { it.width.toDouble() }.toFloat()
    val kept = bottom.filterNot { it.action == KeyAction.LanguageSwitch }
    val space = kept.indexOfFirst { it.action == KeyAction.Space }
    val row = if (space >= 0) {
        kept.mapIndexed { index, key ->
            if (index == space) key.copy(width = key.width + freed) else key
        }
    } else {
        val total = kept.sumOf { it.width.toDouble() }.toFloat()
        kept.map { it.copy(width = it.width * (total + freed) / total) }
    }
    return copy(rows = rows.dropLast(1) + listOf(row))
}

/**
 * Whether the focused field's keypad should be showing.
 *
 * A numeric field gets its keypad whatever the layout mode says — the pads
 * have no ?123 key to leave by, so the letter/symbol cycle does not apply.
 * The exception is anything that reroutes keystrokes away from the editor:
 * the emoji, media, dictionary and clipboard search boxes, a plugin's own text
 * box and the typing test all need letters, and a digits-only pad would leave
 * them impossible to type in.
 */
private fun numericPadActive(state: KeyboardUiState): Boolean =
    state.fieldKind.isNumericPad &&
        // A digits-only pad is about the *app's* field. While one of the
        // keyboard's own fields has the keys, that field decides what they
        // are — a search box on a phone-number field still needs letters.
        // The two numeric ones are the exception: their keypads are digits.
        state.captureTarget().let { it == null || it == CaptureTarget.CALC || it == CaptureTarget.CONVERTER }


private fun String.isSingleDigit(): Boolean = length == 1 && this[0].isDigit()

/**
 * The digits a hold on the number row offers besides the ones a tap types
 * (#309), or null when the language has only one set.
 *
 * A tap types the chosen system, so the hold offers the other: ASCII under a
 * native system, the language's own digits under Latin. Under "display only" a
 * tap types ASCII whatever the keys show, so the hold offers the glyphs drawn.
 */
private fun otherNumeralDigits(state: KeyboardUiState): String? {
    val behavior = state.settings.layoutBehavior
    val drawn = resolveNumeralDigits(behavior.numeralSystemFor(state.language.id), state.language)
    return when {
        drawn == null -> state.language.numeralSystem.digits
        behavior.numeralCommitScope == NumeralCommitScope.DISPLAY_ONLY -> drawn
        else -> ASCII_DIGITS
    }
}

/**
 * Each digit key offers [other]'s digit first under its hold, so a plain hold
 * and release types it (#309) — an Arabic writer on ٠-٩ reaches 0-9 without a
 * trip to settings, and one on 0-9 reaches ٠-٩. Marked [VERBATIM_DIGITS]
 * because an ASCII digit would otherwise be rewritten straight back.
 */
private fun List<Key>.withOtherNumerals(other: String?): List<Key> {
    if (other == null) return this
    return map { key ->
        val digit = (key.output ?: key.label).singleOrNull()
        if (key.action != KeyAction.Text || digit == null || digit !in '0'..'9') return@map key
        val alternate = VERBATIM_DIGITS + other[digit - '0']
        key.copy(longPress = listOf(alternate) + key.longPress.filterNot { it == alternate })
    }
}

/**
 * Places a popup centered above its anchor with a clear gap, so the
 * character bubble and long-press alternates are not hidden under the
 * pressing finger.
 */
private class AboveAnchorPopupPositionProvider(
    private val gapPx: Int,
    /**
     * Sideways nudge, positive to the right, for the preview bubble's own
     * setting. Applied before the clamp below, so a bubble shifted toward an
     * edge stops at the edge rather than leaving the keyboard.
     */
    private val offsetXPx: Int = 0,
) : PopupPositionProvider {
    override fun calculatePosition(
        anchorBounds: IntRect,
        windowSize: IntSize,
        layoutDirection: LayoutDirection,
        popupContentSize: IntSize,
    ): IntOffset {
        val x = (anchorBounds.left + (anchorBounds.width - popupContentSize.width) / 2 + offsetXPx)
            .coerceIn(0, (windowSize.width - popupContentSize.width).coerceAtLeast(0))
        val y = (anchorBounds.top - popupContentSize.height - gapPx).coerceAtLeast(0)
        return IntOffset(x, y)
    }
}

/**
 * Gap a popup keeps from the key it belongs to, so the bubble and the long-press
 * alternates are not hidden under the pressing finger. Named because the preview
 * overlay sizes its headroom from it — the two have to agree or the top row's
 * bubble is clipped.
 */
private val KeyPopupGap = 10.dp

/**
 * The preview bubble's label: its size in each style, and in the on-key style
 * the padding above and below it. The overlay floors an on-key bubble at its
 * key plus this lane ([onKeyBubbleHeightPx]), so the label and the bubble have
 * to agree on the numbers.
 */
private const val OnKeyLabelSp = 34f
private const val FloatingLabelSp = 22f
private val OnKeyLabelTopPadding = 8.dp
private val OnKeyLabelBottomPadding = 4.dp

/** A text line's height over its font size, for the fonts the bubble draws in. */
private const val LabelLineHeightRatio = 1.2f

@Composable
private fun rememberAboveAnchorPopup(): PopupPositionProvider {
    val density = LocalDensity.current
    return remember(density) {
        AboveAnchorPopupPositionProvider(with(density) { KeyPopupGap.roundToPx() })
    }
}

/**
 * Places the popup so its bottom edge lines up with the pressed key's
 * bottom, growing upward from the key itself — the tall stock-keyboard
 * style where the bubble visually replaces the key.
 */
private object OnKeyPopupPositionProvider : PopupPositionProvider {
    override fun calculatePosition(
        anchorBounds: IntRect,
        windowSize: IntSize,
        layoutDirection: LayoutDirection,
        popupContentSize: IntSize,
    ): IntOffset {
        val x = (anchorBounds.left + (anchorBounds.width - popupContentSize.width) / 2)
            .coerceIn(0, (windowSize.width - popupContentSize.width).coerceAtLeast(0))
        val y = (anchorBounds.bottom - popupContentSize.height).coerceAtLeast(0)
        return IntOffset(x, y)
    }
}

/** Visual gap between keys, provided as padding inside each touch cell. */
private val KeyGapHorizontal = 2.5.dp
private val KeyGapVertical = 4.dp

/**
 * The gaps above, scaled by the user's key-spacing setting. Every gap-consuming
 * site reads these so the touch-cell padding and the height math in
 * [keyRowsHeight] scale together — the keyboard's height and the panels that
 * mirror it stay in step when the spacing changes.
 */
internal fun keyGapH(settings: KeyboardSettings): Dp = KeyGapHorizontal * settings.keyGapScale
internal fun keyGapV(settings: KeyboardSettings): Dp = KeyGapVertical * settings.keyGapScale

/**
 * Peak extra glide-start slop applied the instant after a tap, on top of the
 * user's start-distance multiplier, decaying to 0 across the post-typing
 * cooldown window. 2.5 means a glide starting right after a keypress must travel
 * 3.5× as far (1 + 2.5) as it normally would before it is read as a swipe-word.
 */
private const val POST_TYPE_SLOP_BOOST = 2.5f

/**
 * How far apart two glide-trail samples must be before the step between them is
 * taken as a direction, in pixels.
 *
 * A finger that has stopped still reports a stream of samples a fraction of a
 * pixel apart, and normalising one of those amplifies the digitizer's noise into
 * a normal pointing anywhere — which shows as the ribbon flaring sideways where
 * the hand paused. Below this the previous direction stands.
 */
private const val TRAIL_MIN_STEP_PX = 0.5f

/**
 * When the directions into and out of a trail sample are treated as cancelling.
 *
 * Their sum is a unit-length vector for a straight run and shrinks towards zero
 * as the path folds back; at a true reversal there is no bisector to take a
 * normal from, so the incoming direction decides alone and the fold is drawn
 * over itself rather than as a spike off to one side.
 */
private const val TRAIL_MIN_BISECTOR = 1e-3f

/**
 * How often a glide in progress asks the decoder for a preview word.
 *
 * Counting samples instead ties the rate to the digitizer: every sixth touch
 * report is ten decodes a second on a 60 Hz panel and forty on a 240 Hz one, so
 * the better screen paid four times as much for the same swipe. 40 ms is about
 * two frames — fast enough that the floating word keeps up with the finger.
 */
private const val PREVIEW_INTERVAL_MS = 40L

/**
 * How many points a segment needs before it is previewed, and before an
 * ordinary lift commits it. A frozen segment — one the ambiguity picker opened
 * on — commits at the preview floor, since the picker's words came from a
 * preview of exactly those points.
 */
private const val PREVIEW_MIN_POINTS = 3
private const val COMMIT_MIN_POINTS = 4

/** Samples a stroke needs before the flick test can be asked about it: two, the
 * fewest that have a direction at all. */
private const val OCTOPUS_MIN_POINTS = 2

/**
 * How far the finger may drift and still count as held, in key widths. A finger
 * resting on glass is never perfectly still, and a threshold that demanded it
 * would mean the picker never appeared for anybody. (How *long* it has to hold
 * is the user's: `GestureSettings.pickerDwellMs`.)
 */
private const val PICKER_STILL_WIDTHS = 0.3f

/** The picker's target height and the gaps around it. */
private val GlidePickerHeight = 44.dp
private val GlidePickerGap = 10.dp

/** How faint the targets go once the finger has dropped into the cancel zone. */
private const val GlidePickerDimmedAlpha = 0.4f

/** The accent outline on the leader target, and the cancel hint's text. */
private const val GlidePickerLeaderOutlineAlpha = 0.6f
private const val GlideHintTextAlpha = 0.8f

/** How many targets share the picker's row at most: the width cap is a third of the window. */
private const val GlidePickerRowMax = 3

/**
 * How many of the picker's targets go on the row nearest the finger: all of
 * them when they fit in [maxWidth] with [gapPx] between, else the larger half,
 * so the leader's row is the fuller one and the second row sits above it. Two
 * rows are always enough, because each target is measured no wider than a
 * third of the window less the gaps, so three share a row whatever the words.
 */
internal fun pickerLeaderRowCount(widths: IntArray, gapPx: Int, maxWidth: Int): Int {
    val total = widths.sum() + gapPx * (widths.size - 1).coerceAtLeast(0)
    return if (total <= maxWidth) widths.size else (widths.size + 1) / 2
}

/**
 * How far above the fingertip each slot of a row of [count] rides, in the
 * anchor key's heights: one key for the slots off to either side, two for the
 * one in the middle. The middle slot is the one a straight flick up runs into,
 * and at a single key it sat so close to the near slots that the three read as
 * one blob under the finger; a second key of clearance makes the straight move
 * and the diagonal ones plainly different moves. A row with no single middle —
 * two targets, or four — is all near slots.
 */
internal fun pickerRowLifts(count: Int): FloatArray = FloatArray(count) { slot ->
    if (count % 2 == 1 && slot == count / 2) GlidePickerFarLift else GlidePickerNearLift
}

/**
 * Which word goes in which slot: the likeliest into the nearest slot to where
 * the finger is holding, the next into the next nearest, and so on down.
 * Returns the word's index for each slot, in slot order.
 *
 * Nearest is the straight-line distance from the fingertip to the slot's
 * centre, except that [middleSlot] — the one the arc raises, straight up from
 * the finger — counts at [GlidePickerMiddleFavour] of its real distance. Going
 * straight up is the easiest move on the board and the one the hand is already
 * lined up for, so the middle keeps the leader unless a side slot is more than
 * twice as close: mid-board it always is the leader, and only a stroke that
 * ended near an edge — where the row is clamped and the middle is most of a row
 * away — hands it over to the side slot under the finger. Pass -1 for a row
 * with no single middle.
 *
 * Ties go to the earlier slot, so the leader sits left of the runner-up rather
 * than swapping with it as the words change width.
 */
internal fun pickerWordAtSlot(
    slotX: FloatArray,
    slotY: FloatArray,
    anchorX: Float,
    anchorY: Float,
    middleSlot: Int,
): IntArray {
    val slots = slotX.indices.sortedBy { slot ->
        val dx = slotX[slot] - anchorX
        val dy = slotY[slot] - anchorY
        val reach = sqrt(dx * dx + dy * dy)
        if (slot == middleSlot) reach * GlidePickerMiddleFavour else reach
    }
    val wordAt = IntArray(slotX.size)
    slots.forEachIndexed { word, slot -> wordAt[slot] = word }
    return wordAt
}

/**
 * The two distances a picker target sits from the fingertip, in the anchor
 * key's heights, measured centre to fingertip. The middle slot's extra quarter
 * key is clearance, not a journey: it lifts the straight-up target off the line
 * of its neighbours without putting it a key further away. See
 * [pickerRowLifts].
 */
private const val GlidePickerNearLift = 1f
private const val GlidePickerFarLift = 1.25f

/**
 * What the middle slot's distance counts as when the words are dealt out: half,
 * so it keeps the leader unless a side slot is more than twice as close. See
 * [pickerWordAtSlot].
 */
private const val GlidePickerMiddleFavour = 0.5f

/** The pill's vertical padding; [GlideOverlay]'s headroom estimate counts it twice. */
private val GlidePillPaddingV = 6.dp

/**
 * Line height per sp of the pill's font, for the same estimate. Real fonts run
 * about 1.2–1.4; over-estimating only adds transparent window.
 */
private const val GlidePillLineHeightRatio = 1.5f

/** The pill's id among [GlideOverlay]'s measurables; the targets carry their index. */
private const val GlidePillId = "glide-pill"

/** The cancel hint's id among the same measurables. */
private const val GlideHintId = "glide-hint"

/** Vertical padding of the [KeyRows] column, mirrored into [keyRowsHeight]. */
internal val KeyRowsPadVertical = 2.dp

/**
 * Horizontal padding of the [KeyRows] column. Named because the gesture
 * decoder's key-width derivation has to subtract it to get the real cell width.
 */
internal val KeyRowsPadHorizontal = 1.5.dp

/**
 * Default height of [TopBar] (suggestions/toolbar row), and the fallback when
 * no settings are on hand. The live height is [topBarHeight], which honours
 * the user's `toolbarHeightDp` — prefer it wherever settings are available so
 * a taller bar and its full-bleed accounting stay in step.
 */
internal val TopBarHeight = 44.dp

/** Downward travel on the strip that counts as a "hide the keyboard" flick. */
private val ToolbarSwipeHideThreshold = 48.dp

/**
 * Whether the pinned tools should read right-to-left: the setting is on and
 * the active layout's script runs RTL.
 *
 * The one answer for every part of the toolbar's behaviour — the direction the
 * bar draws tools under (see [TopBar]), the direction of the tools sub-row
 * inside it, the direction of an own-row placement ([ToolsRow]), and the edge
 * the drag counts its slots from — so a reorder can never disagree with what is
 * on screen and turning the setting off leaves the toolbar where it was rather
 * than sliding the whole cluster to the other edge (issue #80).
 *
 * Deliberately not read by the suggestion strip: that surface is text, and its
 * best candidate belongs where an RTL eye starts whatever the tools do.
 */
private fun toolbarReadsRtl(state: KeyboardUiState): Boolean =
    state.settings.toolbarBehavior.reverseForRtl && state.script.direction == TextDirection.RTL

/**
 * The top strip's height for the current settings (see [TopBarHeight]).
 * Collapses to zero when the toolbar is disabled, so every height-accounting
 * caller (full-bleed absorption, emoji-search sizing) drops the strip with it.
 */
internal fun topBarHeight(settings: KeyboardSettings): Dp =
    if (settings.toolbarBehavior.enabled) {
        (settings.toolbarHeightDp + settings.toolbarBehavior.paddingTopDp + settings.toolbarBehavior.paddingBottomDp).dp
    } else {
        0.dp
    }

/**
 * The user's toolbar top and bottom padding (#208), for a row sized with
 * [topBarHeight]. Applied inside that height, so the row's content keeps
 * `toolbarHeightDp` and every height-accounting caller still sees one number.
 */
internal fun Modifier.toolbarPadding(settings: KeyboardSettings): Modifier =
    if (settings.toolbarBehavior.enabled) {
        padding(
            top = settings.toolbarBehavior.paddingTopDp.dp,
            bottom = settings.toolbarBehavior.paddingBottomDp.dp,
        )
    } else {
        this
    }

/**
 * Exact height of [KeyRows]: [LayoutSet.rowSpan] key rows (each key height plus
 * its vertical gaps), the optional number row, and the column padding. Every
 * panel sizes itself with this so opening a tool or switching layers never
 * changes the keyboard's height under the user's fingers.
 *
 * Takes the whole state rather than the settings because the row count is a
 * property of the active layout set — a custom layout may be three rows or six.
 * Threading the resolved [LayoutSet] through as its own parameter was the
 * alternative and was rejected: every call site already has the state in scope,
 * so it would have touched every panel signature and bought nothing.
 */
/**
 * Whether the dedicated number row is drawn on the *current* layer. Honours the
 * global [KeyboardSettings.numberRow] and the opt-out
 * [LayoutBehaviorSettings.numberRowInSymbols], which drops the row from the
 * ?123 / symbols layers where the symbols already carry their own top row.
 * Shared by the render loop and [keyRowsHeight] so the reserved height and the
 * drawn row always agree — otherwise a suppressed row would leave a blank gap.
 */
internal fun numberRowShown(state: KeyboardUiState): Boolean =
    state.settings.numberRow &&
        // A secondary layout is drawn exactly as its author built it.
        state.layoutMode != LayoutMode.SECONDARY &&
        (state.settings.layoutBehavior.numberRowInSymbols ||
            (state.layoutMode != LayoutMode.SYMBOLS &&
                state.layoutMode != LayoutMode.SYMBOLS_SHIFTED))

// ---- what is on screen: one answer, read by the renderer and the service ----
//
// The physical keyboard's hint badges pair a key with the button under it, and
// the service dispatches the same key against the same list. Both sides derive
// their list here rather than each working it out, because a disagreement is
// silent and vicious: the badge says one thing and another cell opens.

/**
 * Lock-screen privacy has dropped the whole top strip, taking the clipboard
 * tool and paste chip with it.
 */
internal fun barLockHidden(state: KeyboardUiState): Boolean =
    state.deviceLocked && state.settings.toolbarBehavior.hideWhenLocked

/**
 * The clipboard panel has traded its full-bleed height for one of its own
 * fields — the search pill or the clip editor — with the keys back beneath.
 */
internal fun barClipboardSearching(state: KeyboardUiState): Boolean =
    state.clipboardTakesKeys && !barLockHidden(state)

/**
 * Whether the key rows are drawn under the open panel: one of the keyboard's
 * own fields has taken the keys, and a focused field needs something on screen
 * to type into it. Asked by the body, which draws them, and by
 * [FullBleedTool], which has to leave them room.
 */
internal fun keyRowsUnderPanel(state: KeyboardUiState): Boolean = when (state.captureTarget()) {
    null, CaptureTarget.CALC, CaptureTarget.CONVERTER, CaptureTarget.WORD_SPELL -> false
    // The emoji and clipboard panels reroute their search pills;
    // the rest are only ever up with their own panel open.
    CaptureTarget.EMOJI_SEARCH -> state.panel == PanelMode.EMOJI
    CaptureTarget.CLIPBOARD_SEARCH, CaptureTarget.CLIP_EDIT -> barClipboardSearching(state)
    CaptureTarget.DICTIONARY_SEARCH -> state.panel == PanelMode.DICTIONARY
    CaptureTarget.MEDIA_SEARCH -> state.panel.hasMediaSearch
    else -> true
}

/** A panel is claiming the strip's height, so the rows above the keys are gone. */
internal fun barFullBleed(state: KeyboardUiState): Boolean =
    isFullBleedPanel(state.panel, state.settings) && !barClipboardSearching(state)

internal fun emojiRowVisible(state: KeyboardUiState): Boolean =
    !barFullBleed(state) &&
        state.settings.emojiBarMode == EmojiBarMode.ALWAYS &&
        state.panel != PanelMode.EMOJI

internal fun symbolRowVisible(state: KeyboardUiState): Boolean =
    !barFullBleed(state) &&
        state.settings.symbolRowEnabled &&
        state.panel != PanelMode.SYMBOLS

/**
 * The pinned tools the bar draws, in storage order. An RTL bar reads the same
 * list backwards — that is a layout direction on the row, not a different
 * order (see [toolbarReadsRtl]) — so a digit badge names the same tool on
 * either side of the flip.
 *
 * [KeyboardUiState.mediaPinned] adds the media tool on the end for as long as
 * music is playing. It goes last, and only when the user has not pinned it
 * themselves, so nothing they *did* pin ever moves — every other tool keeps
 * its slot, and with it its hardware digit.
 */
internal fun visibleToolbarTools(state: KeyboardUiState): List<ToolbarTool> =
    state.settings.toolbarTools
        .let { if (mediaAutoPinned(state)) it + ToolbarTool.MEDIA_CONTROL else it }
        .filter {
            it in state.settings.enabledTools && isSupportedTool(it) &&
                isUsableTool(it, state.settings)
        }

/**
 * Whether the media tool is riding the toolbar on playback rather than on a
 * pin the user saved. False once they have pinned it for real — there is one
 * slot for one tool, and the saved one wins.
 */
internal fun mediaAutoPinned(state: KeyboardUiState): Boolean =
    state.mediaPinned && ToolbarTool.MEDIA_CONTROL !in state.settings.toolbarTools

/**
 * What the toolbox has to show: everything enabled that is not already pinned
 * — the transient media pin included, so the tool is never in both places at
 * once and a drag has one cell to start from — less the tools the user hid
 * from the grid ([ToolboxSettings.hiddenTools]), which stay on everywhere else.
 */
internal fun visibleToolboxTools(state: KeyboardUiState): List<ToolbarTool> {
    val pinned = state.settings.toolbarTools.toSet() +
        if (mediaAutoPinned(state)) setOf(ToolbarTool.MEDIA_CONTROL) else emptySet()
    val hidden = state.settings.toolbox.hiddenTools
    return state.settings.toolboxOrder.filter {
        it !in pinned && it !in hidden && it in state.settings.enabledTools &&
            isSupportedTool(it) && isUsableTool(it, state.settings)
    }
}

/** The symbol set the row is showing, resolved the way the row itself resolves it. */
internal fun activeSymbolSet(state: KeyboardUiState): SymbolSet {
    val all = resolveSymbolSets(state.settings.customSymbolSets)
    val enabled = state.settings.symbolRowSetIds
        .mapNotNull { id -> all.firstOrNull { it.id == id } }
        .ifEmpty { BuiltInSymbolSets.sets }
    val activeId = state.activeSymbolSetId ?: state.settings.symbolRowActiveSetId
    return enabled.firstOrNull { it.id == activeId } ?: enabled.first()
}

/** The emoji the bar is showing, already toned, in the order the cells draw them. */
internal fun visibleEmojiBarItems(state: KeyboardUiState): List<String> =
    when (state.settings.emojiBarContent) {
        EmojiBarContent.MOST_USED -> state.emojiFrequents
        EmojiBarContent.RECENTS -> state.emojiRecents
        EmojiBarContent.FAVOURITES -> state.emojiFavourites
    }.ifEmpty { DEFAULT_BAR_EMOJIS.map { emojiDisplay(state, it) } }

/**
 * Every hotkey the keyboard is currently offering.
 *
 * Cheap enough to call per composition and per keystroke: it walks four short
 * lists and allocates two maps. Caching it would mean inventing an invalidation
 * rule for a value that has to be exactly right at both call sites.
 */
internal fun keyboardHintPlan(state: KeyboardUiState): HintPlan {
    val hw = state.settings.hardwareKeyboard
    if (!hw.shortcutsEnabled) return HintPlan()
    val symbols = if (symbolRowVisible(state)) activeSymbolSet(state).chars.size else 0
    val emoji = if (emojiRowVisible(state)) {
        minOf(
            visibleEmojiBarItems(state).size,
            state.settings.emoji.barCount.coerceIn(EmojiBarCountRange),
        )
    } else {
        0
    }
    return buildHintPlan(
        toolbarTools = visibleToolbarTools(state),
        toolboxTools = if (state.panel == PanelMode.TOOLBOX) visibleToolboxTools(state) else emptyList(),
        toolLetters = resolvedToolLetters(hw.toolByLetter, usableTools(state.settings)),
        symbolCells = symbols,
        emojiCells = emoji,
        suggestions = state.suggestions.size,
        digitChord = hw.toolbarDigitChord,
        leaderDigitsPickSuggestions = hw.suggestionHotkeys == SuggestionHotkeyMode.LEADER_DIGIT,
        suggestionAltDigits = hw.suggestionHotkeys == SuggestionHotkeyMode.ALT_DIGIT,
        modifiers = HintModifiers.of(hw.hintModifierWords),
    )
}

/**
 * Which engine rank each suggestion slot is drawing, left to right.
 *
 * The centre-primary setting swaps the first two chips, so slot 0 shows rank 1.
 * The badges count slots, not ranks — a strip labelled 2 1 3 is exactly the
 * puzzle the badges exist to remove — which means the key must resolve back to
 * the rank before it commits. Shared with the service so the badge and the
 * keypress can never disagree about which word is which.
 *
 * Only the Latin chips reorder: the conversion strip is a scrolling row in the
 * composer's own order, and the inline-emoji row is not word candidates at all.
 */
internal fun suggestionDisplayOrder(state: KeyboardUiState): List<Int> {
    val reorders = !state.composer.isConversion && !state.inlineEmoji &&
        state.settings.suggestionStrip.suggestionPrimaryCenter && !state.fixedPhoneticStrip()
    return suggestionSlotOrder(state.suggestions.size, reorders)
}

/**
 * Whether the strip is a phonetic layout's fixed one (the word as typed, then
 * its transliteration, then suggestions): its chips have to stay in the order
 * the engine put them, so the centred-primary shuffle sits out.
 */
internal fun KeyboardUiState.fixedPhoneticStrip(): Boolean =
    settings.suggestionStrip.phoneticFixedStripFor(composer.phoneticLanguage) != null

/**
 * The hints to draw on the tools and rows, which is only ever while the picker
 * is armed. Badges on every icon at all times would be noise for the far larger
 * number of people who never plug a keyboard in.
 */
internal fun armedHintPlan(state: KeyboardUiState): HintPlan? =
    state.toolPicker?.let { keyboardHintPlan(state) }

/**
 * The hints to draw on the suggestion strip, which is the one surface that
 * shows them without being asked.
 *
 * The strip is where a hardware-keyboard user's eyes already are, and `Alt`+1
 * needs no leader, so its digits are worth standing ink. The leader-digit mode
 * is the opposite: a bare `1` does nothing until the picker is armed, and a
 * badge promising otherwise would be a lie.
 */
internal fun suggestionHintPlan(state: KeyboardUiState): HintPlan? {
    val hw = state.settings.hardwareKeyboard
    if (!hw.shortcutsEnabled) return null
    val standing = state.hardwareKeyboardPresent &&
        hw.suggestionHintsAlways &&
        hw.suggestionHotkeys == SuggestionHotkeyMode.ALT_DIGIT
    return if (state.toolPicker != null || standing) keyboardHintPlan(state) else null
}

/**
 * Rows the key grid reserves right now: the layout set's span, or more while a
 * secondary layout taller than it is showing.
 *
 * A secondary grid is deliberately *not* a term in [LayoutSet.rowSpan]: one
 * six-row macro pad would otherwise pad two blank rows onto every letters grid
 * the user types on. So the board grows only while that grid is up, and only by
 * what it needs — the one place the "never resize under the fingers" rule
 * yields, because the user asked for a different keyboard, not a different
 * layer of this one.
 */
internal fun reservedRowSpan(state: KeyboardUiState): Int =
    if (state.layoutMode == LayoutMode.SECONDARY) {
        maxOf(state.layouts.rowSpan, currentLayout(state).rows.size)
    } else {
        state.layouts.rowSpan
    }

/**
 * The lane each row reserves above itself for its floating words, in the
 * octopus's "own lane" placement (discussion #102). Zero in the other two,
 * which draw in space the rows already leave.
 *
 * Read by the render loop and by [keyRowsHeight] alike, and reserved on the
 * *setting* alone rather than on whether anything is floating right now: every
 * panel sizes itself from [keyRowsHeight], and a lane that came and went would
 * resize the host app mid-sentence.
 */
internal fun octopusLane(state: KeyboardUiState): Dp {
    val octopus = state.settings.octopus
    return if (octopus.enabled && octopus.placement == OctopusPlacement.STRIP) {
        OctopusLaneDp
    } else {
        0.dp
    }
}

private val OctopusLaneDp = 11.dp

internal fun keyRowsHeight(state: KeyboardUiState): Dp {
    val settings = state.settings
    val rowSpan = reservedRowSpan(state)
    val layout = currentLayout(state)
    val rowHeights = layout.rowHeights
    var height = if (rowHeights == null) {
        (settings.keyHeightDp.dp + keyGapV(settings) * 2) * rowSpan
    } else {
        // A layout with per-row heights: sum its body rows at their scaled
        // heights and pad the rest at the base height, mirroring the render
        // loop key for key so the reserved height matches what is drawn.
        val bodyRowCount = layout.rows.size.coerceAtMost(rowSpan)
        var sum = 0.dp
        for (i in 0 until bodyRowCount) {
            sum += rowScaledKeyHeight(settings.keyHeightDp, rowHeights.getOrNull(i)).dp +
                keyGapV(settings) * 2
        }
        sum + (settings.keyHeightDp.dp + keyGapV(settings) * 2) * (rowSpan - bodyRowCount)
    }
    height += KeyRowsPadVertical * 2
    if (numberRowShown(state)) {
        height += settings.numberRowHeightDp.dp + keyGapV(settings) * 2
    }
    // One lane per reserved row, which is what the render loop draws: a lane
    // before every body block, and the padding rows' share folded into the pad
    // spacer. The two counts have to agree exactly or every panel opens at a
    // different height from the keys.
    height += octopusLane(state) * rowSpan
    // The bottom row's independent height (A45) rides on top: the render loop
    // swaps one base-height row for bottomRowHeightDp, so reserve the delta.
    // Only when the layout has no per-row heights, matching the render guard.
    val bottomRowHeightDp = settings.layoutBehavior.bottomRowHeightDp
    if (bottomRowHeightDp > 0 && rowHeights == null) {
        height += (bottomRowHeightDp - settings.keyHeightDp).dp
    }
    return height
}

/**
 * One key's tremor filter — the "ignore repeated presses" accessibility
 * setting, which drops a second contact on the same key inside a window.
 *
 * The verdict is taken on the way down rather than at the commit, because
 * everything a press costs is spent on the way down: the haptic, the click,
 * and only then the character. Judging late left the filter buzzing and
 * clicking for presses it went on to throw away, which is what it is there to
 * stop happening.
 *
 * Plain fields, not Compose state: the pointer handlers read and write these
 * outside composition, and nothing draws from them.
 */
private class KeyDebounceGate {
    private var lastAcceptedAt = 0L
    private var mutedUntil = 0L

    /** Whether the press this gate judged last is allowed to type. */
    var accepted = true
        private set

    /** Judges a contact. [debounceMs] of 0 or less turns the filter off. */
    fun press(debounceMs: Int) {
        val now = SystemClock.uptimeMillis()
        accepted = debounceMs <= 0 || now - lastAcceptedAt >= debounceMs
        if (accepted) lastAcceptedAt = now else mutedUntil = lastAcceptedAt + debounceMs
    }

    /**
     * Whether feedback fired *now* belongs to a press that was kept. Time-based
     * rather than latched to [accepted]: a dropped contact that the finger then
     * holds becomes a deliberate long press or repeat run, and by the time
     * those fire the window has passed, so they are heard.
     */
    fun audible(): Boolean = SystemClock.uptimeMillis() >= mutedUntil
}

/**
 * One key.
 *
 * Takes its resolved [KeyVisual] rather than the whole [KeyboardUiState] so a
 * keystroke that only moves the suggestions leaves every parameter here
 * untouched and this body — 15-odd modifier links and a pointer detector's worth
 * of lambdas — skips. [settings] is the one exception: it is compared by
 * instance (Compose reads it as unstable, being full of collections), which is
 * why [KeyboardScreen] holds its identity stable across keystrokes.
 */
@Composable
internal fun KeyButton(
    visual: KeyVisual,
    settings: KeyboardSettings,
    modifier: Modifier = Modifier,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    onCursorMove: (Int) -> Unit = {},
    onLayoutSelect: (String) -> Unit = {},
    heightDp: Int? = null,
    /** The field wants a keypad: the preview bubble is off unless opted back in. */
    numericField: Boolean = false,
    /** Active layout, for the spacebar's language cycle and the picker highlight. */
    layoutId: String = BuiltInLayouts.DEFAULT_ID,
    /** The board's shared preview bubble; this key only publishes to it. */
    keyPreview: KeyPreviewState,
    smartResolve: (Key, PointerId) -> Key = { k, _ -> k },
    /** Spawns the theme's press burst at this key; null when the effect is off. */
    onBurst: ((Rect, String?) -> Unit)? = null,
) {
    val key = visual.key
    // Held as the state object, never read through a `by` delegate: every read of
    // the press below is either inside a draw lambda or inside a composable of
    // its own, so a press repaints the key instead of recomposing it. Reading it
    // anywhere in this body puts composition and layout back on the press path.
    val pressed = remember { mutableStateOf(false) }
    var showAlternates by remember { mutableStateOf(false) }
    // The popup built ahead of the long press, hidden, while the finger is still
    // down: creating its window is the slow part of opening it (a first
    // relayout, ~15 ms on a mid-range phone, then a first draw), and paying that
    // after the long press fired put the popup a few frames behind the buzz that
    // says it is open. Armed [AlternatesPrewarmLeadMs] before the long press and
    // dropped on the lift, so a tap never gets this far.
    var alternatesPrepared by remember { mutableStateOf(false) }
    val alternatesPrewarm = remember { arrayOfNulls<Job>(1) }
    // The hold that opened the popup, while one is open: it carries the geometry
    // both windows need to agree on and the entry the finger is choosing. One
    // per key, and null throughout when the behaviour is switched off, which is
    // what every reader below tests rather than the setting itself.
    val alternatesGate = LocalAlternatesGate.current
    val alternatesHold = remember(alternatesGate) { AlternatesHold(alternatesGate) }
    val holdToSelect = settings.popup.alternatesHoldToSelect
    // Assigned rather than passed down: the gesture handlers take the hold and
    // nothing else, and this closes over the key and the callbacks as they are
    // now instead of as they were when the hold was remembered. The entry order
    // is the popup's own — the characters, then the action alternates.
    alternatesHold.onCommit = { index ->
        showAlternates = false
        when (val entry = key.alternateEntries().getOrNull(index)) {
            is AlternateEntry.Character -> onText(entry.text)
            is AlternateEntry.Action ->
                onKey(Key(label = entry.alternate.label, action = entry.alternate.action))
            // A negative index is "nothing selected"; past the end cannot
            // happen, but the popup and the hold are two windows and this is
            // the seam between them.
            null -> Unit
        }
    }
    // The flick arm the finger is currently over on a kana-pad key, driving the
    // cross popup's highlight; null when centred (a plain tap) or released.
    val flickDirection = remember { mutableStateOf<FlickDirection?>(null) }
    // Full tappable language picker (a list or, by setting, a carousel):
    // opened by a long-press on the globe key or by holding the spacebar when
    // more than two languages are enabled (a swipe through a long ring is
    // tedious). Independent of languagePreview.
    var showLanguagePicker by remember { mutableStateOf(false) }
    // Entry of the open picker the spacebar hold-drag currently has selected;
    // null until the finger actually moves (a plain hold leaves the popup up
    // for tapping, exactly as before).
    var pickerDragIndex by remember { mutableStateOf<Int?>(null) }
    // Language the spacebar swipe currently has selected, shown in a tooltip
    // popup above the spacebar while the finger is still down.
    var languagePreview by remember { mutableStateOf<String?>(null) }
    // The language a swipe just committed, lingering after the lift; only a
    // spacebar draws it, and the live swipe preview takes over while one runs.
    val languageSwitchEcho = LocalLanguageSwitchEcho.current
    val shownLanguage = languagePreview
        ?: languageSwitchEcho.shown?.layoutId?.takeIf { key.action == KeyAction.Space }
    val scope = rememberCoroutineScope()
    // The role-carrying locals, because this is the key grid: a sound pack may
    // have recorded the spacebar separately from the letters.
    val rawKeyPress = LocalKeyRoleFeedback.current
    val rawKeySound = LocalKeyRoleSound.current
    // Buzz with no click. Only the repeat tick uses it, for the case where the
    // user wants the held key to keep vibrating without machine-gunning the
    // sound.
    val onKeyHaptic = LocalHapticFeedback.current
    val onClipboardKey = LocalClipboardKeyAction.current
    val onSelectionHold = LocalSelectionHold.current
    val canDelete = LocalCanDelete.current
    val canForwardDelete = LocalCanForwardDelete.current
    val deleteSwipe = LocalDeleteSwipe.current
    val onCursorMoveVertical = LocalCursorMoveVertical.current
    val caretDrag = LocalCaretDrag.current
    val onHideKeyboard = LocalHideKeyboard.current

    // What this key would put in the shared bubble, were it pressed right now.
    // Held as updated state rather than captured: the press handler lives inside
    // a pointerInput whose block only restarts when its keys change, so a value
    // read straight out of the composition would be the one from whenever that
    // last happened — the label a shift had since changed, for one.
    //
    // Numeric keypads (number/phone/date/time fields) suppress the bubble unless
    // the user opted back in: a floating digit over a PIN pad is noise, and easy
    // shoulder-surfing.
    val previewToken = remember { Any() }
    val previewWanted = rememberUpdatedState(
        settings.popup.enabled &&
            (settings.popup.inNumericFields || !numericField) &&
            key.action == KeyAction.Text,
    )
    val previewLabel = rememberUpdatedState(visual.label)
    // Same staleness rule as the label: the pointer input holds its lambdas
    // across recompositions, so a per-key popup colour has to be read through
    // an updated state or a theme edit would keep bubbling the old colour.
    val previewColors = rememberUpdatedState(visual.popupBackground to visual.popupText)
    // And the burst likewise: switching to an effect-less theme must null it
    // out under a finger that is already down.
    val burst = rememberUpdatedState(onBurst)
    // The key's place in the compose root, for the overlay to position against.
    val keyBounds = remember { mutableStateOf(Rect.Zero) }

    // The popups' own colours; the key's face is already resolved in [visual].
    val kb = LocalKbTheme.current
    // The theme's key textures. A static local, changing only on a theme
    // switch — reading it here adds nothing to the press path.
    val textures = LocalKeyTextures.current
    // The gap is handed to the shape as the room a leaning outline may spill
    // into: a slanted key then leans across the gap rather than out of its own
    // width, and neighbouring keys interlock instead of thinning out.
    val keyShape = kb.keyShape(bleedDp = keyGapH(settings).value, kind = visual.shapeKind)
    // A key the theme gave its own shape re-runs the shadow guard for that
    // shape: a round enter key may cast one on a board whose own shape cannot.
    val keyElevation = visual.shapeKind
        ?.let { elevationFor(it, kb.keyElevation) }
        ?: kb.keyElevation

    // Outer box = full grid cell and the touch target; inner box = the
    // visible key, inset by the gap. Presses in the gap between keys land
    // on whichever cell they fall in, so there are no dead zones.

    // Tremor filter: drop a second contact on the same key that lands
    // within the debounce window. Scoped per key, so alternating keys
    // (typing "aa" vs "ab") are never affected — only a bouncing repeat is.
    val debounceMs = rememberUpdatedState(settings.accessibility.keyDebounceMs)
    val gate = remember { KeyDebounceGate() }
    val debounced: (Key) -> Unit = remember(onKey, gate) {
        { pressedKey -> if (gate.accepted) onKey(pressedKey) }
    }
    // The buzz and the click are spent on contact, before the key ever commits,
    // so a discarded press has to be silenced there too — a filter that still
    // buzzes for every dropped tap feels exactly like no filter at all. Only
    // the press's own feedback is muted: the long-press cue and the repeat
    // ticks under the same finger land past the window and ring normally.
    //
    // The role is bound once, here, rather than threaded further down: the
    // spacebar's swipe handler and the delete key's repeat tick both take these
    // lambdas as plain `() -> Unit` parameters, so binding at the top means the
    // held-repeat on backspace is already a delete-role sound with nothing else
    // to change.
    val soundRole = key.keySoundRole()
    val onKeyPress: () -> Unit = remember(rawKeyPress, gate, soundRole) {
        { if (gate.audible()) rawKeyPress(soundRole) }
    }
    val onKeySound: () -> Unit = remember(rawKeySound, gate, soundRole) {
        { if (gate.audible()) rawKeySound(soundRole, KeySoundPhase.PRESS) }
    }
    // The finger leaving. Gated on the same window as the press, and for a
    // sharper reason: a contact the tremor filter dropped is a bounce, and a
    // bounce lifts again within a millisecond or two — still inside the window.
    // Ungated, that lift would play a key coming back up that was never heard
    // going down, which is the one artefact the filter exists to prevent.
    val onKeyRelease: () -> Unit = remember(rawKeySound, gate, soundRole) {
        { if (gate.audible()) rawKeySound(soundRole, KeySoundPhase.RELEASE) }
    }

    // Under an explore-by-touch service the accessibility framework owns the
    // touch stream, so the custom press/long-press/swipe detector never sees
    // a coherent gesture. Hand the key over to semantics instead: TalkBack
    // announces on hover and commits on the activation tap.
    val touchExploration = LocalTouchExploration.current
    val screenReaderKeys = settings.accessibility.screenReader != ScreenReaderMode.OFF
    // Pass-through mode keeps the keyboard's own detector under a screen
    // reader — the touches really do arrive, because the app's accessibility
    // service carves this window out of touch exploration. Without that
    // service granted there is no carve-out, so it degrades to EXPLORE rather
    // than to a keyboard that types on contact and says nothing.
    val passthrough = touchExploration &&
        settings.accessibility.screenReader == ScreenReaderMode.PASSTHROUGH &&
        LocalPassthroughService.current
    val semanticsDriven = touchExploration && when (settings.accessibility.screenReader) {
        ScreenReaderMode.EXPLORE -> true
        ScreenReaderMode.PASSTHROUGH -> !passthrough
        else -> false
    }
    val label = visual.spoken.resolved()
    // Hoisted: the semantics block below is not a composable scope. Gated
    // because only the semantics-driven branch reads it, and formatting it
    // otherwise meant a Resources.getString with an argument — per key, per
    // grid build — for a string nobody was going to speak. Calling a
    // @ReadOnlyComposable conditionally is safe; it opens no group.
    val typeAction =
        if (semanticsDriven) stringResource(R.string.ime_key_type_action, label) else ""
    // The floating word this key is offering (discussion #102). Read only when
    // something will speak it — a board with no screen reader takes out no
    // subscription and pays nothing, the way [typeAction] already does. The
    // word cannot come through [KeyVisual]: it changes on every keystroke, and
    // a key that read it there would cost the whole board its skip.
    val octopusWord = if (screenReaderKeys) {
        LocalOctopusWords.current.value.top(key.glideAnchor() ?: -1)?.word
    } else {
        null
    }
    val octopusOffer = octopusWord
        ?.let { stringResource(R.string.ime_key_octopus_offer, it) }
        .orEmpty()
    val octopusAction = octopusWord
        ?.let { stringResource(R.string.ime_key_octopus_action, it) }
        .orEmpty()
    val octopusPick = LocalOctopusPick.current
    // Nothing announces the keys once the window is passed through — TalkBack
    // no longer sees the touches that would make it speak. The keyboard says
    // the key itself on press; the press only commits on release, so a key can
    // still be heard before it types.
    val view = LocalView.current
    val announce: (Boolean) -> Unit = remember(passthrough, label, octopusOffer, view) {
        { down ->
            if (passthrough && down) {
                // Nothing announces the keys once the window is passed through,
                // so the offer rides the same announcement the letter does.
                view.announceForAccessibility(
                    if (octopusOffer.isEmpty()) label else "$label, $octopusOffer",
                )
            }
        }
    }

    Box(
        modifier = modifier
            .height((heightDp ?: settings.keyHeightDp).dp + keyGapV(settings) * 2)
            .then(
                if (screenReaderKeys) {
                    Modifier.semantics {
                        contentDescription = label
                        role = Role.Button
                        if (octopusWord != null) {
                            // Hovering the key says the letter, then what it is
                            // offering. A custom action rather than the click:
                            // activating a key still has to mean "type this
                            // letter", whatever is floating above it.
                            stateDescription = octopusOffer
                            customActions = listOf(
                                CustomAccessibilityAction(octopusAction) {
                                    octopusPick(octopusWord, OctopusSource.A11Y)
                                    true
                                },
                            )
                        }
                        if (semanticsDriven) {
                            // No pointer went down here, so the activation has
                            // to open the window itself.
                            onClick(label = typeAction) {
                                gate.press(debounceMs.value)
                                debounced(key)
                                true
                            }
                        }
                    }
                } else {
                    Modifier
                }
            )
            // Beside the pointer handler and before the padding, so it reports the
            // node the pointer positions are measured from and not the smaller
            // face that is drawn. Off entirely when nothing will read it.
            .then(
                if (semanticsDriven || !holdToSelect) Modifier
                else Modifier.onGloballyPositioned {
                    alternatesHold.cell = Rect(it.positionInWindow(), it.size.toSize())
                }
            )
            .then(
                if (semanticsDriven) Modifier
                else Modifier.pointerInputKey(
                    key, settings.longPressDelayMs, settings.keyRepeat, settings.textEditing,
                    spaceShortSwipe = settings.spaceShortSwipe,
                    spaceLongSwipe = settings.spaceLongSwipe,
                    enabledLayoutIds = settings.enabledLayoutIds.ifEmpty { listOf(BuiltInLayouts.DEFAULT_ID) },
                    currentLayoutId = layoutId,
                    setPressed = { down ->
                        // Judged here rather than at the commit: every branch
                        // below reports the contact before it spends anything
                        // on it, which is the one point where a press can still
                        // be dropped silently.
                        if (down) gate.press(debounceMs.value)
                        pressed.value = down
                        alternatesPrewarm[0]?.cancel()
                        val prewarmAt = settings.longPressDelayMs - AlternatesPrewarmLeadMs
                        if (down && prewarmAt >= AlternatesPrewarmFloorMs && key.opensAlternatesPopup()) {
                            alternatesPrewarm[0] = scope.launch {
                                delay(prewarmAt.toLong())
                                alternatesPrepared = true
                            }
                        } else if (!down) {
                            alternatesPrepared = false
                        }
                        announce(down)
                        // The burst spends nothing when off, and rides the same
                        // debounce as the sound: a dropped contact throws no
                        // confetti either.
                        if (down && gate.accepted) {
                            burst.value?.invoke(keyBounds.value, visual.overrideId)
                        }
                        if (down && previewWanted.value) {
                            val bounds = keyBounds.value
                            keyPreview.press(
                                KeyPreview(
                                    token = previewToken,
                                    label = previewLabel.value,
                                    position = bounds.topLeft,
                                    size = IntSize(
                                        bounds.width.roundToInt(),
                                        bounds.height.roundToInt(),
                                    ),
                                    popupBackground = previewColors.value.first,
                                    popupText = previewColors.value.second,
                                ),
                            )
                        } else if (!down) {
                            // Unconditional, unlike the press: the gate can turn
                            // off under a held finger (a field change swapping in
                            // a keypad), and a release that never ran would leave
                            // the bubble owned by a key nobody is touching.
                            keyPreview.release(previewToken)
                        }
                    },
                    onKeyPress = onKeyPress,
                    onKeySound = onKeySound,
                    onKeyRelease = onKeyRelease,
                    vibrateOnSpace = settings.feedback.vibrateOnSpace,
                    vibrateOnDeleteSwipe = settings.feedback.vibrateOnDeleteSwipe,
                    vibrateOnRepeat = settings.feedback.vibrateOnRepeat,
                    soundOnRepeat = settings.feedback.soundOnRepeat,
                    onKeyHaptic = onKeyHaptic,
                    hapticOnLongPress = settings.haptics.onLongPress,
                    hapticOnLongPressRelease = settings.haptics.onLongPressRelease,
                    // The alternates take the bubble's place outright, so it goes
                    // now rather than serving out its minimum duration under them.
                    openAlternates = {
                        showAlternates = true
                        alternatesHold.open()
                        keyPreview.cancel(previewToken)
                    },
                    setFlickDirection = { flickDirection.value = it },
                    onKey = debounced,
                    // Repeat ticks bypass the debounce (raw onKey), taps don't.
                    onKeyRepeat = onKey,
                    onClipboardKey = onClipboardKey,
                    onSelectionHold = onSelectionHold,
                    onCursorMove = onCursorMove,
                    onCursorMoveVertical = onCursorMoveVertical,
                    onCaretDrag = { caretDrag(CaretDragSource.SPACEBAR, it) },
                    onHideKeyboard = onHideKeyboard,
                    spaceCursor2d = settings.layoutBehavior.spaceCursor2d,
                    spaceSwipeDownHide = settings.layoutBehavior.spaceSwipeDownHide,
                    symbolsLongPressNumpad = settings.layoutBehavior.symbolsLongPressNumpad,
                    onLayoutSelect = onLayoutSelect,
                    pickerIsCarousel =
                        settings.layoutBehavior.languagePickerStyle == LanguagePickerStyle.CAROUSEL,
                    pickerForLongRing = settings.layoutBehavior.spaceHoldPickerForLongRing,
                    openLanguagePicker = { pickerDragIndex = null; showLanguagePicker = true },
                    closeLanguagePicker = { showLanguagePicker = false; pickerDragIndex = null },
                    setPickerDragIndex = { pickerDragIndex = it },
                    setLanguagePreview = {
                        if (it != null) languageSwitchEcho.clear()
                        languagePreview = it
                    },
                    echoLanguageSwitch = languageSwitchEcho::show,
                    canDelete = canDelete,
                    canForwardDelete = canForwardDelete,
                    deleteSwipe = deleteSwipe,
                    backspaceSwipeDelete = settings.backspaceSwipeDelete,
                    scope = scope,
                    smartResolve = smartResolve,
                    alternates = alternatesHold.takeIf { holdToSelect },
                )
            )
            .padding(horizontal = keyGapH(settings), vertical = keyGapV(settings))
            // The theme's lift, under the fill and the border so both ride it.
            // Modifier.shadow is a no-op at 0 dp with clip off, so a flat theme
            // pays nothing for this being in the chain; kb.keyElevation is
            // already 0 for a shape or a fill that must not cast one.
            .then(
                if (keyElevation > 0.dp) {
                    Modifier.shadow(keyElevation, keyShape, clip = false)
                } else {
                    Modifier
                }
            )
            // A layer of the key's own, so the draw a press invalidates is this
            // key's and nothing else's. Without one (every theme with no key
            // shadow) the nearest layer was the window's root: each press and
            // each release re-recorded every key's face, label and hint, plus
            // the toolbar and the strip — 2-5 ms of display-list recording per
            // frame on a CPH2481, the largest piece of a typing frame.
            .graphicsLayer()
            // The face and its sheen are painted here rather than by
            // Modifier.background, because both depend on the press: read inside
            // the draw lambda, a press invalidates only the draw, so pressing a
            // key no longer recomposes or re-measures it. The outline and the
            // brush are built in the cache block, which the press does not touch.
            .drawWithCache {
                val outline = keyShape.createOutline(size, layoutDirection, this)
                // A theme with no key shape dresses no resting face, so it gets
                // neither the sheen nor the class texture. The press keeps its
                // colour and its own texture, which is how the key still shows
                // that it was hit.
                val faces = kb.keysHaveFaces
                // Sheen over letter keys only; pressed/enter/modifier states keep
                // their solid colors so state changes stay legible.
                val sheen = kb.keyGradient
                    ?.takeIf { faces && key.action == KeyAction.Text }
                    ?.brush()
                // The theme's texture for this key class, prepared here so the
                // press-path draw below only picks between ready-made values.
                // The clip path and tile brush depend on size/shape alone —
                // the cache block's own invalidation keys.
                val texture = if (faces) textures.forKey(key.action, visual.overrideId) else null
                val texturePaint = texture?.let {
                    KeyTexturePaint.of(it, textures, outline, size)
                }
                val pressedTexture = textures.pressed
                val pressedPaint = pressedTexture?.let {
                    KeyTexturePaint.of(it, textures, outline, size)
                }
                onDrawBehind {
                    val down = pressed.value
                    drawOutline(outline, if (down) visual.pressedBackground else visual.background)
                    val paint = if (down) pressedPaint ?: texturePaint else texturePaint
                    if (paint != null) {
                        paint.draw(this, textures.opacity)
                        // With no pressed texture of its own, the press stays
                        // visible as a tint over the textured face.
                        if (down && pressedPaint == null) {
                            drawOutline(outline, visual.pressedBackground.copy(alpha = 0.5f))
                        }
                    }
                    if (sheen != null && !down) drawOutline(outline, sheen)
                }
            }
            .then(
                // Left as a border modifier: it does not depend on the press, and
                // Modifier.border insets a rounded outline by half the stroke so
                // the whole width lands inside the key — hand-stroking the same
                // outline would straddle the edge and read thinner. A per-key
                // border colour wins over the theme's, and draws at the theme's
                // width or 1.5 dp when the theme has no border of its own. A theme
                // with no key shape draws no border of its own either.
                run {
                    val border = visual.borderColor ?: kb.keyBorder?.takeIf { kb.keysHaveFaces }
                    val width = if (visual.borderColor != null) {
                        maxOf(kb.keyBorderWidthDp, 1.5f)
                    } else {
                        kb.keyBorderWidthDp
                    }
                    if (border != null && width > 0f) {
                        Modifier.border(width.dp, border, keyShape)
                    } else {
                        Modifier
                    }
                }
            )
            .onGloballyPositioned { keyBounds.value = it.boundsInRoot() },
        contentAlignment = Alignment.Center,
    ) {
        KeyLabel(visual, settings, pressed)
        val popupPosition = rememberAboveAnchorPopup()

        if ((showAlternates || alternatesPrepared) && key.opensAlternatesPopup()) {
            // The popup can go away with the finger still down: a second finger
            // switching layer under it, or the board recomposed away. Nothing
            // then delivers the lift, and the board-wide gate would stay raised
            // with glide typing refusing to start. Registered only while the
            // popup is up, so it costs a node on one key rather than on all.
            // Not only for hold-to-select: the tap-a-second-time popup raises
            // the gate on opening too, and its ways out (an entry tapped, a
            // tap outside) never reach the hold, so this is the one place
            // that lowers it for them (#89).
            // Only once it is shown: a prepared popup dropped on a tap never
            // raised the gate, and lowering it then would lower it under a
            // popup another key has open.
            if (showAlternates) {
                DisposableEffect(alternatesHold) {
                    onDispose { alternatesHold.cancel() }
                }
            }
            AlternatesPopup(
                key = key,
                visible = showAlternates,
                popupPosition = popupPosition,
                popup = settings.popup,
                hold = alternatesHold.takeIf { holdToSelect },
                shifted = visual.alternatesShifted,
                onDismiss = { showAlternates = false },
                onText = { text ->
                    showAlternates = false
                    onText(text)
                },
                onAction = { alternateKey ->
                    showAlternates = false
                    onKey(alternateKey)
                },
            )
        }

        KeyFlickPopup(
            key = key,
            fontScale = settings.popup.fontScale,
            alternatesOpen = showAlternates,
            pressed = pressed,
            flickDirection = flickDirection,
        )

        // Tooltip above the spacebar while a swipe is cycling languages: the
        // enabled modes in a row, the live selection highlighted. Capped at a
        // five-chip window sliding with the selection — drawing every enabled
        // layout ran off the screen the moment a handful were enabled.
        shownLanguage?.let { previewMode ->
            val enabledLayoutIds = settings.enabledLayoutIds.ifEmpty { listOf(BuiltInLayouts.DEFAULT_ID) }
            val previewWindow = if (enabledLayoutIds.size <= 5) {
                enabledLayoutIds
            } else {
                val sel = enabledLayoutIds.indexOf(previewMode).coerceAtLeast(0)
                val start = (sel - 2).coerceIn(0, enabledLayoutIds.size - 5)
                enabledLayoutIds.subList(start, start + 5)
            }
            // Five chips still overflow a phone once the labels are long — two
            // layouts of one language both read "Language (Layout)". Squeezed
            // into the window, the Row starved the last chips to no width, the
            // selection vanished into them and a one-glyph-per-line label grew
            // the popup over the whole screen. So the strip scrolls instead,
            // one line per chip, and follows the selection.
            val previewScroll = rememberScrollState()
            val previewChipBounds = remember { mutableStateMapOf<String, Pair<Int, Int>>() }
            var previewViewportWidth by remember { mutableIntStateOf(0) }
            // Opens already centred; every switch after that slides. A jump of a
            // whole chip per switch read as the strip jittering under the finger.
            val previewCentred = remember { mutableStateOf(false) }
            LaunchedEffect(previewMode) {
                val (x, width) = snapshotFlow { previewChipBounds[previewMode] }.filterNotNull().first()
                val viewport = snapshotFlow { previewViewportWidth }.first { it > 0 }
                val target = (x + width / 2 - viewport / 2).coerceIn(0, previewScroll.maxValue)
                if (previewCentred.value) previewScroll.animateScrollTo(target) else previewScroll.scrollTo(target)
                previewCentred.value = true
            }
            Popup(
                popupPositionProvider = popupPosition,
                properties = PreviewPopupProperties,
            ) {
                Surface(
                    shape = kb.popupShape(),
                    color = kb.popup,
                    border = kb.popupSurfaceBorder(),
                    shadowElevation = elevationFor(kb.popupShapeKind, 8.dp),
                ) {
                    Row(
                        modifier = Modifier
                            .onSizeChanged { previewViewportWidth = it.width }
                            .horizontalScroll(previewScroll)
                            .padding(6.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        for (chipLayoutId in previewWindow) {
                            val selected = chipLayoutId == previewMode
                            val label = layoutSwitchLabel(
                                chipLayoutId,
                                enabledLayoutIds,
                                settings.customLayouts,
                                settings.layoutBehavior.spacebarDisplay,
                            )
                            val chipFontSize = (14 * settings.popup.fontScale).sp
                            Box(
                                contentAlignment = Alignment.Center,
                                modifier = Modifier
                                    .onPlaced {
                                        previewChipBounds[chipLayoutId] =
                                            it.positionInParent().x.roundToInt() to it.size.width
                                    }
                                    .padding(horizontal = 2.dp)
                                    .background(
                                        if (selected) kb.pressedKey else Color.Transparent,
                                        RoundedCornerShape(kb.popupRadiusDp.dp),
                                    )
                                    .padding(horizontal = 10.dp, vertical = 8.dp),
                            ) {
                                // Every chip holds its semibold width, so the
                                // selection's weight change never reflows the
                                // strip and nudges the chips beside it.
                                Text(
                                    text = label,
                                    maxLines = 1,
                                    softWrap = false,
                                    fontSize = chipFontSize,
                                    fontWeight = FontWeight.SemiBold,
                                    color = Color.Transparent,
                                )
                                Text(
                                    text = label,
                                    maxLines = 1,
                                    softWrap = false,
                                    fontSize = chipFontSize,
                                    fontWeight = if (selected) FontWeight.SemiBold else FontWeight.Normal,
                                    color = if (selected) kb.popupText else kb.popupText.copy(alpha = 0.45f),
                                )
                            }
                        }
                    }
                }
            }
        }

        if (showLanguagePicker) {
            val pickerIds = settings.enabledLayoutIds.ifEmpty { listOf(BuiltInLayouts.DEFAULT_ID) }
            val onPick: (String) -> Unit = {
                showLanguagePicker = false
                pickerDragIndex = null
                if (it != layoutId) onLayoutSelect(it)
            }
            // Routed through the key dispatch rather than a callback of its
            // own: the service already answers this action for a key bound
            // to it, and KeyboardScreen cannot take another parameter.
            val onOtherKeyboards = {
                showLanguagePicker = false
                pickerDragIndex = null
                onKey(Key(label = "", action = KeyAction.InputMethodPicker))
            }
            val onDismiss = { showLanguagePicker = false; pickerDragIndex = null }
            when (settings.layoutBehavior.languagePickerStyle) {
                LanguagePickerStyle.LIST -> LanguagePickerPopup(
                    popupPosition = popupPosition,
                    enabledLayoutIds = pickerIds,
                    currentLayoutId = layoutId,
                    customLayouts = settings.customLayouts,
                    displayMode = settings.layoutBehavior.spacebarDisplay,
                    highlightIndex = pickerDragIndex,
                    onPick = onPick,
                    onOtherKeyboards = onOtherKeyboards,
                    onDismiss = onDismiss,
                )
                LanguagePickerStyle.CAROUSEL -> LanguageCarouselPopup(
                    popupPosition = popupPosition,
                    enabledLayoutIds = pickerIds,
                    currentLayoutId = layoutId,
                    customLayouts = settings.customLayouts,
                    displayMode = settings.layoutBehavior.spacebarDisplay,
                    highlightIndex = pickerDragIndex,
                    onPick = onPick,
                    onOtherKeyboards = onOtherKeyboards,
                    onDismiss = onDismiss,
                )
            }
        }
    }
}

/**
 * A press and hold that has an alternates popup open under it, so the finger
 * that opened the popup keeps choosing inside it: the first entry is highlighted
 * as the popup appears, sliding the finger moves the highlight, and the lift
 * commits whatever is highlighted. That is what a press and hold does on every
 * other keyboard, and without it a hold that ended on the key typed nothing at
 * all — the popup waited for a second, separate tap.
 *
 * The geometry is the awkward half. A popup is a window of its own, so nothing
 * it lays out shares a coordinate space with the pointer events, which arrive in
 * the key's. Both ends are converted into the *keyboard window*, and no screen
 * or View coordinate is involved (which is what keeps a floating, split or
 * one-handed board honest): [popupOffset] is what the position provider hands
 * the popup and Compose defines it in exactly those coordinates, [gridOffset] is
 * where the grid sits inside the popup, [rects] where each entry sits inside the
 * grid, and [cell] is the key's own touch cell.
 *
 * Every field but [selected] is a plain var written from a layout callback: they
 * are read only while a finger is down, and making them state would recompose
 * the popup as a consequence of measuring it. [selected] is read in the draw
 * phase alone, so moving the highlight repaints the popup and never recomposes
 * it.
 *
 * One instance per key, remembered beside the popup's own visibility flag. Null
 * is passed to the gesture handlers instead when the behaviour is switched off
 * ([KeyPopupSettings.alternatesHoldToSelect]), which is also what puts the old
 * tap-a-second-time popup back.
 */
internal class AlternatesHold(
    /** The board-wide flag this hold raises while it owns its finger. */
    private val gate: AlternatesGate = AlternatesGate(),
) {
    /** Where the popup window sits in the keyboard window. */
    var popupOffset: IntOffset = IntOffset.Zero

    /** Where the grid sits in the popup window: the surface's padding, mostly. */
    var gridOffset: Offset = Offset.Zero

    /** Each entry's rect within the grid, in popup order: characters, then actions. */
    var rects: List<Rect> = emptyList()

    /** The key's touch cell in the keyboard window; the pointer's origin. */
    var cell: Rect = Rect.Zero

    /** Where the finger was when the popup opened, and whether it has left yet. */
    private var anchor: Offset? = null
    private var steering = false

    /** The entry under the finger, or -1 for none — a lift then commits nothing. */
    val selected = mutableIntStateOf(-1)

    /**
     * Commits entry `index` of the open popup, or dismisses it for -1. Assigned
     * by the key each composition rather than passed in, so the gesture handlers
     * take one parameter for all of this and the lambda can close over the key
     * as it is now.
     */
    var onCommit: (Int) -> Unit = {}

    /** The popup has just opened under this finger: pre-select the first entry. */
    fun open() {
        // Not the rects: a popup prepared ahead of the long press has already
        // been laid out and reported them, and nothing would report them again.
        // The popup clears them itself when it goes.
        selected.intValue = 0
        anchor = null
        steering = false
        gate.open = true
    }

    /**
     * The finger moved; [local] is in the key's own coordinates.
     *
     * The pre-selection survives until the finger has actually gone somewhere
     * ([steerPx] from where the popup found it). Without that the first jitter
     * hands the choice to whichever entry happens to be above the finger, and on
     * a centred popup that is the middle one, not the first: a hold and release
     * would type a different character depending on how still the hand was.
     * Once the finger has left, it steers for the rest of the gesture.
     */
    fun moveTo(local: Offset, reachPx: Float, steerPx: Float) {
        val start = anchor ?: local.also { anchor = it }
        if (!steering) {
            if ((local - start).getDistance() < steerPx) return
            steering = true
        }
        selected.intValue = indexAt(local, reachPx)
    }

    /** Commits what the finger is on and clears the highlight. */
    fun commit() {
        val index = selected.intValue
        selected.intValue = -1
        gate.open = false
        onCommit(index)
    }

    /** The gesture ended without choosing (a stolen pointer, or the key gone). */
    fun cancel() {
        selected.intValue = -1
        gate.open = false
    }

    /**
     * The entry a finger at [local] is choosing, or -1 for none.
     *
     * An exact hit wins. Otherwise the nearest entry still counts, as long as
     * the finger is somewhere over the popup, over the key that opened it, or
     * within [slopPx] of either: the popup opens directly above the key, so a
     * natural hold spends its whole life in the gap between them and a finger
     * resting on the key must still be choosing the entry it pre-selected.
     * Further out than that is a deliberate move away, and cancels.
     *
     * With no rects yet — the popup opened this frame and has not been measured
     * — the answer is the first entry, which is what was pre-selected.
     */
    fun indexAt(local: Offset, slopPx: Float): Int {
        val entries = rects
        if (entries.isEmpty()) return 0
        val origin = Offset(popupOffset.x + gridOffset.x, popupOffset.y + gridOffset.y)
        val point = cell.topLeft + local
        var best = -1
        var bestDistance = Float.MAX_VALUE
        // The popup's own bounds, grown entry by entry: Rect has no union.
        var left = cell.left
        var top = cell.top
        var right = cell.right
        var bottom = cell.bottom
        for ((index, rect) in entries.withIndex()) {
            val entry = rect.translate(origin)
            left = minOf(left, entry.left)
            top = minOf(top, entry.top)
            right = max(right, entry.right)
            bottom = max(bottom, entry.bottom)
            val dx = max(max(entry.left - point.x, 0f), point.x - entry.right)
            val dy = max(max(entry.top - point.y, 0f), point.y - entry.bottom)
            val distance = dx * dx + dy * dy
            if (distance < bestDistance) {
                bestDistance = distance
                best = index
            }
        }
        if (bestDistance == 0f) return best
        val reachable = Rect(left, top, right, bottom).inflate(slopPx)
        return if (reachable.contains(point)) best else -1
    }
}

/** How far outside the popup and its key a finger may stray and still be choosing. */
private val AlternatesReachDp = 24.dp

/** How far the finger travels before it steers the popup instead of holding still. */
private val AlternatesSteerDp = 12.dp

/**
 * How far a finger may drift and still count as holding one key still during a
 * layer peek (issue #108), which is what opens that key's alternates. A finger
 * resting on glass is never perfectly still, and a slow drift across a key must
 * not read as a hold that never ends.
 */
private val LayerDragStillDp = 12.dp

/**
 * The long-press alternates: the key's characters, then the entries that run an
 * action rather than typing (issue #21).
 *
 * Wrapped rather than the single [Row] this was, because a single row is only as
 * wide as the screen by luck. A letter key with every accent merged in (the
 * "All accents on press and hold" setting does exactly that), or an ordinary one
 * at a raised popup font size, ran off the right-hand edge and took its last few
 * alternates with it — the popup is positioned by clamping *its* left edge into
 * the window, so what overflows is unreachable rather than merely ugly (issue
 * #20). Wrapping keeps every entry on screen and costs a popup that already fits
 * nothing: one wrapped line measures exactly as the Row did.
 *
 * [AlternatesGrid] rather than the [FlowRow] that first did the wrapping, because
 * two of the three things issue #64 asks of this popup are outside what a FlowRow
 * can be asked: a fixed column count, and a fill that starts on the row nearest
 * the key. Its automatic mode packs each line exactly as the FlowRow did.
 *
 * The scroll is a backstop, not the feature. It engages only past
 * [MaxPopupHeightFraction] of the display — some dozens of entries at the default
 * size, which no shipped layout comes near — and exists so a pathological popup
 * is scrollable rather than growing off the top of the screen.
 */
@Composable
private fun AlternatesPopup(
    key: Key,
    /**
     * False while the popup is prepared ahead of the long press: composed,
     * laid out and drawn in a window of its own, but transparent and letting
     * every touch through to the keyboard beneath.
     */
    visible: Boolean = true,
    popupPosition: PopupPositionProvider,
    popup: KeyPopupSettings,
    onDismiss: () -> Unit,
    onText: (String) -> Unit,
    /** An action alternate, as the key the service dispatches for it. */
    onAction: (Key) -> Unit,
    /** The finger still steering this popup, or null when hold-to-select is off. */
    hold: AlternatesHold?,
    /**
     * Shift will capitalise whatever is picked ([shiftCasesText]), so the
     * characters draw as the capitals they type. Only the drawing: the entry
     * still hands back its own text and the key output applies the case, the
     * way it does for every key.
     */
    shifted: Boolean = false,
) {
    val kb = LocalKbTheme.current
    val configuration = LocalConfiguration.current
    val fontScale = popup.alternatesFontScale
    val entryPadding = popup.alternatesPaddingDp.dp
    // The widest the wrap is allowed to grow: the display, less a margin at each
    // edge. Measured against the display rather than the keyboard because the
    // popup is a window of its own — it is free to be wider than a one-handed or
    // floating board, and stopping it at the board's width would wrap popups
    // that had room to spare.
    val maxWidth = (configuration.screenWidthDp - PopupSideMarginDp * 2).dp
    val maxHeight = (configuration.screenHeightDp * MaxPopupHeightFraction).dp
    // Where the popup lands is decided here and nowhere else, and Compose states
    // it in the anchor's own window coordinates — which is exactly the space the
    // hold-drag needs the entries in. So the provider is wrapped rather than the
    // arithmetic being repeated on the other side, where it would go quietly
    // stale the first time the clamping changed.
    //
    // The wrap also keeps the side margin the width budget above set aside. The
    // anchor's provider only keeps the popup on the display, so a popup as wide
    // as that budget, over a key right of centre (the spacebar), sat flush
    // against the right edge with twice the margin on the left (#298).
    val marginPx = with(LocalDensity.current) { PopupSideMarginDp.dp.roundToPx() }
    // The centre of the key the popup belongs to, in the popup's own space: the
    // point it grows out of. The provider is the one place that knows both the
    // key's bounds and where it put the popup, in the same coordinates, so it
    // records the point as it places the window, before the first frame draws.
    val growPivot = remember { mutableStateOf<Offset?>(null) }
    val provider = remember(popupPosition, hold, marginPx) {
        object : PopupPositionProvider {
            override fun calculatePosition(
                anchorBounds: IntRect,
                windowSize: IntSize,
                layoutDirection: LayoutDirection,
                popupContentSize: IntSize,
            ): IntOffset {
                val at = popupPosition
                    .calculatePosition(anchorBounds, windowSize, layoutDirection, popupContentSize)
                val x = alternatesPopupX(at.x, windowSize.width - popupContentSize.width, marginPx)
                val key = anchorBounds.center
                growPivot.value = Offset((key.x - x).toFloat(), (key.y - at.y).toFloat())
                return IntOffset(x, at.y).also { hold?.popupOffset = it }
            }
        }
    }
    // Opens out of the key it was held on and settles, rather than appearing at
    // full size in one step. Nothing waits for it: the first frame is fully
    // opaque, and every entry is already laid out where it will be.
    // Started when the popup is shown rather than when it is composed: a
    // prepared popup would otherwise have grown out of sight.
    val grow = remember { Animatable(if (kb.reduceMotion) 1f else AlternatesGrowFrom) }
    LaunchedEffect(grow, visible) {
        if (visible) grow.animateTo(1f, tween(AlternatesGrowMs, easing = FastOutSlowInEasing))
    }
    DisposableEffect(hold) {
        onDispose { hold?.rects = emptyList() }
    }
    val shown by rememberUpdatedState(visible)
    // Hidden, the window takes no touches at all: a second finger landing where
    // the popup will be belongs to the keyboard until it is shown. Changing that
    // is a window relayout (~8 ms on a mid-range phone), so it waits one frame
    // behind showing: the frame that reveals the popup only repaints it, and
    // nothing can reach for a popup in the frame before it is on screen.
    var touchable by remember { mutableStateOf(visible) }
    LaunchedEffect(visible) {
        if (visible) withFrameNanos {}
        touchable = visible
    }
    Popup(
        popupPositionProvider = provider,
        onDismissRequest = onDismiss,
        properties = if (touchable) AlternatesShownProperties else AlternatesHiddenProperties,
    ) {
        Surface(
            // A scale at draw time, never a transform in the layer: the
            // hold-drag reads the grid's window position and its entries'
            // laid-out rects, and a layer transform would shift both for as
            // long as the popup was growing. The layer's alpha moves nothing.
            modifier = Modifier
                .graphicsLayer { alpha = if (shown) 1f else 0f }
                .growFrom(pivot = { growPivot.value }) { grow.value },
            shape = kb.popupShape(),
            color = kb.popup,
            border = kb.popupSurfaceBorder(),
            shadowElevation = elevationFor(kb.popupShapeKind, 8.dp),
        ) {
            AlternatesGrid(
                // The key's own count wins, and 0 there means it has none of its
                // own rather than "wrap": a key set to 5 keeps 5 whatever the
                // setting says, and every other key follows the setting.
                columns = key.alternateColumns.takeIf { it > 0 } ?: popup.alternatesColumns,
                nearestFirst = popup.alternatesNearestFirst,
                onRects = hold?.let { { rects: List<Rect> -> it.rects = rects } },
                modifier = Modifier
                    .widthIn(max = maxWidth)
                    .heightIn(max = maxHeight)
                    .verticalScroll(rememberScrollState())
                    // Inside the scroll, so a scrolled popup reports where its
                    // entries are now rather than where they started.
                    .onGloballyPositioned { hold?.gridOffset = it.positionInWindow() }
                    .padding(4.dp),
            ) {
                // One list, so the drawn order and the index the hold commits
                // are the same statement rather than two that have to agree.
                key.alternateEntries().forEachIndexed { index, entry ->
                    when (entry) {
                        is AlternateEntry.Character -> Text(
                            text = shiftCased(entry.text, shifted),
                            modifier = Modifier
                                .clickable { onText(entry.text) }
                                .alternateHighlight(
                                    index, hold, kb.pressedKey, kb.popupRadiusDp.dp,
                                )
                                .alternatePadding(entryPadding),
                            fontSize = (18 * fontScale).sp,
                            color = kb.popupText,
                        )
                        is AlternateEntry.Action -> AlternateAction(
                            alternate = entry.alternate,
                            fontScale = fontScale,
                            padding = entryPadding,
                            tint = kb.popupText,
                            modifier = Modifier.alternateHighlight(
                                index = index,
                                hold = hold,
                                color = kb.pressedKey,
                                radius = kb.popupRadiusDp.dp,
                            ),
                        ) {
                            onAction(
                                Key(
                                    label = entry.alternate.label,
                                    action = entry.alternate.action,
                                ),
                            )
                        }
                    }
                }
            }
        }
    }
}

/** The size the alternates popup opens at, as a share of its own. */
private const val AlternatesGrowFrom = 0.6f

/** How long the alternates popup takes to grow out of its key. */
private const val AlternatesGrowMs = 140

/**
 * How long before the long press fires its popup starts being built, hidden.
 * Enough for the window's first relayout and draw on a slow phone; short
 * enough that an ordinary tap has lifted long before.
 */
private const val AlternatesPrewarmLeadMs = 100

/**
 * The earliest into a press the prewarm may start. Below it (a long-press
 * delay set very short) ordinary taps would be building and throwing away
 * popups, so the popup is built when the long press fires, as before.
 */
private const val AlternatesPrewarmFloorMs = 120

/** The alternates popup's window as Compose's defaults make it. */
private val AlternatesShownProperties = PopupProperties()

/**
 * The same window while prepared: not touchable (touches fall through to the
 * keyboard) and not watching outside touches, which would dismiss it.
 */
private val AlternatesHiddenProperties = PopupProperties(
    flags = WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
        WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,
    inheritSecurePolicy = true,
    dismissOnBackPress = true,
    dismissOnClickOutside = true,
    excludeFromSystemGesture = true,
    usePlatformDefaultWidth = false,
)

/**
 * Draws the content scaled by [scale] about [pivot], the point it grows out of
 * (the popup's own key, which may lie outside its bounds; the bottom centre
 * until that is known). Paint only: layout and every coordinate read from it
 * stay at full size, which a popup that is being steered by a finger needs.
 */
private fun Modifier.growFrom(pivot: () -> Offset?, scale: () -> Float): Modifier = drawWithContent {
    val s = scale()
    if (s >= 1f) {
        drawContent()
    } else {
        val at = pivot() ?: Offset(size.width / 2f, size.height)
        scale(s, s, pivot = at) {
            this@drawWithContent.drawContent()
        }
    }
}

/**
 * The alternates, laid out in rows.
 *
 * [columns] is the key's own [Key.alternateColumns] where it has one and the
 * global setting otherwise; the popup only sees the resolved number.
 *
 * [columns] of 0 wraps on measured width — an entry starts a new row when it
 * would not fit on this one — which is the [FlowRow] behaviour this replaced,
 * down to centring a part-full row under the ones it shares the popup with. Any
 * other value is a fixed column count: every entry takes the width of the widest,
 * so the columns line up down the popup, and a part-full row keeps its place on
 * that grid rather than being centred off it. The count is a ceiling rather than
 * a promise: when the display cannot fit that many of the widest glyph across,
 * the grid lays out as many as it can ([fittedAlternateColumns]).
 *
 * [nearestFirst] flips which end of the popup the first entry lands on. Off, the
 * rows are placed in order and the popup fills like a paragraph — first entry
 * top left, and on a tall popup that is the corner furthest from the finger. On,
 * the rows are placed bottom upward, so the first entry is on the row nearest the
 * key and the overflow climbs away from it (issue #64). Neither changes the order
 * inside a row, and neither is visible at all on a popup of one row.
 */
@Composable
private fun AlternatesGrid(
    columns: Int,
    nearestFirst: Boolean,
    /**
     * Called with every entry's rect inside the grid, in content order, each
     * time the grid is placed. This is the only place those rects exist: the
     * packing decides them, and a hold-drag needs them to say which entry a
     * finger in another window is on. Null when nothing is dragging.
     */
    onRects: ((List<Rect>) -> Unit)?,
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit,
) {
    Layout(content = content, modifier = modifier) { measurables, constraints ->
        val bounded = constraints.maxWidth != Constraints.Infinity
        val limit = if (bounded) constraints.maxWidth else Int.MAX_VALUE
        // A fixed-column entry is measured against its share of the width rather
        // than the whole of it, so a long one wraps inside its cell instead of
        // pushing the grid off the screen. Only down to its longest unbreakable
        // run, though: squeezed past that, an emoji still draws at full width,
        // spilling out of its cell to the right while the finger is matched
        // against the cell (#298). So a count that cannot hold every entry's
        // glyph drops to one that can. The entries' side padding has already
        // given way by then ([alternatePadding]), which is why the width asked
        // of them here is the glyph's alone.
        val fitted = if (columns > 0) {
            val floor = measurables.maxOfOrNull { it.minIntrinsicWidth(Constraints.Infinity) } ?: 0
            fittedAlternateColumns(columns, floor, limit)
        } else {
            columns
        }
        val cell = if (fitted > 0) (limit / fitted).coerceAtLeast(1) else limit
        val placeables = measurables.map { it.measure(Constraints(maxWidth = cell)) }
        var taken = 0
        val rows = alternateRowSizes(placeables.map { it.width }, fitted, limit).map { count ->
            placeables.subList(taken, taken + count).also { taken += count }
        }
        val heights = rows.map { row -> row.maxOfOrNull { it.height } ?: 0 }
        val cellWidth = (placeables.maxOfOrNull { it.width } ?: 0).coerceAtMost(cell)
        val widest = if (fitted > 0) {
            cellWidth * minOf(fitted, placeables.size)
        } else {
            rows.maxOfOrNull { row -> row.sumOf { it.width } } ?: 0
        }
        val width = widest.coerceAtMost(limit).coerceAtLeast(constraints.minWidth)
        val height = heights.sum().coerceAtLeast(constraints.minHeight)
        layout(width, height) {
            // Content order, not placement order: nearestFirst places the rows
            // bottom upward, and the caller counts entries the way it wrote them.
            val bounds = arrayOfNulls<Rect>(placeables.size)
            var placed = 0
            var y = 0
            for (index in if (nearestFirst) rows.indices.reversed() else rows.indices) {
                val row = rows[index]
                val rowHeight = heights[index]
                var x = if (fitted > 0) 0 else (width - row.sumOf { it.width }) / 2
                // Where this row starts in the content, which is what the rows
                // were cut from and so is the sum of every earlier row's size.
                var slot = rows.take(index).sumOf { it.size }
                for (placeable in row) {
                    val lane = if (fitted > 0) cellWidth else placeable.width
                    val left = x + (lane - placeable.width) / 2
                    val top = y + (rowHeight - placeable.height) / 2
                    placeable.place(left, top)
                    bounds[slot] = Rect(
                        left.toFloat(),
                        top.toFloat(),
                        (left + placeable.width).toFloat(),
                        (top + placeable.height).toFloat(),
                    )
                    slot++
                    placed++
                    x += lane
                }
                y += rowHeight
            }
            if (onRects != null && placed == placeables.size) {
                onRects(bounds.map { it ?: Rect.Zero })
            }
        }
    }
}

/**
 * How the alternates divide into rows: the number of entries on each, in the
 * order they were given, top row first.
 *
 * Split out from [AlternatesGrid] to be a plain function over the measured
 * widths — the packing is the part with the off-by-one in it, and this way it can
 * be tested without a composition.
 */
internal fun alternateRowSizes(widths: List<Int>, columns: Int, limit: Int): List<Int> {
    if (widths.isEmpty()) return emptyList()
    if (columns > 0) {
        val rows = ArrayList<Int>()
        var left = widths.size
        while (left > 0) {
            rows += minOf(columns, left)
            left -= columns
        }
        return rows
    }
    val rows = ArrayList<Int>()
    var count = 0
    var used = 0
    for (width in widths) {
        // An entry wider than the whole popup still gets a row of its own rather
        // than an empty one above it, which is what the `count > 0` guard buys.
        if (count > 0 && used + width > limit) {
            rows += count
            count = 0
            used = 0
        }
        count++
        used += width
    }
    if (count > 0) rows += count
    return rows
}

/**
 * The column count [AlternatesGrid] actually lays out: the one asked for, or
 * fewer when a share of [limit] that small is narrower than [floor], the widest
 * any entry can be squeezed to. Never below one column. [columns] of 0 is the
 * automatic wrap and passes through untouched.
 */
internal fun fittedAlternateColumns(columns: Int, floor: Int, limit: Int): Int =
    if (columns <= 0 || floor <= 0) {
        columns
    } else {
        columns.coerceAtMost((limit / floor).coerceAtLeast(1))
    }

/**
 * How much of [padding] each side of an alternate keeps when the entry is
 * offered [maxWidth] and its content cannot go narrower than [content]: all of
 * it while there is room, then an equal share of what is left, down to none.
 */
internal fun alternateSidePadding(maxWidth: Int, content: Int, padding: Int): Int =
    ((maxWidth - content) / 2).coerceIn(0, padding)

/**
 * Where the alternates popup's left edge goes: [x] as the anchor's provider
 * placed it, held [margin] clear of both sides of the display. [room] is the
 * display's width less the popup's. A popup too wide for both margins is
 * centred instead, which is still the most room it can have on each side.
 */
internal fun alternatesPopupX(x: Int, room: Int, margin: Int): Int =
    if (room >= margin * 2) x.coerceIn(margin, room - margin) else (room / 2).coerceAtLeast(0)

/**
 * An alternate's padding, whose sides give way before its content does.
 *
 * The padding is both the gap between entries and their touch target
 * ([KeyPopupSettings.alternatesPaddingDp]), and a fixed column count
 * ([AlternatesGrid]) can offer an entry less than its glyph plus both sides.
 * Plain padding keeps its sides and hands the squeeze to the text, but an emoji
 * cannot wrap: it drew at full width from the left inset, off-centre in its cell
 * and out past it (#298). Here the sides shrink evenly to what the content's
 * longest unbreakable run leaves, so the glyph stays whole and centred, and the
 * cell the hold-drag matches the finger against is the cell the glyph is in.
 * Top and bottom keep the full padding; nothing squeezes a row's height.
 *
 * For the same reason the entry's minimum intrinsic width is its content's alone:
 * the sides can go to nothing, and that is the width [AlternatesGrid] fits its
 * column count to.
 */
private fun Modifier.alternatePadding(padding: Dp): Modifier = this then AlternatePaddingElement(padding)

private data class AlternatePaddingElement(val padding: Dp) : ModifierNodeElement<AlternatePaddingNode>() {
    override fun create() = AlternatePaddingNode(padding)

    override fun update(node: AlternatePaddingNode) {
        node.padding = padding
    }
}

private class AlternatePaddingNode(var padding: Dp) : Modifier.Node(), LayoutModifierNode {
    override fun MeasureScope.measure(measurable: Measurable, constraints: Constraints): MeasureResult {
        val pad = padding.roundToPx()
        val side = if (constraints.hasBoundedWidth) {
            alternateSidePadding(constraints.maxWidth, measurable.minIntrinsicWidth(constraints.maxHeight), pad)
        } else {
            pad
        }
        val placeable = measurable.measure(constraints.offset(-side * 2, -pad * 2))
        return layout(
            constraints.constrainWidth(placeable.width + side * 2),
            constraints.constrainHeight(placeable.height + pad * 2),
        ) {
            placeable.place(side, pad)
        }
    }

    override fun IntrinsicMeasureScope.minIntrinsicWidth(measurable: IntrinsicMeasurable, height: Int): Int =
        measurable.minIntrinsicWidth(height)

    override fun IntrinsicMeasureScope.maxIntrinsicWidth(measurable: IntrinsicMeasurable, height: Int): Int =
        measurable.maxIntrinsicWidth(height) + padding.roundToPx() * 2

    override fun IntrinsicMeasureScope.minIntrinsicHeight(measurable: IntrinsicMeasurable, width: Int): Int =
        measurable.minIntrinsicHeight(width) + padding.roundToPx() * 2

    override fun IntrinsicMeasureScope.maxIntrinsicHeight(measurable: IntrinsicMeasurable, width: Int): Int =
        measurable.maxIntrinsicHeight(width) + padding.roundToPx() * 2
}

/**
 * One action entry of the alternates popup: the tool's own icon, a named icon,
 * or the action's glyph — in that order, which is the order that answers "what
 * will this do" fastest.
 *
 * A tool wears the icon it wears on the toolbar, resolved through the slot
 * registry so an icon pack redresses it here too.
 */
@Composable
private fun AlternateAction(
    alternate: KeyAlternate,
    fontScale: Float,
    padding: Dp,
    tint: Color,
    modifier: Modifier = Modifier,
    onClick: () -> Unit,
) {
    val action = alternate.action
    val tool = (action as? KeyAction.Tool)?.tool
    val editOp = (action as? KeyAction.Edit)?.op
    // The icon slot an action draws from on the board, so an alternate wears
    // the same face the key would (#156). `fallbackLabel` returns "" for every
    // one of these — on the board their icon branches run first — and a popup
    // entry drawing "" was a blank cell the colour of the popup: a "switch
    // layout" alternate read as a black square. Text keeps the author's label
    // when one was written; the slot is only for an unlabelled entry.
    val slot = when (action) {
        KeyAction.Shift -> IconSlots.KEY_SHIFT
        KeyAction.CapsLock -> IconSlots.KEY_SHIFT_LOCK
        KeyAction.Delete -> IconSlots.KEY_BACKSPACE
        KeyAction.ForwardDelete -> IconSlots.KEY_FORWARD_DELETE
        KeyAction.Enter, KeyAction.Newline -> IconSlots.KEY_ENTER
        // The field's action, whose glyph the enter key's swap hands over in
        // `icon` (see [withEnterHoldFor]); a hand-written one gets the return.
        KeyAction.EditorAction -> alternate.icon ?: IconSlots.KEY_ENTER
        KeyAction.LanguageSwitch -> IconSlots.KEY_GLOBE
        KeyAction.InputMethodPicker, is KeyAction.SwitchInputMethod -> IconSlots.KEY_INPUT_METHOD_PICKER
        KeyAction.Emoji -> IconSlots.KEY_EMOJI
        is KeyAction.Tool -> IconSlots.forTool(action.tool)
        else -> null
    }?.takeIf { alternate.label.isBlank() }
    // Named, so both branches below can speak the entry rather than going silent
    // on an icon: the label the author gave it, else the tool's own name, else
    // what the same key on the board would be read out as.
    val spoken = alternate.label.ifBlank {
        tool?.let { toolLabel(it) }
            ?: editOp?.let { stringResource(textEditDescription(it)) }
            ?: (editorActionSpoken(alternate) ?: alternateActionSpoken(action))?.let { stringResource(it) }
            .orEmpty()
    }
    // A text-editing alternate (Page Up on a held Home) draws its operation's
    // icon, exactly as the key it would be on its own.
    val namedIcon = KeyIcons.byName(alternate.icon)
        ?: editOp?.takeIf { alternate.label.isBlank() }?.let { textEditIcon(it) }
    Box(
        modifier = Modifier
            .clickable(onClick = onClick)
            .then(modifier)
            .alternatePadding(padding),
        contentAlignment = Alignment.Center,
    ) {
        when {
            namedIcon != null -> Icon(
                namedIcon,
                contentDescription = spoken.ifBlank { null },
                tint = tint,
                modifier = Modifier.size((20 * fontScale).dp),
            )
            slot != null -> SlotIcon(
                slot,
                contentDescription = spoken.ifBlank { null },
                tint = tint,
                modifier = Modifier.size((20 * fontScale).dp),
            )
            else -> Text(
                // A space alternate has no icon slot and a label of " ", which
                // draws as nothing; the open-box glyph is what keycap
                // legends use for it.
                text = alternate.drawnLabel().ifBlank { AlternateSpaceGlyph },
                fontSize = (18 * fontScale).sp,
                color = tint,
                maxLines = 1,
            )
        }
    }
}

/** What an unlabelled space alternate draws: the keycap legend for the space bar. */
private const val AlternateSpaceGlyph = "␣"

/**
 * The name of a [KeyAction.EditorAction] entry, read off the slot it draws:
 * "Send" rather than "Enter", the same word the enter key itself is read out
 * as in that field ([enterActionSpoken]). Null for any other entry.
 */
private fun editorActionSpoken(alternate: KeyAlternate): Int? =
    if (alternate.action != KeyAction.EditorAction) {
        null
    } else {
        when (alternate.icon) {
            IconSlots.KEY_ENTER_SEARCH -> R.string.ime_enter_search
            IconSlots.KEY_ENTER_SEND -> R.string.ime_enter_send
            IconSlots.KEY_ENTER_GO -> R.string.ime_enter_go
            IconSlots.KEY_ENTER_NEXT -> R.string.ime_enter_next
            IconSlots.KEY_ENTER_PREVIOUS -> R.string.ime_enter_previous
            IconSlots.KEY_ENTER_DONE -> R.string.ime_enter_done
            else -> R.string.ime_enter_default
        }
    }

/**
 * The spoken name of an action alternate that draws from an icon slot — the
 * same string the key on the board is read out as — or null for an action the
 * popup draws as text, which speaks for itself.
 */
private fun alternateActionSpoken(action: KeyAction): Int? = when (action) {
    KeyAction.Shift -> R.string.ime_key_shift
    KeyAction.CapsLock -> R.string.ime_key_caps_lock
    KeyAction.Delete -> R.string.ime_key_delete
    KeyAction.ForwardDelete -> R.string.ime_key_forward_delete
    KeyAction.Enter -> R.string.ime_enter_default
    KeyAction.Newline -> R.string.ime_key_newline
    KeyAction.LanguageSwitch -> R.string.ime_key_language_switch
    KeyAction.InputMethodPicker, is KeyAction.SwitchInputMethod -> R.string.ime_key_input_method_picker
    KeyAction.Emoji -> R.string.ime_key_emoji
    KeyAction.Space -> R.string.ime_key_space
    else -> null
}

/**
 * Paints the hold-drag's highlight behind an alternate.
 *
 * A draw modifier rather than a background: the selection is read in the draw
 * phase, so sliding the finger across a popup of twenty entries repaints it and
 * recomposes nothing. Placed before the entry's padding so the highlight covers
 * the whole touch target rather than only the glyph.
 */
private fun Modifier.alternateHighlight(
    index: Int,
    hold: AlternatesHold?,
    color: Color,
    radius: Dp,
): Modifier = if (hold == null) {
    this
} else {
    drawBehind {
        if (hold.selected.intValue == index) {
            drawRoundRect(color, cornerRadius = CornerRadius(radius.toPx()))
        }
    }
}

/** Clearance the alternates popup keeps from each edge of the display. */
private const val PopupSideMarginDp = 8

/** How much of the display a wrapped alternates popup may fill before it scrolls. */
private const val MaxPopupHeightFraction = 0.6f

/**
 * The key's label, in a restart scope of its own.
 *
 * Enter is the one key whose label colour flips under the finger, and a text
 * colour cannot move to the draw phase the way the key's face did — it is baked
 * into the text layout. So the label gets its own composable: pressing Enter
 * recomposes this and nothing else, instead of the whole key. Every other key
 * reads no press state at all, because the two colours are the same value and
 * the `&&` never gets that far — those keys stay entirely off the press path.
 *
 * The alternative was dropping the Enter recolour outright. Kept because it is
 * the only feedback that key has: its face is already the accent colour, so a
 * press that only swapped the face would barely read.
 */
@Composable
private fun KeyLabel(visual: KeyVisual, settings: KeyboardSettings, pressed: State<Boolean>) {
    val recolours = visual.pressedContentColor != visual.contentColor
    KeyContent(
        visual,
        settings,
        if (recolours && pressed.value) visual.pressedContentColor else visual.contentColor,
    )
}

/**
 * The flick cross a press raises on a kana-pad key: the centre kana with its
 * arms laid out around it, the arm under the finger highlighted. Shown while the
 * key is held, unless the long-press alternates popup took over.
 *
 * Its own restart scope, for the same reason as [KeyLabel] — a Popup is composed
 * content, so unlike the key's face it cannot be moved to the draw phase.
 * Keeping the press read here means a press recomposes this small function
 * rather than [KeyButton]'s body, and only for a key that has flicks at all: the
 * `&&` reaches [pressed] on no other key. The long-press and spacebar popups stay
 * with the key, not being on the per-keystroke path.
 */
@Composable
private fun KeyFlickPopup(
    key: Key,
    fontScale: Float,
    /** The long-press alternates took over, so this is not shown. */
    alternatesOpen: Boolean,
    pressed: State<Boolean>,
    flickDirection: State<FlickDirection?>,
) {
    if (key.flick.isNotEmpty() && !alternatesOpen && pressed.value) {
        Popup(popupPositionProvider = FlickPopupPositionProvider) {
            FlickCrossPopup(key, flickDirection.value, fontScale)
        }
    }
}

/**
 * The flick preview shown while a kana-pad key is held: the centre kana with
 * its defined arms laid out in a plus, the arm the finger is over — or the
 * centre, when [active] is null — highlighted. Only arms the key actually
 * defines are drawn, so a key with two flicks shows two chips, not four blanks.
 */
@Composable
private fun FlickCrossPopup(key: Key, active: FlickDirection?, fontScale: Float) {
    Box(modifier = Modifier.size(148.dp)) {
        FlickCell(key.output ?: key.label, active == null, Alignment.Center, fontScale)
        FlickCell(key.flick[FlickDirection.UP], active == FlickDirection.UP, Alignment.TopCenter, fontScale)
        FlickCell(key.flick[FlickDirection.LEFT], active == FlickDirection.LEFT, Alignment.CenterStart, fontScale)
        FlickCell(key.flick[FlickDirection.RIGHT], active == FlickDirection.RIGHT, Alignment.CenterEnd, fontScale)
        FlickCell(key.flick[FlickDirection.DOWN], active == FlickDirection.DOWN, Alignment.BottomCenter, fontScale)
    }
}

/** One chip of the flick cross: an empty/absent arm draws nothing. */
@Composable
private fun BoxScope.FlickCell(
    text: String?,
    highlighted: Boolean,
    align: Alignment,
    fontScale: Float,
) {
    if (text.isNullOrEmpty()) return
    val kb = LocalKbTheme.current
    Box(
        modifier = Modifier
            .align(align)
            .padding(3.dp)
            .background(
                if (highlighted) kb.popupSelected else kb.popup,
                RoundedCornerShape(kb.popupRadiusDp.dp),
            )
            .padding(horizontal = 12.dp, vertical = 8.dp),
        contentAlignment = Alignment.Center,
    ) {
        Text(
            text = text,
            fontSize = (20 * fontScale).sp,
            color = if (highlighted) kb.popupSelectedText else kb.popupText,
        )
    }
}

/** Centres the flick cross popup on the key it belongs to. */
private object FlickPopupPositionProvider : PopupPositionProvider {
    override fun calculatePosition(
        anchorBounds: IntRect,
        windowSize: IntSize,
        layoutDirection: LayoutDirection,
        popupContentSize: IntSize,
    ): IntOffset {
        val x = anchorBounds.left + (anchorBounds.width - popupContentSize.width) / 2
        val y = anchorBounds.top + (anchorBounds.height - popupContentSize.height) / 2
        return IntOffset(x, y)
    }
}

/**
 * A tappable list of every enabled layout, current one highlighted. Opened by
 * a long-press on the globe key, or a spacebar hold when more than four layouts
 * are enabled or the language swipe is off; picking one switches to it. Rows
 * read like the spacebar (language, with the layout in parentheses when a
 * language has several enabled layouts). Non-focusable like the other key
 * popups so it never steals the edited field's input connection.
 *
 * The last row leaves this keyboard entirely, through [onOtherKeyboards]. It is
 * pinned below the scrolling list rather than being row *n+1* of it, because
 * this is the only place in the keyboard that offers the system picker and a
 * user with eight layouts enabled would have to scroll past all of them to find
 * out it exists. The spacebar hold-drag walks the list by index and so never
 * lands on it, which is the other reason it sits outside the scroller.
 */
@Composable
private fun LanguagePickerPopup(
    popupPosition: PopupPositionProvider,
    enabledLayoutIds: List<String>,
    currentLayoutId: String,
    customLayouts: List<LayoutSpec>,
    displayMode: SpacebarDisplay,
    onPick: (String) -> Unit,
    onOtherKeyboards: () -> Unit,
    onDismiss: () -> Unit,
    /**
     * Row a spacebar hold-drag has walked to, or null when the popup is in
     * plain tap mode (globe long-press, or a hold that has not moved yet).
     * Kept scrolled into view so the finger never outruns the viewport.
     */
    highlightIndex: Int? = null,
) {
    val kb = LocalKbTheme.current
    val scrollState = rememberScrollState()
    val layoutRail = rememberScrollRailState(scrollState)
    val density = LocalDensity.current
    LaunchedEffect(highlightIndex) {
        if (highlightIndex != null) {
            val rowPx = with(density) { PickerRowHeightDp.dp.toPx() }
            val centerPx = with(density) { 100.dp.toPx() }
            scrollState.animateScrollTo(
                (rowPx * highlightIndex - centerPx).toInt().coerceIn(0, scrollState.maxValue),
            )
        }
    }
    Popup(
        popupPositionProvider = popupPosition,
        onDismissRequest = onDismiss,
    ) {
        Surface(
            shape = kb.menuShape(),
            color = kb.popup,
            border = kb.popupSurfaceBorder(),
            shadowElevation = elevationFor(kb.menuShapeKind, 8.dp),
        ) {
            Column(modifier = Modifier.widthIn(min = 160.dp, max = 240.dp)) {
                ScrollRail(
                    state = layoutRail,
                    modifier = Modifier
                        .heightIn(max = 240.dp)
                        .padding(vertical = 4.dp),
                    fadeColor = kb.popup,
                    colors = kbRailColors(kb),
                ) {
                    for ((index, layoutId) in enabledLayoutIds.withIndex()) {
                        val selected = layoutId == currentLayoutId
                        val dragged = index == highlightIndex
                        Text(
                            text = layoutSwitchLabel(layoutId, enabledLayoutIds, customLayouts, displayMode),
                            color = if (selected) kb.popupSelectedText else kb.popupText,
                            fontWeight = if (selected || dragged) FontWeight.Bold else FontWeight.Normal,
                            fontSize = 15.sp,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier
                                .fillMaxWidth()
                                // Fixed row height — the hold-drag gesture steps its
                                // highlight by this exact amount of finger travel.
                                .height(PickerRowHeightDp.dp)
                                .background(
                                    if (dragged || (selected && highlightIndex == null)) {
                                        kb.popupSelected
                                    } else {
                                        Color.Transparent
                                    },
                                )
                                .clickable { onPick(layoutId) }
                                .padding(horizontal = 16.dp)
                                .wrapContentHeight(Alignment.CenterVertically),
                        )
                    }
                }
                HorizontalDivider(color = kb.popupText.copy(alpha = 0.15f))
                Text(
                    text = stringResource(R.string.ime_language_picker_other_keyboards),
                    color = kb.popupText,
                    fontSize = 14.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(PickerRowHeightDp.dp)
                        .clickable { onOtherKeyboards() }
                        .padding(horizontal = 16.dp)
                        .wrapContentHeight(Alignment.CenterVertically),
                )
            }
        }
    }
}

/**
 * The language picker turned sideways (issue #150): one strip of chips, the
 * current layout centred, the rest scrolling off either end. It stands in for
 * [LanguagePickerPopup] when [LanguagePickerStyle.CAROUSEL] is on, and takes
 * the same callbacks, so the two are interchangeable at the one call site.
 *
 * The point of it is the axis. A spacebar hold-drag through the list walks up
 * and down, which turns the sideways language swipe into a vertical gesture
 * the moment the ring is long enough to need the list. Here the hold-drag
 * keeps its direction — the gesture steps [highlightIndex] by the swipe's own
 * 44 dp — and the strip re-centres on the highlighted chip, so the finger
 * never has to chase the viewport. A chip is also tappable, exactly like a
 * list row.
 *
 * "Other keyboards…" is a keyboard glyph past a divider at the strip's end,
 * outside the scroller for the reason the list keeps it outside its own: the
 * hold-drag walks by index and must never land on it.
 */
@Composable
private fun LanguageCarouselPopup(
    popupPosition: PopupPositionProvider,
    enabledLayoutIds: List<String>,
    currentLayoutId: String,
    customLayouts: List<LayoutSpec>,
    displayMode: SpacebarDisplay,
    onPick: (String) -> Unit,
    onOtherKeyboards: () -> Unit,
    onDismiss: () -> Unit,
    /**
     * Chip a spacebar hold-drag has walked to, or null when the popup is in
     * plain tap mode (globe long-press, or a hold that has not moved yet).
     */
    highlightIndex: Int? = null,
) {
    val kb = LocalKbTheme.current
    val scrollState = rememberScrollState()
    // Where each chip sits in the strip (x, width), reported as it is placed,
    // so the centring below can aim at a chip whose width depends on its label.
    val chipBounds = remember(enabledLayoutIds) { mutableStateMapOf<Int, Pair<Int, Int>>() }
    var viewportWidth by remember { mutableIntStateOf(0) }
    val currentIndex = enabledLayoutIds.indexOf(currentLayoutId).coerceAtLeast(0)
    val centreOn = highlightIndex ?: currentIndex
    // The first centring is a jump — the strip should open already looking at
    // the current layout — and every one after it slides, following the drag.
    val opened = remember { mutableStateOf(false) }
    LaunchedEffect(centreOn) {
        val (x, width) = snapshotFlow { chipBounds[centreOn] }.filterNotNull().first()
        val viewport = snapshotFlow { viewportWidth }.first { it > 0 }
        val target = (x + width / 2 - viewport / 2).coerceIn(0, scrollState.maxValue)
        if (opened.value) scrollState.animateScrollTo(target) else scrollState.scrollTo(target)
        opened.value = true
    }
    Popup(
        popupPositionProvider = popupPosition,
        onDismissRequest = onDismiss,
    ) {
        Surface(
            shape = kb.menuShape(),
            color = kb.popup,
            border = kb.popupSurfaceBorder(),
            shadowElevation = elevationFor(kb.menuShapeKind, 8.dp),
        ) {
            Row(
                modifier = Modifier.height(IntrinsicSize.Min),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Row(
                    modifier = Modifier
                        .widthIn(max = CarouselMaxWidthDp.dp)
                        .onSizeChanged { viewportWidth = it.width }
                        .horizontalScroll(scrollState)
                        .padding(horizontal = 6.dp, vertical = 4.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    for ((index, layoutId) in enabledLayoutIds.withIndex()) {
                        val selected = layoutId == currentLayoutId
                        val dragged = index == highlightIndex
                        Text(
                            text = layoutSwitchLabel(layoutId, enabledLayoutIds, customLayouts, displayMode),
                            color = if (selected) kb.popupSelectedText else kb.popupText,
                            fontWeight = if (selected || dragged) FontWeight.Bold else FontWeight.Normal,
                            fontSize = 15.sp,
                            maxLines = 1,
                            modifier = Modifier
                                .onPlaced {
                                    chipBounds[index] =
                                        it.positionInParent().x.roundToInt() to it.size.width
                                }
                                .padding(horizontal = 2.dp)
                                .height(PickerRowHeightDp.dp)
                                .background(
                                    if (dragged || (selected && highlightIndex == null)) {
                                        kb.pressedKey
                                    } else {
                                        Color.Transparent
                                    },
                                    RoundedCornerShape(kb.popupRadiusDp.dp),
                                )
                                .clip(RoundedCornerShape(kb.popupRadiusDp.dp))
                                .clickable { onPick(layoutId) }
                                .padding(horizontal = 12.dp)
                                .wrapContentHeight(Alignment.CenterVertically),
                        )
                    }
                }
                VerticalDivider(
                    modifier = Modifier.fillMaxHeight().padding(vertical = 8.dp),
                    color = kb.popupText.copy(alpha = 0.15f),
                )
                Icon(
                    imageVector = Icons.Outlined.Keyboard,
                    contentDescription = stringResource(R.string.ime_language_picker_other_keyboards),
                    tint = kb.popupText,
                    modifier = Modifier
                        .clickable { onOtherKeyboards() }
                        .padding(horizontal = 12.dp, vertical = 8.dp)
                        .size(22.dp),
                )
            }
        }
    }
}

/**
 * Label for an enabled layout in the spacebar language switcher (tooltip and
 * picker). Follows the same rule as the spacebar label: the language name, the
 * layout name, or "Language (Layout)" — and always the combined form when more
 * than one enabled layout shares the language, so the rows stay distinct.
 */
internal fun layoutSwitchLabel(
    layoutId: String,
    enabledLayoutIds: List<String>,
    customLayouts: List<LayoutSpec>,
    mode: SpacebarDisplay,
): String {
    val spec = resolveLayout(customLayouts, layoutId)
    // The short half of the registry's "native · english" display name — the
    // full form overflows the preview row and picker with even three
    // languages enabled, and the native name is what the switcher's audience
    // reads fastest (it is also the colloquial name for the romanized
    // variants: Banglish, Hinglish, …).
    val lang = spec.language().displayName.substringBefore(" · ")
    val layout = spec.name
    val sameLangCount = enabledLayoutIds.count {
        resolveLayout(customLayouts, it).langId == spec.langId
    }
    return when {
        mode == SpacebarDisplay.LAYOUT -> layout
        // A transliterating layout is named by its method, never by its output.
        // Avro, Probhat and Jatiya all write বাংলা, so the language name says
        // nothing about which of them is under the fingers — and on Avro it is
        // actively wrong about what the user is looking at, which is a roman
        // grid. "Avro phonetic" is both the name they picked it by and the
        // answer to "why are these keys Latin".
        mode == SpacebarDisplay.LANGUAGE && spec.composerType() == ComposerType.TRANSLITERATE ->
            layout
        // A layout named after its language ("Banglish (Banglish)") collapses.
        (mode == SpacebarDisplay.BOTH || sameLangCount > 1) && layout != lang -> "$lang ($layout)"
        else -> lang
    }
}

/**
 * The glyph an action key draws: the icon its layout named, when it named one
 * (issue #187), otherwise its slot's, which is what an icon pack redresses. A
 * named icon is the author choosing for this one key, so it stands over the pack
 * the same way a label typed on a tool key stands over the tool's icon.
 */
@Composable
private fun ActionKeyIcon(
    named: ImageVector?,
    slot: String,
    contentDescription: String?,
    tint: Color,
) {
    if (named != null) {
        Icon(named, contentDescription = contentDescription, tint = tint)
    } else {
        SlotIcon(slot, contentDescription = contentDescription, tint = tint)
    }
}

@Composable
private fun KeyContent(visual: KeyVisual, settings: KeyboardSettings, contentColor: Color) {
    val key = visual.key
    // The user's own size, then the grid's. Multiplied rather than replaced, so
    // a layout asking for smaller labels still leaves a larger accessibility
    // font size in force underneath it instead of silently discarding it.
    val fontScale = settings.fontScale * visual.fontScale
    // An icon the layout named for this key (issue #187). Every branch below
    // honours it, so a space bar or a shift key can wear one as well as a letter.
    val namedIcon = KeyIcons.byName(key.icon)
    when (key.action) {
        // The shift slot and its spoken name both track the live shift state, and
        // [spokenLabel] already words it the way this key wants read out.
        KeyAction.Shift -> ActionKeyIcon(
            namedIcon,
            visual.iconSlot ?: IconSlots.KEY_SHIFT,
            contentDescription = visual.spoken.resolved(),
            tint = if (visual.iconActive) MaterialTheme.colorScheme.primary else contentColor,
        )
        KeyAction.CapsLock -> ActionKeyIcon(
            namedIcon,
            visual.iconSlot ?: IconSlots.KEY_SHIFT_LOCK,
            contentDescription = visual.spoken.resolved(),
            tint = if (visual.iconActive) MaterialTheme.colorScheme.primary else contentColor,
        )
        KeyAction.Delete -> ActionKeyIcon(
            namedIcon,
            IconSlots.KEY_BACKSPACE,
            contentDescription = stringResource(R.string.ime_key_delete),
            tint = contentColor,
        )
        KeyAction.ForwardDelete -> ActionKeyIcon(
            namedIcon,
            IconSlots.KEY_FORWARD_DELETE,
            contentDescription = stringResource(R.string.ime_key_forward_delete),
            tint = contentColor,
        )
        // An app-supplied actionLabel is drawn as text — that is the whole
        // point of it, and no icon can stand in for wording the app chose.
        // It is clipped to one line so a long label cannot blow up the row.
        // CUSTOM is also the one enter action with no icon slot, for the same
        // reason: there is nothing to replace.
        KeyAction.Enter -> Box(
            modifier = Modifier.fillMaxSize(),
            contentAlignment = Alignment.Center,
        ) {
            if (visual.enterLabel != null) {
                Text(
                    text = visual.enterLabel,
                    fontSize = (13 * fontScale).sp,
                    color = contentColor,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 4.dp),
                )
            } else {
                ActionKeyIcon(
                    namedIcon,
                    visual.iconSlot ?: IconSlots.KEY_ENTER,
                    contentDescription = stringResource(R.string.ime_enter_default),
                    tint = contentColor,
                )
            }
            // The other thing this key does right now, drawn small in the same
            // corner lane a letter puts its alternate in (see [enterHintSlot]).
            // It answers to no hint switch: it is not an annotation of a hold
            // but half of a pair with the face below it, and the pair is the
            // whole point — a shift swaps them over rather than making the
            // field's action disappear (issue #107). `hideHint` still silences
            // it, since that is an author asking for a clean corner, and the
            // face still names whatever Enter does.
            val hint = if (key.hideHint) null else visual.enterHint
            if (hint != null) {
                SlotIcon(
                    hint,
                    contentDescription = null,
                    tint = visual.hintColor ?: contentColor.copy(alpha = 0.55f),
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .padding(
                            top = settings.layoutBehavior.hintOffsetDp.dp,
                            end = HintEndPadding,
                        )
                        .size(
                            (HintIconDp * fontScale * settings.layoutBehavior.hintFontScale).dp,
                        ),
                )
            }
        }
        // The enter glyph, never one of the action icons: this key types a line
        // break whatever the field declares, and drawing a paper plane on it
        // would promise the Send it exists to avoid.
        KeyAction.Newline -> ActionKeyIcon(
            namedIcon,
            IconSlots.KEY_ENTER,
            contentDescription = stringResource(R.string.ime_key_newline),
            tint = contentColor,
        )
        KeyAction.LanguageSwitch -> ActionKeyIcon(
            namedIcon,
            IconSlots.KEY_GLOBE,
            contentDescription = stringResource(R.string.ime_key_language_switch),
            tint = contentColor,
        )
        KeyAction.InputMethodPicker, is KeyAction.SwitchInputMethod -> ActionKeyIcon(
            namedIcon,
            IconSlots.KEY_INPUT_METHOD_PICKER,
            contentDescription = stringResource(R.string.ime_key_input_method_picker),
            tint = contentColor,
        )
        KeyAction.Emoji -> ActionKeyIcon(
            namedIcon,
            IconSlots.KEY_EMOJI,
            contentDescription = stringResource(R.string.ime_key_emoji),
            tint = contentColor,
        )
        // A text-editing key wears its operation's icon, or the short word the
        // old panel drew for the ones no glyph explains (Select, Select all,
        // Copy, Paste). An icon the author named still wins, like any key.
        is KeyAction.Edit -> {
            val op = (key.action as KeyAction.Edit).op
            val mainIcon = namedIcon ?: textEditIcon(op)
            if (mainIcon != null && key.label.isBlank()) {
                Icon(
                    mainIcon,
                    contentDescription = visual.spoken.resolved(),
                    tint = contentColor,
                    modifier = Modifier.size((22f * fontScale).dp),
                )
            } else {
                Text(
                    text = key.label.ifBlank { textEditLabel(op) },
                    fontSize =
                        (ModeLabelSp * (visual.drawnLabelScale() ?: 1f) * fontScale).sp,
                    fontWeight = FontWeight.Medium,
                    color = contentColor,
                    maxLines = 1,
                    softWrap = false,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.padding(horizontal = 4.dp),
                )
            }
        }
        KeyAction.Space -> Box(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp),
            contentAlignment = Alignment.Center,
        ) {
            // Split-spacebar left halves carry an empty label: no language name.
            // A named icon takes the name's place, or sits before it when the
            // key asks for both (issue #187).
            val showText = key.label.isNotEmpty() && (namedIcon == null || key.iconBesideLabel)
            if (showText || namedIcon != null) {
                val showArrows = visual.spaceArrows
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                ) {
                    if (showArrows) Text(
                        text = "◀",
                        fontSize = (8 * fontScale).sp,
                        color = contentColor.copy(alpha = 0.35f),
                    )
                    if (namedIcon != null) {
                        // Beside the name it is read at the name's weight; alone
                        // it is the key's face, like an icon on any other key.
                        Icon(
                            namedIcon,
                            contentDescription = if (showText) null else visual.spoken.resolved(),
                            tint = if (showText) contentColor.copy(alpha = 0.5f) else contentColor,
                            modifier = Modifier.size(((if (showText) 16f else 22f) * fontScale).dp),
                        )
                    }
                    // A custom label replaces the language name; %s inside it
                    // puts the name back, so "— %s —" keeps tracking the mode.
                    if (showText) Text(
                        text = visual.spaceText,
                        fontSize = (11 * fontScale).sp,
                        color = contentColor.copy(alpha = 0.5f),
                        maxLines = 1,
                        softWrap = false,
                        overflow = TextOverflow.Ellipsis,
                    )
                    if (showArrows) Text(
                        text = "▶",
                        fontSize = (8 * fontScale).sp,
                        color = contentColor.copy(alpha = 0.35f),
                    )
                }
            }
        }
        else -> Box(modifier = Modifier.fillMaxSize()) {
            // A key may draw a named icon in place of its glyph; an unknown name
            // resolves to null and falls through to the text label below.
            val mainIcon = namedIcon
            // A tool key with no label and no icon of its own wears the icon the
            // tool wears on the toolbar — through the slot registry, so an icon
            // pack redresses the key with the tool. A label the author typed wins:
            // a key that says "Voice" was asked for in words.
            val toolSlot = (key.action as? KeyAction.Tool)
                ?.takeIf { mainIcon == null && key.label.isBlank() }
                ?.let { IconSlots.forTool(it.tool) }
            if (mainIcon != null) {
                Icon(
                    mainIcon,
                    contentDescription = key.label.ifBlank { key.icon.orEmpty()},
                    tint = contentColor,
                    modifier = Modifier
                        .align(Alignment.Center)
                        .size((22f * fontScale).dp),
                )
            } else if (toolSlot != null) {
                SlotIcon(
                    toolSlot,
                    contentDescription = visual.spoken.resolved(),
                    tint = contentColor,
                    modifier = Modifier
                        .align(Alignment.Center)
                        .size((22f * fontScale).dp),
                )
            } else {
                // A blank label on an action key used to draw literally nothing,
                // so a Tab, Escape, Ctrl or Fn key made in the editor — where the
                // action picker never asks for a label — arrived here invisible.
                // The fallback lives in the layout module so the editor's preview
                // and this draw the same thing.
                val text = visual.label.ifBlank { key.action.fallbackLabel() }
                // Multi-character mode labels (?123, ABC, =\<, Ctrl) read as
                // labels, not characters — render them clearly smaller than
                // letters. Measured on the resolved text, or every fallback above
                // would come out at full letter size.
                //
                // A key carrying its own labelScale overrides that rule outright
                // rather than scaling its result: the whole point of the field is
                // to say what the automatic answer got wrong on this one key, and
                // it is what carries a HeliBoard label flag across (issue #18).
                val isModeLabel = key.action != KeyAction.Text && text.length > 1
                val keyScale = visual.drawnLabelScale()
                val baseSize = when {
                    keyScale != null -> LetterLabelSp * keyScale
                    isModeLabel -> ModeLabelSp
                    else -> LetterLabelSp
                }
                // A custom layout may put any string on a key — ".com", or a word
                // like "SEND". Left alone, a long one wrapped onto a second line
                // and drew outside the key it belongs to, so it is held to one
                // line and stepped down until it fits.
                //
                // Measured rather than counted: a Bengali conjunct is three
                // UTF-16 units and one glyph, so a rule on `length` would shrink
                // exactly the labels that never needed it. Asking the finished
                // layout whether it overflowed is script-agnostic, costs the
                // ordinary one-glyph key nothing, and settles in a frame or two.
                var scale by remember(text, baseSize, fontScale) { mutableFloatStateOf(1f) }
                Text(
                    text = text,
                    modifier = Modifier.align(Alignment.Center),
                    fontSize = (baseSize * fontScale * scale).sp,
                    fontWeight = if (visual.bold ?: settings.accessibility.boldLabels) {
                        FontWeight.Bold
                    } else {
                        FontWeight.Medium
                    },
                    color = contentColor,
                    maxLines = 1,
                    softWrap = false,
                    overflow = TextOverflow.Ellipsis,
                    onTextLayout = {
                        // Floored, so a label nothing could fit ellipsises rather
                        // than shrinking to nothing.
                        if (it.hasVisualOverflow && scale > 0.5f) scale -= 0.08f
                    },
                )
            }
            // Corner hint: a named icon if the key carries one, otherwise the
            // key's first long-press alternate. The character hint is shown by
            // whichever keys the popup actually opens on — a clipboard shortcut
            // takes the long press over, and the delete keys hold to repeat, so
            // neither annotates a popup that never appears. An explicit icon
            // hint is an authored annotation and stands regardless. The spacebar
            // is in that set once it carries keys of its own (issue #57): the
            // corner glyph is the only thing on the board that says the hold
            // stopped opening the language picker.
            //
            // Enter and the other action keys are in now that they can carry
            // alternates (issue #22): a key that does something on hold should
            // say so in the corner, the same as a letter does.
            //
            // Key.hideHint silences both: the author asked this one key for a
            // clean corner while keeping its alternates reachable. Key.forceHint
            // is the mirror (issue #33) — this one key keeps its hint on a board
            // whose global toggle is off. hideHint wins if a file sets both.
            val hintIcon = if (key.hideHint) null else KeyIcons.byName(key.iconHint)
            // Cased with the popup it previews: under shift a hold types the capital.
            val hint = if (key.hideHint) {
                null
            } else {
                key.longPress.firstOrNull()?.let { shiftCased(it, visual.alternatesShifted) }
            }
            val showHints = settings.longPressHints || key.forceHint
            // A theme may name the hint colour outright (issue #72); otherwise
            // it is the label colour faded, so it follows a per-key override
            // and the Enter key's pressed flip for free.
            val hintColor = visual.hintColor ?: contentColor.copy(alpha = 0.55f)
            // A floating word and a corner hint a few pixels apart read as one
            // thing, so a key carrying a word drops its hint for as long as it
            // has one. Read at *draw* time: this changes on every keystroke,
            // and a key that read it in composition would cost the whole board
            // the skip [KeyVisual] exists to buy. Only the long-press hints —
            // the transliteration hint is the reading of the buffer, and the
            // only thing on a phonetic board that says what a roman key does.
            val octopusHere = if (
                settings.octopus.enabled && settings.octopus.suppressHints
            ) {
                LocalOctopusOccupancy.current.flag(key.glideAnchor() ?: -1)
            } else {
                null
            }
            val hintMask = if (octopusHere == null) {
                Modifier
            } else {
                Modifier.drawWithContent { if (!octopusHere.value) drawContent() }
            }
            KeyCornerHint(
                transliterationRoman = if (key.hideHint) null else visual.transliterationRoman,
                hintIcon = hintIcon.takeIf { showHints },
                hint = hint.takeIf { showHints && key.opensAlternatesPopup() },
                hintMask = hintMask,
                hintColor = hintColor,
                fontScale = fontScale,
                settings = settings,
            )
        }
    }
}

/**
 * A key's corner: what the transliterator is about to write with it, or else
 * the icon an author named, or else the first long-press alternate.
 *
 * Its own composable so the transliteration reading, which changes on every
 * keystroke of a phonetic board, is read in a scope of its own: a letter
 * typed recomposes this corner and leaves the key around it alone.
 */
@Composable
private fun BoxScope.KeyCornerHint(
    transliterationRoman: String?,
    hintIcon: ImageVector?,
    hint: String?,
    hintMask: Modifier,
    hintColor: Color,
    fontScale: Float,
    settings: KeyboardSettings,
) {
    // What the transliterator is about to write with this key. It takes
    // the corner over the long-press alternate, and answers to its own
    // switch rather than `longPressHints`: the two annotate different
    // things — the alternate is a second glyph the key also has, this
    // is what the key does right now — and on a phonetic board this is
    // the only thing that says what a roman key means. `hideHint` still
    // silences it, since that is an author asking for a clean corner
    // rather than an opinion about which hint belongs in it.
    val translit = transliterationRoman?.let { LocalTransliterationPreview.current?.of(it) }
    when {
        // Drawn a step larger than the hint lane: these are Bengali
        // conjuncts, not a single Latin letter, and ক্ক at [HintLabelSp]
        // is a smudge. The user's hint scale still applies.
        translit != null -> Text(
            text = translit,
            modifier = Modifier
                .align(Alignment.TopEnd)
                .padding(top = settings.layoutBehavior.hintOffsetDp.dp, end = HintEndPadding),
            fontSize = (TranslitHintSp * fontScale * settings.layoutBehavior.hintFontScale).sp,
            color = hintColor,
            maxLines = 1,
            softWrap = false,
            style = keyHintTextStyle(),
        )
        hintIcon != null -> Icon(
            hintIcon,
            contentDescription = null,
            tint = hintColor,
            modifier = hintMask
                .align(Alignment.TopEnd)
                .padding(top = settings.layoutBehavior.hintOffsetDp.dp, end = HintEndPadding)
                .size((HintIconDp * fontScale * settings.layoutBehavior.hintFontScale).dp),
        )
        hint != null -> Text(
            text = hint,
            modifier = hintMask
                .align(Alignment.TopEnd)
                .padding(top = settings.layoutBehavior.hintOffsetDp.dp, end = HintEndPadding),
            fontSize = (HintLabelSp * fontScale * settings.layoutBehavior.hintFontScale).sp,
            color = hintColor,
            maxLines = 1,
            softWrap = false,
            style = keyHintTextStyle(),
        )
    }
}

/**
 * The size an ordinary letter key's label is drawn at, before the user's
 * [KeyboardSettings.fontScale] and the layout's own multiplier. Also the unit a
 * [Key.labelScale] is a multiple of, which is why it is named rather than
 * inline.
 */
internal const val LetterLabelSp = 23f

/** The smaller size a multi-character mode label (`?123`, `ABC`) falls back to. */
private const val ModeLabelSp = 15.6f

/**
 * The corner hint lane: the long-press alternate a key annotates, the icon hint
 * an author named, and the transliterated reading, all drawn in the key's top
 * right corner.
 *
 * Sized and placed as an annotation rather than a second label. A hint that
 * competes with the glyph under it reads as clutter — on a grid where most keys
 * carry one it is a whole second row of text — so it sits hard against the top
 * edge and a good deal smaller than the letter it belongs to. The transliterated
 * reading keeps its extra step: a Bengali conjunct is several glyphs and shrinks
 * into a smudge where a lone Latin letter stays legible.
 */
private const val HintLabelSp = 8.5f

/** The transliteration hint's size; see [HintLabelSp]. */
private const val TranslitHintSp = 10.5f

/** An icon hint's box, matched to the text hints' height. */
private const val HintIconDp = 9.5f

/** How far the hint lane sits from the key's trailing edge. */
private val HintEndPadding = 4.dp

/**
 * The hint lane's text style: no font padding, so the glyph hugs the top edge
 * the padding above measures from. With it left on, a 1 dp inset drew a hint
 * three or four dp down the key — far enough to crowd the label.
 *
 * Merged onto the ambient style rather than replacing it: the theme's keyboard
 * font arrives through [LocalTextStyle], and a bare [TextStyle] here would draw
 * every corner hint in the platform default while its key kept the theme's face.
 */
@Composable
internal fun hintTextStyle(): TextStyle {
    val base = LocalTextStyle.current
    return remember(base) { base.merge(NoFontPadding) }
}

/**
 * [hintTextStyle] with the line box shrunk to the font, for the hints drawn in a
 * key's corner (#208). The ambient style is Material's bodyLarge, whose 24 sp
 * line height centred an 8.5 sp hint in a box nearly three times its size: the
 * glyph landed about ten dp down the key, on top of the label, whatever the top
 * padding said. The octopus overlay keeps the plain style, because its word band
 * is measured from it.
 */
@Composable
private fun keyHintTextStyle(): TextStyle {
    val base = hintTextStyle()
    return remember(base) { base.copy(lineHeight = TextUnit.Unspecified) }
}

private val NoFontPadding = TextStyle(
    platformStyle = PlatformTextStyle(includeFontPadding = false),
)

/**
 * Text drawn on the spacebar: the live language name, or the user's custom
 * [SettingsRepository.spacebarLabel] with %s standing in for that name.
 * Shared by the main keyboard's spacebar and the emoji panel's spacebar so
 * both read the same.
 */
private fun spacebarText(state: KeyboardUiState): String {
    val name = layoutSwitchLabel(
        state.layoutId,
        state.settings.enabledLayoutIds,
        state.settings.customLayouts,
        state.settings.layoutBehavior.spacebarDisplay,
    )
    val label = state.settings.spacebarLabel
    return if (label.isEmpty()) name else label.replace("%s", name)
}

/**
 * The script a key is about to write, for the corner of a transliterating
 * layout: ক on the `k` at a word start, and once a consonant is composing
 * either the ্ক that key adds or the ক্ক it leaves, whichever
 * [TransliterationHintMode] the user picked. It follows the composing buffer
 * and the shift state, so a roman grid reads as the Bengali it produces —
 * which is otherwise the one thing a phonetic board never says.
 *
 * Null when there is nothing useful to draw: a board that does not
 * transliterate, the mode switched off, a key that is not a letter (the
 * composer refuses those — a digit commits straight through and never reaches
 * the transliterator), a key that adds no glyph of its own (Avro's inherent
 * "o" after a consonant), or one whose answer is the roman letter back again.
 */
private fun transliterationRoman(key: Key, state: KeyboardUiState): String? {
    if (key.action != KeyAction.Text || !state.transliterationHintsShown()) return null
    // What the keypress would actually feed the buffer, shift included. Taken
    // the same way [WMKeyboardService.keyOutput] takes it rather than off the
    // drawn label, because the two must not be able to disagree: `t` is ত and
    // `T` is ট, so a hint read from the unshifted label would name the wrong
    // letter every time shift is down.
    val base = key.output ?: key.label
    val shiftLabel = key.shiftLabel
    return when {
        state.shiftState != ShiftState.OFF && shiftLabel != null -> shiftLabel
        state.shiftState != ShiftState.OFF -> base.uppercase()
        else -> base
    }
}

/**
 * The composer and the live roman buffer, for the corners of a transliterating
 * board to read what each key is about to write ([KeyCornerHint]).
 *
 * The buffer is a [State] read only by the corners, so a keystroke recomposes
 * those small scopes and nothing else. Handed to the grid through
 * [KeyVisual] it had to be a key of `rememberKeyGrid`, and every letter typed
 * rebuilt all ~40 key visuals and recomposed every key body with them.
 */
@Stable
internal class TransliterationPreview(
    private val composer: com.wasimaster.wmkeyboard.core.input.composer.Composer,
    private val wholeCluster: Boolean,
    private val buffer: State<String>,
) {
    /** What [roman] would write now, or null when that is nothing worth drawing. */
    fun of(roman: String): String? =
        composer.keyPreview(buffer.value, roman, wholeCluster)
            ?.takeIf { it.isNotEmpty() && it != roman }
}

/** Null on every board whose corners do not read a transliteration. */
internal val LocalTransliterationPreview =
    staticCompositionLocalOf<TransliterationPreview?> { null }

@Composable
private fun rememberTransliterationPreview(state: KeyboardUiState): TransliterationPreview? {
    // Always taken, so the slot does not come and go with the setting.
    val buffer = rememberUpdatedState(state.composingRoman)
    if (!state.transliterationHintsShown()) return null
    val composer = state.composer
    val wholeCluster =
        state.settings.layoutBehavior.transliterationHints == TransliterationHintMode.CLUSTER
    return remember(composer, wholeCluster, buffer) {
        TransliterationPreview(composer, wholeCluster, buffer)
    }
}

private fun displayLabel(key: Key, state: KeyboardUiState): String {
    // Digit keys draw the chosen numeral system's glyphs (in every commit
    // scope, including display-only). The layout data stays ASCII; the swap
    // happens here at draw time. Non-digit labels pass through untouched.
    val digits = resolveNumeralDigits(
        state.settings.layoutBehavior.numeralSystemFor(state.language.id),
        state.language,
    )
    val shiftLabel = key.shiftLabel
    val raw = when {
        state.shiftState != ShiftState.OFF && shiftLabel != null -> shiftLabel
        // Cased-script letter labels track the live shift state: lowercase
        // normally, uppercase while shift or caps lock is active (Latin,
        // Cyrillic, Greek — not Bengali/Arabic/Hangul, which have no case).
        //
        // A transliterating layout is judged by its keys, not by its script.
        // Avro's script is Bengali and uncased, but the grid it wears is roman
        // and the rules behind it read case — `t` is ত and `T` is ট — and the
        // service already commits the capital ([keyOutput] gates on the same
        // isClusterShaping and nothing else). Without this the key drew `t`
        // while shift fed the transliterator `T`, so shift silently changed
        // the letter and the board never said so.
        state.shiftState != ShiftState.OFF && key.action == KeyAction.Text &&
            !state.composer.isClusterShaping &&
            (state.script.hasLetterCase || state.composer.isTransliterating) &&
            key.label.singleOrNull()?.isLetter() == true ->
            key.label.uppercase()
        else -> key.label
    }
    // Fixed Bengali layouts: vowel keys track the cursor context — the
    // independent letter (আ, ই …) at a word start, the kar (া, ি …) after a
    // consonant, the য়-glide (য়া) after a vowel — matching what the key
    // will actually commit.
    if (state.composer.isClusterShaping && key.action == KeyAction.Text &&
        state.vowelForm != BengaliGraphemes.VowelKeyForm.KAR
    ) {
        raw.singleOrNull()
            ?.let { BengaliGraphemes.vowelKeyText(it, state.vowelForm) }
            ?.let { return it }
    }
    // Fancy Text: the layout carries plain a–z; the selected style's glyph is
    // drawn here (and committed by the service's twin of this substitution),
    // so the keys are WYSIWYG and the compiled layout never varies. The
    // uppercase branch above already cased the plain letter, so shift shows
    // the style's capital via the upper map.
    fancyStyleFor(state)?.let { style -> return FancyStyles.transform(raw, style) }
    return mapDigits(raw, digits)
}

/**
 * The preview bubble is a separate window that lingers briefly after release
 * and, in on-key mode, covers the key itself plus part of the row above. It
 * must never intercept touches, or rapid re-taps land on the bubble window
 * and get dropped before the keyboard sees them.
 */
private val PreviewPopupProperties = PopupProperties(
    flags = WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
        WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,
)

/**
 * Hold time after which a spacebar press (with language switching on the
 * short-swipe slot) shows the language picker: longer than any normal tap,
 * shorter than the long-press delay so the picker feels immediate.
 */
private const val SpaceHoldPickerMs = 250

/**
 * Fixed height of one language-picker row, shared between the popup's layout
 * and the spacebar hold-drag gesture that steps through it — the two must
 * agree or the finger and the highlight drift apart.
 */
private const val PickerRowHeightDp = 40

/**
 * Widest the language carousel's scrolling strip gets before its chips scroll
 * instead. Narrower than any phone the keyboard runs on, so the strip reads as
 * a strip with ends rather than a bar across the whole board; the popup's
 * positioner clamps it to the window on anything narrower still.
 */
private const val CarouselMaxWidthDp = 320

/**
 * How long a spacebar language swipe waits after one step before it takes
 * another the same way. Longer than a whole flick lasts, so a flick switches
 * exactly one language however fast it travels; a drag that keeps moving walks
 * on one language per step, and a reversal answers at once.
 */
private const val LanguageStepDwellMs = 200L

/** Where a spacebar language swipe has stepped to, and which way (0 = no step). */
internal data class RingStep(val index: Int, val remainder: Float, val dir: Int)

/**
 * One step of the spacebar language swipe around the enabled ring. A step
 * costs [stepPx] of travel, and wrapping past either end costs [wrapPx], so the
 * ends act as a detent. A step the same way as [lastDir] before the last one
 * has [settled] is held back, and the travel it banks meanwhile is capped at
 * one step: a fast flick cannot store up a second switch to fire the moment the
 * dwell ends, and the finger has to keep moving to take it.
 */
internal fun stepLanguageRing(
    index: Int,
    travel: Float,
    stepPx: Float,
    wrapPx: Float,
    last: Int,
    lastDir: Int,
    settled: Boolean,
): RingStep {
    if (last <= 0 || travel == 0f) return RingStep(index, travel, 0)
    val dir = if (travel > 0f) 1 else -1
    val atEnd = if (dir > 0) index == last else index == 0
    val need = if (atEnd) wrapPx else stepPx
    if (dir == lastDir && !settled) {
        return RingStep(index, dir * minOf(abs(travel), need), 0)
    }
    if (abs(travel) <= need) return RingStep(index, travel, 0)
    val next = when {
        !atEnd -> index + dir
        dir > 0 -> 0
        else -> last
    }
    return RingStep(next, travel - dir * need, dir)
}

/** Where a picker hold-drag has walked to, and the travel it has not spent yet. */
internal data class PickerWalk(val index: Int, val remainder: Float)

/**
 * Steps a picker hold-drag's selection by whole steps of finger travel, clamped
 * to the ends of the ring. Travel is spent in [stepPx] units whether or not a
 * step was available, so a drag past the last entry banks nothing: coming back
 * costs one step, not the whole overshoot. The list and the carousel share this
 * and differ only in the axis they feed it and the size of a step.
 */
internal fun walkPicker(index: Int, travel: Float, stepPx: Float, last: Int): PickerWalk {
    var at = index
    var left = travel
    while (left > stepPx) {
        if (at < last) at++
        left -= stepPx
    }
    while (left < -stepPx) {
        if (at > 0) at--
        left += stepPx
    }
    return PickerWalk(at, left)
}

/** The up half of a braille dot press: the same key with its release flag set. */
private fun brailleRelease(key: Key): Key {
    val action = key.action as KeyAction.BrailleDot
    return key.copy(action = action.copy(release = true))
}

/**
 * The backspace word-swipe curve, as fractions of the first word's distance
 * ([TextEditingSettings.backspaceWordStepDp]). The shipped 72 dp first pull
 * gives back the 56/6/28 dp the curve used to hard-code, and a user who
 * retunes the first pull moves the rest of the curve with it.
 */
private const val NEXT_WORD_STEP_RATIO = 56f / 72f
private const val WORD_STEP_SHRINK_RATIO = 6f / 72f
private const val MIN_WORD_STEP_RATIO = 28f / 72f

/**
 * What a held key's repeat tick plays.
 *
 * The buzz and the click are one call when both are wanted, because the sound
 * pack times its click against the haptic. Turning one off splits them: the
 * haptic-only path exists exactly so a held backspace can keep vibrating
 * without machine-gunning the click, which is the complaint that made
 * [FeedbackSettings.soundOnRepeat] a setting.
 */
private fun repeatFeedback(
    vibrate: Boolean,
    sound: Boolean,
    onKeyPress: () -> Unit,
    onKeySound: () -> Unit,
    onKeyHaptic: () -> Unit,
) {
    when {
        vibrate && sound -> onKeyPress()
        vibrate -> onKeyHaptic()
        sound -> onKeySound()
    }
}

/**
 * Whether a plain hold on the spacebar may open the language chooser.
 *
 * Three things can want that hold and only one of them can have it. Keys the
 * user authored onto the space key take it outright (issue #57). The long-swipe
 * slot takes it next: that slot is the setting for what a hold-then-drag *does*,
 * so one set to the cursor or the numpad keeps the chooser off the hold. A
 * chooser that opened first swallowed the drag it was configured for, which left
 * "press and hold, then swipe" unable to do anything but switch languages
 * (issue #122). What is left over — a slot set to the language switch, or to
 * nothing at all — leaves the hold free for the chooser. One enabled layout
 * leaves nothing worth choosing between, and holding would only cost a space.
 *
 * The chooser is still on the 🌐 key's long press and on either swipe slot set
 * to the language switch, so nothing here takes it away entirely. Hiding the
 * 🌐 key (issue #139) with neither slot set to the language switch does, and
 * that setting's info text tells the user which swipe brings switching back.
 */
internal fun spaceHoldOpensPicker(
    enabledLayoutCount: Int,
    holdOpensAlternates: Boolean,
    spaceLongSwipe: SpaceSwipeAction,
): Boolean = enabledLayoutCount > 1 &&
    !holdOpensAlternates &&
    (spaceLongSwipe == SpaceSwipeAction.NONE || spaceLongSwipe == SpaceSwipeAction.LANGUAGE)

/**
 * Press handling: tap commits, long-press opens alternates (or begins
 * repeating for delete), release cancels. The spacebar instead supports
 * horizontal swipes: a swipe that starts moving right away performs
 * [spaceShortSwipe], one that begins after holding the spacebar past the
 * long-press delay performs [spaceLongSwipe] — cursor movement steps the
 * text cursor, language switching cycles the enabled input modes with a
 * live tooltip preview and commits on release. Implemented with raw press
 * detection so repeat, popup and drag can share the gesture.
 */
private fun Modifier.pointerInputKey(
    key: Key,
    longPressDelayMs: Int,
    keyRepeat: KeyRepeatSettings,
    /** Carries the spacebar cursor step and the backspace word step. */
    textEditing: TextEditingSettings,
    spaceShortSwipe: SpaceSwipeAction,
    spaceLongSwipe: SpaceSwipeAction,
    enabledLayoutIds: List<String>,
    currentLayoutId: String,
    setPressed: (Boolean) -> Unit,
    onKeyPress: () -> Unit,
    onKeySound: () -> Unit,
    /**
     * The key coming back up, once per finger that lifts off it.
     *
     * Not folded into [setPressed], which is the *visual* press and so fires
     * only when the last finger leaves: a burst double-tap that lands a second
     * finger before the first lifts really is two keystrokes, and owes two
     * sounds at each end. Silent unless the sound in use recorded a key-up.
     */
    onKeyRelease: () -> Unit,
    vibrateOnSpace: Boolean,
    vibrateOnDeleteSwipe: Boolean,
    vibrateOnRepeat: Boolean,
    soundOnRepeat: Boolean,
    /** Buzz with no click, for a repeat tick that vibrates but stays quiet. */
    onKeyHaptic: () -> Unit,
    hapticOnLongPress: Boolean,
    hapticOnLongPressRelease: Boolean,
    openAlternates: () -> Unit,
    /** Live flick arm for the cross popup, or null when centred / released. */
    setFlickDirection: (FlickDirection?) -> Unit,
    onKey: (Key) -> Unit,
    /**
     * Un-debounced sink for auto-repeat ticks (held backspace/space). The
     * software repeat is deterministic, so it must bypass the tremor debounce
     * that [onKey] carries — otherwise repeats landing inside the debounce
     * window are dropped and the repeat rate is silently capped.
     */
    onKeyRepeat: (Key) -> Unit,
    onClipboardKey: (ClipboardKeyAction) -> Unit,
    /**
     * A Select key held down and let go. Paired: every path out of the press
     * releases what it armed. See [LocalSelectionHold].
     */
    onSelectionHold: (Boolean) -> Unit,
    onCursorMove: (Int) -> Unit,
    onCursorMoveVertical: (Int) -> Unit,
    /**
     * A spacebar drag started (true) or stopped (false) moving the caret, for
     * the magnifier over it. Paired: the release ends what the drag began.
     */
    onCaretDrag: (Boolean) -> Unit = {},
    onHideKeyboard: () -> Unit,
    spaceCursor2d: Boolean,
    spaceSwipeDownHide: Boolean,
    symbolsLongPressNumpad: Boolean,
    onLayoutSelect: (String) -> Unit,
    openLanguagePicker: () -> Unit,
    closeLanguagePicker: () -> Unit,
    /** Entry of the open picker a hold-drag has reached; null clears the highlight. */
    setPickerDragIndex: (Int?) -> Unit,
    /**
     * The picker is the sideways carousel (issue #150), so a hold-drag through
     * it walks left and right by the language swipe's own step, instead of up
     * and down by the list's row height.
     */
    pickerIsCarousel: Boolean = false,
    /**
     * A hold with more than four layouts on opens the picker. Off keeps the
     * inline preview at any ring length; it windows and scrolls itself.
     */
    pickerForLongRing: Boolean = true,
    setLanguagePreview: (String?) -> Unit,
    /** Keeps a just-switched-to language on screen briefly after the lift. */
    echoLanguageSwitch: (String, Long) -> Unit = { _, _ -> },
    canDelete: () -> Boolean,
    canForwardDelete: () -> Boolean,
    deleteSwipe: DeleteSwipeCallbacks,
    backspaceSwipeDelete: Boolean,
    scope: kotlinx.coroutines.CoroutineScope,
    smartResolve: (Key, PointerId) -> Key = { k, _ -> k },
    /**
     * The hold-drag through an open alternates popup, or null when the popup is
     * the older kind that waits for a second tap. Every branch below tests this
     * rather than a setting, so there is one thing to switch off.
     */
    alternates: AlternatesHold? = null,
): Modifier = this.then(
    if (key.action == KeyAction.Space &&
        (spaceShortSwipe != SpaceSwipeAction.NONE || spaceLongSwipe != SpaceSwipeAction.NONE ||
            spaceSwipeDownHide)
    ) {
        Modifier.pointerInput(
            key, spaceShortSwipe, spaceLongSwipe, enabledLayoutIds, currentLayoutId, longPressDelayMs,
            hapticOnLongPress, hapticOnLongPressRelease, vibrateOnSpace, spaceCursor2d,
            spaceSwipeDownHide, textEditing, alternates, pickerIsCarousel, pickerForLongRing,
        ) {
            val slopPx = 12.dp.toPx()
            val reachPx = AlternatesReachDp.toPx()
            val steerPx = AlternatesSteerDp.toPx()
            val cursorStepPx = textEditing.spaceCursorStepDp.dp.toPx()
            val langStepPx = 44.dp.toPx()
            // One picker row of vertical travel moves the hold-drag selection
            // one row; must match the fixed row height LanguagePickerPopup lays
            // out, or the finger and the highlight drift apart.
            val pickerRowPx = PickerRowHeightDp.dp.toPx()
            // A swipe-down must clear this before it dismisses the keyboard —
            // well past the slop so a diagonal cursor drag never trips it.
            val hideThresholdPx = 40.dp.toPx()
            // Extra travel demanded before the language list wraps around at
            // either end — the boundary acts like a detent, not a wall.
            val langWrapPx = langStepPx * 2.5f
            // Set while a cursor drag holds the caret magnifier up, so a
            // restart of this loop mid-drag (one of the keys above changed)
            // still takes the bubble down instead of stranding it.
            var caretDragOpen = false
            try {
                awaitEachGesture {
                    val down = awaitFirstDown()
                    setPressed(true)
                    // Space press feedback: sound stays, buzz is gated on its toggle.
                    if (vibrateOnSpace) onKeyPress() else onKeySound()
                    // Resolved on the first movement past the slop; null until
                    // then (and forever for a plain tap).
                    var action: SpaceSwipeAction? = null
                    var accumulated = 0f
                    var lastX = down.position.x
                    // Vertical accumulator for the 2-D cursor pad, and a latch set
                    // once a swipe-down has dismissed the keyboard (so release does
                    // not also type a space).
                    var accumulatedY = 0f
                    var lastY = down.position.y
                    var hidden = false
                    var langIndex = enabledLayoutIds.indexOf(currentLayoutId).coerceAtLeast(0)
                    // With exactly two languages a swipe direction means "the
                    // other language", so a single run of travel toggles at most
                    // once: runDir is the direction of the current run and
                    // runSwitched whether it already toggled. Continued travel in
                    // the same direction must never cycle back to the language the
                    // user deliberately swiped away from; only reversing direction
                    // switches back.
                    val twoModes = enabledLayoutIds.size == 2
                    var runDir = 0
                    var runSwitched = false
                    // When the swipe last stepped the language ring. A step in the
                    // same direction waits LanguageStepDwellMs after it, so a flick
                    // moves one language however far it travels and only a swipe
                    // that keeps going walks on (see [stepLanguageRing]). Also how
                    // long the preview has shown the language at the lift, which
                    // sizes the echo after it (see [languageEchoMs]).
                    var lastStepAt = 0L
                    var liftAt = 0L
                    // With language switching on the short-swipe slot, holding
                    // the spacebar just past a normal tap shows the language
                    // picker without needing any initial swipe. The action is
                    // not locked in — a drag afterwards still resolves short vs
                    // long normally, so a hold + swipe cursor action survives —
                    // but a release with the picker up must not type a space.
                    var holdPreviewShown = false
                    // With more than two languages the swipe ring is long, so a
                    // hold opens the full tappable picker instead of the inline
                    // preview. Once open, a drag walks it entry by entry — up and
                    // down through the list, sideways along the carousel — and
                    // release commits the highlighted layout; a hold that never
                    // moves leaves the popup up for tapping, and release types
                    // nothing either way.
                    var pickerOpened = false
                    var pickerIndex = langIndex
                    var pickerMoved = false
                    var pickerPrimed = false
                    // Issue #57: alternates authored onto the spacebar own the hold,
                    // and the language picker gives way to them. A hold cannot mean
                    // two things, and the keys are there because someone typed them
                    // in; the picker is still on the 🌐 key and on the swipe.
                    val holdOpensAlternates = key.opensAlternatesPopup()
                    var alternatesOpened = false
                    // Arm the hold-to-switch gesture only when the hold is free to
                    // mean it — see [spaceHoldOpensPicker]. The picker only opens on
                    // a still-hold (action == null); a drag sets action first and
                    // still runs the swipe/cursor gesture.
                    val holdOpensSwitcher = spaceHoldOpensPicker(
                        enabledLayoutIds.size, holdOpensAlternates, spaceLongSwipe,
                    )
                    // The popup waits out the full long-press delay, like every other
                    // key's does; the picker keeps its own shorter cap.
                    val holdDelayMs = if (holdOpensAlternates) {
                        longPressDelayMs
                    } else {
                        minOf(longPressDelayMs, SpaceHoldPickerMs)
                    }
                    val holdJob = if (holdOpensAlternates || holdOpensSwitcher) {
                        scope.launch {
                            delay(holdDelayMs.toLong())
                            if (action == null) {
                                if (holdOpensAlternates) {
                                    alternatesOpened = true
                                    if (hapticOnLongPress) onKeyPress()
                                    openAlternates()
                                    return@launch
                                }
                                // List for a long ring (> 4, unless the user keeps
                                // the preview for every length) or when the swipe
                                // can't cycle languages; otherwise the inline preview.
                                val useList = (pickerForLongRing && enabledLayoutIds.size > 4) ||
                                    spaceShortSwipe != SpaceSwipeAction.LANGUAGE
                                if (useList) {
                                    pickerOpened = true
                                    pickerIndex = langIndex
                                    openLanguagePicker()
                                } else {
                                    holdPreviewShown = true
                                    setLanguagePreview(enabledLayoutIds[langIndex])
                                }
                                if (hapticOnLongPress) onKeyPress()
                            }
                        }
                    } else {
                        null
                    }
                    while (true) {
                        val event = awaitPointerEvent()
                        val change = event.changes.firstOrNull { it.id == down.id } ?: break
                        if (!change.pressed) {
                            liftAt = change.uptimeMillis
                            break
                        }
                        // The alternates popup owns the gesture from here (issue
                        // #57): the finger is choosing inside it, and none of the
                        // swipes may also run under it. Swallowed so the release
                        // types no space either.
                        if (alternatesOpened) {
                            alternates?.moveTo(change.position, reachPx, steerPx)
                            change.consume()
                            continue
                        }
                        // Picker is up: the finger now navigates it. The first
                        // event only re-bases the origin — the finger may have
                        // drifted (below slop) before the hold fired, and that
                        // drift must not count as a step.
                        if (pickerOpened) {
                            if (!pickerPrimed) {
                                pickerPrimed = true
                                lastX = change.position.x
                                lastY = change.position.y
                                accumulated = 0f
                                accumulatedY = 0f
                                change.consume()
                                continue
                            }
                            // The carousel keeps the swipe's own axis (issue
                            // #150): sideways travel walks it one chip per
                            // language step. The list walks by its row height.
                            val walk = if (pickerIsCarousel) {
                                accumulated += change.position.x - lastX
                                lastX = change.position.x
                                walkPicker(pickerIndex, accumulated, langStepPx, enabledLayoutIds.size - 1)
                                    .also { accumulated = it.remainder }
                            } else {
                                accumulatedY += change.position.y - lastY
                                lastY = change.position.y
                                walkPicker(pickerIndex, accumulatedY, pickerRowPx, enabledLayoutIds.size - 1)
                                    .also { accumulatedY = it.remainder }
                            }
                            if (walk.index != pickerIndex) {
                                pickerIndex = walk.index
                                pickerMoved = true
                                setPickerDragIndex(pickerIndex)
                                onKeyPress()
                            }
                            change.consume()
                            continue
                        }
                        // The action this gesture would resolve to right now (short
                        // vs long by hold time). Used to decide whether the 2-D pad
                        // owns the vertical axis for this drag.
                        val candidate = if (change.uptimeMillis - down.uptimeMillis < longPressDelayMs) {
                            spaceShortSwipe
                        } else {
                            spaceLongSwipe
                        }
                        val cursorOwnsVertical = spaceCursor2d &&
                            (action == SpaceSwipeAction.CURSOR ||
                                (action == null && candidate == SpaceSwipeAction.CURSOR))
                        // Swipe straight down to dismiss the keyboard — unless the
                        // 2-D pad is claiming vertical for cursor movement.
                        if (spaceSwipeDownHide && !cursorOwnsVertical) {
                            val totalDy = change.position.y - down.position.y
                            val totalDx = change.position.x - down.position.x
                            if (totalDy > hideThresholdPx && totalDy > abs(totalDx)) {
                                change.consume()
                                hidden = true
                                onHideKeyboard()
                                break
                            }
                        }
                        if (action == null) {
                            val totalDx = change.position.x - down.position.x
                            val totalDy = change.position.y - down.position.y
                            // The pad may also resolve on a vertical drag, so a
                            // straight up/down slide starts moving the cursor; the
                            // language and horizontal-cursor paths still need
                            // horizontal slop, which keeps their flick direction sane.
                            val vertForCursor = spaceCursor2d &&
                                candidate == SpaceSwipeAction.CURSOR && abs(totalDy) > slopPx
                            if (abs(totalDx) > slopPx || vertForCursor) {
                                // Short vs long is decided by hold time, not travel
                                // distance — a fast flick covers more ground than a
                                // careful drag, so distance can't tell them apart.
                                // With the hold preview up the drag always
                                // navigates the language ring: the user is looking
                                // at a language chooser, so resolving the drag to
                                // the long-swipe action read as "swiping does
                                // nothing". Safe to override the candidate here
                                // because the preview only comes up when the long
                                // slot is free (see holdOpensSwitcher) — it can no
                                // longer eat a cursor or numpad hold.
                                action = if (holdPreviewShown) SpaceSwipeAction.LANGUAGE else candidate
                                if (action == SpaceSwipeAction.CURSOR) {
                                    onCaretDrag(true)
                                    caretDragOpen = true
                                }
                                lastX = change.position.x
                                lastY = change.position.y
                                accumulated = 0f
                                accumulatedY = 0f
                                if (action == SpaceSwipeAction.NUMPAD) {
                                    // Discrete action (A39): open the numeric panel once
                                    // and go inert. The synthetic Numpad key routes
                                    // through the same onKey dispatch the ?123 long-press
                                    // uses. `hidden` latches so release types no space.
                                    onKey(Key(label = " ", action = KeyAction.Numpad))
                                    hidden = true
                                    change.consume()
                                    break
                                }
                                if (action == SpaceSwipeAction.LANGUAGE) {
                                    // The movement that crossed the slop already
                                    // counts: a quick flick switches one language.
                                    // At a list end the flick parks on the boundary
                                    // — wrapping needs a continued drag past the
                                    // langWrapPx detent below. With two languages
                                    // either direction simply toggles to the other.
                                    val dir = if (totalDx > 0) 1 else -1
                                    val flicked = if (twoModes) {
                                        1 - langIndex
                                    } else {
                                        (langIndex + dir).coerceIn(0, enabledLayoutIds.size - 1)
                                    }
                                    if (flicked != langIndex) {
                                        langIndex = flicked
                                        onKeyPress()
                                    }
                                    runDir = dir
                                    runSwitched = true
                                    lastStepAt = change.uptimeMillis
                                    setLanguagePreview(enabledLayoutIds[langIndex])
                                }
                                change.consume()
                            }
                            continue
                        }
                        // 2-D touchpad: while sliding the cursor, a vertical drag
                        // steps the caret up and down as well. Runs alongside the
                        // horizontal step below, so a diagonal drag moves both axes.
                        if (spaceCursor2d && action == SpaceSwipeAction.CURSOR) {
                            accumulatedY += change.position.y - lastY
                            lastY = change.position.y
                            var movedV = false
                            while (accumulatedY > cursorStepPx) {
                                onCursorMoveVertical(1); accumulatedY -= cursorStepPx; movedV = true
                            }
                            while (accumulatedY < -cursorStepPx) {
                                onCursorMoveVertical(-1); accumulatedY += cursorStepPx; movedV = true
                            }
                            if (movedV) change.consume()
                        }
                        accumulated += change.position.x - lastX
                        lastX = change.position.x
                        when (action) {
                            SpaceSwipeAction.CURSOR -> {
                                var moved = false
                                while (accumulated > cursorStepPx) {
                                    onCursorMove(1); accumulated -= cursorStepPx; moved = true
                                }
                                while (accumulated < -cursorStepPx) {
                                    onCursorMove(-1); accumulated += cursorStepPx; moved = true
                                }
                                if (moved) change.consume()
                            }
                            SpaceSwipeAction.LANGUAGE -> {
                                if (twoModes) {
                                    // One toggle per run of travel: piling on more
                                    // distance in the same direction never wraps
                                    // back to the starting language — the user
                                    // swiped away from it on purpose. Reversing
                                    // direction starts a new run and toggles back.
                                    val dir = when {
                                        accumulated > langStepPx -> 1
                                        accumulated < -langStepPx -> -1
                                        else -> 0
                                    }
                                    if (dir != 0) {
                                        if (dir != runDir) {
                                            runDir = dir
                                            runSwitched = false
                                        }
                                        if (!runSwitched) {
                                            langIndex = 1 - langIndex
                                            runSwitched = true
                                            lastStepAt = change.uptimeMillis
                                            setLanguagePreview(enabledLayoutIds[langIndex])
                                            onKeyPress()
                                        }
                                        // Drain the overshoot so a reversal only
                                        // needs one step of travel to respond.
                                        accumulated = 0f
                                    }
                                    change.consume()
                                    continue
                                }
                                // One step per event at most, and a same-way
                                // step only once the last one has settled: a flick
                                // lands on the next language, never two over, and
                                // the list ends wrap only on a deliberate pull.
                                val step = stepLanguageRing(
                                    index = langIndex,
                                    travel = accumulated,
                                    stepPx = langStepPx,
                                    wrapPx = langWrapPx,
                                    last = enabledLayoutIds.size - 1,
                                    lastDir = runDir,
                                    settled = change.uptimeMillis - lastStepAt >= LanguageStepDwellMs,
                                )
                                accumulated = step.remainder
                                if (step.dir != 0) {
                                    langIndex = step.index
                                    runDir = step.dir
                                    lastStepAt = change.uptimeMillis
                                    setLanguagePreview(enabledLayoutIds[langIndex])
                                    onKeyPress()
                                }
                                change.consume()
                            }
                            // NONE: the swipe is deliberately inert — swallow it
                            // so release does not type a space.
                            else -> change.consume()
                        }
                    }
                    holdJob?.cancel()
                    if (caretDragOpen) {
                        onCaretDrag(false)
                        caretDragOpen = false
                    }
                    setPressed(false)
                    onKeyRelease()
                    setLanguagePreview(null)
                    when {
                        // A swipe-down already dismissed the keyboard: the finger
                        // lifting must not also type a space.
                        hidden -> {}
                        // The hold opened the alternates popup: the lift commits
                        // whatever it has highlighted, and types no space. With
                        // hold-to-select off there is nothing to commit and the
                        // popup waits for the next tap, as it always did.
                        alternatesOpened -> {
                            alternates?.commit()
                            if (hapticOnLongPressRelease) onKeyPress()
                        }
                        // The picker is up. A hold-drag that walked it commits
                        // the highlighted entry; a hold that never moved leaves
                        // the popup up for tapping. Neither types a space.
                        action == null && pickerOpened -> {
                            if (pickerMoved) {
                                val selected = enabledLayoutIds[pickerIndex]
                                closeLanguagePicker()
                                if (selected != currentLayoutId) onLayoutSelect(selected)
                            }
                        }
                        // Releasing with the hold preview up commits whatever it
                        // showed (usually the current language — a no-op) and
                        // must not type a space.
                        action == null && holdPreviewShown -> {
                            val selected = enabledLayoutIds[langIndex]
                            if (selected != currentLayoutId) onLayoutSelect(selected)
                        }
                        action == null -> onKey(key)
                        action == SpaceSwipeAction.LANGUAGE -> {
                            val selected = enabledLayoutIds[langIndex]
                            if (selected != currentLayoutId) {
                                // A lift with no up event (the pointer was cancelled)
                                // counts as unseen: echo in full.
                                val seenMs = if (liftAt > 0L) liftAt - lastStepAt else 0L
                                echoLanguageSwitch(selected, languageEchoMs(seenMs))
                                onLayoutSelect(selected)
                            }
                        }
                        else -> {}
                    }
                }
            } finally {
                if (caretDragOpen) onCaretDrag(false)
            }
        }
    } else if (
        (key.action.deletesBackward() && backspaceSwipeDelete) ||
        (key.action.deletesForward() && textEditing.forwardDeleteSwipe)
    ) {
        // A delete key owns its whole gesture rather than bolting a drag onto
        // the shared press handler: tap, hold-to-repeat and the delete swipe
        // are one state machine, so a drag can cleanly take over from the
        // repeat loop mid-press and the move events are consumed while it does.
        Modifier.pointerInput(key, longPressDelayMs, keyRepeat, textEditing, hapticOnLongPress,
            hapticOnLongPressRelease, vibrateOnRepeat, soundOnRepeat, vibrateOnDeleteSwipe) {
            val slopPx = 10.dp.toPx()
            val byWord = textEditing.backspaceSwipeUnit == BackspaceSwipeUnit.WORD
            // ⌦ runs the identical machine pointed the other way (issue #226):
            // the finger travels the way the deletion travels, so every step is
            // measured along [dir] and nothing else about the gesture forks.
            // Asked of the action rather than compared to [KeyAction.ForwardDelete],
            // so the text-editing pad's own delete keys — which are `Edit`
            // actions, not these — run this machine too (issue #226).
            val forward = key.action.deletesForward()
            val dir = if (forward) 1f else -1f
            fun canDeleteHere(): Boolean = if (forward) canForwardDelete() else canDelete()
            // The repeat clears whole words instead of characters (issue #216),
            // at its own slower cadence — a word every 50 ms empties a
            // paragraph before a finger can lift.
            val holdWords = textEditing.deleteHoldDeletesWords
            val repeatMs =
                (if (holdWords) keyRepeat.wordDeleteMs else keyRepeat.deleteMs).toLong()
            // Words accelerate: the first costs a deliberate drag; later ones
            // get cheaper, down to a floor, so clearing a sentence is one long
            // pull but a flick can never take more than a word or two.
            //
            // The whole curve is derived from the one setting, in the same
            // proportions the fixed 72/56/6/28 dp had, so a user who shortens
            // the first pull shortens the rest with it rather than ending up
            // with a first word that costs less than the second.
            val firstStepDp = textEditing.backspaceWordStepDp.toFloat()
            val firstStepPx = firstStepDp.dp.toPx()
            val nextStepPx = (firstStepDp * NEXT_WORD_STEP_RATIO).dp.toPx()
            val stepShrinkPx = (firstStepDp * WORD_STEP_SHRINK_RATIO).dp.toPx()
            val minStepPx = (firstStepDp * MIN_WORD_STEP_RATIO).dp.toPx()
            // Characters do not: one letter is one letter, and a curve would
            // make the count the finger is watching unpredictable. It is also
            // why the character step is its own setting rather than a fraction
            // of the word one (issue #36).
            val charStepPx = textEditing.backspaceCharStepDp.dp.toPx()
            // How far the finger still has to travel for the next unit, given
            // how many it has already taken.
            fun stepPx(taken: Int): Float = when {
                !byWord -> charStepPx
                taken == 0 -> firstStepPx
                else -> (nextStepPx - (taken - 1) * stepShrinkPx).coerceAtLeast(minStepPx)
            }
            fun stepFeedback() = if (vibrateOnDeleteSwipe) onKeyPress() else onKeySound()
            awaitEachGesture {
                val down = awaitFirstDown()
                setPressed(true)
                onKeyPress()
                var swiping = false
                // Units the swipe has taken so far: selected and still
                // returnable while a preview is up, already gone when not.
                var taken = 0
                // Whether the field is showing what the release will delete.
                // Starts as the setting and can only be given up, when an
                // editor turns out not to be able to hold a selection.
                var previewing = textEditing.backspaceSwipePreview
                // X the next step is measured from: the press point until the
                // first unit goes, then walked one step at a time.
                var anchorX = down.position.x
                var longPressFired = false
                val repeat = scope.launch {
                    delay(keyRepeat.startDelayMs.toLong())
                    longPressFired = true
                    while (canDeleteHere()) {
                        repeatFeedback(vibrateOnRepeat, soundOnRepeat, onKeyPress, onKeySound, onKeyHaptic)
                        // Through the swipe's own delete rather than the key's:
                        // a word clear is the swipe's one-step call, and going
                        // by the key would repeat a single character.
                        if (holdWords) deleteSwipe.onDeleteUnit(true, forward) else onKeyRepeat(key)
                        delay(repeatMs)
                    }
                }
                while (true) {
                    val event = awaitPointerEvent()
                    val change = event.changes.firstOrNull { it.id == down.id } ?: break
                    if (!change.pressed) {
                        change.consume()
                        break
                    }
                    if (!swiping && abs(change.position.x - down.position.x) > slopPx) {
                        swiping = true
                        repeat.cancel()
                        anchorX = down.position.x
                    }
                    if (swiping) {
                        // Claim the drag so nothing upstream reinterprets it.
                        change.consume()
                        // How far the finger has gone *the way the deletion
                        // goes* since the anchor; negative is a drag back.
                        fun travelled(): Float = (change.position.x - anchorX) * dir
                        while (travelled() >= stepPx(taken)) {
                            // Held over the whole iteration: the anchor only
                            // walks for a step that was actually taken, so a
                            // swipe stopped by the start of the text does not
                            // silently owe the drag back an extra step before
                            // the preview starts shrinking again.
                            val step = stepPx(taken)
                            if (previewing) {
                                val covered = deleteSwipe.onSelect(taken + 1, byWord, forward)
                                if (covered >= 0) {
                                    // A preview that stops growing has reached
                                    // the start of the text: no buzz, and no
                                    // step, for a drag that deletes nothing.
                                    if (covered <= taken) break
                                    anchorX += step * dir
                                    taken = covered
                                    stepFeedback()
                                    continue
                                }
                                // No preview to be had here (a panel search owns
                                // backspace, or the editor will not say where its
                                // cursor is). Bank what is already selected and
                                // delete outright from here on.
                                if (taken > 0) deleteSwipe.onCommit()
                                previewing = false
                                taken = 0
                            }
                            if (!canDeleteHere()) break
                            anchorX += step * dir
                            taken++
                            stepFeedback()
                            deleteSwipe.onDeleteUnit(byWord, forward)
                        }
                        if (previewing) {
                            // Dragging back gives the text back a unit at a
                            // time — the whole point of selecting first. The
                            // step returned is the one that was spent to take
                            // the unit, so the gesture retraces its own path.
                            while (taken > 0 && -travelled() >= stepPx(taken - 1)) {
                                anchorX -= stepPx(taken - 1) * dir
                                taken--
                                stepFeedback()
                                deleteSwipe.onSelect(taken, byWord, forward)
                            }
                        } else if (travelled() < 0f) {
                            // Nothing to give back once the text is gone, so a
                            // reversal only re-anchors and resets the
                            // acceleration: it stops the run, never replays it.
                            anchorX = change.position.x
                            taken = 0
                        }
                    }
                }
                repeat.cancel()
                setPressed(false)
                onKeyRelease()
                when {
                    // The lift is what deletes, once the finger has had the
                    // whole drag to change its mind.
                    swiping && previewing && taken > 0 -> deleteSwipe.onCommit()
                    // Dragged out and all the way back: the field goes back to
                    // how the swipe found it, and nothing is deleted.
                    swiping && previewing -> deleteSwipe.onCancel()
                    // The swipe already did the deleting.
                    swiping -> Unit
                    !longPressFired -> onKey(key)
                    hapticOnLongPressRelease -> onKeyPress()
                }
            }
        }
    } else if ((key.action == KeyAction.Text || key.action is KeyAction.KeymanKey) && key.flick.isNotEmpty()) {
        // A 12-key kana pad key: a tap commits the centre kana, a directional
        // flick past the slop commits that arm's kana instead. A Keyman key's
        // flicks work the same way, each arm being a key of its own that
        // [flickKey] hands to the rules. One pointer owns
        // the whole gesture (like space/backspace) so the cross popup can track
        // the live direction; a long press still opens the alternates popup.
        Modifier.pointerInput(
            key, longPressDelayMs, hapticOnLongPress, hapticOnLongPressRelease, alternates,
        ) {
            val slopPx = 22.dp.toPx()
            val reachPx = AlternatesReachDp.toPx()
            val steerPx = AlternatesSteerDp.toPx()
            awaitEachGesture {
                val down = awaitFirstDown()
                setPressed(true)
                onKeyPress()
                var dir: FlickDirection? = null
                var longFired = false
                val longJob = if (key.opensAlternatesPopup()) {
                    scope.launch {
                        delay(longPressDelayMs.toLong())
                        if (dir == null) {
                            longFired = true
                            if (hapticOnLongPress) onKeyPress()
                            openAlternates()
                        }
                    }
                } else {
                    null
                }
                while (true) {
                    val event = awaitPointerEvent()
                    val change = event.changes.firstOrNull { it.id == down.id } ?: break
                    if (!change.pressed) { change.consume(); break }
                    // The popup is up: the finger is choosing in it, not picking
                    // a kana arm. The two cannot both read this drag, and the
                    // popup is the one the user is looking at.
                    if (longFired && alternates != null) {
                        alternates.moveTo(change.position, reachPx, steerPx)
                        change.consume()
                        continue
                    }
                    val dx = change.position.x - down.position.x
                    val dy = change.position.y - down.position.y
                    // Dominant axis picks the arm; only directions the key
                    // actually defines count, so a flick toward an empty arm
                    // falls back to the centre tap rather than committing nothing.
                    val raw = when {
                        max(abs(dx), abs(dy)) < slopPx -> null
                        abs(dx) >= abs(dy) -> if (dx < 0) FlickDirection.LEFT else FlickDirection.RIGHT
                        else -> if (dy < 0) FlickDirection.UP else FlickDirection.DOWN
                    }
                    val resolved = raw?.takeIf { key.flick.containsKey(it) }
                    if (resolved != dir) {
                        dir = resolved
                        setFlickDirection(dir)
                        // Committing to a flick arm cancels the pending long press.
                        if (dir != null) longJob?.cancel()
                    }
                    change.consume()
                }
                longJob?.cancel()
                setPressed(false)
                onKeyRelease()
                setFlickDirection(null)
                val chosen = dir?.let { key.flickKey(it) }
                when {
                    chosen != null -> onKey(chosen)
                    // The long press already opened alternates; release commits
                    // what the popup has highlighted, and never the centre kana.
                    longFired -> {
                        alternates?.commit()
                        if (hapticOnLongPressRelease) onKeyPress()
                    }
                    else -> onKey(key)
                }
            }
        }
    } else {
        // Settings are part of the pointerInput keys: pointerInput only
        // restarts when its keys change, so leaving them out would keep a
        // stale closure alive (e.g. release haptics still firing after the
        // toggle was turned off).
        Modifier.pointerInput(key, spaceShortSwipe, spaceLongSwipe, longPressDelayMs, keyRepeat,
            hapticOnLongPress, hapticOnLongPressRelease, vibrateOnSpace, vibrateOnRepeat,
            soundOnRepeat, alternates) {
            val reachPx = AlternatesReachDp.toPx()
            val steerPx = AlternatesSteerDp.toPx()
            // Raw per-pointer tracking rather than detectTapGestures, which
            // handles one gesture at a time per key: a second finger landing
            // on the same key before the first lifts (burst double-taps) was
            // swallowed. Here every pointer gets its own press lifecycle.
            class Press {
                var longPressFired = false
                var job: Job? = null
                /**
                 * This press opened the alternates popup and is steering it, so
                 * its moves choose an entry and its lift commits one. Only the
                 * finger that opened the popup owns it: a second finger landing
                 * on the same key is its own press and types normally.
                 */
                var holdsAlternates = false
                /**
                 * This press armed selection mode for as long as it lasts
                 * (issue #41), so its release has to hand it back. Every exit
                 * below checks it — a stolen pointer as much as a clean lift.
                 */
                var armedSelection = false
            }
            val presses = HashMap<PointerId, Press>()
            awaitPointerEventScope {
                while (true) {
                    val event = awaitPointerEvent()
                    for (change in event.changes) {
                        val press = presses[change.id]
                        when {
                            press == null && change.changedToDown() -> {
                                val p = Press()
                                presses[change.id] = p
                                setPressed(true)
                                // Space press buzz is gated on its own toggle;
                                // the key sound (if on) still plays either way.
                                if (key.action == KeyAction.Space && !vibrateOnSpace) {
                                    onKeySound()
                                } else {
                                    onKeyPress()
                                }
                                // A braille dot key chords: it reports the press
                                // itself (the chord engine gathers dots on the way
                                // down, commits when the last finger lifts) and has
                                // no tap-vs-long-press distinction, so no timer.
                                // Through the un-debounced sink: the tremor filter
                                // would eat the up half of a quick chord and leave
                                // the engine counting a finger that already left.
                                if (key.action is KeyAction.BrailleDot) {
                                    onKeyRepeat(key)
                                    continue
                                }
                                // One timer, two meanings: on a repeating key it
                                // is how long before the repeat starts, and on
                                // every other key it is how long before the
                                // accent popup opens. They were the same number
                                // until the repeat got its own, so pick here
                                // rather than after the wait.
                                // Issue #57: a spacebar carrying alternates has
                                // given its hold away, so it stops repeating —
                                // the repeat is the default the popup replaces,
                                // and a second tap still types a second space.
                                // A text-editing key repeats when its operation
                                // does (the moves, backspace), at the text-edit
                                // tool's own cadence; Home, End and the selection
                                // commands hold to their alternates instead. And
                                // any key at all repeats when its author said so
                                // (issue #231) — the answer lives on the key so
                                // the sheet that offers the switch and the draw
                                // that drops the hint cannot disagree with this.
                                val editOp = (key.action as? KeyAction.Edit)?.op
                                val repeats = key.holdRepeats()
                                p.job = scope.launch {
                                    delay(
                                        if (repeats) keyRepeat.startDelayMs.toLong()
                                        else longPressDelayMs.toLong(),
                                    )
                                    p.longPressFired = true
                                    if (repeats) {
                                        // Space and the two deletes each hold to
                                        // a different purpose, so each has its
                                        // own cadence.
                                        val deletesBack = key.action.deletesBackward()
                                        val deletesFwd = key.action.deletesForward()
                                        // A held delete key can clear whole
                                        // words (issue #216), which is slower
                                        // on purpose and so keeps its own
                                        // number. The text-edit pad's delete
                                        // keys are delete keys too (issue
                                        // #226), so they count here as well.
                                        val holdWords = textEditing.deleteHoldDeletesWords &&
                                            (deletesBack || deletesFwd)
                                        val intervalMs = when {
                                            key.action == KeyAction.Space -> keyRepeat.spaceMs
                                            holdWords -> keyRepeat.wordDeleteMs
                                            // Before the edit-key cadence, so a
                                            // delete key on the pad repeats at
                                            // the delete interval like every
                                            // other delete key (issue #226).
                                            deletesBack || deletesFwd -> keyRepeat.deleteMs
                                            editOp != null -> textEditing.repeatMs
                                            // Everything left is a key an author
                                            // turned the repeat on for.
                                            else -> keyRepeat.customKeyMs
                                        }.toLong()
                                        // Held backspace stops once there is
                                        // nothing left to delete — no point
                                        // buzzing against an empty field. ⌦
                                        // runs out at the other end of the text,
                                        // so it polls its own predicate.
                                        while (
                                            when {
                                                deletesBack -> canDelete()
                                                deletesFwd -> canForwardDelete()
                                                else -> true
                                            }
                                        ) {
                                            repeatFeedback(
                                                vibrateOnRepeat, soundOnRepeat,
                                                onKeyPress, onKeySound, onKeyHaptic,
                                            )
                                            // The swipe's one-step call is what
                                            // knows how to take a word; the key
                                            // itself only ever takes one
                                            // character.
                                            if (holdWords) {
                                                deleteSwipe.onDeleteUnit(true, deletesFwd)
                                            } else {
                                                onKeyRepeat(key)
                                            }
                                            delay(intervalMs)
                                        }
                                    } else if (key.clipboardAction != null) {
                                        // Clipboard shortcut replaces the alternates popup
                                        // on this key; the action fires immediately.
                                        if (hapticOnLongPress) onKeyPress()
                                        key.clipboardAction?.let(onClipboardKey)
                                    } else if (key.opensAlternatesPopup()) {
                                        p.holdsAlternates = alternates != null
                                        // Characters, actions, or both: any key with
                                        // alternates opens the popup, which is what
                                        // puts them on the enter key (issue #22).
                                        //
                                        // Tactile cue that the long press registered and the
                                        // finger can be released (alternates are open / the
                                        // long-press action fired). Delete/space skip it:
                                        // their repeat loop already buzzes per repeat.
                                        if (hapticOnLongPress) onKeyPress()
                                        openAlternates()
                                    } else if (key.action == KeyAction.Symbols &&
                                        symbolsLongPressNumpad
                                    ) {
                                        // Opt-in: long-pressing ?123 opens the
                                        // numpad panel instead of acting like a tap.
                                        if (hapticOnLongPress) onKeyPress()
                                        onKey(key.copy(action = KeyAction.Numpad))
                                    } else if (key.action == KeyAction.LanguageSwitch) {
                                        // Tap cycles to the next language; the
                                        // long press opens the full picker.
                                        if (hapticOnLongPress) onKeyPress()
                                        openLanguagePicker()
                                    } else if (
                                        editOp == TextEditAction.SELECT &&
                                        textEditing.selectionModeHold
                                    ) {
                                        // Issue #41: the same momentary arm the
                                        // Selection mode tool's hold gives —
                                        // selection extends while the finger is
                                        // down and stops when it lifts. Below
                                        // the alternates branch on purpose: a
                                        // Select key the user has hung a second
                                        // action on keeps that action, and the
                                        // panel editor says so as it is bound.
                                        if (hapticOnLongPress) onKeyPress()
                                        p.armedSelection = true
                                        onSelectionHold(true)
                                    } else {
                                        // No alternates: long press behaves like a tap.
                                        if (hapticOnLongPress) onKeyPress()
                                        onKey(key)
                                    }
                                }
                            }
                            // Another handler claimed the pointer (glide typing
                            // consumed the move/up on the Initial pass): the
                            // press must not commit.
                            press != null && change.isConsumed -> {
                                press.job?.cancel()
                                if (press.holdsAlternates) alternates?.cancel()
                                if (press.armedSelection) onSelectionHold(false)
                                presses.remove(change.id)
                                if (presses.isEmpty()) setPressed(false)
                                onKeyRelease()
                                // The chord engine counted this finger on the way
                                // down; a stolen pointer still has to count as a
                                // lift or the engine waits forever for it.
                                if (key.action is KeyAction.BrailleDot) {
                                    onKeyRepeat(brailleRelease(key))
                                }
                            }
                            press != null && change.changedToUp() -> {
                                change.consume()
                                press.job?.cancel()
                                if (press.armedSelection) onSelectionHold(false)
                                presses.remove(change.id)
                                if (presses.isEmpty()) setPressed(false)
                                onKeyRelease()
                                if (key.action is KeyAction.BrailleDot) {
                                    // No bounds test: the dot was gathered on the
                                    // press, so the lift only closes the chord —
                                    // sliding off cannot un-press what already
                                    // counted, it just must not strand the engine.
                                    onKeyRepeat(brailleRelease(key))
                                    continue
                                }
                                // Forgiving bounds: a sloppy fast tap that drifts
                                // slightly off the cell still commits; a deliberate
                                // slide well away (≥ half a key beyond the edge)
                                // cancels, preserving slide-off-to-cancel.
                                val inBounds =
                                    change.position.x > -size.width * 0.5f &&
                                        change.position.x < size.width * 1.5f &&
                                        change.position.y > -size.height * 0.5f &&
                                        change.position.y < size.height * 1.5f
                                when {
                                    // Smart key-hit may swap in a likelier
                                    // neighbour chosen when this pointer went down.
                                    !press.longPressFired ->
                                        if (inBounds) onKey(smartResolve(key, change.id))
                                    // The lift chooses: whatever the popup has
                                    // highlighted, which is the first entry when
                                    // the finger never moved off the key. No
                                    // bounds test of its own — the highlight is
                                    // already null once the finger has strayed
                                    // out of reach of the popup.
                                    press.holdsAlternates -> {
                                        alternates?.commit()
                                        if (hapticOnLongPressRelease) onKeyPress()
                                    }
                                    hapticOnLongPressRelease -> onKeyPress()
                                }
                            }
                            // Steering an open popup. Last, so a lift or a
                            // stolen pointer is dealt with first; the popup is
                            // in a window of its own, so these moves keep
                            // arriving here even under it.
                            press != null && press.holdsAlternates && change.pressed -> {
                                alternates?.moveTo(change.position, reachPx, steerPx)
                                change.consume()
                            }
                        }
                    }
                }
            }
        }
    }
)

// ---- emoji panel ----

/** Sentinel tab id for the history tab; ★ avoids clashing with catalog categories. */
internal const val RECENT_TAB = "★recent"

/** Sentinel tab ids for the two optional text-art tabs. See [TextArt]. */
internal const val KAOMOJI_TAB = "★kaomoji"
internal const val EMOTICON_TAB = "★emoticon"

/**
 * Tab-strip label for the text-art tabs. They get a glyph instead of an icon:
 * two more smiley icons next to the existing ones would be indistinguishable,
 * and the glyph says exactly what the tab holds.
 */
internal fun textArtTabLabel(tab: String): String? = when (tab) {
    KAOMOJI_TAB -> "^_^"
    EMOTICON_TAB -> ":)"
    else -> null
}

/**
 * Tab key → icon slot. The history tab is two slots, not one: "recent" and
 * "most used" are different orderings and wear different glyphs, so a pack can
 * replace them independently. The text-art tabs have no slot — they draw
 * [textArtTabLabel] instead of an icon.
 */
internal fun emojiTabSlot(tab: String, mostUsed: Boolean): String = when (tab) {
    RECENT_TAB -> if (mostUsed) IconSlots.EMOJI_TAB_MOST_USED else IconSlots.EMOJI_TAB_RECENT
    else -> IconSlots.forEmojiCategory(tab)
}

/**
 * One compact emoji tab: a 20dp icon over a 2dp selection bar, in a plain
 * weighted cell so search + every category share the row evenly. [label]
 * substitutes a short glyph for the icon (the text-art tabs use it).
 *
 * [bar] false leaves the bar's 2dp slot empty for a row that draws one bar of
 * its own across every tab ([emojiTabIndicator]), so the icons sit exactly
 * where they would with a bar under each.
 */
@Composable
internal fun RowScope.EmojiTab(
    slot: String,
    description: String,
    selected: Boolean,
    onClick: () -> Unit,
    label: String? = null,
    focused: Boolean = false,
    bar: Boolean = true,
) {
    Column(
        modifier = Modifier
            .weight(1f)
            .height(EmojiTabHeight)
            .focusRing(focused, RoundedCornerShape(8.dp))
            .clickable(onClick = onClick),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.Center) {
            val tint = if (selected) MaterialTheme.colorScheme.onSurface
            else MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
            if (label != null) {
                Text(
                    text = label,
                    // Never wraps: the cell is one tab wide and a broken
                    // "^_^" would read as a rendering bug, not a label.
                    maxLines = 1,
                    softWrap = false,
                    // Smaller than the 20dp icons it sits beside: with a dozen
                    // categories every tab cell is barely 28dp wide.
                    fontSize = 11.sp,
                    color = tint,
                    modifier = Modifier.semantics { contentDescription = description },
                )
            } else {
                SlotIcon(
                    slot,
                    contentDescription = description,
                    modifier = Modifier.size(20.dp),
                    tint = tint,
                )
            }
        }
        Box(
            modifier = Modifier
                .fillMaxWidth(0.6f)
                .height(2.dp)
                .background(
                    if (bar && selected) MaterialTheme.colorScheme.onSurface else Color.Transparent,
                    RoundedCornerShape(1.dp),
                ),
        )
    }
}

/** Height of an [EmojiTab] cell, which the row's own indicator is placed against. */
internal val EmojiTabHeight = 32.dp

/**
 * One selection bar for a whole row of [count] evenly weighted [EmojiTab]s,
 * drawn where the pager is rather than under whichever tab is selected: it
 * slides with a tap's page scroll and follows a swipe under the finger, instead
 * of blinking out under one tab and in under the next.
 *
 * [position] is read in the draw phase only (the pager's page plus its offset
 * fraction), so a swipe repaints the row and never recomposes it. Goes after
 * the row's own padding, where the tabs' cells start.
 */
internal fun Modifier.emojiTabIndicator(
    count: Int,
    color: Color,
    position: () -> Float,
): Modifier = if (count <= 0) this else drawBehind {
    val tabWidth = size.width / count
    val barWidth = tabWidth * 0.6f
    val barHeight = 2.dp.toPx()
    // The cells are centred in the row and never taller than it (see EmojiTab).
    val cellHeight = minOf(EmojiTabHeight.toPx(), size.height)
    val top = (size.height - cellHeight) / 2f + cellHeight - barHeight
    val at = position().coerceIn(0f, (count - 1).toFloat())
    val start = at * tabWidth + (tabWidth - barWidth) / 2f
    // A right-to-left row lays its first tab out at the right-hand end.
    val left = if (layoutDirection == LayoutDirection.Rtl) size.width - start - barWidth else start
    drawRoundRect(
        color = color,
        topLeft = Offset(left, top),
        size = Size(barWidth, barHeight),
        cornerRadius = CornerRadius(1.dp.toPx()),
    )
}

/**
 * The panel's search box: a tappable pill showing the live query, with a
 * hold-to-repeat backspace that edits the real text field while search mode
 * stays up. Shared by the in-panel layout and the full-bleed header.
 */
@Composable
internal fun EmojiSearchField(
    state: KeyboardUiState,
    onEmojiQueryTap: () -> Unit,
    onSearchFieldDelete: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val feedback = LocalKeyPressFeedback.current
    val keySound = LocalKeySound.current
    val canDeleteField = LocalCanDeleteField.current
    val scope = rememberCoroutineScope()
    val vibrateOnRepeat = state.settings.feedback.vibrateOnRepeat
    Row(
        modifier = modifier
            .background(MaterialTheme.colorScheme.surfaceContainer, RoundedCornerShape(20.dp))
            .clickable { onEmojiQueryTap() }
            .padding(horizontal = 12.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Icon(
            Icons.Outlined.Search,
            contentDescription = null,
            modifier = Modifier.size(18.dp),
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Box(modifier = Modifier.width(8.dp))
        SearchQueryText(
            query = state.emojiQuery,
            placeholder = stringResource(R.string.ime_emoji_search_hint),
            active = state.emojiSearchActive,
            textColor = MaterialTheme.colorScheme.onSurface,
            placeholderColor = MaterialTheme.colorScheme.onSurfaceVariant,
            fontSize = 14.sp,
            modifier = Modifier.weight(1f),
        )
        // While searching, the keys type into the query — so an emoji just
        // inserted from the results can't be deleted from the field with
        // them. This backspace edits the real text field (with
        // hold-to-repeat), keeping search mode up.
        if (state.emojiSearchActive) {
            Icon(
                Icons.AutoMirrored.Outlined.Backspace,
                contentDescription = stringResource(R.string.ime_emoji_search_delete_desc),
                modifier = Modifier
                    .padding(start = 8.dp)
                    .size(18.dp)
                    .pointerInput(
                        state.settings.longPressDelayMs,
                        state.settings.keyRepeat.deleteMs,
                        vibrateOnRepeat,
                    ) {
                        detectTapGestures(
                            onPress = {
                                feedback()
                                onSearchFieldDelete()
                                val repeat = scope.launch {
                                    delay(state.settings.longPressDelayMs.toLong())
                                    while (canDeleteField()) {
                                        if (vibrateOnRepeat) feedback() else keySound()
                                        onSearchFieldDelete()
                                        delay(state.settings.keyRepeat.deleteMs.toLong())
                                    }
                                }
                                tryAwaitRelease()
                                repeat.cancel()
                            },
                        )
                    },
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * The face to show for an emoji [base] in the panel grid and in search: the
 * global default skin tone, or the last-used variant when that override is
 * enabled. Mirrors the IME's `applyEmojiTone`, so what is drawn is what a tap
 * commits.
 */
internal fun emojiDisplay(state: KeyboardUiState, base: String): String {
    val emoji = state.settings.emoji
    return state.emojiVariants.tonedDisplay(
        base = base,
        tone = emoji.defaultSkinTone.toneIndex,
        preferred = state.emojiVariantPrefs[base],
        overrideWithPreferred = emoji.toneOverrideByLastUsed,
    )
}

/**
 * A text-art tab's grid — kaomoji when [kaomoji], Western emoticons
 * otherwise. Grouped by mood behind full-width headers, because a flat 200-
 * entry wall of faces is unskimmable.
 *
 * Kaomoji get much wider cells than emoticons: ":-)" is three characters and
 * "(╯°□°）╯︵ ┻━┻" is thirteen, so one column width for both would either
 * waste most of the row or squeeze the long ones to nothing.
 */
@Composable
internal fun TextArtGrid(kaomoji: Boolean, onTap: (String) -> Unit) {
    val groups = if (kaomoji) TextArt.kaomoji else TextArt.emoticons
    LazyVerticalGrid(
        columns = GridCells.Adaptive(minSize = if (kaomoji) 132.dp else 64.dp),
        modifier = Modifier.fillMaxSize(),
        contentPadding = PaddingValues(horizontal = 6.dp, vertical = 4.dp),
    ) {
        groups.forEach { group ->
            item(key = "§${group.name}", span = { GridItemSpan(maxLineSpan) }) {
                Text(
                    text = group.name,
                    modifier = Modifier.padding(start = 4.dp, top = 8.dp, bottom = 2.dp),
                    fontSize = 11.sp,
                    fontWeight = FontWeight.Medium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                )
            }
            // Keyed by group + entry: a handful of faces appear in more than
            // one mood, and a bare entry key would collide across groups.
            items(group.items, key = { "${group.name}\u0000$it" }) { art ->
                TextArtCell(art = art, onTap = onTap)
            }
        }
    }
}

/**
 * One text-art cell: a key-coloured chip whose glyph shrinks until it fits on
 * a single line. Wrapping or ellipsizing are both wrong here — half a kaomoji
 * is unrecognisable, and the user is picking by shape, not by name.
 */
@Composable
private fun TextArtCell(art: String, onTap: (String) -> Unit) {
    val kb = LocalKbTheme.current
    val feedback = LocalKeyPressFeedback.current
    // Reset per entry: cells are recycled across scroll positions, so a size
    // shrunk to fit a long kaomoji would otherwise stick to a short one.
    var fontSize by remember(art) { mutableStateOf(15.sp) }
    var settled by remember(art) { mutableStateOf(false) }
    Box(
        modifier = Modifier
            .padding(3.dp)
            .fillMaxWidth()
            .height(38.dp)
            .background(kb.keyFace(kb.key), kb.keyShape())
            .clickable {
                feedback()
                onTap(art)
            },
        contentAlignment = Alignment.Center,
    ) {
        Text(
            text = art,
            modifier = Modifier
                .padding(horizontal = 4.dp)
                // Hidden until the shrink loop settles: the first frame is
                // laid out at full size and would visibly overflow the chip.
                .graphicsLayer { alpha = if (settled) 1f else 0f },
            maxLines = 1,
            softWrap = false,
            fontSize = fontSize,
            color = kb.keyText,
            onTextLayout = { result ->
                if (result.hasVisualOverflow && fontSize.value > 8f) {
                    fontSize = (fontSize.value * 0.88f).sp
                } else {
                    settled = true
                }
            },
        )
    }
}

/**
 * One emoji in the grid. Tap commits [display] (the user's preferred
 * variant of [base]); long-press opens the variant popup with the
 * favourite toggle, gender variants, skin tones, and — for two-person
 * emojis like the handshake — a per-person tone selector.
 */
@Composable
internal fun EmojiCell(
    base: String,
    display: String,
    state: KeyboardUiState,
    genderVariants: List<String>,
    onTap: (String) -> Unit,
    onPick: (String) -> Unit,
    onFavourite: (String) -> Unit,
    onReorderFavourites: (() -> Unit)? = null,
    onLongPress: (String) -> Unit = {},
    onLongPressEnd: () -> Unit = {},
    onAnimatedSend: (String) -> Unit = {},
    onStickerSend: (String) -> Unit = {},
    onRemove: ((String) -> Unit)? = null,
    focused: Boolean = false,
) {
    var showVariants by remember { mutableStateOf(false) }
    val onHaptic = LocalHapticFeedback.current
    Box {
        Text(
            text = LocalEmojiShaper.current.shape(display),
            modifier = Modifier
                .focusRing(focused)
                .pointerInput(base, display) {
                    detectTapGestures(
                        onTap = { onTap(display) },
                        onLongPress = {
                            // Haptic only: the key sound would read as "emoji
                            // inserted", which a long press does not do.
                            if (state.settings.haptics.onLongPress) onHaptic()
                            showVariants = true
                            onLongPress(display)
                        },
                    )
                }
                .padding(6.dp),
            fontSize = state.settings.emoji.gridEmojiSize.sp,
            fontFamily = emojiFamilyFor(display),
        )
        if (showVariants) {
            EmojiVariantPopup(
                base = base,
                display = display,
                name = if (state.settings.emojiLongPressName) {
                    // Named in the language being typed when a pack for it is
                    // installed, and in the catalog's own (Unicode) name
                    // otherwise — never in whatever other language happens to
                    // have a pack on the device.
                    EmojiNames.of(
                        catalog = state.emojiCatalog,
                        emoji = display,
                        base = base,
                        localised = state.emojiNamesByLang[state.language.id].orEmpty(),
                    )
                } else {
                    null
                },
                index = state.emojiVariants,
                genderVariants = genderVariants,
                favourite = display in state.emojiFavourites,
                animated = state.animatedEmojiOffer(display),
                onAnimatedSend = { onAnimatedSend(display) },
                sticker = state.canSendEmojiSticker(),
                stickerSending = state.mediaDownloadingId == emojiStickerJobId(display),
                onStickerSend = { onStickerSend(display) },
                onDismiss = {
                    showVariants = false
                    onLongPressEnd()
                },
                onPick = {
                    showVariants = false
                    onLongPressEnd()
                    onPick(it)
                },
                onFavourite = onFavourite,
                onReorderFavourites = onReorderFavourites?.let { reorder ->
                    {
                        showVariants = false
                        onLongPressEnd()
                        reorder()
                    }
                },
                onRemove = onRemove?.let { remove ->
                    {
                        showVariants = false
                        onLongPressEnd()
                        remove(display)
                    }
                },
            )
        }
    }
}

/**
 * What the long-press popup knows about an emoji's animated version: the
 * preview file once it lands, whether it is still on its way, and whether the
 * GIF behind the send button is being fetched right now.
 */
internal data class AnimatedEmojiOffer(
    val file: File?,
    val loading: Boolean,
    val sending: Boolean,
    /** How far the GIF has come down, or null while that isn't known yet. */
    val progress: Float? = null,
    /** No preview is coming: data saving held it back, or its fetch failed. */
    val noPreview: Boolean = false,
) {
    /**
     * Whether the Send row is drawn. Normally only once the preview is on
     * screen, so nobody is offered an animation they haven't seen. But when no
     * preview is coming, waiting for one hid Send for good and left an empty
     * box: on a metered connection that took the feature away entirely, since
     * pressing Send is the only way to answer data saving's "ask".
     */
    val canSend: Boolean get() = file != null || noPreview

    /** Whether the preview slot is drawn: something is in it, or on its way. */
    val showsPreview: Boolean get() = file != null || !noPreview
}

/**
 * The animated version on offer for [emoji], or null when there is none to
 * offer: nothing is published for it, the setting is off, or the focused field
 * takes no images and a GIF would have nowhere to go.
 */
internal fun KeyboardUiState.animatedEmojiOffer(emoji: String): AnimatedEmojiOffer? {
    if (!settings.emoji.animated || !acceptsRichMedia) return null
    // Data saving turned this one off outright: no offer at all, since there
    // is nothing to say about it that a greyed-out button would say better.
    // "Ask each time" still offers it — the press is the answer, and only the
    // automatic preview is held back (see `onEmojiLongPressed`).
    if (dataSaver.decide(MeteredFeature.ANIMATED_EMOJI) == MeteredDecision.BLOCKED) return null
    val key = animatedEmoji.keyFor(emoji) ?: return null
    val sending = mediaDownloadingId == key
    return AnimatedEmojiOffer(
        file = animatedEmojiFile,
        loading = animatedEmojiLoading,
        sending = sending,
        progress = mediaDownloadProgress.takeIf { sending },
        noPreview = animatedEmojiNoPreview,
    )
}

/**
 * Whether the popup may offer to send [emoji] itself as a sticker. Unlike the
 * animation this needs nothing downloaded — the glyph is on the device — so it
 * turns only on the setting and on the field taking images at all.
 */
internal fun KeyboardUiState.canSendEmojiSticker(): Boolean =
    settings.emoji.sendAsSticker && acceptsRichMedia

/**
 * The id the service publishes while it draws [emoji] into a sticker, so the
 * row that started it can spin. Spelled in one place because both sides have
 * to agree on it.
 */
internal fun emojiStickerJobId(emoji: String): String = "emoji_sticker:$emoji"

/**
 * The animated-emoji block of the long-press popup: the animation itself,
 * looping, over a button that sends it as a GIF.
 *
 * The button waits for the preview, so there is never a control that says it
 * will send an animation nobody has seen yet, unless no preview is coming at
 * all (see [AnimatedEmojiOffer.canSend]). The credit line is not decoration:
 * the assets are Noto Animated Emoji, and CC BY 4.0 asks for attribution
 * wherever they are used.
 */
@Composable
private fun ColumnScope.AnimatedEmojiOffer(offer: AnimatedEmojiOffer, onSend: () -> Unit) {
    if (offer.showsPreview) {
        val loader = rememberMediaImageLoader()
        Box(
            modifier = Modifier
                .padding(horizontal = 12.dp, vertical = 4.dp)
                .size(96.dp)
                .align(Alignment.CenterHorizontally),
            contentAlignment = Alignment.Center,
        ) {
            if (offer.file != null) {
                AsyncImage(
                    model = offer.file,
                    contentDescription = null,
                    imageLoader = loader,
                    modifier = Modifier.matchParentSize(),
                    contentScale = ContentScale.Fit,
                )
            } else if (offer.loading) {
                CircularProgressIndicator(modifier = Modifier.size(22.dp), strokeWidth = 2.5.dp)
            }
        }
    }
    if (!offer.canSend) return
    PopupAction(
        icon = Icons.Outlined.PlayCircleOutline,
        label = stringResource(R.string.ime_emoji_send_animated),
        caption = stringResource(R.string.ime_emoji_animated_credit),
        busy = offer.sending,
        progress = offer.progress,
        onClick = onSend,
    )
}

/**
 * One tappable row of the long-press popup, with the same shape as the
 * favourite and remove rows above it. [busy] swaps the icon for a spinner,
 * which is what the send rows do while their file is being fetched or drawn —
 * the popup stays open through a send, so it has to show that something is
 * happening.
 *
 * [progress] fills that spinner in when there is a download behind it and its
 * size is known; a row that draws its file locally has nothing to count, and
 * keeps turning instead.
 */
@Composable
private fun PopupAction(
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    label: String,
    caption: String? = null,
    busy: Boolean = false,
    progress: Float? = null,
    onClick: () -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(enabled = !busy, onClick = onClick)
            .padding(horizontal = 12.dp, vertical = 12.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        if (busy && progress != null) {
            val fraction by animateFloatAsState(
                targetValue = progress,
                animationSpec = tween(durationMillis = 120, easing = LinearEasing),
                label = "animatedEmojiSendProgress",
            )
            CircularProgressIndicator(
                progress = { fraction },
                modifier = Modifier.size(22.dp),
                strokeWidth = 2.5.dp,
            )
        } else if (busy) {
            CircularProgressIndicator(modifier = Modifier.size(22.dp), strokeWidth = 2.5.dp)
        } else {
            Icon(
                icon,
                contentDescription = null,
                modifier = Modifier.size(22.dp),
                tint = MaterialTheme.colorScheme.primary,
            )
        }
        Box(modifier = Modifier.width(10.dp))
        Column {
            Text(label, fontSize = 15.sp, color = MaterialTheme.colorScheme.onSurface)
            if (caption != null) {
                Text(
                    caption,
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                )
            }
        }
    }
}

/**
 * How wide the long-press popup gets. Wide enough for "Send animated emoji"
 * and for six tone swatches in a row, and fixed so every action row is the
 * same tappable width rather than the width of its own words.
 */
private val PopupActionWidth = 300.dp

/** Fitzpatrick swatches for the two-person tone selector: neutral + 🏻..🏿. */
private val TONE_SWATCHES = listOf(
    Color(0xFFFFCC4D), Color(0xFFF7DECE), Color(0xFFF3D2A2),
    Color(0xFFD5AB88), Color(0xFFAF7E57), Color(0xFF7C533E),
)

@Composable
private fun EmojiVariantPopup(
    base: String,
    display: String,
    name: String?,
    index: EmojiVariantIndex,
    genderVariants: List<String>,
    favourite: Boolean,
    animated: AnimatedEmojiOffer?,
    onAnimatedSend: () -> Unit,
    sticker: Boolean,
    stickerSending: Boolean,
    onStickerSend: () -> Unit,
    onDismiss: () -> Unit,
    onPick: (String) -> Unit,
    onFavourite: (String) -> Unit,
    onReorderFavourites: (() -> Unit)? = null,
    onRemove: (() -> Unit)? = null,
) {
    val kb = LocalKbTheme.current
    Popup(
        popupPositionProvider = rememberAboveAnchorPopup(),
        onDismissRequest = onDismiss,
    ) {
        Surface(
            // Capped rather than wrapped: every row below fills this width, so
            // a tap anywhere along a row counts. Wrapping instead made each row
            // exactly as wide as its own label, and the empty space beside a
            // short one — most of the popup — did nothing.
            modifier = Modifier.widthIn(max = PopupActionWidth),
            shape = kb.popupShape(),
            color = kb.popup,
            border = kb.popupSurfaceBorder(),
            shadowElevation = elevationFor(kb.popupShapeKind, 8.dp),
        ) {
            // Roomy by design: these rows are the only way to favourite or
            // forget an emoji, and at the old 26dp height they were easy to
            // miss with the same finger that just long-pressed.
            Column(modifier = Modifier.padding(8.dp)) {
                if (name != null) {
                    Row(
                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Text(
                            text = LocalEmojiShaper.current.shape(display),
                            fontSize = 20.sp,
                            fontFamily = emojiFamilyFor(display),
                        )
                        Box(modifier = Modifier.width(10.dp))
                        // Long names wrap rather than stretch the popup: the
                        // whole thing is sized by its widest row, and a
                        // one-line "person with white cane facing right" would
                        // leave every row below it in empty space.
                        Text(
                            text = name.replaceFirstChar { it.uppercase() },
                            modifier = Modifier.widthIn(max = 180.dp),
                            fontSize = 14.sp,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.75f),
                        )
                    }
                }
                if (animated != null) {
                    AnimatedEmojiOffer(offer = animated, onSend = onAnimatedSend)
                }
                // Offered for every emoji, not only the animated ones: this is
                // the phone's own glyph, so there is always one to draw.
                if (sticker) {
                    PopupAction(
                        icon = Icons.Outlined.PhotoSizeSelectActual,
                        label = stringResource(R.string.ime_emoji_send_sticker),
                        busy = stickerSending,
                        onClick = onStickerSend,
                    )
                }
                // Favourite pins this emoji to the top of the history tab
                // and the favourites row.
                // Re-seeded when the real flag changes, not only when the
                // emoji does: keyed on display alone the local mirror went
                // stale the moment the store echoed back, so reopening the
                // popup could show an unstarred emoji as favourited.
                var starred by remember(display, favourite) { mutableStateOf(favourite) }
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            starred = !starred
                            onFavourite(display)
                        }
                        .padding(horizontal = 12.dp, vertical = 12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Icon(
                        if (starred) Icons.Outlined.Star else Icons.Outlined.StarBorder,
                        contentDescription = null,
                        modifier = Modifier.size(22.dp),
                        tint = MaterialTheme.colorScheme.primary,
                    )
                    Box(modifier = Modifier.width(10.dp))
                    Text(
                        stringResource(
                            if (starred) R.string.ime_emoji_favourited else R.string.ime_emoji_favourite,
                        ),
                        fontSize = 15.sp,
                        color = MaterialTheme.colorScheme.onSurface,
                    )
                }
                // Only favourites can be reordered, and only when there are at
                // least two (the caller passes null otherwise).
                if (favourite && onReorderFavourites != null) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { onReorderFavourites() }
                            .padding(horizontal = 12.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(
                            Icons.Outlined.DragHandle,
                            contentDescription = null,
                            modifier = Modifier.size(22.dp),
                            tint = MaterialTheme.colorScheme.primary,
                        )
                        Box(modifier = Modifier.width(10.dp))
                        Text(
                            stringResource(R.string.ime_emoji_reorder_favourites),
                            fontSize = 15.sp,
                            color = MaterialTheme.colorScheme.onSurface,
                        )
                    }
                }
                // History cells only: drop this emoji from recents/most-used.
                if (onRemove != null) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { onRemove() }
                            .padding(horizontal = 12.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(
                            Icons.Outlined.Delete,
                            contentDescription = null,
                            modifier = Modifier.size(22.dp),
                            tint = MaterialTheme.colorScheme.primary,
                        )
                        Box(modifier = Modifier.width(10.dp))
                        Text(
                            stringResource(R.string.ime_emoji_remove_from_recents),
                            fontSize = 15.sp,
                            color = MaterialTheme.colorScheme.onSurface,
                        )
                    }
                }
                val members = remember(base, genderVariants) { listOf(base) + genderVariants }
                if (index.hasDualTones(base) || genderVariants.any { index.hasDualTones(it) }) {
                    DualTonePicker(members = members, index = index, onPick = onPick)
                } else {
                    // One row per gender/role member, six cells when toned;
                    // toneless combination groups (families) just flow.
                    val cells = remember(members) { members.flatMap { index.popupVariants(it) } }
                    // A lone cell is the emoji itself — already shown in the
                    // name header, and a grid of one is just a second way to
                    // commit what a plain tap commits.
                    val variantRail = rememberScrollRailState()
                    if (cells.size > 1 || name == null) ScrollRail(
                        state = variantRail,
                        modifier = Modifier.heightIn(max = 260.dp),
                        fadeColor = kb.popup,
                        colors = kbRailColors(kb),
                    ) {
                        for (row in cells.chunked(6)) {
                            Row {
                                for (variant in row) {
                                    Text(
                                        text = LocalEmojiShaper.current.shape(variant),
                                        modifier = Modifier
                                            .clickable { onPick(variant) }
                                            .padding(horizontal = 9.dp, vertical = 9.dp),
                                        fontSize = 26.sp,
                                        fontFamily = emojiFamilyFor(variant),
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

/** Fixed row height inside [FavouritesReorderPopup], so drags map to slots. */
private val FavouriteReorderRowHeight = 48.dp

/**
 * A modal drag-to-reorder list for the favourites, opened from a favourited
 * emoji's long-press popup. Rendered as a [Popup] over the whole IME window
 * (a scrim swallows stray taps and doubles as tap-to-dismiss) rather than a
 * Compose Dialog, which needs a window token the IME does not hand out.
 *
 * The drag mechanic mirrors the settings-side ReorderDialog: each row carries
 * a handle, and dragging one past the next row's height swaps the two so the
 * item tracks the finger. The working copy only reaches the caller through
 * [onConfirm]; cancelling leaves the stored order alone.
 */
@Composable
internal fun FavouritesReorderPopup(
    favourites: List<String>,
    onConfirm: (List<String>) -> Unit,
    onDismiss: () -> Unit,
) {
    val kb = LocalKbTheme.current
    var working by remember { mutableStateOf(favourites) }
    // -1 = nothing being dragged.
    var dragIndex by remember { mutableIntStateOf(-1) }
    var dragOffset by remember { mutableFloatStateOf(0f) }
    val rowPx = with(LocalDensity.current) { FavouriteReorderRowHeight.toPx() }

    Popup(onDismissRequest = onDismiss) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black.copy(alpha = 0.5f))
                // Tap the scrim to dismiss; the surface below swallows its own.
                .pointerInput(Unit) { detectTapGestures { onDismiss() } },
            contentAlignment = Alignment.Center,
        ) {
            Surface(
                shape = kb.menuShape(),
                color = kb.popup,
                border = kb.popupSurfaceBorder(),
                shadowElevation = elevationFor(kb.menuShapeKind, 8.dp),
                modifier = Modifier
                    .padding(16.dp)
                    .fillMaxWidth(0.92f)
                    .fillMaxHeight(0.92f)
                    // Don't let taps inside the card fall through to the scrim.
                    .pointerInput(Unit) { detectTapGestures { } },
            ) {
                Column(modifier = Modifier.padding(12.dp)) {
                    Text(
                        stringResource(R.string.ime_emoji_reorder_favourites),
                        style = MaterialTheme.typography.titleMedium,
                        color = MaterialTheme.colorScheme.onSurface,
                        modifier = Modifier.padding(bottom = 4.dp),
                    )
                    Text(
                        stringResource(R.string.ime_emoji_reorder_hint),
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.padding(bottom = 8.dp),
                    )
                    Column(
                        modifier = Modifier
                            .weight(1f)
                            .verticalScroll(rememberScrollState()),
                    ) {
                        working.forEachIndexed { index, emoji ->
                            val dragging = index == dragIndex
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(FavouriteReorderRowHeight)
                                    // The dragged row rides above its neighbours.
                                    .zIndex(if (dragging) 1f else 0f)
                                    .graphicsLayer {
                                        translationY = if (dragging) dragOffset else 0f
                                    },
                            ) {
                                Text(
                                    stringResource(R.string.ime_emoji_reorder_index, index + 1),
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                    modifier = Modifier.width(28.dp),
                                )
                                Text(
                                    text = LocalEmojiShaper.current.shape(emoji),
                                    fontSize = 24.sp,
                                    fontFamily = emojiFamilyFor(emoji),
                                    modifier = Modifier.weight(1f),
                                )
                                Icon(
                                    Icons.Outlined.DragHandle,
                                    contentDescription = stringResource(
                                        R.string.ime_emoji_reorder_handle_desc, emoji,
                                    ),
                                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                                    modifier = Modifier
                                        .padding(start = 8.dp)
                                        .size(28.dp)
                                        // Keyed on Unit so a swap mid-drag never
                                        // restarts the gesture: slot `index` is
                                        // fixed for the life of the row, only the
                                        // item in it moves. `dragIndex` is live.
                                        .pointerInput(Unit) {
                                            detectDragGestures(
                                                onDragStart = {
                                                    dragIndex = index
                                                    dragOffset = 0f
                                                },
                                                onDragEnd = {
                                                    dragIndex = -1
                                                    dragOffset = 0f
                                                },
                                                onDragCancel = {
                                                    dragIndex = -1
                                                    dragOffset = 0f
                                                },
                                            ) { change, drag ->
                                                change.consume()
                                                dragOffset += drag.y
                                                val from = dragIndex
                                                val to = from + (dragOffset / rowPx).roundToInt()
                                                if (from >= 0 && to != from && to in working.indices) {
                                                    working = working.toMutableList().apply {
                                                        add(to, removeAt(from))
                                                    }
                                                    dragIndex = to
                                                    // Keep the offset relative to
                                                    // the row's new home, or the
                                                    // item would jump a full row.
                                                    dragOffset -= (to - from) * rowPx
                                                }
                                            }
                                        },
                                )
                            }
                        }
                    }
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 8.dp),
                        horizontalArrangement = Arrangement.End,
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        TextButton(onClick = onDismiss) {
                            Text(stringResource(CommonR.string.common_cancel))
                        }
                        TextButton(onClick = { onConfirm(working) }) {
                            Text(stringResource(CommonR.string.common_save))
                        }
                    }
                }
            }
        }
    }
}

/**
 * Gboard-style two-slot skin-tone selector for emojis where each person
 * has an independent tone (🤝, couples, holding hands…). The top row picks
 * the gender/role combination; the two swatch rows pick each person's
 * tone; tapping the live preview commits the exact RGI sequence.
 */
@Composable
private fun DualTonePicker(
    members: List<String>,
    index: EmojiVariantIndex,
    onPick: (String) -> Unit,
) {
    var member by remember { mutableStateOf(members.first()) }
    var first by remember { mutableIntStateOf(0) }
    var second by remember { mutableIntStateOf(0) }
    // Not every combination is RGI (a toned person can't shake a neutral
    // hand), so a pick on one side seeds the other side too.
    val preview = index.tonedPair(member, first, second) ?: member

    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        if (members.size > 1) {
            Row {
                for (candidate in members) {
                    Text(
                        text = LocalEmojiShaper.current.shape(candidate),
                        modifier = Modifier
                            .background(
                                if (candidate == member) {
                                    MaterialTheme.colorScheme.primary.copy(alpha = 0.25f)
                                } else {
                                    Color.Transparent
                                },
                                RoundedCornerShape(8.dp),
                            )
                            .clickable { member = candidate }
                            .padding(horizontal = 6.dp, vertical = 4.dp),
                        fontSize = 22.sp,
                        fontFamily = emojiFamilyFor(candidate),
                    )
                }
            }
        }
        Text(
            text = LocalEmojiShaper.current.shape(preview),
            modifier = Modifier
                .clickable { onPick(preview) }
                .padding(6.dp),
            fontSize = 34.sp,
            fontFamily = emojiFamilyFor(preview),
        )
        for (slot in 0..1) {
            Row(
                modifier = Modifier.padding(vertical = 3.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                for (tone in 0..5) {
                    val selected = tone == if (slot == 0) first else second
                    Box(
                        modifier = Modifier
                            .padding(horizontal = 3.dp)
                            .size(26.dp)
                            .background(TONE_SWATCHES[tone], CircleShape)
                            .then(
                                if (selected) {
                                    Modifier.border(
                                        2.dp, MaterialTheme.colorScheme.primary, CircleShape,
                                    )
                                } else {
                                    Modifier
                                }
                            )
                            .clickable {
                                if (tone == 0) {
                                    first = 0
                                    second = 0
                                } else if (slot == 0) {
                                    first = tone
                                    if (second == 0) second = tone
                                } else {
                                    second = tone
                                    if (first == 0) first = tone
                                }
                            },
                    )
                }
            }
        }
    }
}

/**
 * What a press and hold on a tool reaches, bundled into one [KeyboardScreen]
 * parameter for the reason [SnippetPanelCallbacks] is: its caller sits against
 * the JVM's 64K method-size ceiling, where every added parameter costs bytecode.
 * Selection mode needed a second callback, and the bundle pays for both.
 */
data class ToolHoldCallbacks(
    /** A stationary hold with nothing else bound: open that tool's settings page. */
    val onSettings: (ToolbarTool) -> Unit = {},
    /**
     * A stationary hold on a tool the user bound another tool to: run the bound
     * one. Its own callback rather than the tap dispatcher because the bound
     * tool need not be on the toolbar, and the tap path refuses those.
     */
    val onHoldAction: (ToolbarTool) -> Unit = {},
    /**
     * The Selection mode tool held down (true) and let go (false). Always paired:
     * every path out of the gesture releases what it armed.
     */
    val onSelectionHold: (Boolean) -> Unit = {},
    /**
     * The Trackpad tool held down (true) and let go (false): the trackpad panel
     * for as long as the hold lasts. Paired like [onSelectionHold].
     */
    val onTrackpadHold: (Boolean) -> Unit = {},
    /**
     * A voice typing mode picked off the Voice tool's hold menu (#173):
     * one of the `VoiceBarSettings.TYPING_*` tokens. Persisted and started
     * by the service in one move.
     */
    val onVoiceModePick: (String) -> Unit = {},
    /**
     * The dictionary bar's two callbacks (issue #51). Not a hold at all; they
     * ride this bundle because it is the nearest one already on the call and
     * the caller cannot afford another parameter (see [DictionaryBarCallbacks]).
     */
    val dictionaryBar: DictionaryBarCallbacks = DictionaryBarCallbacks(),
    /** The vocabulary panel's and chips' callbacks; here for the same reason as [dictionaryBar]. */
    val vocab: VocabCallbacks = VocabCallbacks(),
    /** The stickers offered while typing (#329); here for the same reason as [dictionaryBar]. */
    val stickerOffer: StickerOfferCallbacks = StickerOfferCallbacks(),
    /**
     * The selection bar's callbacks (a chip, a ladder pick, an AI button).
     * Ride this bundle for the reason [dictionaryBar] does: it is the nearest
     * one already on the call, and the caller cannot afford another parameter.
     */
    val selection: SelectionMacroCallbacks = SelectionMacroCallbacks(),
    /** The Find and replace panel's callbacks; here for the same reason as [dictionaryBar]. */
    val findReplace: FindReplaceCallbacks = FindReplaceCallbacks(),
    /** The Learn from text panel's callbacks (#174); here for the same reason as [dictionaryBar]. */
    val learnFromText: LearnFromTextCallbacks = LearnFromTextCallbacks(),
    /** The clipboard panel's editor and view switch; here for the same reason as [dictionaryBar]. */
    val clipboard: ClipboardPanelActions = ClipboardPanelActions(),
    /** The caret magnifier (discussion #303); here for the same reason as [dictionaryBar]. */
    val caretMagnifier: CaretMagnifierSeam = CaretMagnifierSeam(),
)

// ---- snippets panel ----

/**
 * The snippets panel's service callbacks, bundled into one [KeyboardScreen]
 * parameter for the reason [ConverterCallbacks] is: its caller sits against the
 * JVM's 64K method-size ceiling, where every added parameter costs bytecode.
 * Folders needed two more callbacks, and the bundle pays for all three.
 */
data class SnippetPanelCallbacks(
    /** A snippet was tapped: insert its default expansion. */
    val onSnippet: (Snippet) -> Unit = {},
    /** Long-press on a snippet with several expansions: list them instead. */
    val onSnippetHold: (Snippet) -> Unit = {},
    /** Drill into a folder, or back out of one with null. */
    val onFolderOpen: (Long?) -> Unit = {},
    /** Long-press on a folder: arm or disarm its triggers, and persist that. */
    val onFolderToggle: (Long) -> Unit = {},
    /** A row of that list was tapped: insert it. */
    val onPickerPick: (Int) -> Unit = {},
    /** A row standing for a linked snippet was opened: list what it offers. */
    val onPickerDrill: (Int) -> Unit = {},
    /** Back out of the list, one level at a time. */
    val onPickerBack: () -> Unit = {},
)

/**
 * The snippets panel, one level of folders deep.
 *
 * With no folders it is the flat grid it has always been. With folders it opens
 * on them — folders first, then whatever is filed in none of them — and a tap
 * goes inside. Which level is showing lives on [KeyboardUiState], not in this
 * composable, so that back leaves the folder before it closes the panel and the
 * hardware focus ring counts the right things.
 *
 * A long press toggles a folder's triggers. It is the one folder edit worth
 * having here rather than in settings: the point of switching a set of work
 * replies off is that you are mid-message when you realise you want them off.
 */
@Composable
private fun SnippetsPanel(
    state: KeyboardUiState,
    callbacks: SnippetPanelCallbacks,
    onOpenSettings: () -> Unit,
) {
    val picker = state.snippetPicker
    if (picker != null) {
        SnippetPickerList(picker, callbacks)
        return
    }
    // Inside a [FullBleedTool], which owns the height — fill what it gives.
    Column(modifier = Modifier.fillMaxSize()) {
        val folders = state.snippetFolders
        val open = state.openSnippetFolder()
        // Only at the top level, and only when there are folders to draw: inside
        // a folder the tiles are all snippets, as they were before folders.
        val tiles = if (open == null) folders else emptyList()
        val shown = state.snippetsShown()
        if (shown.isEmpty() && tiles.isEmpty()) {
            Column(
                modifier = Modifier.fillMaxSize(),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.Center,
            ) {
                Text(
                    stringResource(
                        if (open == null) {
                            R.string.ime_snippets_empty
                        } else {
                            R.string.ime_snippets_folder_empty
                        },
                    ),
                    textAlign = TextAlign.Center,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                Spacer(Modifier.height(10.dp))
                ToolPanelChip(
                    stringResource(R.string.ime_snippets_settings_desc),
                    selected = true,
                    onClick = onOpenSettings,
                )
            }
            return@Column
        }
        // The gear rides in the full-bleed header now, so this is only the
        // reminder that a snippet's text can carry variables.
        Text(
            stringResource(R.string.ime_snippets_variables),
            fontSize = 12.sp,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = 20.dp, end = 8.dp, bottom = 4.dp),
        )
        // One region over both kinds of tile, folders first, in the order the
        // grid lays them out — so Tab walks the panel the way the eye does.
        PanelFocusTarget(
            panel = PanelMode.SNIPPETS,
            count = tiles.size + shown.size,
            columns = 2,
            onActivate = { index ->
                val folder = tiles.getOrNull(index)
                if (folder != null) {
                    callbacks.onFolderOpen(folder.id)
                } else {
                    shown.getOrNull(index - tiles.size)?.let(callbacks.onSnippet)
                }
            },
        )
        val gridState = rememberLazyGridState()
        val focused = state.focusedIndex()
        ScrollFocusIntoView(focused) { gridState.animateScrollToItem(it) }
        LazyVerticalGrid(
            state = gridState,
            columns = GridCells.Fixed(2),
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f),
            contentPadding = androidx.compose.foundation.layout.PaddingValues(8.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            // Keyed apart from the snippets: the two id spaces are independent,
            // so a folder and a snippet can both be 1 and the grid would reuse
            // one's slot for the other on the way into a folder.
            itemsIndexed(tiles, key = { _, folder -> "folder-${folder.id}" }) { index, folder ->
                SnippetFolderTile(
                    folder = folder,
                    count = state.snippets.count { it.folderId == folder.id },
                    focused = index == focused,
                    modifier = snippetTileMotion(state.settings.reduceMotion),
                    onOpen = { callbacks.onFolderOpen(folder.id) },
                    onToggle = { callbacks.onFolderToggle(folder.id) },
                )
            }
            itemsIndexed(shown, key = { _, snippet -> snippet.id }) { index, snippet ->
                SnippetTile(
                    snippet,
                    focused = tiles.size + index == focused,
                    candidateCount = state.snippetCandidateCounts[snippet.id] ?: 1,
                    modifier = snippetTileMotion(state.settings.reduceMotion),
                    onHold = { callbacks.onSnippetHold(snippet) },
                ) { callbacks.onSnippet(snippet) }
            }
        }
    }
}

/**
 * How a tile in the snippets grid moves when the list under it changes — the
 * same spring the panel has always used, lifted out so both kinds of tile get
 * it without either one having to be a lazy-grid item scope itself. Nothing
 * under Reduce motion: the grid simply redraws in its new order.
 */
private fun LazyGridItemScope.snippetTileMotion(reduceMotion: Boolean): Modifier =
    if (reduceMotion) {
        Modifier
    } else {
        Modifier.animateItem(
            fadeInSpec = tween(160),
            placementSpec = spring(
                stiffness = Spring.StiffnessMediumLow,
                visibilityThreshold = IntOffset.VisibilityThreshold,
            ),
            fadeOutSpec = tween(140),
        )
    }

/** One folder in the snippets panel: open it, or hold to arm/disarm it. */
@Composable
private fun SnippetFolderTile(
    folder: SnippetFolder,
    count: Int,
    focused: Boolean,
    modifier: Modifier = Modifier,
    onOpen: () -> Unit,
    onToggle: () -> Unit,
) {
    val kb = LocalKbTheme.current
    val cardShape = kb.cardShape()
    val haptic = LocalHapticFeedback.current
    val description = stringResource(R.string.ime_snippets_folder_desc, folder.name)
    Row(
        modifier = modifier
            .focusRing(focused, cardShape)
            .clip(cardShape)
            .background(kb.chip)
            .chipBorder(kb, cardShape)
            .combinedClickable(
                onClick = onOpen,
                onLongClick = {
                    haptic()
                    onToggle()
                },
            )
            .semantics { contentDescription = description }
            .padding(10.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        // A disarmed folder is dimmed rather than hidden or recoloured: it is
        // still a folder you can open and still inserts on a tap, and the badge
        // below says the one thing that changed.
        val fade = if (folder.enabled) 1f else 0.55f
        Icon(
            // The folder's own icon when it picked one; a folder otherwise. Not
            // ModeIcons.icon(), whose fallback is a mode's and not a folder's.
            ModeIcons.iconOrNull(folder.icon) ?: Icons.Outlined.Folder,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.primary.copy(alpha = fade),
            modifier = Modifier.size(20.dp),
        )
        Column(modifier = Modifier.weight(1f)) {
            Text(
                text = folder.name,
                fontSize = 13.sp,
                fontWeight = FontWeight.SemiBold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = fade),
            )
            Text(
                text = if (folder.enabled) {
                    pluralStringResource(R.plurals.ime_snippets_folder_count, count, count)
                } else {
                    stringResource(R.string.ime_snippets_folder_off)
                },
                fontSize = 11.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * One snippet card: its name, its text, and the rule that fires it.
 *
 * A tap inserts the default expansion, which is the whole point of the panel:
 * one tile, one insertion, no decision. A snippet with more than that says so
 * with a count beside its name, and holding it lists the rest.
 */
@Composable
private fun SnippetTile(
    snippet: Snippet,
    focused: Boolean,
    candidateCount: Int = 1,
    modifier: Modifier = Modifier,
    onHold: (() -> Unit)? = null,
    onClick: () -> Unit,
) {
    val kb = LocalKbTheme.current
    val cardShape = kb.cardShape()
    val haptic = LocalHapticFeedback.current
    val several = candidateCount > 1 && onHold != null
    val description = if (several) {
        pluralStringResource(
            R.plurals.ime_snippets_tile_options_desc,
            candidateCount,
            snippet.label,
            candidateCount,
        )
    } else {
        snippet.label
    }
    Column(
        modifier = modifier
            .focusRing(focused, cardShape)
            .clip(cardShape)
            .background(kb.chip)
            .chipBorder(kb, cardShape)
            .combinedClickable(
                onClick = onClick,
                onLongClick = if (several) {
                    {
                        haptic()
                        onHold()
                    }
                } else {
                    null
                },
            )
            .semantics { contentDescription = description }
            .padding(10.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                text = snippet.label,
                fontSize = 13.sp,
                fontWeight = FontWeight.SemiBold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.primary,
                modifier = Modifier.weight(1f, fill = false),
            )
            if (several) {
                Spacer(Modifier.width(4.dp))
                Text(
                    text = candidateCount.toString(),
                    fontSize = 11.sp,
                    fontWeight = FontWeight.SemiBold,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
        }
        Text(
            text = snippet.text,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis,
            fontSize = 12.sp,
            color = MaterialTheme.colorScheme.onSurface,
        )
        // A pattern snippet is listed with the rule that fires it, because
        // nobody remembers the patterns they wrote weeks ago — and a tap
        // inserts the text with its blanks empty, which only makes sense next
        // to the rule.
        val pattern = snippet.triggerPattern
        if (!pattern.isNullOrBlank() && snippet.trigger.isNullOrBlank()) {
            Text(
                text = stringResource(R.string.ime_snippets_pattern_label, pattern),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                fontSize = 11.sp,
                fontFamily = FontFamily.Monospace,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * Everything one snippet has to offer, after its tile was held: its own
 * expansions, then the snippets it links to.
 *
 * A list rather than the grid the tiles use, because these are sentences to
 * read rather than names to recognise, and because a row can carry the second
 * target that walks into a linked snippet.
 */
@Composable
private fun SnippetPickerList(picker: SnippetPickerUi, callbacks: SnippetPanelCallbacks) {
    Column(modifier = Modifier.fillMaxSize()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = 8.dp, end = 8.dp, bottom = 2.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(4.dp),
        ) {
            IconButton(onClick = callbacks.onPickerBack, modifier = Modifier.size(32.dp)) {
                Icon(
                    Icons.AutoMirrored.Outlined.ArrowBack,
                    contentDescription = stringResource(
                        R.string.ime_snippet_offer_back_desc,
                        picker.title,
                    ),
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.size(18.dp),
                )
            }
            Text(
                text = picker.title,
                fontSize = 13.sp,
                fontWeight = FontWeight.SemiBold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.primary,
            )
        }
        PanelFocusTarget(
            panel = PanelMode.SNIPPETS,
            count = picker.rows.size,
            columns = 1,
            onActivate = callbacks.onPickerPick,
        )
        val listState = rememberLazyListState()
        ScrollFocusIntoView(null) { listState.animateScrollToItem(it) }
        LazyColumn(
            state = listState,
            modifier = Modifier.fillMaxWidth().weight(1f),
            contentPadding = androidx.compose.foundation.layout.PaddingValues(8.dp),
            verticalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            itemsIndexed(picker.rows, key = { index, row -> "$index-${row.snippetId}" }) { index, row ->
                SnippetPickerRow(
                    row = row,
                    drillable = row.drillable && picker.canDrill(row.snippetId),
                    onClick = { callbacks.onPickerPick(index) },
                    onDrill = { callbacks.onPickerDrill(index) },
                )
            }
        }
    }
}

/** One row of [SnippetPickerList]: what it would insert, and a way further in. */
@Composable
private fun SnippetPickerRow(
    row: SnippetChip,
    drillable: Boolean,
    onClick: () -> Unit,
    onDrill: () -> Unit,
) {
    val kb = LocalKbTheme.current
    val cardShape = kb.cardShape()
    val haptic = LocalHapticFeedback.current
    val preview = remember(row.text) { row.text.replace(WHITESPACE_RUN, " ").trim() }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(cardShape)
            .background(kb.chip)
            .chipBorder(kb, cardShape),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Column(
            modifier = Modifier
                .weight(1f)
                .combinedClickable(
                    onClick = onClick,
                    onLongClick = if (drillable) {
                        {
                            haptic()
                            onDrill()
                        }
                    } else {
                        null
                    },
                )
                .padding(horizontal = 10.dp, vertical = 8.dp),
        ) {
            Text(
                text = row.label,
                fontSize = 11.sp,
                fontWeight = FontWeight.SemiBold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.primary,
            )
            Text(
                text = preview,
                fontSize = 13.sp,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.onSurface,
            )
        }
        if (drillable) {
            IconButton(onClick = onDrill, modifier = Modifier.size(36.dp)) {
                Icon(
                    Icons.Outlined.ChevronRight,
                    contentDescription = stringResource(
                        R.string.ime_snippet_offer_more_desc,
                        row.label,
                    ),
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.size(18.dp),
                )
            }
        }
    }
}

// ---- clipboard panel ----

/**
 * Search pill at the top of the clipboard panel. Tapping it routes the keys
 * into [KeyboardUiState.clipboardQuery] (like emoji/dictionary search) so the
 * IME can filter its own history without a focusable text field.
 */
@Composable
internal fun ClipboardSearchField(
    state: KeyboardUiState,
    onToggle: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val active = state.clipboardSearchActive
    val kb = LocalKbTheme.current
    val fieldShape = kb.cardShape()
    Row(
        modifier = modifier
            .clip(fieldShape)
            .background(kb.chip)
            .chipBorder(kb, fieldShape)
            .clickable { onToggle() }
            .padding(horizontal = 12.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Icon(
            Icons.Outlined.Search,
            contentDescription = null,
            modifier = Modifier.size(18.dp),
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Spacer(Modifier.width(8.dp))
        SearchQueryText(
            query = state.clipboardQuery,
            placeholder = stringResource(R.string.ime_clipboard_search_hint),
            active = active,
            textColor = MaterialTheme.colorScheme.onSurface,
            placeholderColor = MaterialTheme.colorScheme.onSurfaceVariant,
            fontSize = 14.sp,
            modifier = Modifier.weight(1f),
        )
        // Only up while searching (typing is the only way to fill the query,
        // and closing clears it). Clears the filter and hands the keys back.
        if (active) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_clipboard_search_clear_desc),
                modifier = Modifier
                    .padding(start = 8.dp)
                    .size(18.dp)
                    .clickable { onToggle() },
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * The strip of fragments — one-time codes, phone numbers, links — pulled out of
 * the clips below it.
 *
 * The visual language carries the whole idea: a history card is a solid filled
 * rectangle holding something the clipboard really contains, while these are
 * dashed cut-outs under a caption that says where they came from. Nothing here
 * is an entry of its own, and long-pressing one shows it highlighted inside the
 * clip it was lifted from, which is the same claim made a second way.
 */
@Composable
internal fun ClipEntityStrip(
    entities: List<ClipEntity>,
    focused: Int?,
    onPaste: (ClipEntity) -> Unit,
) {
    // A light top inset: the panel layout's cell already keeps a key gap
    // above the strip, and every dp here comes out of the chips' row.
    Column(modifier = Modifier.padding(top = 3.dp)) {
        Row(
            modifier = Modifier.padding(start = 12.dp, end = 12.dp, bottom = 4.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(
                Icons.Outlined.ContentCut,
                contentDescription = null,
                modifier = Modifier.size(12.dp),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            Spacer(Modifier.width(5.dp))
            Text(
                stringResource(R.string.ime_clip_entity_hint),
                fontSize = 10.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
        LazyRow(
            contentPadding = androidx.compose.foundation.layout.PaddingValues(horizontal = 10.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            itemsIndexed(entities, key = { _, entity -> entity.key }) { index, entity ->
                ClipEntityChip(entity, focused = index == focused, onPaste = onPaste)
            }
        }
    }
}

/** One dashed fragment chip: kind tag above the text that will be pasted. */
@Composable
private fun ClipEntityChip(
    entity: ClipEntity,
    focused: Boolean,
    onPaste: (ClipEntity) -> Unit,
) {
    val accent = MaterialTheme.colorScheme.primary
    val shape = RoundedCornerShape(10.dp)
    var showSource by remember { mutableStateOf(false) }
    Row(
        modifier = Modifier
            .focusRing(focused, shape)
            .dashedOutline(accent.copy(alpha = 0.6f), 10.dp)
            .pointerInput(entity.key) {
                detectTapGestures(
                    onTap = { onPaste(entity) },
                    onLongPress = { showSource = true },
                )
            }
            .padding(horizontal = 9.dp, vertical = 5.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        if (showSource) {
            ClipEntitySourcePopup(entity, onDismiss = { showSource = false })
        }
        Icon(
            when (entity.kind) {
                ClipEntityKind.OTP -> Icons.Outlined.Password
                ClipEntityKind.PHONE -> Icons.Outlined.Phone
                ClipEntityKind.URL -> Icons.Outlined.Link
            },
            contentDescription = stringResource(entity.kind.labelRes),
            modifier = Modifier.size(15.dp),
            tint = accent,
        )
        Spacer(Modifier.width(6.dp))
        Column {
            Text(
                stringResource(entity.kind.tagRes),
                fontSize = 8.sp,
                letterSpacing = 0.8.sp,
                fontWeight = FontWeight.Medium,
                color = accent.copy(alpha = 0.85f),
                maxLines = 1,
            )
            Text(
                entity.value,
                fontSize = 13.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.onSurface,
                modifier = Modifier.widthIn(max = 170.dp),
            )
        }
    }
}

/**
 * Press-and-hold proof that a chip is a cut-out: the clip it came from, shown
 * with the fragment highlighted in place. Windowed around the fragment so a
 * long clip does not turn the popup into a wall of text.
 */
@Composable
private fun ClipEntitySourcePopup(entity: ClipEntity, onDismiss: () -> Unit) {
    val kb = LocalKbTheme.current
    val source = entity.sourceText
    val from = (entity.start - SOURCE_CONTEXT_CHARS).coerceAtLeast(0)
    val to = (entity.end + SOURCE_CONTEXT_CHARS).coerceAtMost(source.length)
    val shown = remember(entity.key, source) {
        buildAnnotatedString {
            if (from > 0) append("…")
            append(source.substring(from, entity.start))
            withStyle(
                SpanStyle(
                    background = kb.accent.copy(alpha = 0.28f),
                    fontWeight = FontWeight.Medium,
                ),
            ) {
                append(source.substring(entity.start, entity.end))
            }
            append(source.substring(entity.end, to))
            if (to < source.length) append("…")
        }
    }
    Popup(
        popupPositionProvider = rememberAboveAnchorPopup(),
        onDismissRequest = onDismiss,
    ) {
        Surface(
            shape = kb.menuShape(),
            color = kb.popup,
            border = kb.popupSurfaceBorder(),
            shadowElevation = elevationFor(kb.menuShapeKind, 6.dp),
        ) {
            Column(
                modifier = Modifier
                    .widthIn(min = 180.dp, max = 260.dp)
                    .padding(horizontal = 12.dp, vertical = 10.dp),
                verticalArrangement = Arrangement.spacedBy(5.dp),
            ) {
                Text(
                    stringResource(
                        R.string.ime_clip_entity_popup_title,
                        stringResource(entity.kind.labelRes),
                    ),
                    fontSize = 10.sp,
                    fontWeight = FontWeight.Medium,
                    color = kb.popupText.copy(alpha = 0.6f),
                )
                Text(
                    shown,
                    fontSize = 11.sp,
                    color = kb.popupText,
                    maxLines = 5,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        }
    }
}

/** Characters of surrounding clip shown either side of a fragment. */
private const val SOURCE_CONTEXT_CHARS = 60

/**
 * Dashed rounded outline with no fill. Deliberately unlike every filled card in
 * the panel — it is the signal that what it wraps was cut out of something else.
 */
private fun Modifier.dashedOutline(color: Color, radius: Dp, width: Dp = 1.dp) = drawBehind {
    val line = width.toPx()
    drawRoundRect(
        color = color,
        topLeft = Offset(line / 2, line / 2),
        size = Size(size.width - line, size.height - line),
        cornerRadius = CornerRadius(radius.toPx()),
        style = Stroke(
            width = line,
            pathEffect = PathEffect.dashPathEffect(floatArrayOf(7f, 5f)),
        ),
    )
}

/** Small round action button on a clipboard card. */
@Composable
internal fun ClipActionCircle(
    icon: ImageVector,
    description: String,
    tint: Color,
    onClick: () -> Unit,
) {
    Box(
        modifier = Modifier
            .size(30.dp)
            .clip(CircleShape)
            .background(MaterialTheme.colorScheme.surfaceContainerHighest)
            .clickable(onClick = onClick),
        contentAlignment = Alignment.Center,
    ) {
        Icon(
            icon,
            contentDescription = description,
            modifier = Modifier.size(15.dp),
            tint = tint,
        )
    }
}

/**
 * Press-and-hold details for a clip: when it was copied (relative + exact),
 * which app it came from (when source tracking is on), its type, and a size or
 * length. Anchored above the card; dismissed by tapping elsewhere.
 */
@Composable
internal fun ClipInfoPopup(
    item: ClipItem,
    onSendSticker: (() -> Unit)? = null,
    /** Opens the clip in the panel's editor; null for a clip that has no text to edit. */
    onEdit: (() -> Unit)? = null,
    /** Deletes the clip; null while a swipe does that instead (#344). */
    onDelete: (() -> Unit)? = null,
    onDismiss: () -> Unit,
) {
    val kb = LocalKbTheme.current
    val now = System.currentTimeMillis()
    val relative = android.text.format.DateUtils.getRelativeTimeSpanString(
        item.timestamp, now, android.text.format.DateUtils.MINUTE_IN_MILLIS,
    ).toString()
    val exact = remember(item.timestamp) {
        java.text.SimpleDateFormat("MMM d, yyyy · h:mm a", java.util.Locale.getDefault())
            .format(java.util.Date(item.timestamp))
    }
    val typeLabel = stringResource(
        when (item.kind) {
            ClipKind.TEXT -> R.string.ime_clip_type_text
            ClipKind.HTML -> R.string.ime_clip_type_rich_text
            ClipKind.LINK -> R.string.ime_clip_type_link
            ClipKind.IMAGE -> R.string.ime_clip_type_image
            ClipKind.FILE -> R.string.ime_clip_type_file
            ClipKind.FOLDER -> R.string.ime_clip_type_folder
            ClipKind.VIDEO -> R.string.ime_clip_type_video
        },
    )
    val characterCount = pluralStringResource(
        R.plurals.ime_clip_character_count, item.text.length, item.text.length,
    )
    val sizeLabel = when (item.kind) {
        ClipKind.IMAGE -> item.mimeType.substringAfterLast('/').takeIf { it.isNotBlank() }?.uppercase()
        ClipKind.FILE -> formatFileSize(item.fileSize)
        ClipKind.FOLDER -> null
        ClipKind.VIDEO -> listOfNotNull(
            formatDuration(item.durationMs),
            formatFileSize(item.fileSize),
        ).joinToString(" · ").takeIf { it.isNotBlank() }
        else -> characterCount
    }
    Popup(
        popupPositionProvider = rememberAboveAnchorPopup(),
        onDismissRequest = onDismiss,
    ) {
        Surface(
            shape = kb.menuShape(),
            color = kb.popup,
            border = kb.popupSurfaceBorder(),
            shadowElevation = elevationFor(kb.menuShapeKind, 6.dp),
        ) {
            Column(
                modifier = Modifier
                    .widthIn(min = 160.dp, max = 240.dp)
                    .padding(horizontal = 12.dp, vertical = 10.dp),
                verticalArrangement = Arrangement.spacedBy(6.dp),
            ) {
                ClipInfoRow(
                    stringResource(R.string.ime_clip_info_copied),
                    "$relative\n$exact",
                    kb.popupText,
                )
                item.sourceApp?.let {
                    ClipInfoRow(stringResource(R.string.ime_clip_info_from), it, kb.popupText)
                }
                ClipInfoRow(stringResource(R.string.ime_clip_info_type), typeLabel, kb.popupText)
                sizeLabel?.let {
                    ClipInfoRow(stringResource(R.string.ime_clip_info_size), it, kb.popupText)
                }
                if (onEdit != null) {
                    TextButton(
                        onClick = onEdit,
                        modifier = Modifier.fillMaxWidth(),
                    ) {
                        Icon(Icons.Outlined.Edit, contentDescription = null)
                        Spacer(Modifier.width(6.dp))
                        Text(stringResource(R.string.ime_clip_edit))
                    }
                }
                if (onSendSticker != null) {
                    TextButton(
                        onClick = onSendSticker,
                        modifier = Modifier.fillMaxWidth(),
                    ) {
                        Icon(Icons.Outlined.EmojiEmotions, contentDescription = null)
                        Spacer(Modifier.width(6.dp))
                        Text(stringResource(R.string.ime_clip_send_as_sticker))
                    }
                }
                if (onDelete != null) {
                    TextButton(
                        onClick = onDelete,
                        modifier = Modifier.fillMaxWidth(),
                        colors = ButtonDefaults.textButtonColors(
                            contentColor = MaterialTheme.colorScheme.error,
                        ),
                    ) {
                        Icon(Icons.Outlined.Delete, contentDescription = null)
                        Spacer(Modifier.width(6.dp))
                        Text(stringResource(CommonR.string.common_delete))
                    }
                }
                if (item.sensitive) {
                    ClipInfoRow(
                        stringResource(R.string.ime_clip_info_private),
                        stringResource(R.string.ime_clip_info_private_detail),
                        kb.popupText,
                    )
                }
            }
        }
    }
}

/** One "Label: value" line in the clipboard info popup. */
@Composable
private fun ClipInfoRow(label: String, value: String, textColor: Color) {
    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        Text(
            label,
            fontSize = 11.sp,
            fontWeight = FontWeight.Medium,
            color = textColor.copy(alpha = 0.6f),
            modifier = Modifier.width(44.dp),
        )
        Text(
            value,
            fontSize = 11.sp,
            color = textColor,
            modifier = Modifier.weight(1f),
        )
    }
}

/**
 * Horizontal swipe-to-dismiss for a grid card: the card follows the finger,
 * fades as it travels, and a release past 40% of its width deletes it —
 * otherwise it springs back. Vertical scrolling is untouched (only
 * horizontal drags are claimed). With [enabled] false the card claims no
 * drag at all and simply holds [content].
 */
@Composable
internal fun SwipeToDeleteCard(
    onDelete: () -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    content: @Composable () -> Unit,
) {
    if (!enabled) {
        Box(modifier = modifier) { content() }
        return
    }
    val offset = remember { Animatable(0f) }
    val scope = rememberCoroutineScope()
    var width by remember { mutableIntStateOf(0) }
    // A dismissed card stays off-screen and invisible until the grid drops it.
    // The delete only reaches the list a frame or two later, and the grid then
    // plays its fade-out on the card still in place — so putting the card back
    // in the middle first made the deleted clip flash back into its slot.
    var dismissed by remember { mutableStateOf(false) }
    Box(
        modifier = modifier
            .onGloballyPositioned { width = it.size.width }
            .graphicsLayer {
                translationX = offset.value
                alpha = when {
                    dismissed -> 0f
                    width == 0 -> 1f
                    // Gone by the time it has travelled its own width, so the
                    // card never ghosts over its neighbour on the way out.
                    else -> (1f - abs(offset.value) / width).coerceIn(0f, 1f)
                }
            }
            .pointerInput(Unit) {
                detectHorizontalDragGestures(
                    onHorizontalDrag = { change, delta ->
                        if (!dismissed) {
                            change.consume()
                            scope.launch { offset.snapTo(offset.value + delta) }
                        }
                    },
                    onDragEnd = {
                        if (!dismissed) scope.launch {
                            val threshold = width * 0.4f
                            if (width > 0 && abs(offset.value) > threshold) {
                                // Finish the slide off-screen, then delete, and
                                // leave the card where it landed.
                                offset.animateTo(
                                    if (offset.value > 0) width.toFloat() else -width.toFloat(),
                                    tween(120),
                                )
                                dismissed = true
                                onDelete()
                            } else {
                                offset.animateTo(0f, spring(stiffness = Spring.StiffnessMediumLow))
                            }
                        }
                    },
                    onDragCancel = {
                        if (!dismissed) scope.launch { offset.animateTo(0f) }
                    },
                )
            },
    ) { content() }
}

/**
 * A copied file or folder: type icon, name, and either the file size or a
 * "Folder" label. Folders are marked plainly because tapping one can't attach
 * it anywhere — it types the name instead.
 */
@Composable
internal fun ClipFileBody(item: ClipItem) {
    val isFolder = item.kind == ClipKind.FOLDER
    Row(verticalAlignment = Alignment.CenterVertically) {
        Icon(
            if (isFolder) Icons.Outlined.Folder else fileIconFor(item.mimeType),
            contentDescription = stringResource(
                if (isFolder) R.string.ime_clip_type_folder else R.string.ime_clip_type_file,
            ),
            modifier = Modifier
                .size(28.dp)
                .padding(end = 6.dp),
            tint = MaterialTheme.colorScheme.primary,
        )
        Column {
            Text(
                text = item.fileName.orEmpty().ifBlank { item.text },
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                fontSize = 13.sp,
                fontWeight = FontWeight.Medium,
                color = MaterialTheme.colorScheme.onSurface,
            )
            Text(
                text = if (isFolder) stringResource(R.string.ime_clip_type_folder) else listOfNotNull(
                    formatFileSize(item.fileSize),
                    item.mimeType.substringAfterLast('/').takeIf { it.isNotBlank() }?.uppercase(),
                ).joinToString(" · "),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                fontSize = 10.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * A clip holding a secret: bullets instead of the text, with a lock and a
 * character count so the card still says *something* about what it is.
 *
 * Deliberately not revealable in place. Anyone who can see the panel can see
 * whatever a reveal button would show, and the card is already one tap from
 * pasting the real thing where it belongs — a peek affordance would add a way
 * to expose the password without adding a way to use it.
 */
@Composable
internal fun ClipSensitiveBody(item: ClipItem) {
    Row(verticalAlignment = Alignment.CenterVertically) {
        Icon(
            Icons.Outlined.Lock,
            contentDescription = stringResource(R.string.ime_clip_hidden_desc),
            modifier = Modifier
                .size(22.dp)
                .padding(end = 6.dp),
            tint = MaterialTheme.colorScheme.primary,
        )
        Column {
            Text(
                text = "•".repeat(item.text.length.coerceIn(6, 16)),
                maxLines = 1,
                overflow = TextOverflow.Clip,
                fontSize = 15.sp,
                letterSpacing = 2.sp,
                color = MaterialTheme.colorScheme.onSurface,
            )
            Text(
                text = pluralStringResource(
                    R.plurals.ime_clip_hidden_summary, item.text.length, item.text.length,
                ),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                fontSize = 10.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * A copied video: a frame from it under a play badge, with the length and file
 * size beneath. The frame is pulled straight from the source URI — the bytes
 * belong to the app that did the copying and are never duplicated here — so it
 * simply falls back to a plain file row when the grant has lapsed or the
 * container will not decode.
 */
@Composable
internal fun ClipVideoBody(item: ClipItem) {
    val context = LocalContext.current
    val frame by produceState<ImageBitmap?>(initialValue = null, item.uriString) {
        value = withContext(Dispatchers.IO) {
            val uri = item.uriString?.let { runCatching { android.net.Uri.parse(it) }.getOrNull() }
                ?: return@withContext null
            runCatching {
                // Not `use`: MediaMetadataRetriever only became AutoCloseable in
                // API 29, and this app runs back to 24.
                val retriever = android.media.MediaMetadataRetriever()
                try {
                    retriever.setDataSource(context, uri)
                    retriever.getFrameAtTime(0)?.asImageBitmap()
                } finally {
                    retriever.release()
                }
            }.getOrNull()
        }
    }
    val shape = RoundedCornerShape(8.dp)
    val caption = listOfNotNull(
        formatDuration(item.durationMs),
        formatFileSize(item.fileSize),
    ).joinToString(" · ")

    val thumbnail = frame
    if (thumbnail == null) {
        ClipFileBody(item)
        return
    }
    Column {
        Box(contentAlignment = Alignment.Center) {
            Image(
                bitmap = thumbnail,
                contentDescription = stringResource(R.string.ime_clip_video_desc),
                modifier = Modifier
                    .fillMaxWidth()
                    .aspectRatio(
                        (thumbnail.width.toFloat() / thumbnail.height.coerceAtLeast(1))
                            .coerceIn(MIN_THUMBNAIL_RATIO, MAX_THUMBNAIL_RATIO),
                    )
                    .background(MaterialTheme.colorScheme.surfaceContainerHigh, shape)
                    .clip(shape),
                contentScale = ContentScale.Crop,
            )
            Box(
                modifier = Modifier
                    .size(32.dp)
                    .clip(CircleShape)
                    .background(Color.Black.copy(alpha = 0.45f)),
                contentAlignment = Alignment.Center,
            ) {
                Icon(
                    Icons.Outlined.PlayArrow,
                    contentDescription = null,
                    modifier = Modifier.size(20.dp),
                    tint = Color.White,
                )
            }
        }
        if (caption.isNotBlank()) {
            Text(
                text = caption,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                fontSize = 10.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.padding(top = 4.dp, start = 4.dp),
            )
        }
    }
}

/** `1:04`, `12:03:41` — or null when the length could not be read. */
private fun formatDuration(millis: Long): String? {
    if (millis <= 0) return null
    val totalSeconds = millis / 1000
    val hours = totalSeconds / 3600
    val minutes = (totalSeconds % 3600) / 60
    val seconds = totalSeconds % 60
    return if (hours > 0) {
        String.format(java.util.Locale.getDefault(), "%d:%02d:%02d", hours, minutes, seconds)
    } else {
        String.format(java.util.Locale.getDefault(), "%d:%02d", minutes, seconds)
    }
}

/**
 * A copied link, tinted and underlined so it reads as one. When link previews
 * are on and the fetch found something, the page title and description replace
 * the raw URL, which drops to a host line underneath.
 */
@Composable
internal fun ClipLinkBody(item: ClipItem) {
    val preview = item.linkPreview?.takeIf { !it.failed && !it.isEmpty }
    val linkColor = MaterialTheme.colorScheme.primary
    Column {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Icon(
                Icons.Outlined.Link,
                contentDescription = stringResource(R.string.ime_clip_type_link),
                modifier = Modifier
                    .size(22.dp)
                    .padding(end = 4.dp),
                tint = linkColor,
            )
            Text(
                text = preview?.title?.takeIf { it.isNotBlank() } ?: item.text,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                fontSize = 13.sp,
                fontWeight = if (preview != null) FontWeight.Medium else FontWeight.Normal,
                color = if (preview != null) MaterialTheme.colorScheme.onSurface else linkColor,
                textDecoration = if (preview != null) null else TextDecoration.Underline,
            )
        }
        if (preview != null && preview.description.isNotBlank()) {
            Text(
                text = preview.description,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                fontSize = 11.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
        // Title/description replace the raw URL above, so show what actually
        // gets pasted here — otherwise the real clip text is never visible.
        if (preview != null) {
            Text(
                text = item.text,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                fontSize = 10.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
        val host = ClipLinks.host(ClipLinks.asUrl(item.text) ?: item.text)
        if (host.isNotBlank()) {
            Text(
                text = preview?.siteName?.takeIf { it.isNotBlank() } ?: host,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                fontSize = 10.sp,
                color = linkColor,
            )
        }
    }
}

private fun fileIconFor(mimeType: String) = when {
    mimeType.startsWith("audio/") -> Icons.Outlined.AudioFile
    mimeType.startsWith("video/") -> Icons.Outlined.VideoFile
    mimeType.startsWith("image/") -> Icons.Outlined.Image
    mimeType == "application/pdf" -> Icons.Outlined.PictureAsPdf
    mimeType.startsWith("text/") -> Icons.Outlined.Description
    else -> Icons.AutoMirrored.Outlined.InsertDriveFile
}

/** Human file size, or null when the provider didn't report one. */
private fun formatFileSize(bytes: Long): String? {
    if (bytes < 0) return null
    if (bytes < 1024) return "$bytes B"
    val units = listOf("KB", "MB", "GB", "TB")
    var value = bytes.toDouble() / 1024
    var unit = 0
    while (value >= 1024 && unit < units.lastIndex) {
        value /= 1024
        unit++
    }
    return if (value >= 10) "${value.toInt()} ${units[unit]}"
    else String.format(java.util.Locale.getDefault(), "%.1f %s", value, units[unit])
}

/** Decodes a downsampled preview of an image clip off the main thread. */
@Composable
internal fun ClipThumbnail(item: ClipItem) {
    val bitmap by produceState<ImageBitmap?>(initialValue = null, item.imagePath) {
        value = withContext(Dispatchers.IO) {
            val path = item.imagePath ?: return@withContext null
            runCatching {
                val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
                BitmapFactory.decodeFile(path, bounds)
                var sample = 1
                while (bounds.outWidth / (sample * 2) >= THUMBNAIL_TARGET_PX &&
                    bounds.outHeight / (sample * 2) >= THUMBNAIL_TARGET_PX
                ) {
                    sample *= 2
                }
                BitmapFactory.decodeFile(path, BitmapFactory.Options().apply { inSampleSize = sample })
                    ?.asImageBitmap()
            }.getOrNull()
        }
    }
    val shape = RoundedCornerShape(8.dp)
    bitmap?.let {
        // The card takes the image's own aspect ratio, so there is no
        // letterboxing to leave dead space beside it — the staggered grid just
        // makes this cell taller or shorter and packs the other column around
        // it. Only the extremes are clamped (a panorama or a full-page
        // screenshot would otherwise be a sliver or swallow the panel), and
        // those are the one case that crops instead of fits.
        val natural = it.width.toFloat() / it.height.coerceAtLeast(1)
        val ratio = natural.coerceIn(MIN_THUMBNAIL_RATIO, MAX_THUMBNAIL_RATIO)
        Image(
            bitmap = it,
            contentDescription = stringResource(R.string.ime_clip_chip_image),
            modifier = Modifier
                .fillMaxWidth()
                .aspectRatio(ratio)
                .background(MaterialTheme.colorScheme.surfaceContainerHigh, shape)
                .clip(shape),
            contentScale = if (ratio == natural) ContentScale.Fit else ContentScale.Crop,
        )
    } ?: Box(
        Modifier
            .fillMaxWidth()
            .height(64.dp)
            .background(MaterialTheme.colorScheme.surfaceContainerHigh, shape)
    )
}

private const val THUMBNAIL_TARGET_PX = 256

/** Widest and tallest an image card may get before it crops instead. */
private const val MIN_THUMBNAIL_RATIO = 0.62f
private const val MAX_THUMBNAIL_RATIO = 2.2f

/**
 * A word segment as the decoder should see it: the walks out to the shift
 * key and back cut out (#163), copied so the stroke's own buffer can keep
 * growing under an asynchronous decode. With it, what the segment's crossings
 * asked for under the per-letter reading — [GlideCase.None] under the
 * whole-word one, whose count is settled for the stroke as a whole by
 * [wordCaseOr].
 */
private fun glideSegment(
    seg: List<GesturePoint>,
    cuts: List<Int>,
    shiftCenter: GesturePoint?,
    keyWidth: Float,
    letters: Boolean,
    endedOnShift: Boolean,
): Pair<List<GesturePoint>, GlideCase> {
    if (cuts.isEmpty()) return seg.toList() to GlideCase.None
    val trimmed = GlideShiftDetour.trim(seg, cuts.toIntArray(), keyWidth, key = shiftCenter)
    val case = if (letters) GlideCase.Letters(trimmed.cuts, endedOnShift) else GlideCase.None
    return trimmed.points to case
}

/** [case], or the whole-word count of [crossings] when that is the reading in force. */
private fun wordCaseOr(case: GlideCase, letters: Boolean, crossings: Int): GlideCase = when {
    letters -> case
    crossings > 0 -> GlideCase.Word(crossings)
    else -> GlideCase.None
}
